insert into public.lesson_slides (lesson_id, position, kind, payload)
select l.id, v.pos, v.kind, v.payload::jsonb
from (values
  ('hsk2-01-1', 1, 'fact', '{"emoji":"👩‍👩‍👧","title":"Фамилия родом из древних кланов","text":"В знаке 姓 «фамилия» есть 女 «женщина» и 生 «рождаться». Учёные считают, что самые старые китайские фамилии появились в материнских родах: человек рождался от женщины и получал имя её клана. А 大家 буквально «большая семья» и значит «все, всем»: так китайцы обращаются к собравшимся."}'),
  ('hsk2-01-1', 2, 'words', '{"title":"Четыре слова для знакомства","items":[{"hanzi":"姓","pinyin":"xìng","m":"фамилия; зваться по фамилии","emoji":"🪪","ex":{"zh":"我姓王。","py":"Wǒ xìng Wáng.","m":"Моя фамилия Ван."}},{"hanzi":"介绍","pinyin":"jièshào","m":"представлять, знакомить","emoji":"🤝","ex":{"zh":"我介绍我的朋友。","py":"Wǒ jièshào wǒ de péngyou.","m":"Я представляю своего друга."}},{"hanzi":"欢迎","pinyin":"huānyíng","m":"добро пожаловать","emoji":"🎉","ex":{"zh":"欢迎你！","py":"Huānyíng nǐ!","m":"Добро пожаловать!"}},{"hanzi":"大家","pinyin":"dàjiā","m":"все, всем","emoji":"👥","ex":{"zh":"大家好！","py":"Dàjiā hǎo!","m":"Всем привет!"}}]}'),
  ('hsk2-01-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🪪","options":["介绍","姓","欢迎"],"correct":1},{"emoji":"🤝","options":["介绍","大家","姓"],"correct":0},{"emoji":"🎉","options":["姓","大家","欢迎"],"correct":2},{"emoji":"👥","options":["大家","欢迎","介绍"],"correct":0}]}'),
  ('hsk2-01-1', 4, 'theory', '{"title":"Как назвать фамилию и имя","blocks":[{"t":"table","head":["Вопрос","Ответ"],"rows":[["你姓什么？","我姓王。"],["你叫什么名字？","我叫王芳。"],["你姓什么，叫什么？","我姓王，叫王芳。"]]},{"t":"p","text":"Сначала называют фамилию: 我姓王, потом полное имя: 我叫王芳. Фамилия идёт после 姓 без добавок."},{"t":"tip","text":"姓 — глагол: «зваться по фамилии». Говорите 我姓李, а не 我是姓李."}]}'),
  ('hsk2-01-1', 5, 'quiz', '{"title":"Мини-тест: фамилия","qs":[{"q":"Как спросить фамилию?","options":["你叫什么姓？","你姓什么？","你什么姓？"],"correct":1},{"q":"Как сказать «Моя фамилия Ли»?","options":["我姓李。","我李姓。","姓我李。"],"correct":0},{"q":"大家 значит «все».","tf":true}]}'),
  ('hsk2-01-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["姓","фамилия"],["介绍","представлять"],["欢迎","добро пожаловать"],["大家","все"],["我姓王","моя фамилия Ван"]]}'),
  ('hsk2-01-1', 7, 'game', '{"type":"listen","title":"Слушаем знакомство","items":[{"say":"姓","options":["xìng","xíng","xīng"],"correct":0},{"say":"介绍","options":["jièshào","jiéshào","jièshāo"],"correct":0},{"say":"欢迎","options":["huānyíng","huányíng","huānyǐng"],"correct":0},{"say":"大家好","options":["dàjiā hǎo","dàjiā hào"],"correct":0},{"say":"你姓什么","options":["nǐ xìng shénme","nǐ jiào shénme"],"correct":0}]}'),
  ('hsk2-01-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","姓","王"],"hint":"«Моя фамилия Ван.»"},{"answer":["你","姓","什么"],"hint":"«Как твоя фамилия?»"},{"answer":["大家","好"],"hint":"«Всем привет!»"}]}'),
  ('hsk2-01-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"姓","pinyin":"xìng","m":"фамилия","hint":"слева 女, справа 生"},{"hanzi":"家","pinyin":"jiā","m":"дом","hint":"宀 + 豕"},{"hanzi":"迎","pinyin":"yíng","m":"встречать","hint":"слева 辶, справа 卬"}]}'),
  ('hsk2-01-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 欢迎?","options":["представлять","добро пожаловать","фамилия"],"correct":1},{"q":"Как читается 介绍?","options":["jièshào","jiéshào","jièshāo"],"correct":0},{"q":"В знаке 姓 есть 女.","tf":true},{"q":"Что значит 大家 буквально?","options":["большая семья","большой дом","много людей"],"correct":0},{"q":"Как сказать «Меня зовут Ван Фан, моя фамилия Ван»?","options":["我姓王，叫王芳。","我王叫姓芳。","姓我王，叫芳。"],"correct":0}]}'),
  ('hsk2-01-2', 1, 'fact', '{"emoji":"🧰","title":"Четыре маленьких слова, которые делают речь живой","text":"也 «тоже» всегда стоит перед глаголом: 我也是学生. 一下 смягчает просьбу: 看一下 «взгляни разок». 吧 превращает приказ в мягкое предложение: 我们走吧 «давайте пойдём». А 可以 «можно» спрашивает разрешение: 我可以坐吗？ «Можно мне сесть?»"}'),
  ('hsk2-01-2', 2, 'words', '{"title":"Четыре слова-помощника","items":[{"hanzi":"也","pinyin":"yě","m":"тоже","emoji":"➕","ex":{"zh":"我也是学生。","py":"Wǒ yě shì xuésheng.","m":"Я тоже студент."}},{"hanzi":"一下","pinyin":"yíxià","m":"разок, чуть-чуть","emoji":"🤏","ex":{"zh":"介绍一下。","py":"Jièshào yíxià.","m":"Представлю."}},{"hanzi":"吧","pinyin":"ba","m":"частица предложения","emoji":"💬","ex":{"zh":"我们去吧。","py":"Wǒmen qù ba.","m":"Давайте пойдём."}},{"hanzi":"可以","pinyin":"kěyǐ","m":"можно, мочь","emoji":"✅","ex":{"zh":"我可以坐吗？","py":"Wǒ kěyǐ zuò ma?","m":"Можно мне сесть?"}}]}'),
  ('hsk2-01-2', 3, 'theory', '{"title":"也: стоит перед глаголом","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我也是学生。","Я тоже студент."],["他也喜欢茶。","Он тоже любит чай."],["你也去吗？","Ты тоже пойдёшь?"]]},{"t":"p","text":"也 ставится после подлежащего и до глагола, как 都. Если вместе: 我们也都去 «и мы тоже все пойдём»."},{"t":"tip","text":"Не ставьте 也 в конец фразы: «я студент тоже» по-китайски так не говорят."}]}'),
  ('hsk2-01-2', 4, 'quiz', '{"title":"Мини-тест: 也 и 可以","qs":[{"q":"Как сказать «Я тоже студент»?","options":["我是学生也。","我也是学生。","也我是学生。"],"correct":1},{"q":"也 ставится в конец предложения.","tf":false,"explain":"Он стоит перед глаголом."},{"q":"Что значит 可以?","options":["можно","нельзя","очень"],"correct":0}]}'),
  ('hsk2-01-2', 5, 'theory', '{"title":"一下 и 吧: мягкость речи","blocks":[{"t":"table","head":["Слово","Что делает","Пример"],"rows":[["一下","смягчает просьбу, делает действие коротким","介绍一下 / 看一下"],["吧","предлагает, а не приказывает","我们走吧。 / 你来吧。"],["可以","спрашивает разрешение","我可以进来吗？"]]},{"t":"p","text":"一下 ставится после глагола: 看一下, 等一下. 吧 стоит в самом конце предложения. 可以 ставится перед глаголом и означает и «можно», и «уметь»."},{"t":"ex","zh":"请等一下。","py":"Qǐng děng yíxià.","m":"Пожалуйста, подождите немного.","say":"请等一下"}]}'),
  ('hsk2-01-2', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","也","是","学生"],"hint":"«Я тоже студент.»"},{"answer":["我们","说","汉语","吧"],"hint":"«Давайте говорить по-китайски.»"},{"answer":["我","介绍","一下"],"hint":"«Позвольте представить.»"},{"answer":["我","可以","坐","吗"],"hint":"«Можно мне сесть?»"}]}'),
  ('hsk2-01-2', 7, 'game', '{"type":"listen","title":"Слушаем: 也, 一下, 吧, 可以","items":[{"say":"我也是学生","options":["wǒ yě shì xuésheng","wǒ dōu shì xuésheng"],"correct":0},{"say":"介绍一下","options":["jièshào yíxià","jièshào yǐxià"],"correct":0},{"say":"我们走吧","options":["wǒmen zǒu ba","wǒmen zǒu ma"],"correct":0},{"say":"你可以来吗","options":["nǐ kěyǐ lái ma","nǐ kěyǐ qù ma"],"correct":0},{"say":"一下","options":["yíxià","yìxià","yīxià"],"correct":0,"explain":"xià — четвёртый тон, поэтому 一 → yí."}]}'),
  ('hsk2-01-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["也","тоже"],["一下","разок"],["吧","давайте"],["可以","можно"],["我们说汉语吧","Давайте говорить по-китайски"]]}'),
  ('hsk2-01-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: маленькие слова","cases":[{"buggyText":"我是学生也。","context":"«Я тоже студент»","options":["我也是学生。","也我是学生。","我是也学生。"],"correct":0},{"buggyText":"我们走吗。","context":"«Давайте пойдём»","options":["我们走吧。","我们吧走。","吧我们走。"],"correct":0},{"buggyText":"看下一。","context":"«Взгляни разок»","options":["一下看。","看一下。","一看下。"],"correct":1}]}'),
  ('hsk2-01-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как читается 一下?","options":["yíxià","yìxià","yīxià"],"correct":0},{"q":"Как предложить «Давайте пойдём»?","options":["我们去吗。","我们去吧。","去吧我们。"],"correct":1},{"q":"一下 ставится после глагола.","tf":true},{"q":"Как спросить разрешение «Можно мне сесть?»","options":["我坐可以吗？","我可以坐吗？","可以我坐吗？"],"correct":1},{"q":"Что значит 吧 в конце фразы?","options":["мягкое предложение","вопрос","отрицание"],"correct":0}]}'),
  ('hsk2-01-3', 1, 'fact', '{"emoji":"🔁","title":"«Нет» плюс «обычно» даёт «очень»","text":"Слово 非常 fēicháng сложено из 非 «не» и 常 «обычный»: «необычный», то есть «очень». Оно звучит сильнее, чем 很. А 再 zài «снова» вы знаете по 再见 «ещё раз увидимся». Только 再 говорят про будущее: 再说一下 «скажите ещё раз»."}'),
  ('hsk2-01-3', 2, 'words', '{"title":"Два слова","items":[{"hanzi":"非常","pinyin":"fēicháng","m":"очень, крайне","emoji":"💯","ex":{"zh":"非常好！","py":"Fēicháng hǎo!","m":"Очень хорошо!"}},{"hanzi":"再","pinyin":"zài","m":"снова, ещё раз","emoji":"🔄","ex":{"zh":"请再说一下。","py":"Qǐng zài shuō yíxià.","m":"Пожалуйста, скажите ещё раз."}}]}'),
  ('hsk2-01-3', 3, 'game', '{"type":"listen","title":"Слушаем: очень и снова","items":[{"say":"非常","options":["fēicháng","fēichàng","féicháng"],"correct":0},{"say":"再","options":["zǎi","zài","zāi"],"correct":1},{"say":"非常好","options":["fēicháng hǎo","fēicháng hào"],"correct":0},{"say":"请再说一下","options":["qǐng zài shuō yíxià","qǐng zài shuō yìxià"],"correct":0},{"say":"欢迎你们","options":["huānyíng nǐmen","huānyíng nǐ"],"correct":0}]}'),
  ('hsk2-01-3', 4, 'game', '{"type":"tone_visualizer","initialTone":1,"title":"Тренажёр голоса: повторите «fēi» (1 тон)"}'),
  ('hsk2-01-3', 5, 'theory', '{"title":"非常 или 很","blocks":[{"t":"table","head":["Слово","Сила","Пример"],"rows":[["很","обычная степень","很好 — хорошо"],["非常","очень сильно","非常好 — отлично"],["太…了","слишком, эмоция","太好了！"]]},{"t":"p","text":"非常 ставится перед прилагательным: 非常高兴, 非常漂亮. С 再 просят повторить: 请再说一下 «скажите ещё раз»."},{"t":"tip","text":"再 про будущее: 明天再来. Для прошлого говорят другое слово, вы выучите его позже."}]}'),
  ('hsk2-01-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"💯","options":["再","非常","也"],"correct":1},{"emoji":"🔄","options":["再","非常","吧"],"correct":0}]}'),
  ('hsk2-01-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["非常","очень"],["再","снова"],["非常好","отлично"],["再说一下","скажите ещё раз"],["明天再来","приходите ещё завтра"]]}'),
  ('hsk2-01-3', 8, 'game', '{"type":"chatsim","title":"WeChat: встреча гостей","messages":[{"speaker":"Гость","text":"欢迎，欢迎！","pinyin":"Huānyíng, huānyíng!","translation":"Добро пожаловать!","options":["谢谢！非常高兴。","对不起，再见。","不客气，请坐。"],"correct":0},{"speaker":"Гость","text":"你姓什么？","pinyin":"Nǐ xìng shénme?","translation":"Какая у вас фамилия?","options":["我姓安。","我是姓安。","我叫姓安。"],"correct":0},{"speaker":"Гость","text":"请再说一下。","pinyin":"Qǐng zài shuō yíxià.","translation":"Повторите, пожалуйста.","options":["我姓安，叫安娜。","我不说。","再见。"],"correct":0}]}'),
  ('hsk2-01-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["非常","高兴"],"hint":"«Очень рад.»"},{"answer":["请","再","说","一下"],"hint":"«Повторите, пожалуйста.»"},{"answer":["明天","再","来"],"hint":"«Приходите ещё завтра.»"}]}'),
  ('hsk2-01-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 非常?","options":["очень","снова","тоже"],"correct":0},{"q":"Как читается 再?","options":["zài","zǎi","zāi"],"correct":0},{"q":"非常 слабее, чем 很.","tf":false,"explain":"非常 сильнее."},{"q":"Как попросить повторить?","options":["请再说一下。","请说再一下。","再请说一下。"],"correct":0},{"q":"Что значит 非常好?","options":["отлично","нехорошо","не очень"],"correct":0}]}'),
  ('hsk2-01-4', 1, 'fact', '{"emoji":"🎈","title":"Знакомство гостей","text":"Анна принимает гостей и представляет друг друга. В диалоге встретятся 姓, 介绍, 欢迎, 大家, 也, 一下, 吧, 非常, 再."}'),
  ('hsk2-01-4', 2, 'text', '{"title":"Вечеринка","lines":[{"zh":"安娜：大家好！欢迎来我家！","py":"Ānnà: Dàjiā hǎo! Huānyíng lái wǒ jiā!","m":"Анна: Всем привет! Добро пожаловать ко мне!"},{"zh":"安娜：我介绍一下，这是李明，我的同学。","py":"Ānnà: Wǒ jièshào yíxià, zhè shì Lǐ Míng, wǒ de tóngxué.","m":"Анна: Представлю: это Ли Мин, мой одноклассник."},{"zh":"李明：大家好！我姓李，叫李明。","py":"Lǐ Míng: Dàjiā hǎo! Wǒ xìng Lǐ, jiào Lǐ Míng.","m":"Ли Мин: Всем привет! Моя фамилия Ли, меня зовут Ли Мин."},{"zh":"王老师：你好！我姓王。你也是学生吗？","py":"Wáng lǎoshī: Nǐ hǎo! Wǒ xìng Wáng. Nǐ yě shì xuésheng ma?","m":"Учитель Ван: Здравствуй! Моя фамилия Ван. Ты тоже студент?"},{"zh":"李明：是，我也学习汉语。","py":"Lǐ Míng: Shì, wǒ yě xuéxí Hànyǔ.","m":"Ли Мин: Да, я тоже изучаю китайский."},{"zh":"王老师：非常好！我们说汉语吧。","py":"Wáng lǎoshī: Fēicháng hǎo! Wǒmen shuō Hànyǔ ba.","m":"Учитель Ван: Прекрасно! Давайте говорить по-китайски."},{"zh":"李明：好，请再说一下。","py":"Lǐ Míng: Hǎo, qǐng zài shuō yíxià.","m":"Ли Мин: Хорошо, повторите, пожалуйста."},{"zh":"王老师：欢迎你！","py":"Wáng lǎoshī: Huānyíng nǐ!","m":"Учитель Ван: Добро пожаловать!"}],"qs":[{"q":"Кого представляет Анна?","options":["Ли Мина","учителя Вана","саму себя"],"correct":0},{"q":"Какая фамилия у учителя?","options":["Ли","Ван","Ань"],"correct":1},{"q":"Ли Мин тоже изучает китайский.","tf":true},{"q":"Что предлагает учитель?","options":["говорить по-китайски","уйти домой","сесть за стол"],"correct":0},{"q":"Ли Мин просит учителя замолчать.","tf":false,"explain":"Он просит повторить: 请再说一下."},{"q":"Вставьте слово: 你___是学生吗？","options":["也","吧","再"],"correct":0},{"q":"Как учитель оценивает ответ Ли Мина?","options":["很好","非常好","不好"],"correct":1}]}'),
  ('hsk2-01-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["我介绍一下","позвольте представить"],["我姓李","моя фамилия Ли"],["我也学习汉语","я тоже изучаю китайский"],["我们说汉语吧","давайте говорить по-китайски"],["请再说一下","повторите, пожалуйста"]]}'),
  ('hsk2-01-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"欢迎来我家","options":["huānyíng lái wǒ jiā","huānyíng qù wǒ jiā"],"correct":0},{"say":"我介绍一下","options":["wǒ jièshào yíxià","wǒ jièshào yìxià"],"correct":0},{"say":"你也是学生吗","options":["nǐ yě shì xuésheng ma","nǐ dōu shì xuésheng ma"],"correct":0},{"say":"我们说汉语吧","options":["wǒmen shuō Hànyǔ ba","wǒmen shuō Hànyǔ ma"],"correct":0}]}'),
  ('hsk2-01-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: вечеринка","cases":[{"buggyText":"我介绍下一。","context":"«Позвольте представить»","options":["我介绍一下。","我一下介绍。","一下我介绍。"],"correct":0},{"buggyText":"我是姓李。","context":"«Моя фамилия Ли»","options":["我姓李。","我姓是李。","姓我李。"],"correct":0},{"buggyText":"我们说汉语吗。","context":"«Давайте говорить по-китайски»","options":["我们汉语说吧。","我们说汉语吧。","说我们汉语吧。"],"correct":1}]}'),
  ('hsk2-01-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я тоже изучаю китайский»?","options":["我也学习汉语。","我学习汉语也。","也我学习汉语。"],"correct":0},{"q":"Как читается 非常?","options":["fēicháng","féicháng","fēichàng"],"correct":0},{"q":"王 — это фамилия учителя.","tf":true}]}'),
  ('hsk2-01-5', 1, 'fact', '{"emoji":"🥂","title":"Организуйте вечеринку","text":"Вы приглашаете гостей, представляете их друг другу и просите повторить. Только слова из HSK 1 и первой главы HSK 2."}'),
  ('hsk2-01-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"姓","correctRadicals":["女","生"],"title":"Пазл: соберите 姓"}'),
  ('hsk2-01-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"迎","radicals":["辶","卬","亻"],"correctOrder":["辶","卬"],"explain":"Слева 辶 «ходьба», справа 卬."},{"targetHanzi":"欢","radicals":["又","欠","木"],"correctOrder":["又","欠"],"explain":"Слева 又, справа 欠."},{"targetHanzi":"绍","radicals":["纟","召","口"],"correctOrder":["纟","召"],"explain":"Слева 纟 «нить», справа 召."}]}'),
  ('hsk2-01-5', 4, 'game', '{"type":"build","title":"Мастерская приглашений","items":[{"target":"(Приглашение)","answer":["欢迎","大家","来","我","家"],"hint":"«Все, добро пожаловать ко мне!»"},{"target":"(Знакомство)","answer":["我","介绍","一下","我","的","朋友"],"hint":"«Позвольте представить моего друга.»"},{"target":"(Просьба)","answer":["请","再","说","一下"],"hint":"«Повторите, пожалуйста.»"},{"target":"(Предложение)","answer":["我们","说","汉语","吧"],"hint":"«Давайте говорить по-китайски.»"}]}'),
  ('hsk2-01-5', 5, 'theory', '{"title":"Образец приветствия хозяина","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["1. Приветствие","大家好！"],["2. Гости","欢迎，欢迎！"],["3. Знакомство","我介绍一下……"],["4. Предложение","我们说汉语吧。"]]}]}'),
  ('hsk2-01-5', 6, 'game', '{"type":"chatsim","title":"WeChat: приём гостей","messages":[{"speaker":"Гость","text":"你好！我姓王。","pinyin":"Nǐ hǎo! Wǒ xìng Wáng.","translation":"Здравствуйте! Моя фамилия Ван.","options":["欢迎！我姓安。","再见。","不客气。"],"correct":0},{"speaker":"Гость","text":"你也学习汉语吗？","pinyin":"Nǐ yě xuéxí Hànyǔ ma?","translation":"Ты тоже изучаешь китайский?","options":["是，我也学习汉语。","不是，我汉语也。","我是汉语吗。"],"correct":0},{"speaker":"Гость","text":"我们说汉语吧！","pinyin":"Wǒmen shuō Hànyǔ ba!","translation":"Давайте говорить по-китайски!","options":["好！非常好！","对不起。","再见。"],"correct":0}]}'),
  ('hsk2-01-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["女 + 生","姓"],["辶 + 卬","迎"],["又 + 欠","欢"],["纟 + 召","绍"]]}'),
  ('hsk2-01-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"也","pinyin":"yě","m":"тоже","hint":"три черты: сверху изгиб, вертикаль, крючок"},{"hanzi":"吧","pinyin":"ba","m":"частица","hint":"слева 口, справа 巴"},{"hanzi":"再","pinyin":"zài","m":"снова","hint":"горизонталь, рамка, внутри 土"}]}'),
  ('hsk2-01-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как пригласить гостей?","options":["欢迎大家！","再见大家！","谢谢大家吗！"],"correct":0},{"q":"Из каких частей состоит 姓?","options":["女 и 生","亻 и 也","口 и 巴"],"correct":0},{"q":"Для мягкого предложения используют 吧.","tf":true}]}'),
  ('hsk2-01-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 1 (HSK 2)","text":"姓, 介绍, 欢迎, 大家, 也, 一下, 吧, 可以, 非常 и 再. Не набрали проходной балл — повторите уроки."}'),
  ('hsk2-01-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"我姓王","options":["wǒ xìng Wáng","wǒ jiào Wáng","wǒ shì Wáng"],"correct":0},{"say":"欢迎你","options":["huānyíng nǐ","huānyíng nǐmen"],"correct":0},{"say":"我也是学生","options":["wǒ yě shì xuésheng","wǒ dōu shì xuésheng"],"correct":0},{"say":"介绍一下","options":["jièshào yìxià","jièshào yíxià"],"correct":1},{"say":"我们走吧","options":["wǒmen zǒu ba","wǒmen zǒu ma"],"correct":0},{"say":"非常好","options":["fēicháng hǎo","fēicháng hào"],"correct":0}]}'),
  ('hsk2-01-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🪪","options":["姓","介绍","欢迎"],"correct":0},{"emoji":"🎉","options":["大家","欢迎","也"],"correct":1},{"emoji":"➕","options":["吧","也","再"],"correct":1},{"emoji":"🔄","options":["再","可以","吧"],"correct":0}]}'),
  ('hsk2-01-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["姓","фамилия"],["介绍","представлять"],["欢迎","добро пожаловать"],["大家","все"],["也","тоже"],["一下","разок"],["吧","предложение"],["可以","можно"],["非常","очень"],["再","снова"]]}'),
  ('hsk2-01-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как спросить фамилию?","options":["你姓什么？","你什么姓？","你叫姓什么？"],"correct":0},{"q":"Как сказать «Я тоже студент»?","options":["我是学生也。","也我是学生。","我也是学生。"],"correct":2},{"q":"Как предложить «Давайте пойдём»?","options":["我们去吧。","我们去吗。","去我们吧。"],"correct":0},{"q":"也 ставится в конце фразы.","tf":false},{"q":"Как читается 一下?","options":["yìxià","yíxià","yīxià"],"correct":1},{"q":"Как попросить повторить?","options":["请再说一下。","请说再一下。","再请说下一。"],"correct":0},{"q":"非常 сильнее, чем 很.","tf":true},{"q":"Как спросить «Можно мне сесть?»","options":["我坐可以吗？","可以我坐吗？","我可以坐吗？"],"correct":2},{"q":"Что значит 大家?","options":["все","дом","семья"],"correct":0},{"q":"Как сказать «Позвольте представить»?","options":["我介绍一下。","我一下介绍。","介绍我一下。"],"correct":0}]}'),
  ('hsk2-01-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","姓","王"],"hint":"«Моя фамилия Ван.»"},{"answer":["我","也","是","学生"],"hint":"«Я тоже студент.»"},{"answer":["我们","说","汉语","吧"],"hint":"«Давайте говорить по-китайски.»"},{"answer":["请","再","说","一下"],"hint":"«Повторите, пожалуйста.»"}]}'),
  ('hsk2-01-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我是姓王。","context":"«Моя фамилия Ван»","options":["我姓王。","我王姓。","姓我王。"],"correct":0},{"buggyText":"我们走吗。","context":"«Давайте пойдём»","options":["我们走吧。","我们吧走。","吧我们走。"],"correct":0},{"buggyText":"我是学生也。","context":"«Я тоже студент»","options":["我是也学生。","我也是学生。","也我是学生。"],"correct":1}]}'),
  ('hsk2-01-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Гость","text":"你好！你姓什么？","pinyin":"Nǐ hǎo! Nǐ xìng shénme?","translation":"Здравствуйте! Какая у вас фамилия?","options":["我姓安。","我是姓安。","我叫姓安。"],"correct":0},{"speaker":"Гость","text":"我们说汉语吧！","pinyin":"Wǒmen shuō Hànyǔ ba!","translation":"Давайте говорить по-китайски!","options":["好，非常好！","对不起。","没有。"],"correct":0}]}'),
  ('hsk2-01-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"姓","pinyin":"xìng","m":"фамилия","hint":"女 + 生"},{"hanzi":"也","pinyin":"yě","m":"тоже","hint":"изгиб, вертикаль, крючок"},{"hanzi":"再","pinyin":"zài","m":"снова","hint":"рамка и 土"}]}'),
  ('hsk2-01-6', 10, 'recall', '{"words":[{"hanzi":"姓","pinyin":"xìng","m":"фамилия"},{"hanzi":"介绍","pinyin":"jièshào","m":"представлять"},{"hanzi":"欢迎","pinyin":"huānyíng","m":"добро пожаловать"},{"hanzi":"大家","pinyin":"dàjiā","m":"все"},{"hanzi":"也","pinyin":"yě","m":"тоже"},{"hanzi":"一下","pinyin":"yíxià","m":"разок"},{"hanzi":"吧","pinyin":"ba","m":"предложение"},{"hanzi":"可以","pinyin":"kěyǐ","m":"можно"},{"hanzi":"非常","pinyin":"fēicháng","m":"очень"},{"hanzi":"再","pinyin":"zài","m":"снова"}],"tf":[{"zh":"我是学生也。","py":"wǒ shì xuésheng yě.","m":"Я тоже студент.","ok":false,"explain":"也 стоит перед глаголом."},{"zh":"我们走吧。","py":"wǒmen zǒu ba.","m":"Давайте пойдём.","ok":true}],"sentences":[{"zh":"我姓王。","tokens":["我","姓","王"],"m":"Моя фамилия Ван."},{"zh":"我也是学生。","tokens":["我","也","是","学生"],"m":"Я тоже студент."},{"zh":"请再说一下。","tokens":["请","再","说","一下"],"m":"Повторите, пожалуйста."}]}'),
  ('hsk2-02-1', 1, 'fact', '{"emoji":"👨‍👩‍👧‍👦","title":"В китайском нет просто «брата»","text":"Китайский обязательно уточняет, старший или младший: 哥哥 gēge — старший брат, 弟弟 dìdi — младший брат, 姐姐 jiějie — старшая сестра, 妹妹 mèimei — младшая сестра. Слоги удваиваются, как в 爸爸 и 妈妈, и второй слог звучит коротко. Для китайца возраст внутри семьи важен: от него зависит, как обращаться."}'),
  ('hsk2-02-1', 2, 'words', '{"title":"Четыре родственника","items":[{"hanzi":"哥哥","pinyin":"gēge","m":"старший брат","emoji":"👦","ex":{"zh":"我有一个哥哥。","py":"Wǒ yǒu yí gè gēge.","m":"У меня есть старший брат."}},{"hanzi":"弟弟","pinyin":"dìdi","m":"младший брат","emoji":"🧒","ex":{"zh":"我弟弟很小。","py":"Wǒ dìdi hěn xiǎo.","m":"Мой младший брат маленький."}},{"hanzi":"姐姐","pinyin":"jiějie","m":"старшая сестра","emoji":"👩","ex":{"zh":"我姐姐是医生。","py":"Wǒ jiějie shì yīshēng.","m":"Моя старшая сестра врач."}},{"hanzi":"妹妹","pinyin":"mèimei","m":"младшая сестра","emoji":"👧","ex":{"zh":"我妹妹十岁。","py":"Wǒ mèimei shí suì.","m":"Моей младшей сестре десять."}}]}'),
  ('hsk2-02-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"👦","options":["弟弟","哥哥","妹妹"],"correct":1},{"emoji":"🧒","options":["弟弟","姐姐","哥哥"],"correct":0},{"emoji":"👩","options":["妹妹","哥哥","姐姐"],"correct":2},{"emoji":"👧","options":["妹妹","姐姐","弟弟"],"correct":0}]}'),
  ('hsk2-02-1', 4, 'theory', '{"title":"Как говорят о братьях и сёстрах","blocks":[{"t":"table","head":["Слово","Старше / младше","Тоны"],"rows":[["哥哥 gēge","старший брат","1 + нейтральный"],["姐姐 jiějie","старшая сестра","3 + нейтральный"],["弟弟 dìdi","младший брат","4 + нейтральный"],["妹妹 mèimei","младшая сестра","4 + нейтральный"]]},{"t":"p","text":"Притяжательное 的 с ними не нужно: 我哥哥, 我妹妹. Для вопроса «у тебя есть сестра?»: 你有姐姐吗？"},{"t":"tip","text":"Знак 哥 состоит из двух 可: «два одобрения». Знак 姐 содержит 女, а 妹 тоже: женские родственницы."}]}'),
  ('hsk2-02-1', 5, 'quiz', '{"title":"Мини-тест: родственники","qs":[{"q":"Как сказать «старший брат»?","options":["弟弟","哥哥","妹妹"],"correct":1},{"q":"Как сказать «младшая сестра»?","options":["妹妹","姐姐","哥哥"],"correct":0},{"q":"哥哥 — это младший брат.","tf":false,"explain":"哥哥 — старший брат."}]}'),
  ('hsk2-02-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["哥哥","старший брат"],["弟弟","младший брат"],["姐姐","старшая сестра"],["妹妹","младшая сестра"],["我哥哥","мой старший брат"]]}'),
  ('hsk2-02-1', 7, 'game', '{"type":"listen","title":"Слушаем семью","items":[{"say":"哥哥","options":["gēge","gēgē","gégé"],"correct":0},{"say":"弟弟","options":["dídi","dìdi","dǐdi"],"correct":1},{"say":"姐姐","options":["jiějie","jièjie","jiéjie"],"correct":0},{"say":"妹妹","options":["mèimei","méimei","měimei"],"correct":0},{"say":"我有一个哥哥","options":["wǒ yǒu yí gè gēge","wǒ yǒu yí gè dìdi"],"correct":0}]}'),
  ('hsk2-02-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","有","一个","哥哥"],"hint":"«У меня есть старший брат.»"},{"answer":["我","妹妹","十","岁"],"hint":"«Моей младшей сестре десять лет.»"},{"answer":["我","姐姐","是","医生"],"hint":"«Моя старшая сестра врач.»"}]}'),
  ('hsk2-02-1', 9, 'write', '{"title":"Пропись: родственники","items":[{"hanzi":"哥","pinyin":"gē","m":"старший брат","hint":"сверху 可 и 可"},{"hanzi":"弟","pinyin":"dì","m":"младший брат","hint":"сверху 丷, ниже 弓 и штрих"},{"hanzi":"姐","pinyin":"jiě","m":"старшая сестра","hint":"слева 女, справа 且"},{"hanzi":"妹","pinyin":"mèi","m":"младшая сестра","hint":"слева 女, справа 未"}]}'),
  ('hsk2-02-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 姐姐?","options":["старшая сестра","младшая сестра","мама"],"correct":0},{"q":"Как читается 弟弟?","options":["dídi","dǐdi","dìdi"],"correct":2},{"q":"Как сказать «У меня есть младшая сестра»?","options":["我有一个妹妹。","我妹妹有一个。","有我妹妹一个。"],"correct":0},{"q":"Второй слог в 哥哥 безударный.","tf":true},{"q":"Какой ключ в знаке 妹?","options":["亻","女","口"],"correct":1}]}'),
  ('hsk2-02-2', 1, 'fact', '{"emoji":"🚸","title":"Иероглифы, которые рисуют пол","text":"男 «мужской» состоит из 田 «поле» и 力 «сила»: мужчина работает в поле. 女 «женский» нарисован как женщина со скрещёнными руками. Слово 孩子 «ребёнок» — это 子 «дитя» и 亥. А слова 男孩子 и 女孩子 — «мальчик» и «девочка»."}'),
  ('hsk2-02-2', 2, 'words', '{"title":"Пол и дети","items":[{"hanzi":"男","pinyin":"nán","m":"мужской, мужчина","emoji":"👨","ex":{"zh":"他是男老师。","py":"Tā shì nán lǎoshī.","m":"Он учитель-мужчина."}},{"hanzi":"女","pinyin":"nǚ","m":"женский, женщина","emoji":"👩","ex":{"zh":"她是女医生。","py":"Tā shì nǚ yīshēng.","m":"Она женщина-врач."}},{"hanzi":"孩子","pinyin":"háizi","m":"ребёнок, дети","emoji":"🧒","ex":{"zh":"我有两个孩子。","py":"Wǒ yǒu liǎng gè háizi.","m":"У меня двое детей."}}]}'),
  ('hsk2-02-2', 3, 'theory', '{"title":"Мужчина, женщина, ребёнок","blocks":[{"t":"table","head":["Слово","Смысл"],"rows":[["男孩子","мальчик"],["女孩子","девочка"],["男老师","учитель-мужчина"],["女医生","женщина-врач"]]},{"t":"p","text":"男 и 女 ставятся ПЕРЕД словом: 男老师, 女学生. Слово 孩子 принимает и 男, и 女: 男孩子, 女孩子. 们 здесь допустимо: 孩子们 «дети»."},{"t":"tip","text":"男, 女 произносятся: nán, nǚ. Второй слог в 孩子 — безударный: háizi."}]}'),
  ('hsk2-02-2', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["他","是","男","孩子"],"hint":"«Он мальчик.»"},{"answer":["她","是","女","孩子"],"hint":"«Она девочка.»"},{"answer":["我","有","一个","孩子"],"hint":"«У меня есть ребёнок.»"}]}'),
  ('hsk2-02-2', 5, 'quiz', '{"title":"Мини-тест: пол","qs":[{"q":"Как сказать «девочка»?","options":["男孩子","女孩子","孩子女"],"correct":1},{"q":"男 ставится после слова, к которому относится.","tf":false,"explain":"Он стоит перед словом."},{"q":"Как читается 女?","options":["nǚ","nù","nǔ"],"correct":0}]}'),
  ('hsk2-02-2', 6, 'theory', '{"title":"孩子 в вопросах и ответах","blocks":[{"t":"table","head":["Вопрос","Ответ"],"rows":[["你有孩子吗？","有，我有一个孩子。"],["你的孩子几岁？","他五岁。"],["他是男孩子还是女孩子？","他是男孩子。"]]},{"t":"p","text":"Вопрос с выбором строится со словом 还是 «или»; оно появится позже, пока можно спрашивать две фразы подряд."},{"t":"ex","zh":"你有孩子吗？","py":"Nǐ yǒu háizi ma?","m":"У тебя есть дети?","say":"你有孩子吗"}]}'),
  ('hsk2-02-2', 7, 'game', '{"type":"listen","title":"Слушаем: мальчик, девочка, дети","items":[{"say":"男","options":["nán","nǎn","nàn"],"correct":0},{"say":"女","options":["nǚ","nǔ","nù"],"correct":0},{"say":"孩子","options":["háizi","hǎizi","hàizi"],"correct":0},{"say":"男孩子","options":["nán háizi","nǚ háizi"],"correct":0},{"say":"我有一个孩子","options":["wǒ yǒu yí gè háizi","wǒ yǒu yí gè gēge"],"correct":0}]}'),
  ('hsk2-02-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["男","мужской"],["女","женский"],["孩子","ребёнок"],["男孩子","мальчик"],["女孩子","девочка"]]}'),
  ('hsk2-02-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: пол и дети","cases":[{"buggyText":"孩子男","context":"«Мальчик»","options":["孩子男","男孩子","男子孩"],"correct":1},{"buggyText":"我有孩子一个。","context":"«У меня есть ребёнок»","options":["我有孩子一个。","我有一孩子个。","我有一个孩子。"],"correct":2},{"buggyText":"她是孩子女。","context":"«Она девочка»","options":["她是女孩子。","她是孩子女。","她女是孩子。"],"correct":0}]}'),
  ('hsk2-02-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 孩子?","options":["ребёнок","муж","жена"],"correct":0},{"q":"Как сказать «женщина-врач»?","options":["医生女","女医生","医女生"],"correct":1},{"q":"男 состоит из 田 и 力.","tf":true},{"q":"Как читается 孩子?","options":["hǎizi","háizi","hàizi"],"correct":1},{"q":"Как спросить «У тебя есть дети?»","options":["你有孩子吗？","你孩子有吗？","有你孩子吗？"],"correct":0}]}'),
  ('hsk2-02-3', 1, 'fact', '{"emoji":"💍","title":"Три слова про близких","text":"丈夫 zhàngfu «муж» и 妻子 qīzi «жена» — формальные слова: так говорят о чужой семье или в документах. Дома говорят по-другому, но эти слова нужны. А 它 tā «оно» (для животных и вещей) читается так же, как 他 и 她, но пишется со знаком 宀: оно «под крышей»."}'),
  ('hsk2-02-3', 2, 'words', '{"title":"Муж, жена, оно","items":[{"hanzi":"丈夫","pinyin":"zhàngfu","m":"муж","emoji":"🤵","ex":{"zh":"她丈夫是医生。","py":"Tā zhàngfu shì yīshēng.","m":"Её муж врач."}},{"hanzi":"妻子","pinyin":"qīzi","m":"жена","emoji":"👰","ex":{"zh":"他妻子是老师。","py":"Tā qīzi shì lǎoshī.","m":"Его жена учитель."}},{"hanzi":"它","pinyin":"tā","m":"оно, он, она (о предметах и животных)","emoji":"🐾","ex":{"zh":"它是我的猫。","py":"Tā shì wǒ de māo.","m":"Это моя кошка."}}]}'),
  ('hsk2-02-3', 3, 'game', '{"type":"listen","title":"Слушаем: муж, жена, оно","items":[{"say":"丈夫","options":["zhàngfu","zhāngfu","zhàngfù"],"correct":0},{"say":"妻子","options":["qīzi","qízi","qǐzi"],"correct":0},{"say":"它","options":["tā","tá","tǎ"],"correct":0},{"say":"他妻子是老师","options":["tā qīzi shì lǎoshī","tā zhàngfu shì lǎoshī"],"correct":0},{"say":"它很漂亮","options":["tā hěn piàoliang","tā hěn dà"],"correct":0}]}'),
  ('hsk2-02-3', 4, 'game', '{"type":"tone_visualizer","initialTone":4,"title":"Тренажёр голоса: повторите «zhàng» (4 тон)"}'),
  ('hsk2-02-3', 5, 'theory', '{"title":"Три местоимения «он»","blocks":[{"t":"table","head":["Знак","Для кого","Читается"],"rows":[["他","мужчина","tā"],["她","женщина","tā"],["它","животное, вещь","tā"]]},{"t":"p","text":"Все три знака читаются одинаково, поэтому на слух вы различаете их по контексту. На письме ключи помогают: 亻 у 他 «человек», 女 у 她 «женщина», 宀 у 它 «крыша»."},{"t":"tip","text":"О чужих мужьях и жёнах говорят 她丈夫 и 他妻子. Родным говорят иначе: вы услышите это в следующих уроках."}]}'),
  ('hsk2-02-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🤵","options":["妻子","丈夫","哥哥"],"correct":1},{"emoji":"👰","options":["妻子","姐姐","女"],"correct":0},{"emoji":"🐾","options":["他","她","它"],"correct":2}]}'),
  ('hsk2-02-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["丈夫","муж"],["妻子","жена"],["它","оно (животное, вещь)"],["他","он"],["她","она"]]}'),
  ('hsk2-02-3', 8, 'game', '{"type":"chatsim","title":"WeChat: о семье","messages":[{"speaker":"Друг","text":"你有孩子吗？","pinyin":"Nǐ yǒu háizi ma?","translation":"У тебя есть дети?","options":["有，我有一个孩子。","有，我孩子一个。","不是，我是孩子。"],"correct":0},{"speaker":"Друг","text":"你妻子是老师吗？","pinyin":"Nǐ qīzi shì lǎoshī ma?","translation":"Твоя жена учитель?","options":["是，她是老师。","不是，她是老师。","没有，她老师。"],"correct":0},{"speaker":"Друг","text":"你家有狗吗？","pinyin":"Nǐ jiā yǒu gǒu ma?","translation":"У вас дома есть собака?","options":["有，它很小。","有，他很小。","没有，她很小。"],"correct":0,"explain":"Для собаки — 它."}]}'),
  ('hsk2-02-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["她","丈夫","是","医生"],"hint":"«Её муж врач.»"},{"answer":["他","妻子","是","老师"],"hint":"«Его жена учитель.»"},{"answer":["它","是","我","的","猫"],"hint":"«Это моя кошка.»"}]}'),
  ('hsk2-02-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 丈夫?","options":["жена","муж","ребёнок"],"correct":1},{"q":"Как читается 妻子?","options":["qīzi","qǐzi","qízi"],"correct":0},{"q":"Какое слово подходит для собаки?","options":["他","她","它"],"correct":2},{"q":"它 читается иначе, чем 他.","tf":false,"explain":"Все читаются tā."},{"q":"Какая часть в знаке 它?","options":["宀","亻","女"],"correct":0}]}'),
  ('hsk2-02-4', 1, 'fact', '{"emoji":"👨‍👩‍👦","title":"Анна расспрашивает о семье","text":"В диалоге встретятся братья, сёстры, дети и домашние животные. Слова главы 2 и всего HSK 1."}'),
  ('hsk2-02-4', 2, 'text', '{"title":"Семья Ли Мина","lines":[{"zh":"安娜：李明，你有哥哥吗？","py":"Ānnà: Lǐ Míng, nǐ yǒu gēge ma?","m":"Анна: Ли Мин, у тебя есть старший брат?"},{"zh":"李明：有，我有一个哥哥，也有一个妹妹。","py":"Lǐ Míng: Yǒu, wǒ yǒu yí gè gēge, yě yǒu yí gè mèimei.","m":"Ли Мин: Да, у меня старший брат и младшая сестра."},{"zh":"安娜：你哥哥几岁？","py":"Ānnà: Nǐ gēge jǐ suì?","m":"Анна: Сколько лет твоему брату?"},{"zh":"李明：他二十五岁。他是医生。","py":"Lǐ Míng: Tā èrshíwǔ suì. Tā shì yīshēng.","m":"Ли Мин: Ему 25. Он врач."},{"zh":"安娜：你妹妹呢？","py":"Ānnà: Nǐ mèimei ne?","m":"Анна: А сестра?"},{"zh":"李明：她十岁，她是学生。","py":"Lǐ Míng: Tā shí suì, tā shì xuésheng.","m":"Ли Мин: Ей десять, она школьница."},{"zh":"安娜：你家有狗吗？","py":"Ānnà: Nǐ jiā yǒu gǒu ma?","m":"Анна: У вас дома есть собака?"},{"zh":"李明：有。它很小，很漂亮。","py":"Lǐ Míng: Yǒu. Tā hěn xiǎo, hěn piàoliang.","m":"Ли Мин: Да. Она маленькая и красивая."}],"qs":[{"q":"Кто старше в семье Ли Мина?","options":["сестра","брат","Ли Мин"],"correct":1},{"q":"Брат Ли Мина врач.","tf":true},{"q":"Сколько лет сестре?","options":["5","10","25"],"correct":1},{"q":"Вставьте слово: 他二十五___。","options":["个","岁","本"],"correct":1},{"q":"У Ли Мина нет собаки.","tf":false,"explain":"Он говорит 有."},{"q":"Как Ли Мин называет собаку?","options":["他","她","它"],"correct":2},{"q":"Кто школьница?","options":["сестра","брат","Анна"],"correct":0}]}'),
  ('hsk2-02-4', 3, 'game', '{"type":"match","title":"Кто есть кто","pairs":[["哥哥","старший брат"],["妹妹","младшая сестра"],["医生","врач"],["学生","школьник"],["它","оно (собака)"]]}'),
  ('hsk2-02-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你有哥哥吗","options":["nǐ yǒu gēge ma","nǐ yǒu dìdi ma"],"correct":0},{"say":"他二十五岁","options":["tā èrshíwǔ suì","tā èrshí suì"],"correct":0},{"say":"她十岁","options":["tā shí suì","tā shíyī suì"],"correct":0},{"say":"它很小","options":["tā hěn xiǎo","tā hěn dà"],"correct":0}]}'),
  ('hsk2-02-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: о семье","cases":[{"buggyText":"我有一个哥哥也。","context":"«У меня тоже есть брат»","options":["我也有一个哥哥。","我有一个也哥哥。","也我有一个哥哥。"],"correct":0},{"buggyText":"他是二十五岁。","context":"«Ему 25»","options":["他二十五岁。","他二十五个。","他岁二十五。"],"correct":0},{"buggyText":"她很小，他很漂亮。","context":"О собаке","options":["它很小，它很漂亮。","她很小，她很漂亮。","他很小，他很漂亮。"],"correct":0}]}'),
  ('hsk2-02-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Моему брату 25 лет»?","options":["我哥哥二十五岁。","我哥哥是二十五。","我二十五哥哥岁。"],"correct":0},{"q":"Как читается 妹妹?","options":["mèimei","méimei","měimei"],"correct":0},{"q":"Анна спрашивает Ли Мина о семье.","tf":true}]}'),
  ('hsk2-02-5', 1, 'fact', '{"emoji":"🌳","title":"Нарисуйте семью","text":"Расскажите, кто есть кто в вашей семье, сколько кому лет и кто чем занят. Слова глав 1–2 HSK 2."}'),
  ('hsk2-02-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"妹","correctRadicals":["女","未"],"title":"Пазл: соберите 妹"}'),
  ('hsk2-02-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"姐","radicals":["女","且","亻"],"correctOrder":["女","且"],"explain":"Слева 女, справа 且."},{"targetHanzi":"哥","radicals":["可","可","口"],"correctOrder":["可","可"],"explain":"Два 可 друг над другом."},{"targetHanzi":"孩","radicals":["子","亥","女"],"correctOrder":["子","亥"],"explain":"Слева 子, справа 亥."}]}'),
  ('hsk2-02-5', 4, 'game', '{"type":"build","title":"Мастерская семьи","items":[{"target":"(Семья)","answer":["我","有","一个","哥哥","和","一个","妹妹"],"hint":"«У меня старший брат и младшая сестра.»"},{"target":"(Возраст)","answer":["我","哥哥","二十五","岁"],"hint":"«Моему брату 25 лет.»"},{"target":"(Профессия)","answer":["我","姐姐","是","医生"],"hint":"«Моя старшая сестра врач.»"},{"target":"(Питомец)","answer":["它","是","我","的","猫"],"hint":"«Это моя кошка.»"}]}'),
  ('hsk2-02-5', 5, 'theory', '{"title":"Образец рассказа о семье","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["Кто","我有哥哥和妹妹。"],["Возраст","哥哥二十五岁。"],["Профессия","姐姐是医生。"],["Питомец","我有猫，它很小。"]]}]}'),
  ('hsk2-02-5', 6, 'game', '{"type":"chatsim","title":"WeChat: расскажите о семье","messages":[{"speaker":"Друг","text":"你有哥哥吗？","pinyin":"Nǐ yǒu gēge ma?","translation":"У тебя есть старший брат?","options":["有，我有一个哥哥。","有，我哥哥一个。","没有，我哥哥。"],"correct":0},{"speaker":"Друг","text":"你妹妹几岁？","pinyin":"Nǐ mèimei jǐ suì?","translation":"Сколько лет твоей сестре?","options":["她十岁。","她十个。","她是十。"],"correct":0},{"speaker":"Друг","text":"你家有孩子吗？","pinyin":"Nǐ jiā yǒu háizi ma?","translation":"У вас дома есть дети?","options":["有，一个男孩子。","有，孩子男一个。","没有，我是孩子。"],"correct":0}]}'),
  ('hsk2-02-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["女 + 未","妹"],["女 + 且","姐"],["可 + 可","哥"],["子 + 亥","孩"]]}'),
  ('hsk2-02-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"男","pinyin":"nán","m":"мужской","hint":"сверху 田, снизу 力"},{"hanzi":"女","pinyin":"nǚ","m":"женский","hint":"три черты со скрещиванием"},{"hanzi":"孩","pinyin":"hái","m":"ребёнок","hint":"слева 子, справа 亥"}]}'),
  ('hsk2-02-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «У меня старший брат и младшая сестра»?","options":["我有哥哥和妹妹。","我哥哥有和妹妹。","我有和哥哥妹妹。"],"correct":0},{"q":"Какой знак состоит из 女 и 未?","options":["妹","姐","孩"],"correct":0},{"q":"Для животных используют 它.","tf":true}]}'),
  ('hsk2-02-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 2 (HSK 2)","text":"哥哥, 弟弟, 姐姐, 妹妹, 男, 女, 孩子, 丈夫, 妻子 и 它."}'),
  ('hsk2-02-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"哥哥","options":["gēge","dìdi","jiějie"],"correct":0},{"say":"妹妹","options":["jiějie","mèimei","dìdi"],"correct":1},{"say":"男孩子","options":["nán háizi","nǚ háizi"],"correct":0},{"say":"丈夫","options":["qīzi","zhàngfu"],"correct":1},{"say":"它很漂亮","options":["tā hěn piàoliang","tā hěn dà"],"correct":0},{"say":"我有一个孩子","options":["wǒ yǒu yí gè háizi","wǒ yǒu yí gè gēge"],"correct":0}]}'),
  ('hsk2-02-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"👦","options":["弟弟","哥哥","妹妹"],"correct":1},{"emoji":"👧","options":["姐姐","妹妹","孩子"],"correct":1},{"emoji":"🤵","options":["丈夫","妻子","男"],"correct":0},{"emoji":"🐾","options":["他","它","她"],"correct":1}]}'),
  ('hsk2-02-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["哥哥","старший брат"],["弟弟","младший брат"],["姐姐","старшая сестра"],["妹妹","младшая сестра"],["男","мужской"],["女","женский"],["孩子","ребёнок"],["丈夫","муж"],["妻子","жена"],["它","оно"]]}'),
  ('hsk2-02-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «старшая сестра»?","options":["妹妹","姐姐","弟弟"],"correct":1},{"q":"Как сказать «У меня есть младший брат»?","options":["我有一个弟弟。","我弟弟有一个。","有我弟弟一个。"],"correct":0},{"q":"Как читается 弟弟?","options":["dǐdi","dídi","dìdi"],"correct":2},{"q":"男孩子 — это девочка.","tf":false},{"q":"Как сказать «женщина-врач»?","options":["医女生","女医生","医生女"],"correct":1},{"q":"Какое слово для собаки?","options":["它","他","她"],"correct":0},{"q":"丈夫 — это «муж».","tf":true},{"q":"Как спросить «У тебя есть дети?»","options":["你有孩子吗？","你孩子有吗？","有你孩子吗？"],"correct":0},{"q":"Что значит 孩子?","options":["ребёнок","жена","брат"],"correct":0},{"q":"Как читается 妻子?","options":["qízi","qǐzi","qīzi"],"correct":2}]}'),
  ('hsk2-02-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","有","一个","哥哥"],"hint":"«У меня есть старший брат.»"},{"answer":["我","妹妹","十","岁"],"hint":"«Моей сестре десять лет.»"},{"answer":["他","妻子","是","老师"],"hint":"«Его жена учитель.»"},{"answer":["它","是","我","的","猫"],"hint":"«Это моя кошка.»"}]}'),
  ('hsk2-02-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我有孩子一个。","context":"«У меня есть ребёнок»","options":["我有一个孩子。","我有孩子一个。","有我一个孩子。"],"correct":0},{"buggyText":"孩子男","context":"«Мальчик»","options":["孩子男","男子孩","男孩子"],"correct":2},{"buggyText":"它很漂亮，她是我的猫。","context":"О кошке","options":["它很漂亮，它是我的猫。","她很漂亮，她是我的猫。","他很漂亮，他是我的猫。"],"correct":0}]}'),
  ('hsk2-02-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"你有哥哥吗？","pinyin":"Nǐ yǒu gēge ma?","translation":"У тебя есть старший брат?","options":["有，我有一个哥哥。","有，我哥哥一个。","没有，我是哥哥。"],"correct":0},{"speaker":"Друг","text":"你妹妹几岁？","pinyin":"Nǐ mèimei jǐ suì?","translation":"Сколько лет сестре?","options":["她十岁。","她十个。","她是十。"],"correct":0}]}'),
  ('hsk2-02-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"哥","pinyin":"gē","m":"старший брат","hint":"可 + 可"},{"hanzi":"女","pinyin":"nǚ","m":"женский","hint":"три черты"},{"hanzi":"孩","pinyin":"hái","m":"ребёнок","hint":"子 + 亥"}]}'),
  ('hsk2-02-6', 10, 'recall', '{"words":[{"hanzi":"哥哥","pinyin":"gēge","m":"старший брат"},{"hanzi":"弟弟","pinyin":"dìdi","m":"младший брат"},{"hanzi":"姐姐","pinyin":"jiějie","m":"старшая сестра"},{"hanzi":"妹妹","pinyin":"mèimei","m":"младшая сестра"},{"hanzi":"男","pinyin":"nán","m":"мужской"},{"hanzi":"女","pinyin":"nǚ","m":"женский"},{"hanzi":"孩子","pinyin":"háizi","m":"ребёнок"},{"hanzi":"丈夫","pinyin":"zhàngfu","m":"муж"},{"hanzi":"妻子","pinyin":"qīzi","m":"жена"},{"hanzi":"它","pinyin":"tā","m":"оно"}],"tf":[{"zh":"孩子男","py":"háizi nán","m":"Мальчик.","ok":false,"explain":"Правильно: 男孩子."},{"zh":"她丈夫是医生。","py":"tā zhàngfu shì yīshēng.","m":"Её муж врач.","ok":true}],"sentences":[{"zh":"我有一个哥哥。","tokens":["我","有","一个","哥哥"],"m":"У меня есть старший брат."},{"zh":"他妻子是老师。","tokens":["他","妻子","是","老师"],"m":"Его жена учитель."},{"zh":"它是我的猫。","tokens":["它","是","我","的","猫"],"m":"Это моя кошка."}]}'),
  ('hsk2-03-1', 1, 'fact', '{"emoji":"🎨","title":"Красный — удача, белый — траур","text":"В Китае красный 红 hóng — цвет счастья, свадьбы и Нового года: красные конверты, красные фонари. Белый 白 bái, наоборот, связан с трауром, поэтому белые цветы там не дарят. А чёрный 黑 hēi не имеет такого мрачного смысла и означает просто «чёрный». Слово 颜色 «цвет» состоит из 颜 «лицо» и 色 «цвет»."}'),
  ('hsk2-03-1', 2, 'words', '{"title":"Цвета","items":[{"hanzi":"白","pinyin":"bái","m":"белый","emoji":"⚪","ex":{"zh":"白米饭","py":"bái mǐfàn","m":"белый рис"}},{"hanzi":"黑","pinyin":"hēi","m":"чёрный","emoji":"⚫","ex":{"zh":"黑猫","py":"hēi māo","m":"чёрная кошка"}},{"hanzi":"红","pinyin":"hóng","m":"красный","emoji":"🔴","ex":{"zh":"红苹果","py":"hóng píngguǒ","m":"красное яблоко"}},{"hanzi":"颜色","pinyin":"yánsè","m":"цвет","emoji":"🎨","ex":{"zh":"你喜欢什么颜色？","py":"Nǐ xǐhuan shénme yánsè?","m":"Какой цвет тебе нравится?"}}]}'),
  ('hsk2-03-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🔴","options":["黑","红","白"],"correct":1},{"emoji":"⚪","options":["白","红","颜色"],"correct":0},{"emoji":"⚫","options":["红","颜色","黑"],"correct":2},{"emoji":"🎨","options":["颜色","白","黑"],"correct":0}]}'),
  ('hsk2-03-1', 4, 'theory', '{"title":"Цвет + предмет","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["红苹果","hóng píngguǒ","красное яблоко"],["黑猫","hēi māo","чёрная кошка"],["白米饭","bái mǐfàn","белый рис"]]},{"t":"p","text":"Цвет ставится перед предметом, как все прилагательные в китайском. Для короткого прилагательного 的 не нужно: 红苹果, а не 红的苹果."},{"t":"tip","text":"Спросить про любимый цвет: 你喜欢什么颜色？ Ответить: 我喜欢红。"}]}'),
  ('hsk2-03-1', 5, 'quiz', '{"title":"Мини-тест: цвета","qs":[{"q":"Как сказать «чёрная кошка»?","options":["猫黑","黑猫","黑的猫"],"correct":1},{"q":"В Китае красный цвет — цвет счастья.","tf":true},{"q":"Как спросить «Какой цвет тебе нравится?»","options":["你喜欢什么颜色？","你什么颜色喜欢？","颜色你喜欢什么？"],"correct":0}]}'),
  ('hsk2-03-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["白","белый"],["黑","чёрный"],["红","красный"],["颜色","цвет"],["红苹果","красное яблоко"]]}'),
  ('hsk2-03-1', 7, 'game', '{"type":"listen","title":"Слушаем цвета","items":[{"say":"白","options":["bái","bǎi","bài"],"correct":0},{"say":"黑","options":["hēi","héi","hěi"],"correct":0},{"say":"红","options":["hōng","hóng","hǒng"],"correct":1},{"say":"颜色","options":["yánsè","yǎnsè","yánshè"],"correct":0},{"say":"黑猫","options":["hēi māo","bái māo"],"correct":0}]}'),
  ('hsk2-03-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["红","苹果"],"hint":"«Красное яблоко.»"},{"answer":["黑","猫"],"hint":"«Чёрная кошка.»"},{"answer":["你","喜欢","什么","颜色"],"hint":"«Какой цвет тебе нравится?»"}]}'),
  ('hsk2-03-1', 9, 'write', '{"title":"Пропись: цвета","items":[{"hanzi":"白","pinyin":"bái","m":"белый","hint":"сверху откидная, потом 日 без верхней черты"},{"hanzi":"黑","pinyin":"hēi","m":"чёрный","hint":"сверху 里, снизу четыре точки 灬"},{"hanzi":"红","pinyin":"hóng","m":"красный","hint":"слева 纟, справа 工"}]}'),
  ('hsk2-03-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 红?","options":["белый","красный","чёрный"],"correct":1},{"q":"Как читается 白?","options":["bái","bǎi","bài"],"correct":0},{"q":"Как сказать «белый рис»?","options":["米饭白","白的米饭","白米饭"],"correct":2},{"q":"Белый цвет в Китае связан с траур.","tf":true},{"q":"Что значит 颜色?","options":["цвет","лицо","красота"],"correct":0}]}'),
  ('hsk2-03-2', 1, 'fact', '{"emoji":"📏","title":"Прилагательное стоит перед существительным","text":"В китайском прилагательное ставится перед словом, к которому относится: 新书 «новая книга», 高人 «высокий человек». Короткие прилагательные идут без 的, а длинные или с 很 просят 的: 很新的书 «очень новая книга». У слова 长 два чтения: cháng «длинный» и zhǎng «расти»; сейчас нужно первое."}'),
  ('hsk2-03-2', 2, 'words', '{"title":"Три прилагательных","items":[{"hanzi":"新","pinyin":"xīn","m":"новый","emoji":"🆕","ex":{"zh":"新书","py":"xīn shū","m":"новая книга"}},{"hanzi":"长","pinyin":"cháng","m":"длинный","emoji":"📏","ex":{"zh":"这本书很长。","py":"Zhè běn shū hěn cháng.","m":"Эта книга длинная."}},{"hanzi":"高","pinyin":"gāo","m":"высокий","emoji":"🗼","ex":{"zh":"我哥哥很高。","py":"Wǒ gēge hěn gāo.","m":"Мой брат высокий."}}]}'),
  ('hsk2-03-2', 3, 'theory', '{"title":"Порядок слов: прилагательное + 的 + предмет","blocks":[{"t":"table","head":["Фраза","Когда 的 нужен"],"rows":[["新书","короткое прилагательное, 的 не нужно"],["红苹果","короткое прилагательное, 的 не нужно"],["很新的书","с 很, 的 нужен"],["很长的路","с 很, 的 нужен"]]},{"t":"p","text":"Схема: короткое прилагательное сразу перед предметом; если перед прилагательным есть 很 или оно двуслоговое, добавьте 的."},{"t":"tip","text":"Не путайте с предложением «книга новая»: 这本书很新. Там 的 не нужно."}]}'),
  ('hsk2-03-2', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["新","书"],"hint":"«Новая книга.»"},{"answer":["我","哥哥","很","高"],"hint":"«Мой брат высокий.»"},{"answer":["这","本","书","很","长"],"hint":"«Эта книга длинная.»"}]}'),
  ('hsk2-03-2', 5, 'quiz', '{"title":"Мини-тест: порядок слов","qs":[{"q":"Как сказать «новая книга»?","options":["书新","新书","新的书很"],"correct":1},{"q":"Короткие прилагательные чаще идут без 的.","tf":true},{"q":"Как читается 长 в значении «длинный»?","options":["zhǎng","cháng","chàng"],"correct":1}]}'),
  ('hsk2-03-2', 6, 'theory', '{"title":"Два способа использовать прилагательное","blocks":[{"t":"table","head":["Способ","Пример","Перевод"],"rows":[["перед предметом","新书","новая книга"],["как сказуемое","书很新。","Книга новая."]]},{"t":"p","text":"В первом случае прилагательное определяет предмет, во втором описывает его. В описательной фразе обязательно 很 или другое слово степени."},{"t":"ex","zh":"我哥哥很高。","py":"Wǒ gēge hěn gāo.","m":"Мой брат высокий.","say":"我哥哥很高"}]}'),
  ('hsk2-03-2', 7, 'game', '{"type":"listen","title":"Слушаем: новый, длинный, высокий","items":[{"say":"新","options":["xīn","xín","xǐn"],"correct":0},{"say":"长","options":["chàng","cháng","chǎng"],"correct":1},{"say":"高","options":["gāo","gáo","gǎo"],"correct":0},{"say":"新书","options":["xīn shū","xīn shú"],"correct":0},{"say":"我哥哥很高","options":["wǒ gēge hěn gāo","wǒ gēge hěn dà"],"correct":0}]}'),
  ('hsk2-03-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["新","новый"],["长","длинный"],["高","высокий"],["新书","новая книга"],["书很新","книга новая"]]}'),
  ('hsk2-03-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: порядок слов","cases":[{"buggyText":"书新","context":"«Новая книга»","options":["书新","新书","新的书"],"correct":1},{"buggyText":"我哥哥高很。","context":"«Мой брат высокий»","options":["我哥哥很高。","我很高哥哥。","哥哥我高很。"],"correct":0},{"buggyText":"这书很长的。","context":"«Эта книга длинная»","options":["这书很长。","这书长很。","长这书很。"],"correct":0}]}'),
  ('hsk2-03-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 高?","options":["высокий","новый","длинный"],"correct":0},{"q":"Как читается 新?","options":["xǐn","xīn","xín"],"correct":1},{"q":"Как сказать «Мой брат высокий»?","options":["我哥哥很高。","我哥哥高很。","我高哥哥很。"],"correct":0},{"q":"高 значит «длинный».","tf":false},{"q":"Как сказать «Эта книга новая»?","options":["这本书新很。","新这本书。","这本书很新。"],"correct":2}]}'),
  ('hsk2-03-3', 1, 'fact', '{"emoji":"💸","title":"Ракушка стала «дорогим»","text":"В знаке 贵 «дорогой» стоит 贝 «ракушка»: в древности ракушки служили деньгами. Слово 便宜 piányi «дёшево» буквально «удобно и уместно»: хорошая цена — это когда удобно. А 件 jiàn — счётное слово для одежды, а ещё для дел: 一件衣服 «одна вещь одежды»."}'),
  ('hsk2-03-3', 2, 'words', '{"title":"Цена и одежда","items":[{"hanzi":"贵","pinyin":"guì","m":"дорогой","emoji":"💎","ex":{"zh":"这件衣服很贵。","py":"Zhè jiàn yīfu hěn guì.","m":"Эта одежда дорогая."}},{"hanzi":"便宜","pinyin":"piányi","m":"дешёвый","emoji":"🏷️","ex":{"zh":"这个很便宜。","py":"Zhège hěn piányi.","m":"Это дёшево."}},{"hanzi":"件","pinyin":"jiàn","m":"счётное слово: одежда, дела","emoji":"👕","ex":{"zh":"一件衣服","py":"yí jiàn yīfu","m":"одна вещь одежды"}}]}'),
  ('hsk2-03-3', 3, 'game', '{"type":"listen","title":"Слушаем: цена и одежда","items":[{"say":"贵","options":["guì","guǐ","guí"],"correct":0},{"say":"便宜","options":["piányi","piānyi","pián yí"],"correct":0,"explain":"Второй слог безударный."},{"say":"件","options":["jiān","jiàn","jiǎn"],"correct":1},{"say":"这件衣服很贵","options":["zhè jiàn yīfu hěn guì","zhè jiàn yīfu hěn dà"],"correct":0},{"say":"一件衣服","options":["yí jiàn yīfu","yì jiàn yīfu"],"correct":0}]}'),
  ('hsk2-03-3', 4, 'game', '{"type":"tone_visualizer","initialTone":4,"title":"Тренажёр голоса: повторите «guì» (4 тон)"}'),
  ('hsk2-03-3', 5, 'theory', '{"title":"Одежда и цена","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["这件衣服很贵。","Эта одежда дорогая."],["这件衣服不贵。","Эта одежда недорогая."],["太贵了！","Слишком дорого!"],["有便宜的吗？","Есть что-нибудь подешевле?"]]},{"t":"p","text":"件 ставится между числом и одеждой: 一件衣服, 两件衣服. Слово 的 после прилагательного заменяет предмет: 便宜的 «дешёвое»."},{"t":"tip","text":"Перед 件 (4 тон) число 一 читается yí: 一件."}]}'),
  ('hsk2-03-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"💎","options":["便宜","贵","件"],"correct":1},{"emoji":"🏷️","options":["贵","便宜","新"],"correct":1},{"emoji":"👕","options":["件","贵","便宜"],"correct":0}]}'),
  ('hsk2-03-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["贵","дорогой"],["便宜","дешёвый"],["件","счётное слово одежды"],["太贵了","слишком дорого"],["有便宜的吗？","есть подешевле?"]]}'),
  ('hsk2-03-3', 8, 'game', '{"type":"chatsim","title":"WeChat: покупка одежды","messages":[{"speaker":"Продавец","text":"你好！你买什么？","pinyin":"Nǐ hǎo! Nǐ mǎi shénme?","translation":"Здравствуйте! Что покупаете?","options":["我买衣服。","我是衣服。","我衣服买。"],"correct":0},{"speaker":"Продавец","text":"这件衣服八十块。","pinyin":"Zhè jiàn yīfu bāshí kuài.","translation":"Эта вещь стоит 80 юаней.","options":["太贵了！有便宜的吗？","太便宜了！再见。","不贵，我是学生。"],"correct":0},{"speaker":"Продавец","text":"有。这件白的六十块。","pinyin":"Yǒu. Zhè jiàn bái de liùshí kuài.","translation":"Есть. Эта белая стоит 60.","options":["好，我买这件。","对不起，再见。","不是，我有。"],"correct":0}]}'),
  ('hsk2-03-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["这","件","衣服","很","贵"],"hint":"«Эта одежда дорогая.»"},{"answer":["太","贵","了"],"hint":"«Слишком дорого!»"},{"answer":["有","便宜","的","吗"],"hint":"«Есть что-нибудь подешевле?»"},{"answer":["我","买","一","件","衣服"],"hint":"«Я куплю одну вещь одежды.»"}]}'),
  ('hsk2-03-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 便宜?","options":["дорогой","дешёвый","новый"],"correct":1},{"q":"Как читается 贵?","options":["guì","guǐ","guí"],"correct":0},{"q":"Какое слово считает одежду?","options":["本","个","件"],"correct":2},{"q":"В 贵 есть 贝 «ракушка».","tf":true},{"q":"Как сказать «одна вещь одежды»?","options":["一个衣服","一件衣服","衣服一件"],"correct":1}]}'),
  ('hsk2-03-4', 1, 'fact', '{"emoji":"🛍️","title":"Анна выбирает платье","text":"Анна приходит в магазин, выбирает вещь, торгуется и решает, что купить. Читайте диалог целиком."}'),
  ('hsk2-03-4', 2, 'text', '{"title":"В магазине одежды","lines":[{"zh":"安娜：你好！这件衣服多少钱？","py":"Ānnà: Nǐ hǎo! Zhè jiàn yīfu duōshao qián?","m":"Анна: Здравствуйте! Сколько стоит эта вещь?"},{"zh":"店员：八十块。","py":"Diànyuán: Bāshí kuài.","m":"Продавец: Восемьдесят юаней."},{"zh":"安娜：太贵了！有便宜的吗？","py":"Ānnà: Tài guì le! Yǒu piányi de ma?","m":"Анна: Слишком дорого! Есть что-нибудь подешевле?"},{"zh":"店员：有。这件白的六十块。","py":"Diànyuán: Yǒu. Zhè jiàn bái de liùshí kuài.","m":"Продавец: Есть. Эта белая стоит 60."},{"zh":"安娜：我也喜欢红的。红的多少钱？","py":"Ānnà: Wǒ yě xǐhuan hóng de. Hóng de duōshao qián?","m":"Анна: Мне нравится и красная. Сколько красная?"},{"zh":"店员：红的也六十块。","py":"Diànyuán: Hóng de yě liùshí kuài.","m":"Продавец: Красная тоже 60."},{"zh":"安娜：这件红的很漂亮，也不贵。我买一件。","py":"Ānnà: Zhè jiàn hóng de hěn piàoliang, yě bú guì. Wǒ mǎi yí jiàn.","m":"Анна: Красная красивая и недорогая. Беру одну."}],"qs":[{"q":"Сколько стоит первая вещь?","options":["60","80","100"],"correct":1},{"q":"Анна считает первую вещь дешёвой.","tf":false,"explain":"Она говорит 太贵了."},{"q":"Какого цвета вещь выбрала Анна?","options":["белая","чёрная","красная"],"correct":2},{"q":"Вставьте слово: 我买一___。","options":["个","件","本"],"correct":1},{"q":"Красная и белая вещи стоят одинаково.","tf":true},{"q":"Как Анна просит что-то подешевле?","options":["有便宜的吗？","你有贵吗？","这件多少？"],"correct":0},{"q":"Что значит 红的?","options":["красное (то)","красный цвет","красота"],"correct":0}]}'),
  ('hsk2-03-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["这件衣服多少钱？","Сколько стоит эта вещь?"],["太贵了！","Слишком дорого!"],["有便宜的吗？","Есть подешевле?"],["红的很漂亮","Красная красивая"],["我买一件","Я куплю одну"]]}'),
  ('hsk2-03-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"这件衣服多少钱","options":["zhè jiàn yīfu duōshao qián","zhè běn shū duōshao qián"],"correct":0},{"say":"太贵了","options":["tài guì le","tài piányi le"],"correct":0},{"say":"有便宜的吗","options":["yǒu piányi de ma","yǒu guì de ma"],"correct":0},{"say":"我买一件","options":["wǒ mǎi yí jiàn","wǒ mǎi yí gè"],"correct":0}]}'),
  ('hsk2-03-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: магазин","cases":[{"buggyText":"这个衣服很贵。","context":"«Эта вещь дорогая»","options":["这件衣服很贵。","这本衣服很贵。","这衣服件很贵。"],"correct":0},{"buggyText":"有便宜吗？","context":"«Есть подешевле?»","options":["有便宜的吗？","便宜有吗？","有吗便宜？"],"correct":0},{"buggyText":"我买红一件。","context":"«Я куплю красную»","options":["我买一件红的。","我红买一件。","买我一件红。"],"correct":0}]}'),
  ('hsk2-03-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Слишком дорого!»","options":["太贵了！","很便宜了！","太新了！"],"correct":0},{"q":"Как читается 便宜?","options":["piányi","piānyi","piányí"],"correct":0},{"q":"Анна покупает красную вещь.","tf":true}]}'),
  ('hsk2-03-5', 1, 'fact', '{"emoji":"👗","title":"Соберите гардероб","text":"Выберите цвета и цены, расскажите о вещах и сравните их. Слова глав 1–3 HSK 2."}'),
  ('hsk2-03-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"红","correctRadicals":["纟","工"],"title":"Пазл: соберите 红"}'),
  ('hsk2-03-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"贵","radicals":["贝","中","一"],"correctOrder":["中","一","贝"],"explain":"Сверху 中 и 一, внизу 贝 «ракушка»."},{"targetHanzi":"便","radicals":["亻","更","女"],"correctOrder":["亻","更"],"explain":"Слева 亻, справа 更."},{"targetHanzi":"宜","radicals":["宀","且","一"],"correctOrder":["宀","且"],"explain":"Сверху 宀, внизу 且."}]}'),
  ('hsk2-03-5', 4, 'game', '{"type":"build","title":"Мастерская гардероба","items":[{"target":"(Вещь)","answer":["这","件","衣服","很","新"],"hint":"«Эта одежда новая.»"},{"target":"(Цвет)","answer":["我","喜欢","红","衣服"],"hint":"«Мне нравится красная одежда.»"},{"target":"(Цена)","answer":["这","件","不","贵"],"hint":"«Эта вещь недорогая.»"},{"target":"(Выбор)","answer":["我","买","一","件","白","的"],"hint":"«Я куплю одну белую.»"}]}'),
  ('hsk2-03-5', 5, 'theory', '{"title":"Образец описания вещи","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["Цвет","这件衣服是红的。"],["Размер","这件很长。"],["Цена","这件不贵。"],["Решение","我买这件。"]]}]}'),
  ('hsk2-03-5', 6, 'game', '{"type":"chatsim","title":"WeChat: обсуждаем одежду","messages":[{"speaker":"Друг","text":"你喜欢什么颜色？","pinyin":"Nǐ xǐhuan shénme yánsè?","translation":"Какой цвет тебе нравится?","options":["我喜欢红。","我是红。","我红喜欢。"],"correct":0},{"speaker":"Друг","text":"你的衣服是新的吗？","pinyin":"Nǐ de yīfu shì xīn de ma?","translation":"Твоя одежда новая?","options":["是，很新。","不是，我新。","对，我衣服。"],"correct":0},{"speaker":"Друг","text":"贵吗？","pinyin":"Guì ma?","translation":"Дорого?","options":["不贵，很便宜。","是，我很高。","没有，贵。"],"correct":0}]}'),
  ('hsk2-03-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["纟 + 工","红"],["贝 + 中 + 一","贵"],["亻 + 更","便"],["宀 + 且","宜"]]}'),
  ('hsk2-03-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"新","pinyin":"xīn","m":"новый","hint":"слева 亲, справа 斤"},{"hanzi":"高","pinyin":"gāo","m":"высокий","hint":"сверху 亠, внизу 口 и 冂"},{"hanzi":"件","pinyin":"jiàn","m":"счётное слово","hint":"слева 亻, справа 牛"}]}'),
  ('hsk2-03-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Мне нравится красная одежда»?","options":["我红喜欢衣服。","我喜欢红衣服。","我喜欢衣服红。"],"correct":1},{"q":"Что значит 便宜?","options":["дёшево","дорого","красиво"],"correct":0},{"q":"Знак 贵 содержит 贝.","tf":true}]}'),
  ('hsk2-03-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 3 (HSK 2)","text":"白, 黑, 红, 颜色, 新, 长, 高, 贵, 便宜 и 件."}'),
  ('hsk2-03-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"红","options":["hóng","hōng","hǒng"],"correct":0},{"say":"黑猫","options":["bái māo","hēi māo"],"correct":1},{"say":"新书","options":["xīn shū","xīn shǔ"],"correct":0},{"say":"这件衣服很贵","options":["zhè jiàn yīfu hěn guì","zhè běn shū hěn guì"],"correct":0},{"say":"太便宜了","options":["tài guì le","tài piányi le"],"correct":1},{"say":"我哥哥很高","options":["wǒ gēge hěn gāo","wǒ gēge hěn dà"],"correct":0}]}'),
  ('hsk2-03-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"⚪","options":["黑","白","红"],"correct":1},{"emoji":"🆕","options":["新","长","高"],"correct":0},{"emoji":"💎","options":["便宜","件","贵"],"correct":2},{"emoji":"👕","options":["件","新","贵"],"correct":0}]}'),
  ('hsk2-03-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["白","белый"],["黑","чёрный"],["红","красный"],["颜色","цвет"],["新","новый"],["长","длинный"],["高","высокий"],["贵","дорогой"],["便宜","дешёвый"],["件","счётное слово одежды"]]}'),
  ('hsk2-03-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «красное яблоко»?","options":["苹果红","红苹果","红的苹果很"],"correct":1},{"q":"Как спросить «Какой цвет тебе нравится?»","options":["你什么颜色喜欢？","你喜欢什么颜色？","颜色你喜欢吗？"],"correct":1},{"q":"Как сказать «Слишком дорого!»","options":["太贵了！","太便宜了！","太新了！"],"correct":0},{"q":"Короткое прилагательное обычно без 的.","tf":true},{"q":"Как читается 长 в значении «длинный»?","options":["zhǎng","cháng","chàng"],"correct":1},{"q":"Какое слово считает одежду?","options":["本","个","件"],"correct":2},{"q":"白 — это «красный».","tf":false},{"q":"Как сказать «Мой брат высокий»?","options":["我哥哥很高。","我哥哥高很。","哥哥我高。"],"correct":0},{"q":"Как сказать «Есть подешевле?»","options":["有便宜的吗？","便宜有吗？","有吗便宜？"],"correct":0},{"q":"Что значит 颜色?","options":["цвет","лицо","краска"],"correct":0}]}'),
  ('hsk2-03-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["红","苹果"],"hint":"«Красное яблоко.»"},{"answer":["这","件","衣服","很","贵"],"hint":"«Эта одежда дорогая.»"},{"answer":["我","哥哥","很","高"],"hint":"«Мой брат высокий.»"},{"answer":["我","买","一","件","白","的"],"hint":"«Я куплю белую.»"}]}'),
  ('hsk2-03-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"书新","context":"«Новая книга»","options":["书新","新书","新的书"],"correct":1},{"buggyText":"这个衣服很贵。","context":"«Эта вещь дорогая»","options":["这件衣服很贵。","这本衣服很贵。","这衣服件很贵。"],"correct":0},{"buggyText":"有便宜吗？","context":"«Есть подешевле?»","options":["便宜有吗？","有吗便宜？","有便宜的吗？"],"correct":2}]}'),
  ('hsk2-03-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Продавец","text":"这件衣服八十块。","pinyin":"Zhè jiàn yīfu bāshí kuài.","translation":"Эта вещь 80 юаней.","options":["太贵了！有便宜的吗？","太新了，再见。","不是，我有。"],"correct":0},{"speaker":"Продавец","text":"有。这件白的六十块。","pinyin":"Yǒu. Zhè jiàn bái de liùshí kuài.","translation":"Есть. Эта белая — 60.","options":["好，我买一件。","对不起。","再见。"],"correct":0}]}'),
  ('hsk2-03-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"红","pinyin":"hóng","m":"красный","hint":"纟 + 工"},{"hanzi":"新","pinyin":"xīn","m":"новый","hint":"亲 + 斤"},{"hanzi":"贵","pinyin":"guì","m":"дорогой","hint":"中 + 一 + 贝"}]}'),
  ('hsk2-03-6', 10, 'recall', '{"words":[{"hanzi":"白","pinyin":"bái","m":"белый"},{"hanzi":"黑","pinyin":"hēi","m":"чёрный"},{"hanzi":"红","pinyin":"hóng","m":"красный"},{"hanzi":"颜色","pinyin":"yánsè","m":"цвет"},{"hanzi":"新","pinyin":"xīn","m":"новый"},{"hanzi":"长","pinyin":"cháng","m":"длинный"},{"hanzi":"高","pinyin":"gāo","m":"высокий"},{"hanzi":"贵","pinyin":"guì","m":"дорогой"},{"hanzi":"便宜","pinyin":"piányi","m":"дешёвый"},{"hanzi":"件","pinyin":"jiàn","m":"счётное слово одежды"}],"tf":[{"zh":"书新","py":"shū xīn","m":"Новая книга.","ok":false,"explain":"Правильно: 新书."},{"zh":"这件衣服很贵。","py":"zhè jiàn yīfu hěn guì.","m":"Эта одежда дорогая.","ok":true}],"sentences":[{"zh":"红苹果","tokens":["红","苹果"],"m":"Красное яблоко."},{"zh":"这件衣服很贵。","tokens":["这","件","衣服","很","贵"],"m":"Эта одежда дорогая."},{"zh":"我哥哥很高。","tokens":["我","哥哥","很","高"],"m":"Мой брат высокий."}]}'),
  ('hsk2-04-1', 1, 'fact', '{"emoji":"💯","title":"Два двойки: 二 и 两","text":"У числа «два» в китайском две формы. 二 èr стоит в счёте и в числах: 一, 二, 三; 二十 «двадцать». А 两 liǎng ставится перед счётным словом: 两个人 «два человека», 两本书 «две книги». Новые знаки: 百 «сто», 千 «тысяча» и 零 «ноль», с которым строятся числа вроде 105 («сто ноль пять»)."}'),
  ('hsk2-04-1', 2, 'words', '{"title":"Большие числа","items":[{"hanzi":"百","pinyin":"bǎi","m":"сто","emoji":"💯","ex":{"zh":"一百块","py":"yì bǎi kuài","m":"сто юаней"}},{"hanzi":"千","pinyin":"qiān","m":"тысяча","emoji":"🔢","ex":{"zh":"一千块","py":"yì qiān kuài","m":"тысяча юаней"}},{"hanzi":"零","pinyin":"líng","m":"ноль","emoji":"0️⃣","ex":{"zh":"一百零五","py":"yì bǎi líng wǔ","m":"105"}},{"hanzi":"两","pinyin":"liǎng","m":"два (перед счётным словом)","emoji":"✌️","ex":{"zh":"两个人","py":"liǎng gè rén","m":"два человека"}}]}'),
  ('hsk2-04-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"💯","options":["零","千","百"],"correct":2},{"emoji":"🔢","options":["百","两","千"],"correct":2},{"emoji":"0️⃣","options":["零","两","百"],"correct":0},{"emoji":"✌️","options":["二","千","两"],"correct":2}]}'),
  ('hsk2-04-1', 4, 'theory', '{"title":"Как строятся сотни и тысячи","blocks":[{"t":"table","head":["Число","Китайский","Как собрано"],"rows":[["100","一百","один + сто"],["105","一百零五","сто + ноль + пять"],["120","一百二十","сто + двадцать"],["200","两百","два + сто"],["1000","一千","один + тысяча"],["2000","两千","два + тысяча"]]},{"t":"p","text":"Если в числе пропущен разряд, ставят 零: 105 — 一百零五. В конце число 120 говорят 一百二十, а 二 здесь остаётся 二."},{"t":"tip","text":"Перед 百 и 千 слышно yì: 一百 yì bǎi, 一千 yì qiān. Перед счётным словом: 两个, 两本, 两件."}]}'),
  ('hsk2-04-1', 5, 'quiz', '{"title":"Мини-тест: числа","qs":[{"q":"Как сказать «105»?","options":["一百五","一零五","一百零五"],"correct":2},{"q":"Что ставят перед 个: 二 или 两?","options":["二","两","оба"],"correct":1},{"q":"2000 по-китайски — 两千.","tf":true}]}'),
  ('hsk2-04-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["百","сто"],["千","тысяча"],["零","ноль"],["两","два (перед сч. словом)"],["一百零五","105"]]}'),
  ('hsk2-04-1', 7, 'game', '{"type":"listen","title":"Слушаем большие числа","items":[{"say":"百","options":["bǎi","bái","bài"],"correct":0},{"say":"千","options":["qiǎn","qián","qiān"],"correct":2},{"say":"零","options":["líng","lǐng","lìng"],"correct":0},{"say":"两","options":["liǎng","liàng","liáng"],"correct":0},{"say":"一百零五","options":["yì bǎi wǔ","yì bǎi líng wǔ"],"correct":1}]}'),
  ('hsk2-04-1', 8, 'game', '{"type":"build","title":"Соберите число","items":[{"answer":["一","百","零","五"],"hint":"105"},{"answer":["一","百","二","十"],"hint":"120"},{"answer":["两","千"],"hint":"2000"},{"answer":["两","个","人"],"hint":"«Два человека.»"}]}'),
  ('hsk2-04-1', 9, 'write', '{"title":"Пропись: числа","items":[{"hanzi":"百","pinyin":"bǎi","m":"сто","hint":"сверху 一, снизу 白"},{"hanzi":"千","pinyin":"qiān","m":"тысяча","hint":"откидная, потом 十"},{"hanzi":"两","pinyin":"liǎng","m":"два","hint":"сверху 一, рамка 冂, внутри два 人"}]}'),
  ('hsk2-04-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 零?","options":["ноль","тысяча","сто"],"correct":0},{"q":"Как читается 两?","options":["liàng","liáng","liǎng"],"correct":2},{"q":"Как сказать «два человека»?","options":["两人个","二个人","两个人"],"correct":2},{"q":"百 значит «тысяча».","tf":false},{"q":"Как будет «200»?","options":["零二百","两百","二百零"],"correct":1}]}'),
  ('hsk2-04-2', 1, 'fact', '{"emoji":"📞","title":"Номер телефона читают по цифрам","text":"Телефонный номер 号码 hàomǎ называют цифра за цифрой, и единицу читают не yī, а yāo: так легче отличать её от семёрки qī. Порядковые числа строятся с приставкой 第: 第一 «первый», 第二 «второй». А 次 cì считает «разы», и 每 měi «каждый» помогает говорить «каждый день»."}'),
  ('hsk2-04-2', 2, 'words', '{"title":"Порядок и номера","items":[{"hanzi":"第一","pinyin":"dì-yī","m":"первый","emoji":"🥇","ex":{"zh":"第一次","py":"dì-yī cì","m":"в первый раз"}},{"hanzi":"号码","pinyin":"hàomǎ","m":"номер","emoji":"📱","ex":{"zh":"你的号码是多少？","py":"Nǐ de hàomǎ shì duōshao?","m":"Какой у тебя номер?"}},{"hanzi":"次","pinyin":"cì","m":"раз (счётное слово)","emoji":"🔁","ex":{"zh":"我去过一次。","py":"Wǒ qù guo yí cì.","m":"Я был один раз."}},{"hanzi":"每","pinyin":"měi","m":"каждый","emoji":"📅","ex":{"zh":"我每天学习。","py":"Wǒ měi tiān xuéxí.","m":"Я учусь каждый день."}}]}'),
  ('hsk2-04-2', 3, 'theory', '{"title":"第, 次, 每","blocks":[{"t":"table","head":["Слово","Что делает","Пример"],"rows":[["第 + число","порядковое число","第一, 第二, 第三"],["число + 次","число раз","一次, 两次"],["每 + слово","«каждый»","每天, 每个人, 每次"]]},{"t":"p","text":"第一 — первый, 第二个人 «второй человек». 次 отвечает на «сколько раз»: 你去过几次？ 每 стоит перед словом времени или счётным: 每天, 每个人."},{"t":"tip","text":"В телефонных номерах 1 читают yāo: 138 — yāo sān bā."}]}'),
  ('hsk2-04-2', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["第","一","次"],"hint":"«Первый раз.»"},{"answer":["我","每","天","学习"],"hint":"«Я учусь каждый день.»"},{"answer":["我","去","一","次"],"hint":"«Я пойду один раз.»"}]}'),
  ('hsk2-04-2', 5, 'quiz', '{"title":"Мини-тест: номера и разы","qs":[{"q":"Как сказать «каждый день»?","options":["每天","天每","每个天"],"correct":0},{"q":"Как читается 1 в номере телефона?","options":["yī","yí","yāo"],"correct":2},{"q":"次 считает разы.","tf":true}]}'),
  ('hsk2-04-2', 6, 'theory', '{"title":"Вопросы про номер и разы","blocks":[{"t":"table","head":["Вопрос","Ответ"],"rows":[["你的号码是多少？","我的号码是一三八……"],["你去过几次？","我去过两次。"],["你是第几个？","我是第一个。"]]},{"t":"p","text":"Номер называют по одной цифре: 一三八 «yāo sān bā». Про разы спрашивают 几次, про порядок 第几."},{"t":"ex","zh":"你的号码是多少？","py":"Nǐ de hàomǎ shì duōshao?","m":"Какой у тебя номер?","say":"你的号码是多少"}]}'),
