  ('hsk2-04-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: порядок","cases":[{"buggyText":"一次第","context":"«Первый раз»","options":["次第一","第一次","一第次"],"correct":1},{"buggyText":"天每学习。","context":"«Каждый день учусь»","options":["每天学习。","学习每天。","天每学习。"],"correct":0},{"buggyText":"你的号码多少是？","context":"«Какой у тебя номер?»","options":["号码你的是多少？","你的号码多少是？","你的号码是多少？"],"correct":2}]}'),
  ('hsk2-04-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 第一?","options":["один","первый","каждый"],"correct":1},{"q":"Как читается 每?","options":["méi","měi","mèi"],"correct":1},{"q":"Как спросить «Какой у тебя номер?»","options":["你号码什么？","你的号码是多少？","什么你的号码？"],"correct":1},{"q":"次 стоит перед числом.","tf":false,"explain":"次 стоит после числа: 一次."},{"q":"Как сказать «каждый человек»?","options":["人每个","每个人","个每人"],"correct":1}]}'),
  ('hsk2-04-3', 1, 'fact', '{"emoji":"⭐","title":"«Больше всех» и «по-настоящему»","text":"最 zuì «самый» ставится перед прилагательным: 最好 «самый лучший», 最大 «самый большой». А 真 zhēn «действительно, правда» делает речь эмоциональной: 真好 «как хорошо», 真漂亮 «как красиво». Знак 最 состоит из 日 и 取: «взять самое лучшее»."}'),
  ('hsk2-04-3', 2, 'words', '{"title":"Два слова","items":[{"hanzi":"最","pinyin":"zuì","m":"самый","emoji":"🏆","ex":{"zh":"他的汉语最好。","py":"Tā de Hànyǔ zuì hǎo.","m":"У него лучший китайский."}},{"hanzi":"真","pinyin":"zhēn","m":"действительно, правда","emoji":"💫","ex":{"zh":"这个菜真好！","py":"Zhège cài zhēn hǎo!","m":"Это блюдо правда прекрасное!"}}]}'),
  ('hsk2-04-3', 3, 'game', '{"type":"listen","title":"Слушаем: самый и правда","items":[{"say":"最","options":["zuǐ","zuì","zuí"],"correct":1},{"say":"真","options":["zhěn","zhén","zhēn"],"correct":2},{"say":"最好","options":["zuì hǎo","zuí hǎo"],"correct":0},{"say":"真漂亮","options":["zhēn piàoliang","zhèn piàoliang"],"correct":0},{"say":"他的汉语最好","options":["tā de Hànyǔ hěn hǎo","tā de Hànyǔ zuì hǎo"],"correct":1}]}'),
  ('hsk2-04-3', 4, 'game', '{"type":"tone_visualizer","initialTone":4,"title":"Тренажёр голоса: повторите «zuì» (4 тон)"}'),
  ('hsk2-04-3', 5, 'theory', '{"title":"最 и 真 перед прилагательным","blocks":[{"t":"table","head":["Слово","Смысл","Пример"],"rows":[["最","самый","最大, 最好, 最贵"],["真","действительно, как","真好, 真漂亮, 真贵"],["很","очень (нейтрально)","很好"]]},{"t":"p","text":"最 нужно, чтобы сравнить: 他最高 «он самый высокий». 真 выражает эмоцию: 真贵！ «Как дорого!»"},{"t":"tip","text":"Не ставьте 很 вместе с 最 и 真: говорят 最好, а не 很最好."}]}'),
  ('hsk2-04-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🏆","options":["每","真","最"],"correct":2},{"emoji":"💫","options":["真","次","最"],"correct":0}]}'),
  ('hsk2-04-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["最","самый"],["真","действительно"],["最好","самый лучший"],["真漂亮","как красиво"],["最贵","самый дорогой"]]}'),
  ('hsk2-04-3', 8, 'game', '{"type":"chatsim","title":"WeChat: самый и правда","messages":[{"speaker":"Друг","text":"你的汉语真好！","pinyin":"Nǐ de Hànyǔ zhēn hǎo!","translation":"Твой китайский правда хорош!","options":["对不起，再见。","没关系。","谢谢，老师的汉语最好。"],"correct":2},{"speaker":"Друг","text":"你喜欢什么颜色？","pinyin":"Nǐ xǐhuan shénme yánsè?","translation":"Какой цвет тебе нравится?","options":["我喜欢最红。","最我喜欢红。","我最喜欢红。"],"correct":2,"explain":"最 стоит перед 喜欢."},{"speaker":"Друг","text":"你的号码是多少？","pinyin":"Nǐ de hàomǎ shì duōshao?","translation":"Какой у тебя номер?","options":["我的号码是一三八……","我号码二个。","没有号码。"],"correct":0}]}'),
  ('hsk2-04-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["他","的","汉语","最","好"],"hint":"«У него лучший китайский.»"},{"answer":["这个","菜","真","好"],"hint":"«Это блюдо правда хорошее.»"},{"answer":["我","最","喜欢","红"],"hint":"«Мне больше всего нравится красный.»"}]}'),
  ('hsk2-04-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 最?","options":["самый","действительно","каждый"],"correct":0},{"q":"Как читается 真?","options":["zhèn","zhēn","zhěn"],"correct":1},{"q":"Как сказать «Как красиво!»","options":["最漂亮真！","真漂亮！","漂亮真！"],"correct":1},{"q":"很 можно ставить вместе с 最.","tf":false},{"q":"Как сказать «Я больше всего люблю чай»?","options":["最我喜欢茶。","我喜欢最茶。","我最喜欢茶。"],"correct":2}]}'),
  ('hsk2-04-4', 1, 'fact', '{"emoji":"📲","title":"Анна и Ли Мин обмениваются номерами","text":"Анна записывает номер Ли Мина и повторяет цифры. В диалоге встретятся 号码, 第一, 次, 最, 真, 每."}'),
  ('hsk2-04-4', 2, 'text', '{"title":"Номер телефона","lines":[{"zh":"安娜：李明，你的号码是多少？","py":"Ānnà: Lǐ Míng, nǐ de hàomǎ shì duōshao?","m":"Анна: Ли Мин, какой у тебя номер?"},{"zh":"李明：我的号码是一三八零零一三五七九二。","py":"Lǐ Míng: Wǒ de hàomǎ shì yāo sān bā líng líng yāo sān wǔ qī jiǔ èr.","m":"Ли Мин: Мой номер 138 0013 5792."},{"zh":"安娜：请再说一次，好吗？","py":"Ānnà: Qǐng zài shuō yí cì, hǎo ma?","m":"Анна: Повтори ещё раз, пожалуйста."},{"zh":"李明：一三八零零一三五七九二。","py":"Lǐ Míng: Yāo sān bā líng líng yāo sān wǔ qī jiǔ èr.","m":"Ли Мин: 138 0013 5792."},{"zh":"安娜：好，你是我的第一个中国朋友。","py":"Ānnà: Hǎo, nǐ shì wǒ de dì-yī gè Zhōngguó péngyou.","m":"Анна: Хорошо. Ты мой первый китайский друг."},{"zh":"李明：真的吗？谢谢！","py":"Lǐ Míng: Zhēn de ma? Xièxie!","m":"Ли Мин: Правда? Спасибо!"},{"zh":"安娜：你的汉语真好，老师的汉语最好。","py":"Ānnà: Nǐ de Hànyǔ zhēn hǎo, lǎoshī de Hànyǔ zuì hǎo.","m":"Анна: У тебя отличный китайский, а у учителя лучший."},{"zh":"李明：我每天学习汉语。","py":"Lǐ Míng: Wǒ měi tiān xuéxí Hànyǔ.","m":"Ли Мин: Я каждый день учу китайский."}],"qs":[{"q":"О чём просит Анна?","options":["прийти домой","повторить номер","купить книгу"],"correct":1},{"q":"Анна говорит, что Ли Мин её первый китайский друг.","tf":true},{"q":"Кто лучше всех говорит по-китайски, по словам Анны?","options":["учитель","Ли Мин","Анна"],"correct":0},{"q":"Вставьте слово: 请再说一___。","options":["个","岁","次"],"correct":2},{"q":"Ли Мин учит китайский раз в неделю.","tf":false,"explain":"Он говорит 每天."},{"q":"Как Ли Мин читает цифру 1 в номере?","options":["yāo","èr","yī"],"correct":0},{"q":"Как Анна хвалит китайский Ли Мина?","options":["很不好","最不好","真好"],"correct":2}]}'),
  ('hsk2-04-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["你的号码是多少？","Какой у тебя номер?"],["请再说一次","повтори ещё раз"],["第一个朋友","первый друг"],["我每天学习汉语","я каждый день учу китайский"],["老师的汉语最好","у учителя лучший китайский"]]}'),
