  ('hsk2-04-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: номера и сравнения","cases":[{"buggyText":"请再说次一。","context":"«Повтори ещё раз»","options":["请再说一次。","请一说再次。","请再次说一。"],"correct":0},{"buggyText":"我天每学习。","context":"«Я каждый день учусь»","options":["我学习天每。","我天每学习。","我每天学习。"],"correct":2},{"buggyText":"你汉语很最好。","context":"«У тебя лучший китайский»","options":["你汉语最很好。","你的汉语最好。","你的汉语很最好。"],"correct":1}]}'),
  ('hsk2-04-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Повторите ещё раз»?","options":["请再说一次。","请说再一次。","再请说次一。"],"correct":0},{"q":"Как читается 号码?","options":["hàomá","háomǎ","hàomǎ"],"correct":2},{"q":"Анна и Ли Мин обмениваются номерами телефонов.","tf":true}]}'),
