  ('hsk2-04-5', 6, 'game', '{"type":"chatsim","title":"WeChat: рейтинг","messages":[{"speaker":"Друг","text":"你每天学习汉语吗？","pinyin":"Nǐ měi tiān xuéxí Hànyǔ ma?","translation":"Ты каждый день учишь китайский?","options":["学习，每天一次。","对，我每次。","不是，我每天。"],"correct":0},{"speaker":"Друг","text":"谁最高？","pinyin":"Shéi zuì gāo?","translation":"Кто самый высокий?","options":["我最高哥哥。","我哥哥最高。","最我哥哥高。"],"correct":1},{"speaker":"Друг","text":"你的号码呢？","pinyin":"Nǐ de hàomǎ ne?","translation":"А твой номер?","options":["我是号码。","一三八零零……","号码有。"],"correct":1}]}'),
