  ('hsk2-04-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["一","百","零","五"],"hint":"105"},{"answer":["两","个","人"],"hint":"«Два человека.»"},{"answer":["我","每","天","学习"],"hint":"«Я учусь каждый день.»"},{"answer":["他","的","汉语","最","好"],"hint":"«У него лучший китайский.»"}]}'),
  ('hsk2-04-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"第一次","context":"«Первый раз»","options":["次第一","第一次","一第次"],"correct":1},{"buggyText":"天每学习。","context":"«Каждый день учусь»","options":["每天学习。","天每学习。","学习每天。"],"correct":0},{"buggyText":"你汉语很最好。","context":"«Лучший китайский»","options":["你的汉语很最好。","你汉语最很好。","你的汉语最好。"],"correct":2}]}'),
  ('hsk2-04-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"你的号码是多少？","pinyin":"Nǐ de hàomǎ shì duōshao?","translation":"Какой у тебя номер?","options":["我号码是什么。","没有号码。","我的号码是一三八……"],"correct":2},{"speaker":"Друг","text":"你的汉语真好！","pinyin":"Nǐ de Hànyǔ zhēn hǎo!","translation":"Твой китайский правда хорош!","options":["没关系。","对不起。","谢谢，老师最好。"],"correct":2}]}'),
  ('hsk2-04-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"百","pinyin":"bǎi","m":"сто","hint":"一 + 白"},{"hanzi":"最","pinyin":"zuì","m":"самый","hint":"日 + 取"},{"hanzi":"两","pinyin":"liǎng","m":"два","hint":"一 + 冂 + 人人"}]}'),
  ('hsk2-04-6', 10, 'recall', '{"words":[{"hanzi":"百","pinyin":"bǎi","m":"сто"},{"hanzi":"千","pinyin":"qiān","m":"тысяча"},{"hanzi":"零","pinyin":"líng","m":"ноль"},{"hanzi":"两","pinyin":"liǎng","m":"два"},{"hanzi":"第一","pinyin":"dì-yī","m":"первый"},{"hanzi":"号码","pinyin":"hàomǎ","m":"номер"},{"hanzi":"次","pinyin":"cì","m":"раз"},{"hanzi":"每","pinyin":"měi","m":"каждый"},{"hanzi":"最","pinyin":"zuì","m":"самый"},{"hanzi":"真","pinyin":"zhēn","m":"действительно"}],"tf":[{"zh":"二个人","py":"èr gè rén","m":"Два человека.","ok":false,"explain":"Правильно: 两个人."},{"zh":"一百零五","py":"yì bǎi líng wǔ","m":"105.","ok":true}],"sentences":[{"zh":"一百零五","tokens":["一","百","零","五"],"m":"105"},{"zh":"我每天学习。","tokens":["我","每","天","学习"],"m":"Я учусь каждый день."},{"zh":"他的汉语最好。","tokens":["他","的","汉语","最","好"],"m":"У него лучший китайский."}]}'),
  ('hsk2-05-1', 1, 'fact', '{"emoji":"🌄","title":"Солнце над десяткой","text":"Знак 早 «рано, утро» — это 日 «солнце» над 十: солнце поднимается над горизонтом. А 晚 «поздно, вечер» — 日 и 免: солнце уходит. Слово 小时 xiǎoshí «час как длительность» и 时间 shíjiān «время» вы уже почти понимаете: 时 вы учили в 时候."}'),
  ('hsk2-05-1', 2, 'words', '{"title":"Утро, вечер, часы","items":[{"hanzi":"早上","pinyin":"zǎoshang","m":"утро","emoji":"🌅","ex":{"zh":"我早上七点起床。","py":"Wǒ zǎoshang qī diǎn qǐchuáng.","m":"Я встаю в семь утра."}},{"hanzi":"晚上","pinyin":"wǎnshang","m":"вечер","emoji":"🌃","ex":{"zh":"晚上我回家。","py":"Wǎnshang wǒ huí jiā.","m":"Вечером я иду домой."}},{"hanzi":"小时","pinyin":"xiǎoshí","m":"час (длительность)","emoji":"⏳","ex":{"zh":"学习两个小时","py":"xuéxí liǎng gè xiǎoshí","m":"учиться два часа"}},{"hanzi":"时间","pinyin":"shíjiān","m":"время","emoji":"🕰️","ex":{"zh":"你有时间吗？","py":"Nǐ yǒu shíjiān ma?","m":"У тебя есть время?"}}]}'),
  ('hsk2-05-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🌅","options":["时间","早上","晚上"],"correct":1},{"emoji":"🌃","options":["小时","晚上","早上"],"correct":1},{"emoji":"⏳","options":["小时","时间","晚上"],"correct":0},{"emoji":"🕰️","options":["时间","小时","早上"],"correct":0}]}'),
  ('hsk2-05-1', 4, 'theory', '{"title":"点, 小时 и 时间: в чём разница","blocks":[{"t":"table","head":["Слово","Что отвечает","Пример"],"rows":[["点","в котором часу","七点 — в 7 часов"],["小时","сколько длится","两个小时 — два часа"],["时间","время вообще","你有时间吗？"]]},{"t":"p","text":"Для часа на часах 点, для длительности 小时 со счётным словом 个: 两个小时. 两 вы выучили в главе 4."},{"t":"tip","text":"Не говорите 两点个小时: у 点 и 小时 разные задачи."}]}'),
  ('hsk2-05-1', 5, 'quiz', '{"title":"Мини-тест: время","qs":[{"q":"Как сказать «в семь утра»?","options":["七点早上","早上七点","早七上点"],"correct":1},{"q":"Как сказать «два часа» как длительность?","options":["两个小时","两点","二个小时"],"correct":0},{"q":"时间 значит «время».","tf":true}]}'),
  ('hsk2-05-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["早上","утро"],["晚上","вечер"],["小时","час (длительность)"],["时间","время"],["两个小时","два часа"]]}'),
  ('hsk2-05-1', 7, 'game', '{"type":"listen","title":"Слушаем время","items":[{"say":"早上","options":["záoshang","zǎoshang","zǎoshàng"],"correct":1},{"say":"晚上","options":["wànshang","wǎnshang","wánshang"],"correct":1},{"say":"小时","options":["xiàoshí","xiǎoshì","xiǎoshí"],"correct":2},{"say":"时间","options":["shíjiān","shǐjiān","shíjián"],"correct":0},{"say":"两个小时","options":["liǎng gè xiǎoshí","liǎng diǎn"],"correct":0}]}'),
  ('hsk2-05-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["早上","七","点"],"hint":"«В семь утра.»"},{"answer":["晚上","十","点","睡觉"],"hint":"«В десять вечера я ложусь спать.»"},{"answer":["你","有","时间","吗"],"hint":"«У тебя есть время?»"}]}'),
  ('hsk2-05-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"早","pinyin":"zǎo","m":"рано","hint":"сверху 日, снизу 十"},{"hanzi":"晚","pinyin":"wǎn","m":"вечер","hint":"слева 日, справа 免"},{"hanzi":"时","pinyin":"shí","m":"время","hint":"слева 日, справа 寸"}]}'),
  ('hsk2-05-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 小时?","options":["час (длительность)","утро","время"],"correct":0},{"q":"Как читается 早上?","options":["zǎoshàng","zǎoshang","zàoshang"],"correct":1},{"q":"Как спросить «У тебя есть время?»","options":["你有时间吗？","有你时间吗？","你时间有吗？"],"correct":0},{"q":"早 состоит из 日 и 十.","tf":true},{"q":"Что значит 晚上?","options":["вечер","день","утро"],"correct":0}]}'),
  ('hsk2-05-2', 1, 'fact', '{"emoji":"⏰","title":"Момент до глагола, длительность после","text":"Главное правило китайского: слово «когда» стоит перед глаголом (我早上七点起床), а «как долго» идёт после него (我学习两个小时). Новые слова — тренажёр для этого правила: 起床 «вставать с кровати», 上班 «идти на работу», 去年 «в прошлом году», 日 «число» (письменная форма 号)."}'),
  ('hsk2-05-2', 2, 'words', '{"title":"Время и дела","items":[{"hanzi":"起床","pinyin":"qǐchuáng","m":"вставать с постели","emoji":"🛏️","ex":{"zh":"我七点起床。","py":"Wǒ qī diǎn qǐchuáng.","m":"Я встаю в семь."}},{"hanzi":"上班","pinyin":"shàngbān","m":"идти на работу","emoji":"💼","ex":{"zh":"他八点上班。","py":"Tā bā diǎn shàngbān.","m":"Он начинает работу в восемь."}},{"hanzi":"去年","pinyin":"qùnián","m":"в прошлом году","emoji":"📆","ex":{"zh":"去年我在北京。","py":"Qùnián wǒ zài Běijīng.","m":"В прошлом году я был в Пекине."}},{"hanzi":"日","pinyin":"rì","m":"число, день (письм.)","emoji":"🔢","ex":{"zh":"十一月二十五日","py":"shíyī yuè èrshíwǔ rì","m":"25 ноября"}}]}'),
  ('hsk2-05-2', 3, 'theory', '{"title":"Когда и сколько: два места в предложении","blocks":[{"t":"table","head":["Что выражаем","Где стоит","Пример"],"rows":[["Момент (когда)","перед глаголом","我早上七点起床。"],["Длительность (сколько)","после глагола","我学习两个小时。"],["Год","перед глаголом","去年我在北京。"]]},{"t":"p","text":"Сначала подлежащее, потом время, потом глагол: 我 + 早上七点 + 起床. А длительность идёт после глагола: 我 + 学习 + 两个小时."},{"t":"tip","text":"日 — письменная форма 号. В разговоре говорят 25号, на письме и в документах 25日."}]}'),
  ('hsk2-05-2', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","早上","七","点","起床"],"hint":"«Я встаю в семь утра.»"},{"answer":["他","八","点","上班"],"hint":"«Он идёт на работу в восемь.»"},{"answer":["我","学习","两","个","小时"],"hint":"«Я учусь два часа.»"},{"answer":["去年","我","在","北京"],"hint":"«В прошлом году я был в Пекине.»"}]}'),
  ('hsk2-05-2', 5, 'quiz', '{"title":"Мини-тест: порядок слов","qs":[{"q":"Где стоит слово «в семь часов»?","options":["перед глаголом","в конце фразы","после глагола"],"correct":0},{"q":"Как сказать «Я учусь два часа»?","options":["两个小时我学习。","我两个小时学习。","我学习两个小时。"],"correct":2},{"q":"去年 значит «в прошлом году».","tf":true}]}'),
  ('hsk2-05-2', 6, 'theory', '{"title":"起床 и 上班: глаголы с объектом","blocks":[{"t":"table","head":["Слово","Состав","Смысл"],"rows":[["起床","起 «подниматься» + 床 «кровать»","вставать с постели"],["上班","上 «идти» + 班 «смена»","идти на работу"],["下班","下 «уходить» + 班 «смена»","заканчивать работу"]]},{"t":"p","text":"Оба слова — «глагол + объект». Нельзя добавлять второй объект: 我起床七点, но не 我起床床."}]}'),
  ('hsk2-05-2', 7, 'game', '{"type":"listen","title":"Слушаем: время и дела","items":[{"say":"起床","options":["qíchuáng","qìchuáng","qǐchuáng"],"correct":2},{"say":"上班","options":["shàngbān","shǎngbān","shàngbàn"],"correct":0},{"say":"去年","options":["qúnián","qùnián","qùniǎn"],"correct":1},{"say":"日","options":["rí","rì","rǐ"],"correct":1},{"say":"我早上七点起床","options":["wǒ wǎnshang qī diǎn qǐchuáng","wǒ zǎoshang qī diǎn qǐchuáng"],"correct":1}]}'),
  ('hsk2-05-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["起床","вставать"],["上班","идти на работу"],["去年","в прошлом году"],["日","число"],["我七点起床","я встаю в семь"]]}'),
  ('hsk2-05-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: порядок слов","cases":[{"buggyText":"我起床七点。","context":"«Я встаю в семь»","options":["我七起床点。","我七点起床。","七点我起床。"],"correct":1},{"buggyText":"我两个小时学习。","context":"«Я учусь два часа»","options":["两个小时学习我。","学习我两个小时。","我学习两个小时。"],"correct":2},{"buggyText":"我去年在北京去年。","context":"«В прошлом году я был в Пекине»","options":["我在北京去年去年。","去年我在北京。","我北京在去年。"],"correct":1}]}'),
  ('hsk2-05-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 上班?","options":["ложиться спать","идти на работу","вставать"],"correct":1},{"q":"Как читается 起床?","options":["qǐchuáng","qíchuáng","qìchuáng"],"correct":0},{"q":"Как сказать «Он идёт на работу в восемь»?","options":["八点他上班点。","他上班八点。","他八点上班。"],"correct":2},{"q":"Длительность стоит перед глаголом.","tf":false},{"q":"Как сказать «25 ноября» на письме?","options":["十一月二十五日","十一月日二十五","月十一二十五日"],"correct":0}]}'),
  ('hsk2-05-3', 1, 'fact', '{"emoji":"🎂","title":"День, когда ты родился","text":"生日 shēngrì — «рождения день»: 生 «рождаться» и 日 «день». Китайцы любят отмечать его длинной лапшой на долголетие. А 已经 yǐjīng «уже» в паре с 了 в конце фразы подчёркивает, что действие или состояние наступило: 我已经二十岁了 «мне уже двадцать»."}'),
  ('hsk2-05-3', 2, 'words', '{"title":"Два слова","items":[{"hanzi":"生日","pinyin":"shēngrì","m":"день рождения","emoji":"🎂","ex":{"zh":"今天是我的生日。","py":"Jīntiān shì wǒ de shēngrì.","m":"Сегодня мой день рождения."}},{"hanzi":"已经","pinyin":"yǐjīng","m":"уже","emoji":"✅","ex":{"zh":"我已经二十岁了。","py":"Wǒ yǐjīng èrshí suì le.","m":"Мне уже двадцать."}}]}'),
  ('hsk2-05-3', 3, 'game', '{"type":"listen","title":"Слушаем: день рождения","items":[{"say":"生日","options":["shěngrì","shēngrì","shēnglì"],"correct":1},{"say":"已经","options":["yǐjīng","yíjīng","yìjīng"],"correct":0},{"say":"今天是我的生日","options":["míngtiān shì wǒ de shēngrì","jīntiān shì wǒ de shēngrì"],"correct":1},{"say":"我已经二十岁了","options":["wǒ yǐjīng èrshí suì le","wǒ yǐjīng shí suì le"],"correct":0},{"say":"现在已经八点了","options":["xiànzài yǐjīng bā diǎn le","xiànzài yǐjīng sān diǎn le"],"correct":0}]}'),
  ('hsk2-05-3', 4, 'game', '{"type":"tone_visualizer","initialTone":3,"title":"Тренажёр голоса: повторите «yǐ» (3 тон)"}'),
  ('hsk2-05-3', 5, 'theory', '{"title":"已经 … 了: «уже наступило»","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我已经二十岁了。","Мне уже двадцать."],["现在已经八点了。","Уже восемь часов."],["他已经起床了。","Он уже встал."]]},{"t":"p","text":"已经 ставится перед глаголом или числом, а 了 — в конце фразы. Вместе они делают предложение «уже». 我的生日是… называет дату: 我的生日是三月五号."},{"t":"tip","text":"Ответ на «Когда у тебя день рождения?» — 你的生日是几月几号？ — 我的生日是…月…号."}]}'),
  ('hsk2-05-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🎂","options":["时间","生日","已经"],"correct":1},{"emoji":"✅","options":["已经","生日","小时"],"correct":0}]}'),
  ('hsk2-05-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["生日","день рождения"],["已经","уже"],["我的生日","мой день рождения"],["已经…了","уже…"],["你的生日是几月几号？","Когда твой день рождения?"]]}'),
  ('hsk2-05-3', 8, 'game', '{"type":"chatsim","title":"WeChat: день рождения","messages":[{"speaker":"Друг","text":"今天是你的生日吗？","pinyin":"Jīntiān shì nǐ de shēngrì ma?","translation":"Сегодня твой день рождения?","options":["对，我二十岁了已经。","不是，我生日已经。","是，我已经二十岁了。"],"correct":2},{"speaker":"Друг","text":"你的生日是几月几号？","pinyin":"Nǐ de shēngrì shì jǐ yuè jǐ hào?","translation":"Когда у тебя день рождения?","options":["我生日是三月五。","我的生日是三月五号。","我的生日三五。"],"correct":1},{"speaker":"Друг","text":"你早上几点起床？","pinyin":"Nǐ zǎoshang jǐ diǎn qǐchuáng?","translation":"Во сколько ты встаёшь?","options":["我早上七点起床。","我七点早上起。","我起床七点早上。"],"correct":0}]}'),
  ('hsk2-05-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["今天","是","我","的","生日"],"hint":"«Сегодня мой день рождения.»"},{"answer":["我","已经","二","十","岁","了"],"hint":"«Мне уже двадцать.»"},{"answer":["我","的","生日","是","三","月","五","号"],"hint":"«Мой день рождения 5 марта.»"}]}'),
  ('hsk2-05-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 已经?","options":["очень","ещё","уже"],"correct":2},{"q":"Как читается 生日?","options":["shěngrì","shēnglì","shēngrì"],"correct":2},{"q":"Как сказать «Мне уже двадцать»?","options":["我已经二十岁了。","我二十岁已经了。","已经我二十岁。"],"correct":0},{"q":"已经 ставится в конец фразы.","tf":false,"explain":"已经 — перед глаголом, 了 — в конце."},{"q":"Как спросить «Когда у тебя день рождения?»","options":["你的生日是几月几号？","几月几你的生日？","你生日几月几？"],"correct":0}]}'),
  ('hsk2-05-4', 1, 'fact', '{"emoji":"📅","title":"Один день учителя","text":"Анна узнаёт у учителя Ван, как проходит её день, и приглашает отметить день рождения."}'),
  ('hsk2-05-4', 2, 'text', '{"title":"День учителя Ван","lines":[{"zh":"安娜：王老师，您每天早上几点起床？","py":"Ānnà: Wáng lǎoshī, nín měi tiān zǎoshang jǐ diǎn qǐchuáng?","m":"Анна: Учитель Ван, во сколько Вы встаёте утром?"},{"zh":"王老师：我每天早上六点起床，七点上班。","py":"Wáng lǎoshī: Wǒ měi tiān zǎoshang liù diǎn qǐchuáng, qī diǎn shàngbān.","m":"Учитель Ван: В шесть, а в семь иду на работу."},{"zh":"安娜：您每天工作几个小时？","py":"Ānnà: Nín měi tiān gōngzuò jǐ gè xiǎoshí?","m":"Анна: Сколько часов Вы работаете?"},{"zh":"王老师：八个小时。晚上七点回家。","py":"Wáng lǎoshī: Bā gè xiǎoshí. Wǎnshang qī diǎn huí jiā.","m":"Учитель Ван: Восемь. Вечером в семь иду домой."},{"zh":"安娜：去年也是这样吗？","py":"Ānnà: Qùnián yě shì zhèyàng ma?","m":"Анна: В прошлом году тоже так? (这样 «так» — новое слово)"},{"zh":"王老师：是。今天是我的生日。","py":"Wáng lǎoshī: Shì. Jīntiān shì wǒ de shēngrì.","m":"Учитель Ван: Да. Сегодня мой день рождения."},{"zh":"安娜：真的吗？您有时间吗？我们晚上去饭店吧！","py":"Ānnà: Zhēn de ma? Nín yǒu shíjiān ma? Wǒmen wǎnshang qù fàndiàn ba!","m":"Анна: Правда? У Вас есть время? Давайте вечером в ресторан!"},{"zh":"王老师：好，谢谢你！","py":"Wáng lǎoshī: Hǎo, xièxie nǐ!","m":"Учитель Ван: Хорошо, спасибо!"}],"qs":[{"q":"Во сколько учитель встаёт?","options":["в восемь","в семь","в шесть"],"correct":2},{"q":"Сколько часов она работает?","options":["семь","восемь","шесть"],"correct":1},{"q":"Сегодня у учителя Ван день рождения.","tf":true},{"q":"Во сколько она возвращается домой?","options":["в девять вечера","в пять вечера","в семь вечера"],"correct":2},{"q":"Анна предлагает пойти в школу.","tf":false,"explain":"Она предлагает пойти в ресторан."},{"q":"Вставьте слово: 我们晚上去饭店___！","options":["吧","吗","了"],"correct":0},{"q":"Как Анна уточняет время?","options":["您几点吗？","您晚上吗？","您有时间吗？"],"correct":2}]}'),
  ('hsk2-05-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["早上六点起床","встаёт в шесть утра"],["七点上班","идёт на работу в семь"],["八个小时","восемь часов"],["晚上七点回家","в семь вечера идёт домой"],["今天是我的生日","сегодня мой день рождения"]]}'),
  ('hsk2-05-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"您每天早上几点起床","options":["nín měi tiān zǎoshang jǐ diǎn qǐchuáng","nín měi tiān wǎnshang jǐ diǎn qǐchuáng"],"correct":0},{"say":"我七点上班","options":["wǒ qī diǎn qǐchuáng","wǒ qī diǎn shàngbān"],"correct":1},{"say":"八个小时","options":["bā gè xiǎoshí","liù gè xiǎoshí"],"correct":0},{"say":"今天是我的生日","options":["míngtiān shì wǒ de shēngrì","jīntiān shì wǒ de shēngrì"],"correct":1}]}'),
  ('hsk2-05-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: рабочий день","cases":[{"buggyText":"我早上起床六点。","context":"«Я встаю в шесть утра»","options":["我早上六点起床。","我六起床点早上。","六点我起床早上。"],"correct":0},{"buggyText":"我工作八小时个。","context":"«Я работаю восемь часов»","options":["我八个小时工作。","我工作八个小时。","我工作个八小时。"],"correct":1},{"buggyText":"今天是生日我的。","context":"«Сегодня мой день рождения»","options":["我的今天生日是。","今天是我的生日。","今天生日是我的。"],"correct":1}]}'),
  ('hsk2-05-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я встаю в шесть утра»?","options":["早上我起床六点。","我早上六点起床。","我起床早上六点。"],"correct":1},{"q":"Как читается 晚上?","options":["wǎnshang","wànshang","wánshang"],"correct":0},{"q":"Анна приглашает учителя в ресторан.","tf":true}]}'),
  ('hsk2-05-5', 1, 'fact', '{"emoji":"🗓️","title":"Составьте свой день","text":"Сегодня вы расписываете день по часам: во сколько встаёте, сколько часов работаете, когда день рождения. Слова глав 1–5 HSK 2."}'),
  ('hsk2-05-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"晚","correctRadicals":["日","免"],"title":"Пазл: соберите 晚"}'),
  ('hsk2-05-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"早","radicals":["日","十","月"],"correctOrder":["日","十"],"explain":"Сверху 日, внизу 十."},{"targetHanzi":"起","radicals":["走","己","巳"],"correctOrder":["走","己"],"explain":"Слева 走, справа 己."},{"targetHanzi":"床","radicals":["广","木","米"],"correctOrder":["广","木"],"explain":"Сверху 广, внизу 木."}]}'),
  ('hsk2-05-5', 4, 'game', '{"type":"build","title":"Мастерская расписания","items":[{"target":"(Утро)","answer":["我","早上","七","点","起床"],"hint":"«Я встаю в семь утра.»"},{"target":"(День)","answer":["我","每","天","学习","两","个","小时"],"hint":"«Я каждый день учусь два часа.»"},{"target":"(Вечер)","answer":["晚上","我","回","家"],"hint":"«Вечером я иду домой.»"},{"target":"(Праздник)","answer":["我","的","生日","是","三","月","五","号"],"hint":"«Мой день рождения 5 марта.»"}]}'),
  ('hsk2-05-5', 5, 'theory', '{"title":"Образец расписания","blocks":[{"t":"table","head":["Время","Фраза"],"rows":[["Утро","早上七点起床。"],["День","我学习两个小时。"],["Вечер","晚上八点回家。"],["Праздник","我的生日是三月五号。"]]}]}'),
  ('hsk2-05-5', 6, 'game', '{"type":"chatsim","title":"WeChat: расписание","messages":[{"speaker":"Друг","text":"你每天几点起床？","pinyin":"Nǐ měi tiān jǐ diǎn qǐchuáng?","translation":"Во сколько ты встаёшь?","options":["我七点起床吗。","我七点起床。","我起床七点。"],"correct":1},{"speaker":"Друг","text":"你每天学习几个小时？","pinyin":"Nǐ měi tiān xuéxí jǐ gè xiǎoshí?","translation":"Сколько часов ты учишься?","options":["我两个小时学习。","我学习小时两个。","我学习两个小时。"],"correct":2},{"speaker":"Друг","text":"你的生日是几月几号？","pinyin":"Nǐ de shēngrì shì jǐ yuè jǐ hào?","translation":"Когда твой день рождения?","options":["我生日三五。","我的生日是三月五号。","三月生日。"],"correct":1}]}'),
  ('hsk2-05-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["日 + 十","早"],["日 + 免","晚"],["走 + 己","起"],["广 + 木","床"]]}'),
