  ('hsk2-05-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я каждый день учусь два часа»?","options":["我两个小时每天学习。","我学习每天两小时个。","我每天学习两个小时。"],"correct":2},{"q":"Из каких частей состоит 早?","options":["日 и 十","亻 и 也","女 и 子"],"correct":0},{"q":"День рождения по-китайски — 生日.","tf":true}]}'),
