  ('hsk2-05-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"早上","options":["xiǎoshí","wǎnshang","zǎoshang"],"correct":2},{"say":"晚上","options":["zǎoshang","wǎnshang"],"correct":1},{"say":"两个小时","options":["liǎng gè xiǎoshí","liǎng diǎn"],"correct":0},{"say":"我七点起床","options":["wǒ qī diǎn qǐchuáng","wǒ qī diǎn shàngbān"],"correct":0},{"say":"今天是我的生日","options":["jīntiān shì wǒ de shēngrì","míngtiān shì wǒ de shēngrì"],"correct":0},{"say":"我已经二十岁了","options":["wǒ yǐjīng èrshí suì le","wǒ yǐjīng shí suì le"],"correct":0}]}'),
  ('hsk2-05-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🌅","options":["早上","时间","晚上"],"correct":0},{"emoji":"⏳","options":["小时","早上","时间"],"correct":0},{"emoji":"🛏️","options":["上班","生日","起床"],"correct":2},{"emoji":"🎂","options":["生日","已经","日"],"correct":0}]}'),
  ('hsk2-05-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["早上","утро"],["晚上","вечер"],["小时","час (длительность)"],["时间","время"],["起床","вставать"],["上班","идти на работу"],["去年","в прошлом году"],["日","число"],["生日","день рождения"],["已经","уже"]]}'),
  ('hsk2-05-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Я встаю в семь утра»?","options":["我早上七点起床。","我起床早上七点。","早上我七起床点。"],"correct":0},{"q":"Как сказать «Я учусь два часа»?","options":["我学习小时两个。","我学习两个小时。","我两个小时学习。"],"correct":1},{"q":"Что значит 已经?","options":["уже","очень","ещё"],"correct":0},{"q":"Длительность стоит после глагола.","tf":true},{"q":"Как читается 起床?","options":["qíchuáng","qìchuáng","qǐchuáng"],"correct":2},{"q":"Как спросить «Когда у тебя день рождения?»","options":["几月几你的生日？","你的生日是几月几号？","你生日几月几？"],"correct":1},{"q":"Момент времени стоит после глагола.","tf":false},{"q":"Как сказать «Мне уже двадцать»?","options":["我二十岁已经了。","已经我二十岁。","我已经二十岁了。"],"correct":2},{"q":"Что значит 去年?","options":["завтра","в прошлом году","сегодня"],"correct":1},{"q":"Как сказать «25 ноября» на письме?","options":["月十一二十五日","十一月日二十五","十一月二十五日"],"correct":2}]}'),
  ('hsk2-05-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","早上","七","点","起床"],"hint":"«Я встаю в семь утра.»"},{"answer":["我","学习","两","个","小时"],"hint":"«Я учусь два часа.»"},{"answer":["今天","是","我","的","生日"],"hint":"«Сегодня мой день рождения.»"},{"answer":["我","已经","二","十","岁","了"],"hint":"«Мне уже двадцать.»"}]}'),
  ('hsk2-05-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我起床七点。","context":"«Я встаю в семь»","options":["我七起床点。","七点我起床。","我七点起床。"],"correct":2},{"buggyText":"我两个小时学习。","context":"«Я учусь два часа»","options":["学习我两个小时。","我学习两个小时。","两个小时学习我。"],"correct":1},{"buggyText":"我已经二十岁。","context":"«Мне уже двадцать»","options":["已经我二十岁。","我已经二十岁了。","我二十已经岁。"],"correct":1}]}'),
  ('hsk2-05-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"你每天几点起床？","pinyin":"Nǐ měi tiān jǐ diǎn qǐchuáng?","translation":"Во сколько ты встаёшь?","options":["我早上七点起床。","我起床早上七点。","我七点早上起。"],"correct":0},{"speaker":"Друг","text":"你的生日是几月几号？","pinyin":"Nǐ de shēngrì shì jǐ yuè jǐ hào?","translation":"Когда твой день рождения?","options":["我生日三五。","三月生日。","我的生日是三月五号。"],"correct":2}]}'),
  ('hsk2-05-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"晚","pinyin":"wǎn","m":"вечер","hint":"日 + 免"},{"hanzi":"时","pinyin":"shí","m":"время","hint":"日 + 寸"},{"hanzi":"日","pinyin":"rì","m":"день","hint":"рамка"}]}'),
  ('hsk2-05-6', 10, 'recall', '{"words":[{"hanzi":"早上","pinyin":"zǎoshang","m":"утро"},{"hanzi":"晚上","pinyin":"wǎnshang","m":"вечер"},{"hanzi":"小时","pinyin":"xiǎoshí","m":"час (длительность)"},{"hanzi":"时间","pinyin":"shíjiān","m":"время"},{"hanzi":"起床","pinyin":"qǐchuáng","m":"вставать"},{"hanzi":"上班","pinyin":"shàngbān","m":"идти на работу"},{"hanzi":"去年","pinyin":"qùnián","m":"в прошлом году"},{"hanzi":"日","pinyin":"rì","m":"число"},{"hanzi":"生日","pinyin":"shēngrì","m":"день рождения"},{"hanzi":"已经","pinyin":"yǐjīng","m":"уже"}],"tf":[{"zh":"我起床七点。","py":"wǒ qǐchuáng qī diǎn.","m":"Я встаю в семь.","ok":false,"explain":"Момент перед глаголом: 我七点起床."},{"zh":"我学习两个小时。","py":"wǒ xuéxí liǎng gè xiǎoshí.","m":"Я учусь два часа.","ok":true}],"sentences":[{"zh":"我早上七点起床。","tokens":["我","早上","七","点","起床"],"m":"Я встаю в семь утра."},{"zh":"我学习两个小时。","tokens":["我","学习","两","个","小时"],"m":"Я учусь два часа."},{"zh":"我已经二十岁了。","tokens":["我","已经","二","十","岁","了"],"m":"Мне уже двадцать."}]}'),
  ('hsk2-06-1', 1, 'fact', '{"emoji":"🚪","title":"Солнце сквозь дверь","text":"Знак 间 «промежуток» нарисован как 门 «дверь» с 日 «солнцем» внутри: солнце светит в щель между створками. Отсюда 房间 «комната» (房 «дом» + 间 «промежуток»). А знак 课 «урок» состоит из 讠 «речь» и 果 «плод»: урок должен приносить плоды."}'),
  ('hsk2-06-1', 2, 'words', '{"title":"Комната и класс","items":[{"hanzi":"房间","pinyin":"fángjiān","m":"комната","emoji":"🛏️","ex":{"zh":"我的房间很大。","py":"Wǒ de fángjiān hěn dà.","m":"Моя комната большая."}},{"hanzi":"教室","pinyin":"jiàoshì","m":"класс, аудитория","emoji":"🏫","ex":{"zh":"教室在学校里。","py":"Jiàoshì zài xuéxiào lǐ.","m":"Класс в школе."}},{"hanzi":"门","pinyin":"mén","m":"дверь, ворота","emoji":"🚪","ex":{"zh":"门在前面。","py":"Mén zài qiánmian.","m":"Дверь впереди."}},{"hanzi":"课","pinyin":"kè","m":"урок, занятие","emoji":"📚","ex":{"zh":"今天有课。","py":"Jīntiān yǒu kè.","m":"Сегодня есть урок."}}]}'),
  ('hsk2-06-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🛏️","options":["课","教室","房间"],"correct":2},{"emoji":"🏫","options":["门","教室","房间"],"correct":1},{"emoji":"🚪","options":["门","课","房间"],"correct":0},{"emoji":"📚","options":["课","门","教室"],"correct":0}]}'),
  ('hsk2-06-1', 4, 'theory', '{"title":"Где находится, что делается","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["教室在学校里。","Jiàoshì zài xuéxiào lǐ.","Класс в школе."],["门在教室前面。","Mén zài jiàoshì qiánmian.","Дверь перед классом."],["今天有课。","Jīntiān yǒu kè.","Сегодня есть урок."],["我在房间里。","Wǒ zài fángjiān lǐ.","Я в комнате."]]},{"t":"p","text":"Схема «место + 在 + место» вы знаете из HSK 1. Новое: 课 считают словом 节, но на первом шаге достаточно 有课 «есть урок» и 上课 «идти на урок»."},{"t":"tip","text":"Знак 门 (дверь) входит и в другие слова: 问, 间, 闻. Запомните его как рамку двери."}]}'),
  ('hsk2-06-1', 5, 'quiz', '{"title":"Мини-тест: комната и класс","qs":[{"q":"Как сказать «Сегодня есть урок»?","options":["今天有课。","有今天课。","今天课有。"],"correct":0},{"q":"Что значит 房间?","options":["класс","комната","дверь"],"correct":1},{"q":"门 — это «дверь».","tf":true}]}'),
  ('hsk2-06-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["房间","комната"],["教室","класс"],["门","дверь"],["课","урок"],["有课","есть урок"]]}'),
  ('hsk2-06-1', 7, 'game', '{"type":"listen","title":"Слушаем: комната и класс","items":[{"say":"房间","options":["fángjiān","fángjián","fāngjiān"],"correct":0},{"say":"教室","options":["jiāoshì","jiàoshí","jiàoshì"],"correct":2},{"say":"门","options":["mèn","mén","měn"],"correct":1},{"say":"课","options":["ké","kě","kè"],"correct":2},{"say":"教室在学校里","options":["jiàoshì zài xuéxiào lǐ","jiàoshì zài xuéxiào qiánmian"],"correct":0}]}'),
  ('hsk2-06-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","的","房间","很","大"],"hint":"«Моя комната большая.»"},{"answer":["教室","在","学校","里"],"hint":"«Класс в школе.»"},{"answer":["今天","有","课"],"hint":"«Сегодня есть урок.»"}]}'),
  ('hsk2-06-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"门","pinyin":"mén","m":"дверь","hint":"точка, вертикаль, рамка"},{"hanzi":"间","pinyin":"jiān","m":"промежуток","hint":"门 с 日 внутри"},{"hanzi":"课","pinyin":"kè","m":"урок","hint":"слева 讠, справа 果"}]}'),
  ('hsk2-06-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 课?","options":["урок","дверь","комната"],"correct":0},{"q":"Как читается 教室?","options":["jiàoshí","jiàoshì","jiāoshì"],"correct":1},{"q":"Как сказать «Я в комнате»?","options":["在我房间里。","我房间在里。","我在房间里。"],"correct":2},{"q":"间 содержит 门 и 日.","tf":true},{"q":"Что значит 教室?","options":["комната","класс","дом"],"correct":1}]}'),
  ('hsk2-06-2', 1, 'fact', '{"emoji":"❓","title":"Рот у двери","text":"Знак 问 «спрашивать» — это 口 «рот» в 门 «двери»: человек стучится и спрашивает. Глагол 问 управляет человеком без предлога: 问老师 «спросить у учителя». Слово 问题 wèntí значит «вопрос» и «проблема», а 题 tí — «задание, вопрос в тесте». Всё это нужно для 考试 kǎoshì «экзамен»."}'),
  ('hsk2-06-2', 2, 'words', '{"title":"Вопросы и экзамен","items":[{"hanzi":"问","pinyin":"wèn","m":"спрашивать","emoji":"🙋","ex":{"zh":"我问老师。","py":"Wǒ wèn lǎoshī.","m":"Я спрашиваю учителя."}},{"hanzi":"问题","pinyin":"wèntí","m":"вопрос, проблема","emoji":"❓","ex":{"zh":"我有一个问题。","py":"Wǒ yǒu yí gè wèntí.","m":"У меня есть вопрос."}},{"hanzi":"题","pinyin":"tí","m":"задание, тема","emoji":"📝","ex":{"zh":"第一题","py":"dì-yī tí","m":"первое задание"}},{"hanzi":"考试","pinyin":"kǎoshì","m":"экзамен, сдавать экзамен","emoji":"📃","ex":{"zh":"今天考试。","py":"Jīntiān kǎoshì.","m":"Сегодня экзамен."}}]}'),
  ('hsk2-06-2', 3, 'theory', '{"title":"问 и 问题","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我问老师。","Я спрашиваю учителя."],["我问你一个问题。","Я задам тебе вопрос."],["你有问题吗？","У тебя есть вопрос?"],["没有问题。","Вопросов нет."]]},{"t":"p","text":"问 ставится перед человеком: 问老师, а сам вопрос идёт после: 问你一个问题. Слова 问题 и 题 различаются: 问题 — вопрос вообще, 题 — конкретное задание."},{"t":"tip","text":"考试 — это и «экзамен» (существительное), и «сдавать экзамен» (глагол): 今天考试 «сегодня экзамен»."}]}'),
  ('hsk2-06-2', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","问","老师"],"hint":"«Я спрашиваю учителя.»"},{"answer":["我","有","一个","问题"],"hint":"«У меня есть вопрос.»"},{"answer":["今天","考试"],"hint":"«Сегодня экзамен.»"},{"answer":["第一","题","很","长"],"hint":"«Первое задание длинное.»"}]}'),
  ('hsk2-06-2', 5, 'quiz', '{"title":"Мини-тест: 问 и 考试","qs":[{"q":"Как спросить у учителя?","options":["老师问","问的老师","问老师"],"correct":2},{"q":"问 стоит после вопроса.","tf":false,"explain":"问 стоит перед человеком."},{"q":"Что значит 考试?","options":["задание","вопрос","экзамен"],"correct":2}]}'),
  ('hsk2-06-2', 6, 'theory', '{"title":"题, 问题 и 考试","blocks":[{"t":"table","head":["Слово","Смысл","Пример"],"rows":[["题","задание, вопрос в тесте","第一题"],["问题","вопрос, проблема","有问题吗？"],["考试","экзамен","今天考试"]]},{"t":"p","text":"В тесте говорят «第一题, 第二题»: 第 + число + 题. А на уроке: 你有问题吗？"}]}'),
  ('hsk2-06-2', 7, 'game', '{"type":"listen","title":"Слушаем: вопросы","items":[{"say":"问","options":["wěn","wèn","wén"],"correct":1},{"say":"问题","options":["wèntí","wéntí","wèntǐ"],"correct":0},{"say":"题","options":["tì","tǐ","tí"],"correct":2},{"say":"考试","options":["kàoshì","kǎoshí","kǎoshì"],"correct":2},{"say":"我有一个问题","options":["wǒ yǒu yí gè tí","wǒ yǒu yí gè wèntí"],"correct":1}]}'),
  ('hsk2-06-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["问","спрашивать"],["问题","вопрос"],["题","задание"],["考试","экзамен"],["第一题","первое задание"]]}'),
  ('hsk2-06-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: вопросы","cases":[{"buggyText":"我老师问。","context":"«Я спрашиваю учителя»","options":["我问老师。","问我老师。","老师我问。"],"correct":0},{"buggyText":"我有问题一个。","context":"«У меня есть вопрос»","options":["我一个有问题。","有一个问题我。","我有一个问题。"],"correct":2},{"buggyText":"考试今天。","context":"«Сегодня экзамен»","options":["考试今天吗。","今天考试。","今天考吗试。"],"correct":1}]}'),
  ('hsk2-06-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как читается 问题?","options":["wèntí","wéntí","wěntí"],"correct":0},{"q":"Как сказать «первое задание»?","options":["题第一","第一题","一第题"],"correct":1},{"q":"问题 значит «вопрос».","tf":true},{"q":"Как спросить «У тебя есть вопрос?»","options":["有你问题吗？","你有问题吗？","你问题有吗？"],"correct":1},{"q":"Что значит 题?","options":["урок","дверь","задание"],"correct":2}]}'),
  ('hsk2-06-3', 1, 'fact', '{"emoji":"💡","title":"«Услышать и понять»","text":"Слово 懂 dǒng «понимать» содержит ключ 忄 «сердце»: понять — это почувствовать сердцем. Часто его присоединяют к глаголу и получают результат: 听懂 tīngdǒng «понять на слух», 看懂 kàndǒng «понять, прочитав». А 回答 huídá «отвечать» — это «возвращаться со словом»: 回 + 答."}'),
  ('hsk2-06-3', 2, 'words', '{"title":"Ответить и понять","items":[{"hanzi":"回答","pinyin":"huídá","m":"отвечать, ответ","emoji":"💬","ex":{"zh":"请回答第一题。","py":"Qǐng huídá dì-yī tí.","m":"Пожалуйста, ответьте на первое задание."}},{"hanzi":"懂","pinyin":"dǒng","m":"понимать","emoji":"💡","ex":{"zh":"我懂了。","py":"Wǒ dǒng le.","m":"Я понял."}}]}'),
  ('hsk2-06-3', 3, 'game', '{"type":"listen","title":"Слушаем: понять и ответить","items":[{"say":"回答","options":["huídá","huídǎ","huìdá"],"correct":0},{"say":"懂","options":["dóng","dòng","dǒng"],"correct":2},{"say":"我懂了","options":["wǒ dǒng le","wǒ dòng le"],"correct":0},{"say":"听懂了","options":["tīngdǒng le","tīngdòng le"],"correct":0},{"say":"请回答","options":["qǐng huídá","qǐng huídǎ"],"correct":0}]}'),
  ('hsk2-06-3', 4, 'game', '{"type":"tone_visualizer","initialTone":3,"title":"Тренажёр голоса: повторите «dǒng» (3 тон)"}'),
  ('hsk2-06-3', 5, 'theory', '{"title":"懂 и результат действия","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我懂了。","Я понял."],["我听懂了。","Я понял на слух."],["我看懂了。","Я понял, прочитав."],["我没听懂。","Я не понял на слух."]]},{"t":"p","text":"听懂 — «услышал и понял»: сам результат. Отрицание строят с 没: 我没听懂. Слово 回答 стоит перед объектом: 回答问题 «ответить на вопрос»."},{"t":"tip","text":"Не говорите 我不听懂: для результата нужно 没, а не 不."}]}'),
  ('hsk2-06-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"💬","options":["问","懂","回答"],"correct":2},{"emoji":"💡","options":["回答","懂","问"],"correct":1}]}'),
  ('hsk2-06-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["回答","отвечать"],["懂","понимать"],["听懂","понять на слух"],["看懂","понять, прочитав"],["回答问题","ответить на вопрос"]]}'),
  ('hsk2-06-3', 8, 'game', '{"type":"chatsim","title":"WeChat: урок","messages":[{"speaker":"Учитель","text":"你有问题吗？","pinyin":"Nǐ yǒu wèntí ma?","translation":"У тебя есть вопрос?","options":["有，我问题懂。","有，第一题我不懂。","没有，我问老师。"],"correct":1},{"speaker":"Учитель","text":"你听懂了吗？","pinyin":"Nǐ tīngdǒng le ma?","translation":"Ты понял на слух?","options":["不是，我听不。","对，我再说。","没有，请再说一次。"],"correct":2},{"speaker":"Учитель","text":"第一题的回答是三。","pinyin":"Dì-yī tí de huídá shì sān.","translation":"Ответ на первое задание — три.","options":["对不起，再见。","不客气。","我懂了，谢谢老师！"],"correct":2}]}'),
  ('hsk2-06-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","懂","了"],"hint":"«Я понял.»"},{"answer":["我","没","听懂"],"hint":"«Я не понял на слух.»"},{"answer":["请","回答","第一","题"],"hint":"«Ответьте на первое задание.»"}]}'),
  ('hsk2-06-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 懂?","options":["спрашивать","понимать","отвечать"],"correct":1},{"q":"Как читается 回答?","options":["huídǎ","huìdá","huídá"],"correct":2},{"q":"Как сказать «Я не понял на слух»?","options":["我不听懂。","我听没懂。","我没听懂。"],"correct":2},{"q":"К 懂 для отрицания ставят 没.","tf":true},{"q":"Как сказать «ответить на вопрос»?","options":["答回问题","回答问题","问题回答"],"correct":1}]}'),
  ('hsk2-06-4', 1, 'fact', '{"emoji":"🏫","title":"Сегодня экзамен","text":"Анна сдаёт экзамен и просит учителя повторить задание. В диалоге встретятся 教室, 课, 考试, 问题, 题, 回答, 懂."}'),
  ('hsk2-06-4', 2, 'text', '{"title":"На экзамене","lines":[{"zh":"老师：大家好！请坐。今天我们有一次考试。","py":"Lǎoshī: Dàjiā hǎo! Qǐng zuò. Jīntiān wǒmen yǒu yí cì kǎoshì.","m":"Учитель: Здравствуйте! Садитесь. Сегодня у нас экзамен."},{"zh":"安娜：老师，我有一个问题。","py":"Ānnà: Lǎoshī, wǒ yǒu yí gè wèntí.","m":"Анна: Учитель, у меня есть вопрос."},{"zh":"老师：你问吧。","py":"Lǎoshī: Nǐ wèn ba.","m":"Учитель: Спрашивай."},{"zh":"安娜：第一题我不懂。","py":"Ānnà: Dì-yī tí wǒ bù dǒng.","m":"Анна: Первое задание я не поняла."},{"zh":"老师：你听懂了吗？","py":"Lǎoshī: Nǐ tīngdǒng le ma?","m":"Учитель: Ты поняла на слух?"},{"zh":"安娜：没有。请您再说一次。","py":"Ānnà: Méiyǒu. Qǐng nín zài shuō yí cì.","m":"Анна: Нет. Повторите, пожалуйста."},{"zh":"老师：好。第一题的回答是三。","py":"Lǎoshī: Hǎo. Dì-yī tí de huídá shì sān.","m":"Учитель: Хорошо. Ответ на первое задание — три."},{"zh":"安娜：我懂了，谢谢老师！","py":"Ānnà: Wǒ dǒng le, xièxie lǎoshī!","m":"Анна: Я поняла, спасибо!"}],"qs":[{"q":"Что сегодня в классе?","options":["урок рисования","экзамен","каникулы"],"correct":1},{"q":"Чего не поняла Анна?","options":["второго","первого задания","всего экзамена"],"correct":1},{"q":"Анна просит учителя повторить.","tf":true},{"q":"Вставьте слово: 你问___。","options":["吗","了","吧"],"correct":2},{"q":"Ответ на первое задание — четыре.","tf":false,"explain":"Учитель говорит: 三."},{"q":"Что отвечает Анна на 你听懂了吗？","options":["是","有","没有"],"correct":2},{"q":"Как заканчивает Анна?","options":["我不懂","再见","我懂了"],"correct":2}]}'),
  ('hsk2-06-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["今天有考试","сегодня экзамен"],["我有一个问题","у меня есть вопрос"],["第一题我不懂","первое задание я не поняла"],["请您再说一次","повторите, пожалуйста"],["我懂了","я поняла"]]}'),
  ('hsk2-06-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"今天我们有一次考试","options":["míngtiān wǒmen yǒu yí cì kǎoshì","jīntiān wǒmen yǒu yí cì kǎoshì"],"correct":1},{"say":"第一题我不懂","options":["dì-yī tí wǒ bù dǒng","dì-èr tí wǒ bù dǒng"],"correct":0},{"say":"请您再说一次","options":["qǐng nín zài shuō yíxià","qǐng nín zài shuō yí cì"],"correct":1},{"say":"我懂了","options":["wǒ dǒng le","wǒ méi dǒng"],"correct":0}]}'),
  ('hsk2-06-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: на экзамене","cases":[{"buggyText":"我不听懂。","context":"«Я не понял на слух»","options":["我没听懂。","不我听懂。","我听不懂吗。"],"correct":0},{"buggyText":"第一题我问。","context":"«Первое задание я не понял»","options":["我第一题问不。","第一题我不懂。","题第一我懂。"],"correct":1},{"buggyText":"请您再说一下次。","context":"«Повторите ещё раз»","options":["请您说再一次。","请再次一您说。","请您再说一次。"],"correct":2}]}'),
  ('hsk2-06-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Сегодня экзамен»?","options":["今天考试。","考试今天。","今天考吗试。"],"correct":0},{"q":"Как читается 考试?","options":["kǎoshí","kǎoshì","kàoshì"],"correct":1},{"q":"Анна задаёт учителю вопрос.","tf":true}]}'),
  ('hsk2-06-5', 1, 'fact', '{"emoji":"🏫","title":"Создайте урок","text":"Сегодня вы описываете класс, задаёте вопросы и «отвечаете» на задания. Слова глав 1–6 HSK 2."}'),
  ('hsk2-06-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"课","correctRadicals":["讠","果"],"title":"Пазл: соберите 课"}'),
  ('hsk2-06-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"问","radicals":["门","口","日"],"correctOrder":["门","口"],"explain":"Рот 口 внутри двери 门."},{"targetHanzi":"间","radicals":["门","日","月"],"correctOrder":["门","日"],"explain":"Солнце 日 внутри двери 门."},{"targetHanzi":"懂","radicals":["忄","董","亻"],"correctOrder":["忄","董"],"explain":"Слева 忄 «сердце», справа 董."}]}'),
  ('hsk2-06-5', 4, 'game', '{"type":"build","title":"Мастерская класса","items":[{"target":"(Класс)","answer":["教室","在","学校","里"],"hint":"«Класс в школе.»"},{"target":"(Вопрос)","answer":["我","有","一个","问题"],"hint":"«У меня есть вопрос.»"},{"target":"(Ответ)","answer":["我","懂","了"],"hint":"«Я понял.»"},{"target":"(Экзамен)","answer":["今天","我们","考试"],"hint":"«Сегодня у нас экзамен.»"}]}'),
  ('hsk2-06-5', 5, 'theory', '{"title":"Образец диалога на уроке","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["Вопрос","老师，我有一个问题。"],["Уточнение","第一题我不懂。"],["Просьба","请您再说一次。"],["Итог","我懂了，谢谢！"]]}]}'),
  ('hsk2-06-5', 6, 'game', '{"type":"chatsim","title":"WeChat: вопрос учителю","messages":[{"speaker":"Учитель","text":"今天我们有考试。","pinyin":"Jīntiān wǒmen yǒu kǎoshì.","translation":"Сегодня у нас экзамен.","options":["不客气。","好，我有一个问题。","对不起，再见。"],"correct":1},{"speaker":"Учитель","text":"你有什么问题？","pinyin":"Nǐ yǒu shénme wèntí?","translation":"Какой у тебя вопрос?","options":["我没问。","我问题有。","第一题我不懂。"],"correct":2},{"speaker":"Учитель","text":"第一题的回答是三。","pinyin":"Dì-yī tí de huídá shì sān.","translation":"Ответ на первое задание — три.","options":["是，不客气。","我不懂，再见。","我懂了，谢谢老师！"],"correct":2}]}'),
  ('hsk2-06-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["讠 + 果","课"],["门 + 口","问"],["门 + 日","间"],["忄 + 董","懂"]]}'),
  ('hsk2-06-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"问","pinyin":"wèn","m":"спрашивать","hint":"门 + 口"},{"hanzi":"懂","pinyin":"dǒng","m":"понимать","hint":"忄 + 董"},{"hanzi":"题","pinyin":"tí","m":"задание","hint":"слева 是, справа 页"}]}'),
  ('hsk2-06-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «У меня есть вопрос»?","options":["有我问题。","我问题有。","我有一个问题。"],"correct":2},{"q":"Из каких частей состоит 问?","options":["女 и 子","门 и 口","亻 и 也"],"correct":1},{"q":"懂 содержит 忄 «сердце».","tf":true}]}'),
  ('hsk2-06-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 6 (HSK 2)","text":"房间, 教室, 门, 课, 考试, 题, 问题, 问, 回答 и 懂."}'),
  ('hsk2-06-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"房间","options":["fángjiān","jiàoshì","kǎoshì"],"correct":0},{"say":"教室在学校里","options":["fángjiān zài xuéxiào lǐ","jiàoshì zài xuéxiào lǐ"],"correct":1},{"say":"我有一个问题","options":["wǒ yǒu yí gè wèntí","wǒ yǒu yí gè tí"],"correct":0},{"say":"第一题我不懂","options":["dì-yī tí wǒ bù dǒng","dì-yī tí wǒ bù wèn"],"correct":0},{"say":"我没听懂","options":["wǒ méi tīngdǒng","wǒ bù tīngdǒng"],"correct":0},{"say":"请回答","options":["qǐng wèn","qǐng huídá"],"correct":1}]}'),
  ('hsk2-06-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🛏️","options":["房间","教室","课"],"correct":0},{"emoji":"🚪","options":["课","门","题"],"correct":1},{"emoji":"📃","options":["懂","考试","问"],"correct":1},{"emoji":"💡","options":["回答","懂","问"],"correct":1}]}'),
  ('hsk2-06-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["房间","комната"],["教室","класс"],["门","дверь"],["课","урок"],["考试","экзамен"],["题","задание"],["问题","вопрос"],["问","спрашивать"],["回答","отвечать"],["懂","понимать"]]}'),
  ('hsk2-06-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «У меня есть вопрос»?","options":["我问题有。","我有一个问题。","有我问题。"],"correct":1},{"q":"Как сказать «Я понял»?","options":["懂我了。","我了懂。","我懂了。"],"correct":2},{"q":"Как сказать «Я не понял на слух»?","options":["我没听懂。","我不听懂。","我听没懂。"],"correct":0},{"q":"问 стоит перед человеком.","tf":true},{"q":"Как читается 问题?","options":["wèntí","wéntí","wěntí"],"correct":0},{"q":"Что значит 考试?","options":["урок","экзамен","задание"],"correct":1},{"q":"К 听懂 для отрицания ставят 不.","tf":false},{"q":"Как сказать «первое задание»?","options":["一第题","题第一","第一题"],"correct":2},{"q":"Что значит 课?","options":["дверь","комната","урок"],"correct":2},{"q":"Как спросить «У тебя есть вопрос?»","options":["你问题有吗？","有你问题吗？","你有问题吗？"],"correct":2}]}'),
  ('hsk2-06-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","有","一个","问题"],"hint":"«У меня есть вопрос.»"},{"answer":["我","问","老师"],"hint":"«Я спрашиваю учителя.»"},{"answer":["今天","考试"],"hint":"«Сегодня экзамен.»"},{"answer":["我","懂","了"],"hint":"«Я понял.»"}]}'),
  ('hsk2-06-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我老师问。","context":"«Я спрашиваю учителя»","options":["问我老师。","我问老师。","老师我问。"],"correct":1},{"buggyText":"我不听懂。","context":"«Я не понял на слух»","options":["我听不懂吗。","不我听懂。","我没听懂。"],"correct":2},{"buggyText":"考试今天。","context":"«Сегодня экзамен»","options":["今天考吗试。","今天考试。","考试今天吗。"],"correct":1}]}'),
  ('hsk2-06-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Учитель","text":"你有问题吗？","pinyin":"Nǐ yǒu wèntí ma?","translation":"У тебя есть вопрос?","options":["有，我问题懂。","有，第一题我不懂。","没有，我问老师。"],"correct":1},{"speaker":"Учитель","text":"好。第一题的回答是三。","pinyin":"Hǎo. Dì-yī tí de huídá shì sān.","translation":"Хорошо. Ответ — три.","options":["我不懂，再见。","不客气。","我懂了，谢谢！"],"correct":2}]}'),
  ('hsk2-06-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"问","pinyin":"wèn","m":"спрашивать","hint":"门 + 口"},{"hanzi":"课","pinyin":"kè","m":"урок","hint":"讠 + 果"},{"hanzi":"门","pinyin":"mén","m":"дверь","hint":"рамка двери"}]}'),
  ('hsk2-06-6', 10, 'recall', '{"words":[{"hanzi":"房间","pinyin":"fángjiān","m":"комната"},{"hanzi":"教室","pinyin":"jiàoshì","m":"класс"},{"hanzi":"门","pinyin":"mén","m":"дверь"},{"hanzi":"课","pinyin":"kè","m":"урок"},{"hanzi":"考试","pinyin":"kǎoshì","m":"экзамен"},{"hanzi":"题","pinyin":"tí","m":"задание"},{"hanzi":"问题","pinyin":"wèntí","m":"вопрос"},{"hanzi":"问","pinyin":"wèn","m":"спрашивать"},{"hanzi":"回答","pinyin":"huídá","m":"отвечать"},{"hanzi":"懂","pinyin":"dǒng","m":"понимать"}],"tf":[{"zh":"我不听懂。","py":"wǒ bù tīngdǒng.","m":"Я не понял на слух.","ok":false,"explain":"Правильно: 我没听懂."},{"zh":"我有一个问题。","py":"wǒ yǒu yí gè wèntí.","m":"У меня есть вопрос.","ok":true}],"sentences":[{"zh":"我有一个问题。","tokens":["我","有","一个","问题"],"m":"У меня есть вопрос."},{"zh":"我问老师。","tokens":["我","问","老师"],"m":"Я спрашиваю учителя."},{"zh":"我懂了。","tokens":["我","懂","了"],"m":"Я понял."}]}'),
  ('hsk2-07-1', 1, 'fact', '{"emoji":"🏢","title":"Сердце, которое потерялось","text":"В знаке 忙 «занятой» слева стоит 忄 «сердце», справа 亡 «терять»: от суеты сердце как будто теряется. Слово 公司 gōngsī «компания» — это «общее дело». Слово 服务员 fúwùyuán «официант, работник сервиса» состоит из 服务 «служить» и 员 «работник». А 累 lèi «уставший» несёт 田 «поле»: после работы в поле устают."}'),
  ('hsk2-07-1', 2, 'words', '{"title":"Работа и состояния","items":[{"hanzi":"公司","pinyin":"gōngsī","m":"компания, фирма","emoji":"🏢","ex":{"zh":"我在公司工作。","py":"Wǒ zài gōngsī gōngzuò.","m":"Я работаю в компании."}},{"hanzi":"服务员","pinyin":"fúwùyuán","m":"официант, работник сервиса","emoji":"🧑‍🍳","ex":{"zh":"服务员，你好！","py":"Fúwùyuán, nǐ hǎo!","m":"Здравствуйте (официанту)!"}},{"hanzi":"忙","pinyin":"máng","m":"занятой","emoji":"🏃","ex":{"zh":"我今天很忙。","py":"Wǒ jīntiān hěn máng.","m":"Сегодня я очень занят."}},{"hanzi":"累","pinyin":"lèi","m":"усталый","emoji":"😩","ex":{"zh":"我很累。","py":"Wǒ hěn lèi.","m":"Я очень устал."}}]}'),
  ('hsk2-07-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🏢","options":["忙","累","公司"],"correct":2},{"emoji":"🧑‍🍳","options":["忙","公司","服务员"],"correct":2},{"emoji":"🏃","options":["忙","累","公司"],"correct":0},{"emoji":"😩","options":["服务员","忙","累"],"correct":2}]}'),
  ('hsk2-07-1', 4, 'theory', '{"title":"Как обратиться и как пожаловаться на усталость","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["服务员！","Fúwùyuán!","Официант! (обращение)"],["我在公司工作。","Wǒ zài gōngsī gōngzuò.","Я работаю в компании."],["我今天很忙。","Wǒ jīntiān hěn máng.","Сегодня я очень занят."],["我很累。","Wǒ hěn lèi.","Я очень устал."]]},{"t":"p","text":"忙 и 累 — прилагательные: перед ними ставится 很, а 是 не нужен. Слово 服务员 — не только «официант», так обращаются к любому работнику сервиса."},{"t":"tip","text":"В ресторане зовут официанта: 服务员！ — и это звучит нормально, без обиды."}]}'),
  ('hsk2-07-1', 5, 'quiz', '{"title":"Мини-тест: работа","qs":[{"q":"Как сказать «Я очень устал»?","options":["我很累。","我是累。","累很我。"],"correct":0},{"q":"Как сказать «Я работаю в компании»?","options":["我公司在工作。","我工作公司在。","我在公司工作。"],"correct":2},{"q":"服务员 — это «официант».","tf":true}]}'),
  ('hsk2-07-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["公司","компания"],["服务员","официант"],["忙","занятой"],["累","усталый"],["我很忙","я очень занят"]]}'),
  ('hsk2-07-1', 7, 'game', '{"type":"listen","title":"Слушаем: работа и усталость","items":[{"say":"公司","options":["gōngshī","góngsī","gōngsī"],"correct":2},{"say":"服务员","options":["fúwùyuán","fúwùyuǎn","fǔwùyuán"],"correct":0},{"say":"忙","options":["mǎng","màng","máng"],"correct":2},{"say":"累","options":["lěi","lèi","léi"],"correct":1},{"say":"我今天很忙","options":["wǒ jīntiān hěn lèi","wǒ jīntiān hěn máng"],"correct":1}]}'),
  ('hsk2-07-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","在","公司","工作"],"hint":"«Я работаю в компании.»"},{"answer":["我","今天","很","忙"],"hint":"«Сегодня я очень занят.»"},{"answer":["我","很","累"],"hint":"«Я очень устал.»"}]}'),
  ('hsk2-07-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"忙","pinyin":"máng","m":"занятой","hint":"слева 忄, справа 亡"},{"hanzi":"累","pinyin":"lèi","m":"усталый","hint":"сверху 田, внизу 糸"},{"hanzi":"员","pinyin":"yuán","m":"работник","hint":"сверху 口, внизу 贝"}]}'),
  ('hsk2-07-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 累?","options":["усталый","богатый","занятый"],"correct":0},{"q":"Как читается 公司?","options":["gōngshī","góngsī","gōngsī"],"correct":2},{"q":"忙 содержит 忄 «сердце».","tf":true},{"q":"Что значит 公司?","options":["школа","компания","магазин"],"correct":1},{"q":"Как обратиться к официанту?","options":["老师！","服务员！","先生！"],"correct":1}]}'),
  ('hsk2-07-2', 1, 'fact', '{"emoji":"🎁","title":"Один и тот же порядок слов: кому + что","text":"Китайские глаголы передачи строятся одинаково: глагол + кому + что. 给我一本书 «дай мне книгу», 告诉我名字 «скажи мне имя», 送你一件衣服 «подарю тебе одежду». А 让 ràng «позволять, заставлять» ставится перед человеком и глаголом: 让我看一下 «дай мне взглянуть»."}'),
  ('hsk2-07-2', 2, 'words', '{"title":"Четыре глагола","items":[{"hanzi":"给","pinyin":"gěi","m":"давать; для, кому","emoji":"🎁","ex":{"zh":"给我一本书。","py":"Gěi wǒ yì běn shū.","m":"Дай мне книгу."}},{"hanzi":"送","pinyin":"sòng","m":"дарить, отправлять, провожать","emoji":"📦","ex":{"zh":"我送你一本书。","py":"Wǒ sòng nǐ yì běn shū.","m":"Я подарю тебе книгу."}},{"hanzi":"告诉","pinyin":"gàosu","m":"сказать, сообщить","emoji":"🗣️","ex":{"zh":"告诉我你的名字。","py":"Gàosu wǒ nǐ de míngzi.","m":"Скажи мне своё имя."}},{"hanzi":"让","pinyin":"ràng","m":"позволять, просить","emoji":"🚦","ex":{"zh":"让我看一下。","py":"Ràng wǒ kàn yíxià.","m":"Дай мне взглянуть."}}]}'),
  ('hsk2-07-2', 3, 'theory', '{"title":"Кому и что: порядок слов","blocks":[{"t":"table","head":["Глагол","Схема","Пример"],"rows":[["给","给 + кому + что","给我一本书。"],["送","送 + кому + что","送你一件衣服。"],["告诉","告诉 + кому + что","告诉我你的名字。"],["让","让 + кто + что делать","让我看一下。"]]},{"t":"p","text":"Первым стоит получатель, потом предмет: 给我书 «дай мне книгу». Слово 给 бывает и предлогом «для»: 我给你打电话 «я позвоню тебе»."},{"t":"tip","text":"给 в значении «для»: 给 + кому + глагол. 我给妈妈买苹果 «я куплю маме яблоки»."}]}'),
  ('hsk2-07-2', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["给","我","一","本","书"],"hint":"«Дай мне книгу.»"},{"answer":["我","送","你","一","件","衣服"],"hint":"«Я подарю тебе одежду.»"},{"answer":["告诉","我","你","的","名字"],"hint":"«Скажи мне своё имя.»"},{"answer":["让","我","看","一下"],"hint":"«Дай мне взглянуть.»"}]}'),
  ('hsk2-07-2', 5, 'quiz', '{"title":"Мини-тест: кому и что","qs":[{"q":"Как сказать «Дай мне книгу»?","options":["给我一本书。","我给书一本。","给一本书我。"],"correct":0},{"q":"Что значит 送?","options":["дарить, провожать","понимать","сказать"],"correct":0},{"q":"给 ставится после предмета.","tf":false,"explain":"Порядок: 给 + кому + что."}]}'),
  ('hsk2-07-2', 6, 'theory', '{"title":"给 как предлог и 让 как «позволять»","blocks":[{"t":"table","head":["Фраза","Смысл"],"rows":[["我给你打电话。","Я позвоню тебе."],["我给妈妈买苹果。","Я куплю маме яблоки."],["请让我看一下。","Разрешите взглянуть."],["老师让我回答问题。","Учитель просит меня ответить."]]},{"t":"p","text":"给 + кому + глагол означает «делать для кого-то». 让 + кого + что делать — «разрешить или попросить»: 让我看一下."}]}'),
  ('hsk2-07-2', 7, 'game', '{"type":"listen","title":"Слушаем глаголы","items":[{"say":"给","options":["gěi","géi","gèi"],"correct":0},{"say":"送","options":["sòng","sóng","sǒng"],"correct":0},{"say":"告诉","options":["gàosù","gǎosu","gàosu"],"correct":2},{"say":"让","options":["ràng","ráng","rǎng"],"correct":0},{"say":"给我一本书","options":["gěi wǒ yí gè shū","gěi wǒ yì běn shū"],"correct":1}]}'),
  ('hsk2-07-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["给","давать"],["送","дарить"],["告诉","сказать"],["让","позволять"],["给我一本书","дай мне книгу"]]}'),
  ('hsk2-07-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: кому и что","cases":[{"buggyText":"给一本书我。","context":"«Дай мне книгу»","options":["给我一本书。","我给一本书。","一本书我给。"],"correct":0},{"buggyText":"我送一件衣服你。","context":"«Я подарю тебе одежду»","options":["我送你一件衣服。","我一件衣服送你。","你我送一件衣服。"],"correct":0},{"buggyText":"告诉名字我。","context":"«Скажи мне имя»","options":["告诉我名字。","名字告诉我。","我名字告诉。"],"correct":0}]}'),
  ('hsk2-07-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как читается 告诉?","options":["gàosu","gǎosu","gàosù"],"correct":0},{"q":"Как сказать «Дай мне взглянуть»?","options":["让我看一下。","我让看一下。","让看我一下。"],"correct":0},{"q":"给 может быть предлогом «для».","tf":true},{"q":"Как сказать «Я позвоню тебе»?","options":["给我你打电话。","我给你打电话。","我打电话给你吗。"],"correct":1},{"q":"Что значит 告诉?","options":["сказать","дарить","давать"],"correct":0}]}'),
  ('hsk2-07-3', 1, 'fact', '{"emoji":"🤲","title":"Полотенце, которое помогает","text":"В знаке 帮 «помогать» справа стоит 巾 «платок, ткань»: так помогали, подавая ткань. Слово 帮助 bāngzhù — «помощь», а 事情 shìqing — «дело, обстоятельство». Они часто вместе: 有事情，需要帮助 «есть дело, нужна помощь»."}'),
  ('hsk2-07-3', 2, 'words', '{"title":"Помощь и дела","items":[{"hanzi":"帮助","pinyin":"bāngzhù","m":"помогать, помощь","emoji":"🤲","ex":{"zh":"谢谢你的帮助。","py":"Xièxie nǐ de bāngzhù.","m":"Спасибо за помощь."}},{"hanzi":"事情","pinyin":"shìqing","m":"дело, обстоятельство","emoji":"📋","ex":{"zh":"我有很多事情。","py":"Wǒ yǒu hěn duō shìqing.","m":"У меня много дел."}}]}'),
  ('hsk2-07-3', 3, 'game', '{"type":"listen","title":"Слушаем: помощь и дела","items":[{"say":"帮助","options":["bāngzhǔ","bǎngzhù","bāngzhù"],"correct":2},{"say":"事情","options":["shìqíng","shǐqing","shìqing"],"correct":2,"explain":"Второй слог безударный."},{"say":"谢谢你的帮助","options":["xièxie nǐ de míngzi","xièxie nǐ de bāngzhù"],"correct":1},{"say":"我有很多事情","options":["wǒ yǒu hěn duō shìqing","wǒ yǒu hěn shǎo shìqing"],"correct":0},{"say":"可以帮助我吗","options":["kěyǐ bāngzhù wǒ ma","kěyǐ gàosu wǒ ma"],"correct":0}]}'),
  ('hsk2-07-3', 4, 'game', '{"type":"tone_visualizer","initialTone":1,"title":"Тренажёр голоса: повторите «bāng» (1 тон)"}'),
  ('hsk2-07-3', 5, 'theory', '{"title":"Попросить о помощи","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["你可以帮助我吗？","Ты можешь мне помочь?"],["谢谢你的帮助！","Спасибо за помощь!"],["你有事情吗？","У тебя есть дело?"],["我有很多事情。","У меня много дел."]]},{"t":"p","text":"帮助 стоит перед человеком: 帮助我 «помоги мне». Для вежливой просьбы добавляйте 可以: 你可以帮助我吗？"},{"t":"tip","text":"事情 — «дело, происшествие». А слово 工作 «работа» используют для профессии."}]}'),
  ('hsk2-07-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🤲","options":["帮助","事情","送"],"correct":0},{"emoji":"📋","options":["事情","让","帮助"],"correct":0}]}'),
  ('hsk2-07-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["帮助","помогать"],["事情","дело"],["谢谢你的帮助","спасибо за помощь"],["你可以帮助我吗？","ты можешь мне помочь?"],["我有事情","у меня есть дело"]]}'),
  ('hsk2-07-3', 8, 'game', '{"type":"chatsim","title":"WeChat: просьба о помощи","messages":[{"speaker":"Друг","text":"喂，你今天忙吗？","pinyin":"Wèi, nǐ jīntiān máng ma?","translation":"Алло, ты сегодня занят?","options":["是，我忙很。","我不是忙，我累。","我很忙，也很累。"],"correct":2},{"speaker":"Друг","text":"你可以帮助我吗？","pinyin":"Nǐ kěyǐ bāngzhù wǒ ma?","translation":"Ты можешь мне помочь?","options":["可以，我帮助是。","不可以，我帮助。","可以。你有什么事情？"],"correct":2},{"speaker":"Друг","text":"谢谢你的帮助！","pinyin":"Xièxie nǐ de bāngzhù!","translation":"Спасибо за помощь!","options":["对不起。","不客气。","没有。"],"correct":1}]}'),
  ('hsk2-07-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["你","可以","帮助","我","吗"],"hint":"«Ты можешь мне помочь?»"},{"answer":["谢谢","你","的","帮助"],"hint":"«Спасибо за помощь.»"},{"answer":["我","有","很多","事情"],"hint":"«У меня много дел.»"}]}'),
  ('hsk2-07-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 帮助?","options":["давать","помогать","дарить"],"correct":1},{"q":"Как читается 事情?","options":["shǐqing","shìqíng","shìqing"],"correct":2},{"q":"Как сказать «Спасибо за помощь»?","options":["谢谢帮助的你。","帮助谢谢你的。","谢谢你的帮助。"],"correct":2},{"q":"事情 значит «дело».","tf":true},{"q":"Как вежливо попросить о помощи?","options":["你可以帮助我吗？","帮助我。","你帮助我吧。"],"correct":0}]}'),
  ('hsk2-07-4', 1, 'fact', '{"emoji":"🎁","title":"Просьба по телефону","text":"Ли Мин звонит Анне: у него есть дело, и ему нужна помощь. В диалоге встретятся 公司, 忙, 累, 帮助, 事情, 送, 告诉, 给."}'),
  ('hsk2-07-4', 2, 'text', '{"title":"Звонок","lines":[{"zh":"李明：喂，安娜，你在哪儿？","py":"Lǐ Míng: Wèi, Ānnà, nǐ zài nǎr?","m":"Ли Мин: Алло, Анна, где ты?"},{"zh":"安娜：我在公司。我今天很忙，也很累。","py":"Ānnà: Wǒ zài gōngsī. Wǒ jīntiān hěn máng, yě hěn lèi.","m":"Анна: Я в компании. Сегодня я очень занята и устала."},{"zh":"李明：你有时间吗？我有一件事情。","py":"Lǐ Míng: Nǐ yǒu shíjiān ma? Wǒ yǒu yí jiàn shìqing.","m":"Ли Мин: Есть время? У меня есть одно дело."},{"zh":"安娜：你告诉我吧。","py":"Ānnà: Nǐ gàosu wǒ ba.","m":"Анна: Расскажи."},{"zh":"李明：我想送我哥哥一本书。你可以帮助我吗？","py":"Lǐ Míng: Wǒ xiǎng sòng wǒ gēge yì běn shū. Nǐ kěyǐ bāngzhù wǒ ma?","m":"Ли Мин: Я хочу подарить брату книгу. Ты можешь помочь?"},{"zh":"安娜：可以。我给你一个号码，你给商店打电话吧。","py":"Ānnà: Kěyǐ. Wǒ gěi nǐ yí gè hàomǎ, nǐ gěi shāngdiàn dǎ diànhuà ba.","m":"Анна: Могу. Дам номер, позвони в магазин."},{"zh":"李明：太好了！谢谢你的帮助！","py":"Lǐ Míng: Tài hǎo le! Xièxie nǐ de bāngzhù!","m":"Ли Мин: Здорово! Спасибо за помощь!"},{"zh":"安娜：不客气。","py":"Ānnà: Bú kèqi.","m":"Анна: Не за что."}],"qs":[{"q":"Где сейчас Анна?","options":["дома","в магазине","в компании"],"correct":2},{"q":"Анна не занята.","tf":false,"explain":"Она говорит 很忙，也很累."},{"q":"Что хочет подарить Ли Мин?","options":["книгу брату","одежду маме","яблоки другу"],"correct":0},{"q":"Что даёт Анна Ли Мину?","options":["адрес","номер","книгу"],"correct":1},{"q":"Анна обещает помочь.","tf":true},{"q":"Вставьте слово: 你___我吧。","options":["让","送","告诉"],"correct":2},{"q":"Чем заканчивается разговор?","options":["对不起","不客气","再见"],"correct":1}]}'),
  ('hsk2-07-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["我在公司","я в компании"],["我很忙，也很累","я занята и устала"],["我想送我哥哥一本书","хочу подарить брату книгу"],["我给你一个号码","дам тебе номер"],["谢谢你的帮助","спасибо за помощь"]]}'),
  ('hsk2-07-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"我在公司","options":["wǒ zài xuéxiào","wǒ zài gōngsī"],"correct":1},{"say":"我想送我哥哥一本书","options":["wǒ xiǎng sòng wǒ gēge yì běn shū","wǒ xiǎng gěi wǒ gēge yì běn shū"],"correct":0},{"say":"你可以帮助我吗","options":["nǐ kěyǐ bāngzhù wǒ ma","nǐ kěyǐ gàosu wǒ ma"],"correct":0},{"say":"我给你一个号码","options":["wǒ sòng nǐ yí gè hàomǎ","wǒ gěi nǐ yí gè hàomǎ"],"correct":1}]}'),
  ('hsk2-07-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: просьба","cases":[{"buggyText":"我送一本书我哥哥。","context":"«Я подарю брату книгу»","options":["我哥哥送一本书。","我一本书送哥哥我。","我送我哥哥一本书。"],"correct":2},{"buggyText":"你给商店打电话。","context":"«Позвони в магазин» (с предлогом «для»)","options":["你给商店打电话。","你打电话商店给。","给你商店电话打。"],"correct":0},{"buggyText":"谢谢帮助你的。","context":"«Спасибо за помощь»","options":["你的谢谢帮助。","谢谢你的帮助。","谢谢帮助的你。"],"correct":1}]}'),
  ('hsk2-07-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я хочу подарить брату книгу»?","options":["我哥哥想送一本书。","我想送一本书我哥哥。","我想送我哥哥一本书。"],"correct":2},{"q":"Как читается 帮助?","options":["bāngzhǔ","bāngzhù","bǎngzhù"],"correct":1},{"q":"Ли Мин просит Анну помочь с подарком.","tf":true}]}'),
  ('hsk2-07-5', 1, 'fact', '{"emoji":"💼","title":"Расскажите о рабочем дне","text":"Сегодня вы рассказываете, где работаете, как устали, о чём просите и что дарите. Слова глав 1–7 HSK 2."}'),
  ('hsk2-07-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"告","correctRadicals":["牛","口"],"title":"Пазл: соберите 告"}'),
  ('hsk2-07-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"送","radicals":["辶","关","亻"],"correctOrder":["辶","关"],"explain":"Слева 辶 «ходьба», справа 关."},{"targetHanzi":"忙","radicals":["忄","亡","女"],"correctOrder":["忄","亡"],"explain":"Слева 忄, справа 亡."},{"targetHanzi":"帮","radicals":["邦","巾","口"],"correctOrder":["邦","巾"],"explain":"Сверху 邦, внизу 巾."}]}'),
  ('hsk2-07-5', 4, 'game', '{"type":"build","title":"Мастерская дня","items":[{"target":"(Работа)","answer":["我","在","公司","工作"],"hint":"«Я работаю в компании.»"},{"target":"(Состояние)","answer":["我","今天","很","忙","，","也","很","累"],"hint":"«Сегодня я очень занят и устал.»"},{"target":"(Просьба)","answer":["你","可以","帮助","我","吗"],"hint":"«Ты можешь мне помочь?»"},{"target":"(Подарок)","answer":["我","送","朋友","一","本","书"],"hint":"«Я дарю другу книгу.»"}]}'),
  ('hsk2-07-5', 5, 'theory', '{"title":"Образец разговора о делах","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["Где","我在公司。"],["Как","我很忙，也很累。"],["Просьба","你可以帮助我吗？"],["Благодарность","谢谢你的帮助。"]]}]}'),
  ('hsk2-07-5', 6, 'game', '{"type":"chatsim","title":"WeChat: подарок","messages":[{"speaker":"Друг","text":"你今天忙吗？","pinyin":"Nǐ jīntiān máng ma?","translation":"Ты сегодня занят?","options":["忙，我累是。","很忙，也很累。","不是，我忙。"],"correct":1},{"speaker":"Друг","text":"你想送什么？","pinyin":"Nǐ xiǎng sòng shénme?","translation":"Что ты хочешь подарить?","options":["我送想书。","书我想送吗。","我想送一本书。"],"correct":2},{"speaker":"Друг","text":"好，我给你一个号码。","pinyin":"Hǎo, wǒ gěi nǐ yí gè hàomǎ.","translation":"Хорошо, дам тебе номер.","options":["没关系。","对不起，再见。","谢谢你的帮助！"],"correct":2}]}'),
  ('hsk2-07-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["牛 + 口","告"],["辶 + 关","送"],["忄 + 亡","忙"],["邦 + 巾","帮"]]}'),
  ('hsk2-07-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"给","pinyin":"gěi","m":"давать","hint":"слева 纟, справа 合"},{"hanzi":"送","pinyin":"sòng","m":"дарить","hint":"слева 辶, справа 关"},{"hanzi":"让","pinyin":"ràng","m":"позволять","hint":"слева 讠, справа 上"}]}'),
  ('hsk2-07-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я дарю другу книгу»?","options":["朋友送我一本书。","我送一本书朋友。","我送朋友一本书。"],"correct":2},{"q":"Из каких частей состоит 告?","options":["牛 и 口","女 и 子","亻 и 也"],"correct":0},{"q":"给 может значить «для».","tf":true}]}'),
  ('hsk2-07-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 7 (HSK 2)","text":"公司, 服务员, 忙, 累, 给, 送, 告诉, 让, 帮助 и 事情."}'),
  ('hsk2-07-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"公司","options":["fúwùyuán","gōngsī","shìqing"],"correct":1},{"say":"我今天很忙","options":["wǒ jīntiān hěn máng","wǒ jīntiān hěn lèi"],"correct":0},{"say":"给我一本书","options":["sòng wǒ yì běn shū","gěi wǒ yì běn shū"],"correct":1},{"say":"告诉我","options":["gěi wǒ","gàosu wǒ"],"correct":1},{"say":"让我看一下","options":["ràng wǒ kàn yíxià","gěi wǒ kàn yíxià"],"correct":0},{"say":"谢谢你的帮助","options":["xièxie nǐ de shìqing","xièxie nǐ de bāngzhù"],"correct":1}]}'),
  ('hsk2-07-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🏢","options":["公司","累","忙"],"correct":0},{"emoji":"🎁","options":["让","送","给"],"correct":2},{"emoji":"🤲","options":["告诉","事情","帮助"],"correct":2},{"emoji":"😩","options":["忙","公司","累"],"correct":2}]}'),
  ('hsk2-07-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["公司","компания"],["服务员","официант"],["忙","занятой"],["累","усталый"],["给","давать"],["送","дарить"],["告诉","сказать"],["让","позволять"],["帮助","помогать"],["事情","дело"]]}'),
  ('hsk2-07-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Дай мне книгу»?","options":["我给书一本。","给我一本书。","给一本书我。"],"correct":1},{"q":"Как сказать «Я очень устал»?","options":["我是累。","我很累。","累很我。"],"correct":1},{"q":"Как читается 告诉?","options":["gàosù","gǎosu","gàosu"],"correct":2},{"q":"Порядок: глагол + кому + что.","tf":true},{"q":"Как попросить о помощи?","options":["你帮助我吧。","你可以帮助我吗？","帮助我吗你？"],"correct":1},{"q":"Что значит 事情?","options":["время","помощь","дело"],"correct":2},{"q":"给 не может быть предлогом.","tf":false},{"q":"Как сказать «Я позвоню тебе»?","options":["我打电话给吗。","我给你打电话。","给我你打电话。"],"correct":1},{"q":"Как сказать «Дай мне взглянуть»?","options":["让看我一下。","我让看一下。","让我看一下。"],"correct":2},{"q":"Как обратиться к официанту?","options":["老师！","同学！","服务员！"],"correct":2}]}'),
  ('hsk2-07-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["给","我","一","本","书"],"hint":"«Дай мне книгу.»"},{"answer":["我","送","你","一","件","衣服"],"hint":"«Я подарю тебе одежду.»"},{"answer":["我","今天","很","忙"],"hint":"«Сегодня я очень занят.»"},{"answer":["谢谢","你","的","帮助"],"hint":"«Спасибо за помощь.»"}]}'),
  ('hsk2-07-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"给一本书我。","context":"«Дай мне книгу»","options":["一本书我给。","给我一本书。","我给一本书。"],"correct":1},{"buggyText":"我送一件衣服你。","context":"«Я подарю тебе одежду»","options":["我送你一件衣服。","我一件衣服送你。","你我送一件衣服。"],"correct":0},{"buggyText":"谢谢帮助你的。","context":"«Спасибо за помощь»","options":["你的谢谢帮助。","谢谢你的帮助。","谢谢帮助的你。"],"correct":1}]}'),
  ('hsk2-07-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"你可以帮助我吗？","pinyin":"Nǐ kěyǐ bāngzhù wǒ ma?","translation":"Ты можешь мне помочь?","options":["可以，我帮助是。","不可以，我帮助。","可以。你有什么事情？"],"correct":2},{"speaker":"Друг","text":"谢谢你的帮助！","pinyin":"Xièxie nǐ de bāngzhù!","translation":"Спасибо за помощь!","options":["不客气。","没有。","对不起。"],"correct":0}]}'),
  ('hsk2-07-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"忙","pinyin":"máng","m":"занятой","hint":"忄 + 亡"},{"hanzi":"给","pinyin":"gěi","m":"давать","hint":"纟 + 合"},{"hanzi":"送","pinyin":"sòng","m":"дарить","hint":"辶 + 关"}]}'),
  ('hsk2-07-6', 10, 'recall', '{"words":[{"hanzi":"公司","pinyin":"gōngsī","m":"компания"},{"hanzi":"服务员","pinyin":"fúwùyuán","m":"официант"},{"hanzi":"忙","pinyin":"máng","m":"занятой"},{"hanzi":"累","pinyin":"lèi","m":"усталый"},{"hanzi":"给","pinyin":"gěi","m":"давать"},{"hanzi":"送","pinyin":"sòng","m":"дарить"},{"hanzi":"告诉","pinyin":"gàosu","m":"сказать"},{"hanzi":"让","pinyin":"ràng","m":"позволять"},{"hanzi":"帮助","pinyin":"bāngzhù","m":"помогать"},{"hanzi":"事情","pinyin":"shìqing","m":"дело"}],"tf":[{"zh":"给一本书我。","py":"gěi yì běn shū wǒ.","m":"Дай мне книгу.","ok":false,"explain":"Правильно: 给我一本书."},{"zh":"谢谢你的帮助。","py":"xièxie nǐ de bāngzhù.","m":"Спасибо за помощь.","ok":true}],"sentences":[{"zh":"给我一本书。","tokens":["给","我","一","本","书"],"m":"Дай мне книгу."},{"zh":"我送你一件衣服。","tokens":["我","送","你","一","件","衣服"],"m":"Я подарю тебе одежду."},{"zh":"你可以帮助我吗？","tokens":["你","可以","帮助","我","吗"],"m":"Ты можешь мне помочь?"}]}'),
  ('hsk2-08-1', 1, 'fact', '{"emoji":"🚌","title":"«Общий паровой экипаж»","text":"公共汽车 gōnggòng qìchē — автобус: 公共 «общественный» + 汽车 «паровой экипаж». Знак 汽 «пар» содержит 氵 «вода», потому что первые автомобили ездили на паре. В знаке 路 «дорога» слева 足 «нога»: дорогу создаёт тот, кто идёт. А 机场 jīchǎng — «аэродром»: 机 «механизм» и 场 «площадка»."}'),
  ('hsk2-08-1', 2, 'words', '{"title":"Транспорт и билеты","items":[{"hanzi":"公共汽车","pinyin":"gōnggòng qìchē","m":"автобус","emoji":"🚌","ex":{"zh":"我坐公共汽车去学校。","py":"Wǒ zuò gōnggòng qìchē qù xuéxiào.","m":"Я еду в школу на автобусе."}},{"hanzi":"机场","pinyin":"jīchǎng","m":"аэропорт","emoji":"🛫","ex":{"zh":"机场很大。","py":"Jīchǎng hěn dà.","m":"Аэропорт большой."}},{"hanzi":"路","pinyin":"lù","m":"дорога, путь","emoji":"🛣️","ex":{"zh":"这条路很长。","py":"Zhè tiáo lù hěn cháng.","m":"Эта дорога длинная. (条 — новое слово)"}},{"hanzi":"票","pinyin":"piào","m":"билет","emoji":"🎫","ex":{"zh":"我有票。","py":"Wǒ yǒu piào.","m":"У меня есть билет."}}]}'),
  ('hsk2-08-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🚌","options":["路","公共汽车","票"],"correct":1},{"emoji":"🛫","options":["票","路","机场"],"correct":2},{"emoji":"🛣️","options":["路","票","机场"],"correct":0},{"emoji":"🎫","options":["公共汽车","票","机场"],"correct":1}]}'),
  ('hsk2-08-1', 4, 'theory', '{"title":"Автобус, билет, аэропорт","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["我坐公共汽车去机场。","Wǒ zuò gōnggòng qìchē qù jīchǎng.","Я еду в аэропорт на автобусе."],["我有票。","Wǒ yǒu piào.","У меня есть билет."],["机场很大。","Jīchǎng hěn dà.","Аэропорт большой."],["路很长。","Lù hěn cháng.","Дорога длинная."]]},{"t":"p","text":"坐 + транспорт вы знаете из HSK 1. Новое слово 公共汽车 — «автобус»; в разговоре его часто сокращают до 公交车. Билет называют 票, а покупают его глаголом 买."},{"t":"tip","text":"买票 «купить билет», 有票 «иметь билет»."}]}'),
  ('hsk2-08-1', 5, 'quiz', '{"title":"Мини-тест: транспорт","qs":[{"q":"Как сказать «Я еду на автобусе»?","options":["我坐公共汽车。","公共汽车我坐吗。","我公共汽车坐。"],"correct":0},{"q":"Что значит 票?","options":["билет","дорога","аэропорт"],"correct":0},{"q":"机场 — это «аэропорт».","tf":true}]}'),
  ('hsk2-08-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["公共汽车","автобус"],["机场","аэропорт"],["路","дорога"],["票","билет"],["买票","купить билет"]]}'),
  ('hsk2-08-1', 7, 'game', '{"type":"listen","title":"Слушаем транспорт","items":[{"say":"公共汽车","options":["gōnggòng qìchě","gōnggòng qìchē","gōnggōng qìchē"],"correct":1},{"say":"机场","options":["jíchǎng","jīchǎng","jīchàng"],"correct":1},{"say":"路","options":["lǔ","lù","lú"],"correct":1},{"say":"票","options":["piāo","piáo","piào"],"correct":2},{"say":"我有票","options":["wǒ yǒu piào","wǒ yǒu lù"],"correct":0}]}'),
  ('hsk2-08-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","坐","公共汽车"],"hint":"«Я еду на автобусе.»"},{"answer":["我","去","机场"],"hint":"«Я иду в аэропорт.»"},{"answer":["我","买","票"],"hint":"«Я покупаю билет.»"}]}'),
  ('hsk2-08-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"路","pinyin":"lù","m":"дорога","hint":"слева 足, справа 各"},{"hanzi":"票","pinyin":"piào","m":"билет","hint":"сверху 西, внизу 示"},{"hanzi":"场","pinyin":"chǎng","m":"площадка","hint":"слева 土, справа 汤 без воды"}]}'),
  ('hsk2-08-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 路?","options":["автобус","дорога","билет"],"correct":1},{"q":"Как читается 机场?","options":["jíchǎng","jīchǎng","jīchàng"],"correct":1},{"q":"Как сказать «У меня есть билет»?","options":["我票有。","有我票。","我有票。"],"correct":2},{"q":"Знак 汽 содержит 氵 «вода».","tf":true},{"q":"Что значит 公共汽车?","options":["автобус","такси","поезд"],"correct":0}]}'),
  ('hsk2-08-2', 1, 'fact', '{"emoji":"🧭","title":"Два человека в знаке «из»","text":"Знак 从 «из, от» нарисован как два человека 人人, один идёт за другим: «следовать из». Схема 从 A 到 B «из A в B» — самая частая в китайских маршрутах. А 往 «в направлении» добавляет сторону: 往前走 «идти вперёд». Глагол 走 zǒu значит «идти пешком, уходить»."}'),
  ('hsk2-08-2', 2, 'words', '{"title":"Маршрут","items":[{"hanzi":"到","pinyin":"dào","m":"прибыть, до","emoji":"🏁","ex":{"zh":"我到了。","py":"Wǒ dào le.","m":"Я приехал."}},{"hanzi":"从","pinyin":"cóng","m":"из, от","emoji":"📍","ex":{"zh":"从学校到机场","py":"cóng xuéxiào dào jīchǎng","m":"от школы до аэропорта"}},{"hanzi":"往","pinyin":"wǎng","m":"в сторону, по направлению к","emoji":"➡️","ex":{"zh":"往前走","py":"wǎng qián zǒu","m":"идти вперёд"}},{"hanzi":"走","pinyin":"zǒu","m":"идти пешком, уходить","emoji":"🚶","ex":{"zh":"我走路去学校。","py":"Wǒ zǒulù qù xuéxiào.","m":"Я иду в школу пешком."}}]}'),
  ('hsk2-08-2', 3, 'theory', '{"title":"Схема 从…到…","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["从学校到机场","от школы до аэропорта"],["从家到公司","из дома в компанию"],["往前走","идти вперёд"],["我到了。","Я прибыл."]]},{"t":"p","text":"从 стоит перед местом отправления, 到 перед местом назначения: 从学校到机场. Эта группа ставится перед глаголом: 我从学校走 «я иду от школы». 往 указывает направление: 往前走 «иди вперёд»."},{"t":"tip","text":"走路 — «ходить пешком»: 我走路去学校 «я иду в школу пешком»."}]}'),
  ('hsk2-08-2', 4, 'game', '{"type":"build","title":"Соберите маршрут","items":[{"answer":["从","学校","到","机场"],"hint":"«От школы до аэропорта.»"},{"answer":["我","从","家","走","到","公司"],"hint":"«Я иду из дома до компании.»"},{"answer":["往","前","走"],"hint":"«Иди вперёд.»"},{"answer":["我","走路","去","学校"],"hint":"«Я иду в школу пешком.»"}]}'),
  ('hsk2-08-2', 5, 'quiz', '{"title":"Мини-тест: маршрут","qs":[{"q":"Как сказать «от школы до аэропорта»?","options":["学校从到机场","到学校从机场","从学校到机场"],"correct":2},{"q":"Что значит 往前走?","options":["идти назад","идти вперёд","стоять"],"correct":1},{"q":"从 ставится перед местом назначения.","tf":false,"explain":"从 перед отправлением, 到 перед назначением."}]}'),
  ('hsk2-08-2', 6, 'theory', '{"title":"到 как глагол и 走 как «идти»","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我到了。","Я прибыл."],["他到公司了。","Он дошёл до компании."],["我们走吧。","Пойдёмте."],["你先走。","Иди первым."]]},{"t":"p","text":"到 как глагол ставят после места: 到公司. 走 — самое общее слово для «идти пешком»: 走吧 «пойдёмте»."}]}'),
  ('hsk2-08-2', 7, 'game', '{"type":"listen","title":"Слушаем: от, до, идти","items":[{"say":"到","options":["dáo","dǎo","dào"],"correct":2},{"say":"从","options":["cóng","cǒng","còng"],"correct":0},{"say":"往","options":["wáng","wàng","wǎng"],"correct":2},{"say":"走","options":["zǒu","zóu","zòu"],"correct":0},{"say":"从学校到机场","options":["cóng jīchǎng dào xuéxiào","cóng xuéxiào dào jīchǎng"],"correct":1}]}'),
  ('hsk2-08-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["到","прибыть"],["从","из, от"],["往","в сторону"],["走","идти пешком"],["我到了","я прибыл"]]}'),
  ('hsk2-08-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: маршрут","cases":[{"buggyText":"学校从到机场","context":"«От школы до аэропорта»","options":["到从学校机场","从到学校机场","从学校到机场"],"correct":2},{"buggyText":"我走去学校路。","context":"«Я иду в школу пешком»","options":["我走路去学校。","走我路去学校。","我去学校走路吗。"],"correct":0},{"buggyText":"往走前。","context":"«Иди вперёд»","options":["往前走。","前往走。","走往前。"],"correct":0}]}'),
  ('hsk2-08-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как читается 从?","options":["cóng","còng","cǒng"],"correct":0},{"q":"Как сказать «Я прибыл»?","options":["到我了。","我到了。","我了到。"],"correct":1},{"q":"Как сказать «Пойдёмте»?","options":["走我们吧。","我们走吧。","我们吧走。"],"correct":1},{"q":"走路 — это «идти пешком».","tf":true},{"q":"Как сказать «Я иду в школу пешком»?","options":["走路我学校去。","我走路去学校。","我去走路学校。"],"correct":1}]}'),
  ('hsk2-08-3', 1, 'fact', '{"emoji":"🚪","title":"«Вперёд» и «наружу»","text":"进 jìn «входить» содержит 辶 «ход» и 井 «колодец»: вход похож на спуск в колодец. 出 chū «выходить» — это два гор 山: «из гор на волю». Эти два глагола часто стоят с «приходить» и «уходить»: 进来 jìnlái «войти (сюда)», 出去 chūqù «выйти (туда)»."}'),
  ('hsk2-08-3', 2, 'words', '{"title":"Войти и выйти","items":[{"hanzi":"进","pinyin":"jìn","m":"входить","emoji":"➡️","ex":{"zh":"请进！","py":"Qǐng jìn!","m":"Входите, пожалуйста!"}},{"hanzi":"出","pinyin":"chū","m":"выходить","emoji":"⬅️","ex":{"zh":"他出门了。","py":"Tā chūmén le.","m":"Он вышел из дома."}}]}'),
  ('hsk2-08-3', 3, 'game', '{"type":"listen","title":"Слушаем: войти и выйти","items":[{"say":"进","options":["jìn","jín","jǐn"],"correct":0},{"say":"出","options":["chú","chǔ","chū"],"correct":2},{"say":"请进","options":["qǐng jìng","qǐng jìn"],"correct":1},{"say":"他出门了","options":["tā jìnmén le","tā chūmén le"],"correct":1},{"say":"进教室","options":["jìn jiàoshì","chū jiàoshì"],"correct":0}]}'),
  ('hsk2-08-3', 4, 'game', '{"type":"tone_visualizer","initialTone":4,"title":"Тренажёр голоса: повторите «jìn» (4 тон)"}'),
  ('hsk2-08-3', 5, 'theory', '{"title":"进 и 出 с местом и с 来 / 去","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["进教室","войти в класс"],["出门","выйти из дома"],["请进来。","Входите сюда."],["他出去了。","Он вышел."]]},{"t":"p","text":"进 и 出 ставят перед местом: 进教室, 出门. С 来 и 去 они обозначают направление к говорящему или от него: 进来 «войти сюда», 出去 «выйти туда»."},{"t":"tip","text":"Для вежливого приглашения: 请进！ «Входите, пожалуйста!»"}]}'),
  ('hsk2-08-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"➡️","options":["出","进","到"],"correct":1},{"emoji":"⬅️","options":["出","进","走"],"correct":0}]}'),
  ('hsk2-08-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["进","входить"],["出","выходить"],["进来","войти сюда"],["出去","выйти туда"],["请进","входите"]]}'),
  ('hsk2-08-3', 8, 'game', '{"type":"chatsim","title":"WeChat: гость пришёл","messages":[{"speaker":"Друг","text":"喂，你到了吗？","pinyin":"Wèi, nǐ dào le ma?","translation":"Алло, ты приехал?","options":["到了，我走了到。","到了，我在门前面。","没有，我是到。"],"correct":1},{"speaker":"Друг","text":"好，请进来！","pinyin":"Hǎo, qǐng jìnlái!","translation":"Хорошо, входи!","options":["谢谢，我进去。","再见，我出。","对不起，我走。"],"correct":0},{"speaker":"Друг","text":"你想出去吗？","pinyin":"Nǐ xiǎng chūqù ma?","translation":"Хочешь выйти?","options":["想，我们走吧。","不想，出门。","想，出我们走。"],"correct":0}]}'),
  ('hsk2-08-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["请","进"],"hint":"«Входите, пожалуйста.»"},{"answer":["他","出","门","了"],"hint":"«Он вышел из дома.»"},{"answer":["我","进","教室"],"hint":"«Я вхожу в класс.»"}]}'),
  ('hsk2-08-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 进?","options":["входить","идти","выходить"],"correct":0},{"q":"Как читается 出?","options":["chǔ","chú","chū"],"correct":2},{"q":"Как сказать «Входите, пожалуйста»?","options":["请进。","进请。","请进吗。"],"correct":0},{"q":"出 состоит из двух 山.","tf":true},{"q":"Как сказать «Он вышел из дома»?","options":["他出门了。","他门出了。","出他门了。"],"correct":0}]}'),
  ('hsk2-08-4', 1, 'fact', '{"emoji":"✈️","title":"Встреча в аэропорту","text":"Анна и Ли Мин договариваются о поездке: билет, дорога, остановка. В диалоге встретятся 公共汽车, 机场, 票, 到, 从, 往, 走, 进, 出."}'),
  ('hsk2-08-4', 2, 'text', '{"title":"Договариваемся о поездке","lines":[{"zh":"安娜：李明，你怎么去机场？","py":"Ānnà: Lǐ Míng, nǐ zěnme qù jīchǎng?","m":"Анна: Ли Мин, как ты едешь в аэропорт?"},{"zh":"李明：我坐公共汽车去。你呢？","py":"Lǐ Míng: Wǒ zuò gōnggòng qìchē qù. Nǐ ne?","m":"Ли Мин: Я на автобусе. А ты?"},{"zh":"安娜：我坐出租车。你有票吗？","py":"Ānnà: Wǒ zuò chūzūchē. Nǐ yǒu piào ma?","m":"Анна: Я на такси. У тебя есть билет?"},{"zh":"李明：有。我的票是明天早上八点的。","py":"Lǐ Míng: Yǒu. Wǒ de piào shì míngtiān zǎoshang bā diǎn de.","m":"Ли Мин: Есть. Мой билет на завтра, на восемь утра."},{"zh":"安娜：你从学校走吗？","py":"Ānnà: Nǐ cóng xuéxiào zǒu ma?","m":"Анна: Ты пойдёшь от школы пешком?"},{"zh":"李明：对，我从学校走。往前走十分钟，到公共汽车站。","py":"Lǐ Míng: Duì, wǒ cóng xuéxiào zǒu. Wǎng qián zǒu shí fēnzhōng, dào gōnggòng qìchē zhàn.","m":"Ли Мин: Да. Иду вперёд десять минут и дохожу до остановки. (对 «да» — новое слово)"},{"zh":"安娜：好，我们机场见！","py":"Ānnà: Hǎo, wǒmen jīchǎng jiàn!","m":"Анна: Хорошо, увидимся в аэропорту!"},{"zh":"李明：好，机场见！","py":"Lǐ Míng: Hǎo, jīchǎng jiàn!","m":"Ли Мин: Хорошо, до встречи в аэропорту!"}],"qs":[{"q":"Как Ли Мин едет в аэропорт?","options":["на автобусе","пешком","на такси"],"correct":0},{"q":"Как едет Анна?","options":["на такси","на автобусе","на метро"],"correct":0},{"q":"Билет Ли Мина на завтрашний вечер.","tf":false,"explain":"Он на завтра, на восемь утра."},{"q":"Куда доходит Ли Мин пешком?","options":["до дома","до остановки","до аэропорта"],"correct":1},{"q":"Они договариваются встретиться в аэропорту.","tf":true},{"q":"Вставьте слово: 往前走十分钟，___公共汽车站。","options":["从","进","到"],"correct":2},{"q":"Сколько минут идти до остановки?","options":["пять","двадцать","десять"],"correct":2}]}'),
  ('hsk2-08-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["我坐公共汽车去","я поеду на автобусе"],["我有票","у меня есть билет"],["从学校走","иду от школы"],["往前走十分钟","иду вперёд десять минут"],["机场见","увидимся в аэропорту"]]}'),
  ('hsk2-08-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你怎么去机场","options":["nǐ zěnme huí jiā","nǐ zěnme qù jīchǎng"],"correct":1},{"say":"我的票是明天早上八点的","options":["wǒ de piào shì míngtiān zǎoshang bā diǎn de","wǒ de piào shì míngtiān wǎnshang bā diǎn de"],"correct":0},{"say":"往前走十分钟","options":["wǎng hòu zǒu shí fēnzhōng","wǎng qián zǒu shí fēnzhōng"],"correct":1},{"say":"机场见","options":["jīchǎng zàijiàn","jīchǎng jiàn"],"correct":1}]}'),
  ('hsk2-08-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: поездка","cases":[{"buggyText":"我从走学校。","context":"«Я иду от школы»","options":["我走从学校吗。","从我走学校。","我从学校走。"],"correct":2},{"buggyText":"往前十分钟走。","context":"«Иду вперёд десять минут»","options":["往十分钟前走。","十分钟往前走吗。","往前走十分钟。"],"correct":2},{"buggyText":"我们见机场。","context":"«Увидимся в аэропорту»","options":["见机场我们。","机场我们见吗。","我们机场见。"],"correct":2}]}'),
  ('hsk2-08-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Увидимся в аэропорту»?","options":["机场见！","机场再！","见机场！"],"correct":0},{"q":"Как читается 公共汽车?","options":["gōnggòng qìchē","gōnggòng qìchě","gōnggōng qìchē"],"correct":0},{"q":"Анна едет в аэропорт на такси.","tf":true}]}'),
  ('hsk2-08-5', 1, 'fact', '{"emoji":"🗺️","title":"Построй маршрут","text":"Сегодня вы составляете путь «от дома до аэропорта», выбираете транспорт и покупаете билет. Слова глав 1–8 HSK 2."}'),
  ('hsk2-08-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"路","correctRadicals":["足","各"],"title":"Пазл: соберите 路"}'),
  ('hsk2-08-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"到","radicals":["至","刂","寸"],"correctOrder":["至","刂"],"explain":"Слева 至, справа 刂."},{"targetHanzi":"进","radicals":["辶","井","木"],"correctOrder":["辶","井"],"explain":"Слева 辶, справа 井."},{"targetHanzi":"走","radicals":["土","止","人"],"correctOrder":["土","止"],"explain":"Сверху 土, внизу 止."}]}'),
  ('hsk2-08-5', 4, 'game', '{"type":"build","title":"Мастерская маршрутов","items":[{"target":"(Маршрут)","answer":["我","从","家","到","机场"],"hint":"«Я еду из дома в аэропорт.»"},{"target":"(Транспорт)","answer":["我","坐","公共汽车","去","机场"],"hint":"«Я еду в аэропорт на автобусе.»"},{"target":"(Билет)","answer":["我","买","了","一","个","票"],"hint":"«Я купил билет.»"},{"target":"(Дорога)","answer":["往","前","走","十","分钟"],"hint":"«Иду вперёд десять минут.»"}]}'),
  ('hsk2-08-5', 5, 'theory', '{"title":"Образец маршрута","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["Откуда и куда","从家到机场。"],["На чём","坐公共汽车。"],["Как идти","往前走十分钟。"],["Билет","我有票。"]]}]}'),
  ('hsk2-08-5', 6, 'game', '{"type":"chatsim","title":"WeChat: поездка","messages":[{"speaker":"Друг","text":"你怎么去机场？","pinyin":"Nǐ zěnme qù jīchǎng?","translation":"Как ты едешь в аэропорт?","options":["我去机场坐是。","我公共汽车去坐。","我坐公共汽车去。"],"correct":2},{"speaker":"Друг","text":"你有票吗？","pinyin":"Nǐ yǒu piào ma?","translation":"У тебя есть билет?","options":["有，票我。","有，我有票。","没有，我票是。"],"correct":1},{"speaker":"Друг","text":"好，我们机场见！","pinyin":"Hǎo, wǒmen jīchǎng jiàn!","translation":"Хорошо, увидимся в аэропорту!","options":["没关系。","对不起。","机场见！"],"correct":2}]}'),
  ('hsk2-08-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["足 + 各","路"],["至 + 刂","到"],["辶 + 井","进"],["土 + 止","走"]]}'),
  ('hsk2-08-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"到","pinyin":"dào","m":"прибыть","hint":"слева 至, справа 刂"},{"hanzi":"进","pinyin":"jìn","m":"входить","hint":"слева 辶, справа 井"},{"hanzi":"出","pinyin":"chū","m":"выходить","hint":"два 山"}]}'),
  ('hsk2-08-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я еду из дома в аэропорт»?","options":["我从家到机场。","从我家机场到。","我到家从机场。"],"correct":0},{"q":"Из каких частей состоит 路?","options":["足 и 各","亻 и 也","女 и 子"],"correct":0},{"q":"Для маршрута используют 从…到….","tf":true}]}'),
  ('hsk2-08-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 8 (HSK 2)","text":"公共汽车, 机场, 路, 票, 到, 从, 往, 走, 进 и 出."}'),
  ('hsk2-08-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"公共汽车","options":["chūzūchē","fēijī","gōnggòng qìchē"],"correct":2},{"say":"机场","options":["huǒchēzhàn","jīchǎng"],"correct":1},{"say":"从学校到机场","options":["cóng jīchǎng dào xuéxiào","cóng xuéxiào dào jīchǎng"],"correct":1},{"say":"往前走","options":["wǎng hòu zǒu","wǎng qián zǒu"],"correct":1},{"say":"请进","options":["qǐng jìn","qǐng chū"],"correct":0},{"say":"我有票","options":["wǒ yǒu lù","wǒ yǒu piào"],"correct":1}]}'),
  ('hsk2-08-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🚌","options":["路","公共汽车","票"],"correct":1},{"emoji":"🛫","options":["机场","到","走"],"correct":0},{"emoji":"🎫","options":["票","出","进"],"correct":0},{"emoji":"🚶","options":["往","从","走"],"correct":2}]}'),
  ('hsk2-08-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["公共汽车","автобус"],["机场","аэропорт"],["路","дорога"],["票","билет"],["到","прибыть"],["从","из, от"],["往","в сторону"],["走","идти пешком"],["进","входить"],["出","выходить"]]}'),
  ('hsk2-08-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «от школы до аэропорта»?","options":["到学校从机场","从学校到机场","学校从到机场"],"correct":1},{"q":"Как сказать «Я прибыл»?","options":["我到了。","我了到。","到我了。"],"correct":0},{"q":"Как сказать «Входите, пожалуйста»?","options":["进请。","请进吗。","请进。"],"correct":2},{"q":"从 ставится перед отправлением.","tf":true},{"q":"Как сказать «Я иду в школу пешком»?","options":["我走路去学校。","走路我学校去。","我去走路学校。"],"correct":0},{"q":"Что значит 票?","options":["дорога","билет","автобус"],"correct":1},{"q":"出 значит «входить».","tf":false},{"q":"Как сказать «Иди вперёд»?","options":["往前走。","前往走。","走往前。"],"correct":0},{"q":"Как сказать «Он вышел из дома»?","options":["他出门了。","出他门了。","他门出了。"],"correct":0},{"q":"Как сказать «Я купил билет»?","options":["我买了票。","买我票了。","我票买了。"],"correct":0}]}'),
  ('hsk2-08-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["从","学校","到","机场"],"hint":"«От школы до аэропорта.»"},{"answer":["我","坐","公共汽车","去","机场"],"hint":"«Я еду в аэропорт на автобусе.»"},{"answer":["往","前","走","十","分钟"],"hint":"«Иду вперёд десять минут.»"},{"answer":["请","进"],"hint":"«Входите, пожалуйста.»"}]}'),
  ('hsk2-08-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"学校从到机场","context":"«От школы до аэропорта»","options":["从学校到机场","到从学校机场","从到学校机场"],"correct":0},{"buggyText":"我走去学校路。","context":"«Я иду в школу пешком»","options":["走我路去学校。","我去学校走路吗。","我走路去学校。"],"correct":2},{"buggyText":"往走前。","context":"«Иди вперёд»","options":["走往前。","往前走。","前往走。"],"correct":1}]}'),
  ('hsk2-08-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"你怎么去机场？","pinyin":"Nǐ zěnme qù jīchǎng?","translation":"Как ты едешь в аэропорт?","options":["我去机场坐是。","我公共汽车去坐。","我坐公共汽车去。"],"correct":2},{"speaker":"Друг","text":"你有票吗？","pinyin":"Nǐ yǒu piào ma?","translation":"У тебя есть билет?","options":["有，我有票。","没有，我票是。","有，票我。"],"correct":0}]}'),
  ('hsk2-08-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"路","pinyin":"lù","m":"дорога","hint":"足 + 各"},{"hanzi":"到","pinyin":"dào","m":"прибыть","hint":"至 + 刂"},{"hanzi":"进","pinyin":"jìn","m":"входить","hint":"辶 + 井"}]}'),
  ('hsk2-08-6', 10, 'recall', '{"words":[{"hanzi":"公共汽车","pinyin":"gōnggòng qìchē","m":"автобус"},{"hanzi":"机场","pinyin":"jīchǎng","m":"аэропорт"},{"hanzi":"路","pinyin":"lù","m":"дорога"},{"hanzi":"票","pinyin":"piào","m":"билет"},{"hanzi":"到","pinyin":"dào","m":"прибыть"},{"hanzi":"从","pinyin":"cóng","m":"из, от"},{"hanzi":"往","pinyin":"wǎng","m":"в сторону"},{"hanzi":"走","pinyin":"zǒu","m":"идти пешком"},{"hanzi":"进","pinyin":"jìn","m":"входить"},{"hanzi":"出","pinyin":"chū","m":"выходить"}],"tf":[{"zh":"学校从到机场","py":"xuéxiào cóng dào jīchǎng","m":"От школы до аэропорта.","ok":false,"explain":"Правильно: 从学校到机场."},{"zh":"我有票。","py":"wǒ yǒu piào.","m":"У меня есть билет.","ok":true}],"sentences":[{"zh":"从学校到机场","tokens":["从","学校","到","机场"],"m":"От школы до аэропорта."},{"zh":"我坐公共汽车去机场。","tokens":["我","坐","公共汽车","去","机场"],"m":"Я еду в аэропорт на автобусе."},{"zh":"往前走十分钟。","tokens":["往","前","走","十","分钟"],"m":"Иду вперёд десять минут."}]}'),
  ('hsk2-09-1', 1, 'fact', '{"emoji":"🖐️","title":"Левая рука с инструментом, правая с ртом","text":"Знаки 左 «лево» и 右 «право» отличаются одной деталью. В 左 есть 工 «инструмент»: левая рука держит инструмент. В 右 есть 口 «рот»: правая рука подносит еду ко рту. Забыть, где что, невозможно. А 旁边 pángbiān «рядом, сбоку» и 外 wài «снаружи» дополняют картину."}'),
  ('hsk2-09-1', 2, 'words', '{"title":"Где что находится","items":[{"hanzi":"旁边","pinyin":"pángbiān","m":"рядом, сбоку","emoji":"↔️","ex":{"zh":"商店在学校旁边。","py":"Shāngdiàn zài xuéxiào pángbiān.","m":"Магазин рядом со школой."}},{"hanzi":"左边","pinyin":"zuǒbian","m":"слева","emoji":"⬅️","ex":{"zh":"医院在左边。","py":"Yīyuàn zài zuǒbian.","m":"Больница слева."}},{"hanzi":"右边","pinyin":"yòubian","m":"справа","emoji":"➡️","ex":{"zh":"商店在右边。","py":"Shāngdiàn zài yòubian.","m":"Магазин справа."}},{"hanzi":"外","pinyin":"wài","m":"снаружи, за пределами","emoji":"🚪","ex":{"zh":"他在门外。","py":"Tā zài mén wài.","m":"Он за дверью."}}]}'),
  ('hsk2-09-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"⬅️","options":["右边","旁边","左边"],"correct":2},{"emoji":"➡️","options":["外","右边","左边"],"correct":1},{"emoji":"↔️","options":["外","旁边","左边"],"correct":1},{"emoji":"🚪","options":["外","右边","旁边"],"correct":0}]}'),
  ('hsk2-09-1', 4, 'theory', '{"title":"Схема «А + 在 + место + сторона»","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["商店在学校旁边。","Shāngdiàn zài xuéxiào pángbiān.","Магазин рядом со школой."],["医院在左边。","Yīyuàn zài zuǒbian.","Больница слева."],["商店在右边。","Shāngdiàn zài yòubian.","Магазин справа."],["他在门外。","Tā zài mén wài.","Он за дверью."]]},{"t":"p","text":"Слово места ставится перед направлением: 学校旁边, 门外. Второй слог в 左边 и 右边 безударный: zuǒbian, yòubian."},{"t":"tip","text":"Не ставьте 的: 学校旁边, а не 学校的旁边, если нет акцента на принадлежность."}]}'),
  ('hsk2-09-1', 5, 'quiz', '{"title":"Мини-тест: стороны","qs":[{"q":"Как сказать «Больница слева»?","options":["医院左边在。","在医院左边。","医院在左边。"],"correct":2},{"q":"Что значит 旁边?","options":["впереди","рядом","внутри"],"correct":1},{"q":"В 左 есть 工, а в 右 есть 口.","tf":true}]}'),
  ('hsk2-09-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["旁边","рядом"],["左边","слева"],["右边","справа"],["外","снаружи"],["在学校旁边","рядом со школой"]]}'),
  ('hsk2-09-1', 7, 'game', '{"type":"listen","title":"Слушаем: стороны","items":[{"say":"旁边","options":["pāngbiān","pàngbiān","pángbiān"],"correct":2},{"say":"左边","options":["zuóbian","zuǒbian","zuòbian"],"correct":1},{"say":"右边","options":["yòubian","yǒubian","yóubian"],"correct":0},{"say":"外","options":["wāi","wǎi","wài"],"correct":2},{"say":"商店在学校旁边","options":["shāngdiàn zài xuéxiào pángbiān","shāngdiàn zài xuéxiào hòumian"],"correct":0}]}'),
  ('hsk2-09-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["商店","在","学校","旁边"],"hint":"«Магазин рядом со школой.»"},{"answer":["医院","在","左边"],"hint":"«Больница слева.»"},{"answer":["他","在","门","外"],"hint":"«Он за дверью.»"}]}'),
  ('hsk2-09-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"左","pinyin":"zuǒ","m":"лево","hint":"сверху 一 и 丿, внизу 工"},{"hanzi":"右","pinyin":"yòu","m":"право","hint":"сверху 一 и 丿, внизу 口"},{"hanzi":"外","pinyin":"wài","m":"снаружи","hint":"слева 夕, справа 卜"}]}'),
  ('hsk2-09-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 右边?","options":["рядом","справа","слева"],"correct":1},{"q":"Как читается 左边?","options":["zuóbian","zuòbian","zuǒbian"],"correct":2},{"q":"Какой знак содержит 工?","options":["外","右","左"],"correct":2},{"q":"外 значит «снаружи».","tf":true},{"q":"Как сказать «Магазин справа»?","options":["在商店右边。","商店在右边。","商店右边在。"],"correct":1}]}'),
  ('hsk2-09-2', 1, 'fact', '{"emoji":"📏","title":"离 — не «уходить», а «расстояние до»","text":"Слово 离 lí в схеме «А 离 В 近 / 远» значит «от А до В близко / далеко»: 学校离我家很近 «школа близко от моего дома». Прилагательные 近 jìn «близкий» и 远 yuǎn «далёкий» ставятся после. А частица 过 guò после глагола обозначает опыт: 我去过北京 «я бывал в Пекине»."}'),
  ('hsk2-09-2', 2, 'words', '{"title":"Расстояние и опыт","items":[{"hanzi":"近","pinyin":"jìn","m":"близкий","emoji":"🟢","ex":{"zh":"学校很近。","py":"Xuéxiào hěn jìn.","m":"Школа близко."}},{"hanzi":"远","pinyin":"yuǎn","m":"далёкий","emoji":"🔴","ex":{"zh":"机场很远。","py":"Jīchǎng hěn yuǎn.","m":"Аэропорт далеко."}},{"hanzi":"离","pinyin":"lí","m":"от (расстояние)","emoji":"📐","ex":{"zh":"学校离我家很近。","py":"Xuéxiào lí wǒ jiā hěn jìn.","m":"Школа близко от моего дома."}},{"hanzi":"过","pinyin":"guò","m":"пройти; частица опыта","emoji":"✅","ex":{"zh":"我去过北京。","py":"Wǒ qù guo Běijīng.","m":"Я бывал в Пекине."}}]}'),
  ('hsk2-09-2', 3, 'theory', '{"title":"离 для расстояния","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["学校离我家很近。","Школа недалеко от моего дома."],["机场离学校很远。","Аэропорт далеко от школы."],["你家离公司远吗？","Твой дом далеко от компании?"]]},{"t":"p","text":"Схема: А + 离 + В + 很近 / 很远. 离 не имеет направления, оно только показывает расстояние. Для движения используют 从…到…."},{"t":"tip","text":"Не путайте: 离 — расстояние, 从 — начало движения."}]}'),
  ('hsk2-09-2', 4, 'quiz', '{"title":"Мини-тест: расстояние","qs":[{"q":"Как сказать «Школа далеко от дома»?","options":["学校离我家很远。","学校在我家远。","学校从我家很远。"],"correct":0},{"q":"Что значит 近?","options":["далёкий","большой","близкий"],"correct":2},{"q":"离 показывает расстояние до места.","tf":true}]}'),
  ('hsk2-09-2', 5, 'theory', '{"title":"过 после глагола: был, делал","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我去过北京。","Я был в Пекине."],["你吃过米饭吗？","Ты ел рис?"],["我没去过。","Я не был."]]},{"t":"p","text":"过 ставится сразу после глагола и говорит: «такое в жизни случалось». Отрицание — 没 + глагол + 过: 我没去过. 过 произносится в нейтральном тоне."},{"t":"ex","zh":"你去过北京吗？","py":"Nǐ qù guo Běijīng ma?","m":"Ты бывал в Пекине?","say":"你去过北京吗"}]}'),
  ('hsk2-09-2', 6, 'game', '{"type":"listen","title":"Слушаем: близко, далеко","items":[{"say":"近","options":["jìn","jǐn","jín"],"correct":0},{"say":"远","options":["yuǎn","yuàn","yuán"],"correct":0},{"say":"离","options":["lǐ","lí","lì"],"correct":1},{"say":"我去过北京","options":["wǒ qù guo Běijīng","wǒ qù le Běijīng"],"correct":0},{"say":"学校离我家很近","options":["xuéxiào lí wǒ jiā hěn jìn","xuéxiào lí wǒ jiā hěn yuǎn"],"correct":0}]}'),
  ('hsk2-09-2', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["近","близкий"],["远","далёкий"],["离","от (расстояние)"],["过","частица опыта"],["我去过北京","я бывал в Пекине"]]}'),
  ('hsk2-09-2', 8, 'game', '{"type":"bughunt","title":"Китайский детектив: расстояние и опыт","cases":[{"buggyText":"学校从我家很近。","context":"«Школа близко от дома»","options":["学校离近我家很。","学校我家离很近。","学校离我家很近。"],"correct":2},{"buggyText":"我去北京过。","context":"«Я бывал в Пекине»","options":["我过去北京。","过我去北京。","我去过北京。"],"correct":2},{"buggyText":"我不去过。","context":"«Я не был»","options":["我没去过。","我去不过。","不我去过。"],"correct":0}]}'),
  ('hsk2-09-2', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как читается 远?","options":["yuǎn","yuàn","yuán"],"correct":0},{"q":"Как сказать «Я не был в Пекине»?","options":["我不去过北京。","我没去过北京。","我去没过北京。"],"correct":1},{"q":"过 ставится после глагола.","tf":true},{"q":"Как спросить «Ты бывал в Пекине?»","options":["你过去北京吗？","你去北京过吗？","你去过北京吗？"],"correct":2},{"q":"Как сказать «Аэропорт далеко от школы»?","options":["机场离学校很远。","机场学校离很远。","机场从学校很远。"],"correct":0}]}'),
  ('hsk2-09-3', 1, 'fact', '{"emoji":"🔎","title":"Рука с оружием ищет","text":"Знак 找 «искать» состоит из 扌 «рука» и 戈 «копьё»: поиск был охотой. А 站 zhàn «стоять» содержит 立 «стоять» и 占 «занимать»: стоишь на месте — занимаешь место. Отсюда и 公共汽车站 «автобусная остановка», и 火车站 «вокзал»."}'),
  ('hsk2-09-3', 2, 'words', '{"title":"Искать и остановка","items":[{"hanzi":"找","pinyin":"zhǎo","m":"искать","emoji":"🔎","ex":{"zh":"我在找我的书。","py":"Wǒ zài zhǎo wǒ de shū.","m":"Я ищу свою книгу."}},{"hanzi":"站","pinyin":"zhàn","m":"стоять; остановка, станция","emoji":"🚏","ex":{"zh":"公共汽车站在学校旁边。","py":"Gōnggòng qìchē zhàn zài xuéxiào pángbiān.","m":"Автобусная остановка рядом со школой."}}]}'),
  ('hsk2-09-3', 3, 'game', '{"type":"listen","title":"Слушаем: искать и остановка","items":[{"say":"找","options":["zháo","zhào","zhǎo"],"correct":2},{"say":"站","options":["zhān","zhǎn","zhàn"],"correct":2},{"say":"我在找我的书","options":["wǒ zài zhǎo wǒ de shū","wǒ zài kàn wǒ de shū"],"correct":0},{"say":"公共汽车站","options":["gōnggòng qìchē jiàn","gōnggòng qìchē zhàn"],"correct":1},{"say":"请站在这儿","options":["qǐng zuò zài zhèr","qǐng zhàn zài zhèr"],"correct":1}]}'),
  ('hsk2-09-3', 4, 'game', '{"type":"tone_visualizer","initialTone":3,"title":"Тренажёр голоса: повторите «zhǎo» (3 тон)"}'),
  ('hsk2-09-3', 5, 'theory', '{"title":"找 и 站: примеры","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我在找我的书。","Я ищу свою книгу."],["我找老师。","Я ищу учителя."],["公共汽车站在哪儿？","Где автобусная остановка?"],["请站在这儿。","Пожалуйста, встаньте здесь."]]},{"t":"p","text":"找 ставится перед тем, что ищут. 站 как существительное — «остановка, станция»: 火车站, 公共汽车站. Как глагол — «стоять»: 站在门外 «стоять за дверью»."},{"t":"tip","text":"在 перед глаголом показывает процесс: 我在找 «я ищу прямо сейчас»."}]}'),
  ('hsk2-09-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🔎","options":["站","过","找"],"correct":2},{"emoji":"🚏","options":["站","找","离"],"correct":0}]}'),
  ('hsk2-09-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["找","искать"],["站","остановка, стоять"],["找老师","искать учителя"],["公共汽车站","автобусная остановка"],["站在门外","стоять за дверью"]]}'),
  ('hsk2-09-3', 8, 'game', '{"type":"chatsim","title":"WeChat: найти остановку","messages":[{"speaker":"Прохожий","text":"你好！我在找公共汽车站。","pinyin":"Nǐ hǎo! Wǒ zài zhǎo gōnggòng qìchē zhàn.","translation":"Здравствуйте! Я ищу автобусную остановку.","options":["公共汽车站是找。","我找你。","公共汽车站在学校旁边。"],"correct":2},{"speaker":"Прохожий","text":"离这儿远吗？","pinyin":"Lí zhèr yuǎn ma?","translation":"Далеко отсюда?","options":["不是，我远。","远，我走。","不远，很近。"],"correct":2},{"speaker":"Прохожий","text":"谢谢！","pinyin":"Xièxie!","translation":"Спасибо!","options":["不客气。","没关系。","对不起。"],"correct":0}]}'),
  ('hsk2-09-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","在","找","公共汽车","站"],"hint":"«Я ищу автобусную остановку.»"},{"answer":["公共汽车","站","在","学校","旁边"],"hint":"«Автобусная остановка рядом со школой.»"},{"answer":["请","站","在","门","外"],"hint":"«Пожалуйста, встаньте за дверью.»"}]}'),
  ('hsk2-09-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 找?","options":["стоять","искать","идти"],"correct":1},{"q":"Как читается 站?","options":["zhàn","zhān","zhǎn"],"correct":0},{"q":"Как сказать «Я ищу книгу»?","options":["我找在书。","我在找书。","在我找书。"],"correct":1},{"q":"站 может значить «остановка».","tf":true},{"q":"Что значит 公共汽车站?","options":["такси","автобусная остановка","аэропорт"],"correct":1}]}'),
  ('hsk2-09-4', 1, 'fact', '{"emoji":"🗺️","title":"Спросить дорогу","text":"Ли Мин ищет автобусную остановку и просит Анну объяснить дорогу. В диалоге встретятся 旁边, 左边, 右边, 近, 远, 离, 过, 找, 站."}'),
  ('hsk2-09-4', 2, 'text', '{"title":"Как пройти","lines":[{"zh":"李明：你好！我在找公共汽车站。","py":"Lǐ Míng: Nǐ hǎo! Wǒ zài zhǎo gōnggòng qìchē zhàn.","m":"Ли Мин: Здравствуйте! Я ищу автобусную остановку."},{"zh":"安娜：公共汽车站在学校旁边。","py":"Ānnà: Gōnggòng qìchē zhàn zài xuéxiào pángbiān.","m":"Анна: Остановка рядом со школой."},{"zh":"李明：离学校远吗？","py":"Lǐ Míng: Lí xuéxiào yuǎn ma?","m":"Ли Мин: Далеко от школы?"},{"zh":"安娜：不远，很近。你往前走，左边是商店，右边是医院。","py":"Ānnà: Bù yuǎn, hěn jìn. Nǐ wǎng qián zǒu, zuǒbian shì shāngdiàn, yòubian shì yīyuàn.","m":"Анна: Нет, очень близко. Иди вперёд: слева магазин, справа больница."},{"zh":"李明：你去过那儿吗？","py":"Lǐ Míng: Nǐ qù guo nàr ma?","m":"Ли Мин: Ты там бывала?"},{"zh":"安娜：去过。公共汽车站在医院旁边。","py":"Ānnà: Qù guo. Gōnggòng qìchē zhàn zài yīyuàn pángbiān.","m":"Анна: Бывала. Остановка рядом с больницей."},{"zh":"李明：太好了！我走吧。谢谢你！","py":"Lǐ Míng: Tài hǎo le! Wǒ zǒu ba. Xièxie nǐ!","m":"Ли Мин: Отлично! Пойду. Спасибо!"}],"qs":[{"q":"Что ищет Ли Мин?","options":["магазин","автобусную остановку","больницу"],"correct":1},{"q":"Остановка далеко от школы.","tf":false,"explain":"Анна говорит 不远，很近."},{"q":"Что слева на дороге?","options":["школа","магазин","больница"],"correct":1},{"q":"Что справа?","options":["дом","больница","магазин"],"correct":1},{"q":"Анна бывала у остановки.","tf":true},{"q":"Вставьте слово: 你去___那儿吗？","options":["过","到","走"],"correct":0},{"q":"Рядом с чем находится остановка?","options":["с больницей","с магазином","с аэропортом"],"correct":0}]}'),
  ('hsk2-09-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["我在找公共汽车站","я ищу остановку"],["公共汽车站在学校旁边","остановка рядом со школой"],["离学校远吗？","далеко от школы?"],["左边是商店","слева магазин"],["右边是医院","справа больница"]]}'),
  ('hsk2-09-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"我在找公共汽车站","options":["wǒ zài zhǎo gōnggòng qìchē zhàn","wǒ zài kàn gōnggòng qìchē zhàn"],"correct":0},{"say":"离学校远吗","options":["lí xuéxiào yuǎn ma","cóng xuéxiào yuǎn ma"],"correct":0},{"say":"左边是商店","options":["zuǒbian shì shāngdiàn","yòubian shì shāngdiàn"],"correct":0},{"say":"你去过那儿吗","options":["nǐ qù le nàr ma","nǐ qù guo nàr ma"],"correct":1}]}'),
  ('hsk2-09-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: дорога","cases":[{"buggyText":"学校离公共汽车站旁边。","context":"«Рядом со школой»","options":["公共汽车站在学校旁边。","旁边学校公共汽车站。","学校旁边在公共汽车站。"],"correct":0},{"buggyText":"左边是商店右边是医院。","context":"«Слева магазин, справа больница»","options":["左边是商店，右边是医院。","商店是左边医院是右边。","是左边商店右边医院。"],"correct":0},{"buggyText":"你去那儿过吗？","context":"«Ты там бывала?»","options":["你去吗过那儿？","你过去那儿吗？","你去过那儿吗？"],"correct":2}]}'),
  ('hsk2-09-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Слева магазин»?","options":["是左边商店。","左边是商店。","左边商店是。"],"correct":1},{"q":"Как читается 右边?","options":["yǒubian","yóubian","yòubian"],"correct":2},{"q":"Остановка рядом с больницей.","tf":true}]}'),
  ('hsk2-09-5', 1, 'fact', '{"emoji":"🗺️","title":"Нарисуйте карту","text":"Сегодня вы описываете улицу: что слева, что справа, что рядом, как далеко. Слова глав 1–9 HSK 2."}'),
  ('hsk2-09-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"找","correctRadicals":["扌","戈"],"title":"Пазл: соберите 找"}'),
  ('hsk2-09-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"远","radicals":["辶","元","木"],"correctOrder":["辶","元"],"explain":"Слева 辶, справа 元."},{"targetHanzi":"近","radicals":["辶","斤","口"],"correctOrder":["辶","斤"],"explain":"Слева 辶, справа 斤."},{"targetHanzi":"站","radicals":["立","占","木"],"correctOrder":["立","占"],"explain":"Слева 立, справа 占."}]}'),
  ('hsk2-09-5', 4, 'game', '{"type":"build","title":"Мастерская карты","items":[{"target":"(Карта)","answer":["学校","在","我","家","右边"],"hint":"«Школа справа от моего дома.»"},{"target":"(Карта)","answer":["商店","在","学校","旁边"],"hint":"«Магазин рядом со школой.»"},{"target":"(Расстояние)","answer":["医院","离","学校","很","近"],"hint":"«Больница недалеко от школы.»"},{"target":"(Опыт)","answer":["我","去","过","机场"],"hint":"«Я бывал в аэропорту.»"}]}'),
  ('hsk2-09-5', 5, 'theory', '{"title":"Образец описания улицы","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["Что слева","左边是商店。"],["Что справа","右边是医院。"],["Расстояние","学校离我家很近。"],["Опыт","我去过那儿。"]]}]}'),
  ('hsk2-09-5', 6, 'game', '{"type":"chatsim","title":"WeChat: мой район","messages":[{"speaker":"Друг","text":"你家在哪儿？","pinyin":"Nǐ jiā zài nǎr?","translation":"Где твой дом?","options":["我家是旁边。","学校我家在。","我家在学校旁边。"],"correct":2},{"speaker":"Друг","text":"离公共汽车站远吗？","pinyin":"Lí gōnggòng qìchē zhàn yuǎn ma?","translation":"Далеко ли от остановки?","options":["远，我走。","不远，很近。","不是，我远。"],"correct":1},{"speaker":"Друг","text":"你去过机场吗？","pinyin":"Nǐ qù guo jīchǎng ma?","translation":"Ты был в аэропорту?","options":["去过，我坐公共汽车去。","没去，我是。","过去，我机场去。"],"correct":0}]}'),
  ('hsk2-09-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["扌 + 戈","找"],["辶 + 元","远"],["辶 + 斤","近"],["立 + 占","站"]]}'),
