  ('hsk2-09-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Магазин рядом со школой»?","options":["在商店学校旁边。","商店学校旁边在。","商店在学校旁边。"],"correct":2},{"q":"Из чего состоит 找?","options":["扌 и 戈","女 и 子","辶 и 斤"],"correct":0},{"q":"离 показывает расстояние.","tf":true}]}'),
