  ('hsk2-09-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"⬅️","options":["左边","右边","旁边"],"correct":0},{"emoji":"🟢","options":["离","远","近"],"correct":2},{"emoji":"🔴","options":["近","离","远"],"correct":2},{"emoji":"🔎","options":["站","找","过"],"correct":1}]}'),
  ('hsk2-09-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["旁边","рядом"],["左边","слева"],["右边","справа"],["外","снаружи"],["近","близкий"],["远","далёкий"],["离","от (расстояние)"],["过","частица опыта"],["找","искать"],["站","остановка"]]}'),
  ('hsk2-09-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Школа близко от дома»?","options":["学校离我家很近。","学校从我家很近。","学校我家离近。"],"correct":0},{"q":"Как сказать «Я бывал в Пекине»?","options":["过我去北京。","我过去北京。","我去过北京。"],"correct":2},{"q":"Как сказать «Я не был там»?","options":["我没去过。","我不去过。","我去没过。"],"correct":0},{"q":"离 показывает направление движения.","tf":false},{"q":"Как сказать «Магазин рядом со школой»?","options":["商店学校旁边在。","商店在学校旁边。","在商店学校旁边。"],"correct":1},{"q":"Как читается 左边?","options":["zuòbian","zuǒbian","zuóbian"],"correct":1},{"q":"找 значит «искать».","tf":true},{"q":"Как сказать «Слева магазин, справа больница»?","options":["商店是左边，医院是右边。","左边是商店，右边是医院。","是左边商店，右边医院。"],"correct":1},{"q":"Что значит 站?","options":["остановка, стоять","дорога","идти"],"correct":0},{"q":"Как сказать «Я ищу остановку»?","options":["我在找站。","我找在站。","在我找站。"],"correct":0}]}'),
  ('hsk2-09-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["商店","在","学校","旁边"],"hint":"«Магазин рядом со школой.»"},{"answer":["医院","离","学校","很","近"],"hint":"«Больница недалеко от школы.»"},{"answer":["我","去","过","北京"],"hint":"«Я бывал в Пекине.»"},{"answer":["我","在","找","公共汽车","站"],"hint":"«Я ищу автобусную остановку.»"}]}'),
  ('hsk2-09-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"学校从我家很近。","context":"«Школа близко от дома»","options":["学校我家离很近。","学校离我家很近。","学校离近我家很。"],"correct":1},{"buggyText":"我去北京过。","context":"«Я бывал в Пекине»","options":["我去过北京。","我过去北京。","过我去北京。"],"correct":0},{"buggyText":"我不去过。","context":"«Я не был»","options":["我去不过。","我没去过。","不我去过。"],"correct":1}]}'),
  ('hsk2-09-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Прохожий","text":"我在找公共汽车站。","pinyin":"Wǒ zài zhǎo gōnggòng qìchē zhàn.","translation":"Я ищу автобусную остановку.","options":["我找你。","公共汽车站在学校旁边。","公共汽车站是找。"],"correct":1},{"speaker":"Прохожий","text":"离这儿远吗？","pinyin":"Lí zhèr yuǎn ma?","translation":"Далеко отсюда?","options":["不远，很近。","远，我走。","不是，我远。"],"correct":0}]}'),
  ('hsk2-09-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"左","pinyin":"zuǒ","m":"лево","hint":"ナ + 工"},{"hanzi":"右","pinyin":"yòu","m":"право","hint":"ナ + 口"},{"hanzi":"站","pinyin":"zhàn","m":"стоять","hint":"立 + 占"}]}'),
  ('hsk2-09-6', 10, 'recall', '{"words":[{"hanzi":"旁边","pinyin":"pángbiān","m":"рядом"},{"hanzi":"左边","pinyin":"zuǒbian","m":"слева"},{"hanzi":"右边","pinyin":"yòubian","m":"справа"},{"hanzi":"外","pinyin":"wài","m":"снаружи"},{"hanzi":"近","pinyin":"jìn","m":"близкий"},{"hanzi":"远","pinyin":"yuǎn","m":"далёкий"},{"hanzi":"离","pinyin":"lí","m":"от (расстояние)"},{"hanzi":"过","pinyin":"guò","m":"частица опыта"},{"hanzi":"找","pinyin":"zhǎo","m":"искать"},{"hanzi":"站","pinyin":"zhàn","m":"остановка"}],"tf":[{"zh":"学校从我家很近。","py":"xuéxiào cóng wǒ jiā hěn jìn.","m":"Школа близко от дома.","ok":false,"explain":"Правильно: 学校离我家很近."},{"zh":"我去过北京。","py":"wǒ qù guo Běijīng.","m":"Я бывал в Пекине.","ok":true}],"sentences":[{"zh":"商店在学校旁边。","tokens":["商店","在","学校","旁边"],"m":"Магазин рядом со школой."},{"zh":"学校离我家很近。","tokens":["学校","离","我","家","很","近"],"m":"Школа близко от моего дома."},{"zh":"我去过北京。","tokens":["我","去","过","北京"],"m":"Я бывал в Пекине."}]}'),
  ('hsk2-10-1', 1, 'fact', '{"emoji":"☕","title":"Слово, которое пришло из чужого языка","text":"咖啡 kāfēi «кофе» — звуковая калька: оба знака с 口 «рот» просто передают звучание иностранного слова. Знак 奶 «молоко» содержит 女 «женщина»: материнское молоко. А 面条 miàntiáo — «лапша»: 面 «мука» и 条 «полоска». Так выглядят блюда китайского завтрака."}'),
  ('hsk2-10-1', 2, 'words', '{"title":"Завтрак","items":[{"hanzi":"咖啡","pinyin":"kāfēi","m":"кофе","emoji":"☕","ex":{"zh":"我喝咖啡。","py":"Wǒ hē kāfēi.","m":"Я пью кофе."}},{"hanzi":"牛奶","pinyin":"niúnǎi","m":"молоко","emoji":"🥛","ex":{"zh":"我喜欢喝牛奶。","py":"Wǒ xǐhuan hē niúnǎi.","m":"Я люблю молоко."}},{"hanzi":"面条","pinyin":"miàntiáo","m":"лапша","emoji":"🍜","ex":{"zh":"我吃面条。","py":"Wǒ chī miàntiáo.","m":"Я ем лапшу."}},{"hanzi":"鸡蛋","pinyin":"jīdàn","m":"яйцо","emoji":"🥚","ex":{"zh":"我早上吃鸡蛋。","py":"Wǒ zǎoshang chī jīdàn.","m":"По утрам я ем яйцо."}}]}'),
  ('hsk2-10-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"☕","options":["面条","牛奶","咖啡"],"correct":2},{"emoji":"🥛","options":["牛奶","鸡蛋","咖啡"],"correct":0},{"emoji":"🍜","options":["鸡蛋","咖啡","面条"],"correct":2},{"emoji":"🥚","options":["鸡蛋","牛奶","面条"],"correct":0}]}'),
  ('hsk2-10-1', 4, 'theory', '{"title":"Что едим и пьём","blocks":[{"t":"table","head":["Слово","Глагол","Пример"],"rows":[["咖啡, 牛奶","喝","我喝咖啡。"],["面条, 鸡蛋","吃","我吃面条。"]]},{"t":"p","text":"Напитки пьют (喝), еду едят (吃): правило из HSK 1 остаётся. Для количества используют 杯 с напитками и 个 с яйцами: 一杯咖啡, 一个鸡蛋."},{"t":"tip","text":"鸡蛋 — «куриное яйцо»: 鸡 «курица» и 蛋 «яйцо»."}]}'),
  ('hsk2-10-1', 5, 'quiz', '{"title":"Мини-тест: еда и напитки","qs":[{"q":"Какой глагол сочетается с 咖啡?","options":["买","喝","吃"],"correct":1},{"q":"Как сказать «одно яйцо»?","options":["一个鸡蛋","一杯鸡蛋","鸡蛋一个"],"correct":0},{"q":"牛奶 пьют, а не едят.","tf":true}]}'),
  ('hsk2-10-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["咖啡","кофе"],["牛奶","молоко"],["面条","лапша"],["鸡蛋","яйцо"],["一杯咖啡","чашка кофе"]]}'),
  ('hsk2-10-1', 7, 'game', '{"type":"listen","title":"Слушаем завтрак","items":[{"say":"咖啡","options":["kǎfēi","kāféi","kāfēi"],"correct":2},{"say":"牛奶","options":["níunǎi","niúnài","niúnǎi"],"correct":2},{"say":"面条","options":["miàntiáo","miàntiǎo","miāntiáo"],"correct":0},{"say":"鸡蛋","options":["jídàn","jīdàn","jīdǎn"],"correct":1},{"say":"我喝咖啡","options":["wǒ hē kāfēi","wǒ chī kāfēi"],"correct":0}]}'),
  ('hsk2-10-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","喝","咖啡"],"hint":"«Я пью кофе.»"},{"answer":["我","吃","面条"],"hint":"«Я ем лапшу.»"},{"answer":["我","早上","吃","鸡蛋"],"hint":"«По утрам я ем яйцо.»"}]}'),
  ('hsk2-10-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"奶","pinyin":"nǎi","m":"молоко","hint":"слева 女, справа 乃"},{"hanzi":"蛋","pinyin":"dàn","m":"яйцо","hint":"сверху 疋, внизу 虫"},{"hanzi":"面","pinyin":"miàn","m":"мука, лицо","hint":"горизонталь, вертикаль, рамка"}]}'),
  ('hsk2-10-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 面条?","options":["лапша","яйцо","молоко"],"correct":0},{"q":"Как читается 咖啡?","options":["kāféi","kāfēi","kǎfēi"],"correct":1},{"q":"Как сказать «Я люблю молоко»?","options":["我牛奶喜欢。","喜欢我牛奶。","我喜欢牛奶。"],"correct":2},{"q":"鸡蛋 — это «курица».","tf":false,"explain":"鸡蛋 — яйцо; «курица» — 鸡."},{"q":"Какой ключ у 奶?","options":["口","亻","女"],"correct":2}]}'),
  ('hsk2-10-2', 1, 'fact', '{"emoji":"🐟","title":"Рыба на счастье","text":"Слово 鱼 yú «рыба» звучит как 余 yú «излишек»: на Новый год китайцы подают рыбу и говорят 年年有余 «каждый год есть излишек». А глагол 要 yào в ресторане означает «хочу, мне нужно»: 我要面条. И маленькое слово 好吃 hǎochī «вкусный» состоит из 好 «хороший» и 吃 «есть»."}'),
  ('hsk2-10-2', 2, 'words', '{"title":"Заказ","items":[{"hanzi":"要","pinyin":"yào","m":"хотеть, нужно, будет","emoji":"🙋","ex":{"zh":"我要一杯咖啡。","py":"Wǒ yào yì bēi kāfēi.","m":"Мне чашку кофе."}},{"hanzi":"好吃","pinyin":"hǎochī","m":"вкусный","emoji":"😋","ex":{"zh":"这个菜很好吃。","py":"Zhège cài hěn hǎochī.","m":"Это блюдо очень вкусное."}},{"hanzi":"鱼","pinyin":"yú","m":"рыба","emoji":"🐟","ex":{"zh":"我要鱼。","py":"Wǒ yào yú.","m":"Мне рыбу."}}]}'),
  ('hsk2-10-2', 3, 'theory', '{"title":"Заказываем: 我要…","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我要一杯咖啡。","Мне чашку кофе."],["我要面条和鱼。","Мне лапшу и рыбу."],["你要什么？","Что вы хотите?"],["我不要牛奶。","Мне не нужно молоко."]]},{"t":"p","text":"要 + существительное — «мне нужно…». Отрицание 不要 значит «не нужно». 要 + глагол означает намерение: 我要去北京 «я собираюсь в Пекин»."},{"t":"tip","text":"好吃 — слово для еды. Для напитков говорят 好喝 hǎohē «вкусно пить»."}]}'),
  ('hsk2-10-2', 4, 'game', '{"type":"build","title":"Соберите заказ","items":[{"answer":["我","要","一","杯","咖啡"],"hint":"«Мне чашку кофе.»"},{"answer":["我","要","面条","和","鱼"],"hint":"«Мне лапшу и рыбу.»"},{"answer":["这个","菜","很","好吃"],"hint":"«Это блюдо очень вкусное.»"}]}'),
  ('hsk2-10-2', 5, 'quiz', '{"title":"Мини-тест: заказ","qs":[{"q":"Как заказать кофе?","options":["我杯咖啡要一。","我要一杯咖啡。","要我一杯咖啡。"],"correct":1},{"q":"Что значит 好吃?","options":["большой","дорогой","вкусный"],"correct":2},{"q":"要 в ресторане значит «хочу, мне нужно».","tf":true}]}'),
  ('hsk2-10-2', 6, 'theory', '{"title":"要 как «будет, собираюсь»","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我要去北京。","Я собираюсь в Пекин."],["明天要下雨。","Завтра будет дождь."],["你要吃什么？","Что ты будешь есть?"]]},{"t":"p","text":"Перед глаголом 要 выражает планы и будущее. Значит, одно слово покрывает и «хочу», и «буду»."}]}'),
  ('hsk2-10-2', 7, 'game', '{"type":"listen","title":"Слушаем заказ","items":[{"say":"要","options":["yǎo","yáo","yào"],"correct":2},{"say":"好吃","options":["hǎochí","hǎochī","hàochī"],"correct":1},{"say":"鱼","options":["yú","yù","yǔ"],"correct":0},{"say":"我要一杯咖啡","options":["wǒ yào yí bēi kāfēi","wǒ yào yì bēi kāfēi"],"correct":1},{"say":"这个菜很好吃","options":["zhège cài hěn hǎochī","zhège cài hěn hǎohē"],"correct":0}]}'),
  ('hsk2-10-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["要","хотеть, нужно"],["好吃","вкусный"],["鱼","рыба"],["不要","не нужно"],["我要鱼","мне рыбу"]]}'),
  ('hsk2-10-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: заказ","cases":[{"buggyText":"我要一杯咖啡个。","context":"«Мне чашку кофе»","options":["要我一杯咖啡。","我要一杯咖啡。","我要咖啡一杯个。"],"correct":1},{"buggyText":"这个菜好吃很。","context":"«Это блюдо вкусное»","options":["这个菜很好吃。","好吃这个菜很。","这个很菜好吃。"],"correct":0},{"buggyText":"我吃要鱼。","context":"«Мне рыбу»","options":["我鱼要。","我要鱼。","要我鱼。"],"correct":1}]}'),
  ('hsk2-10-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как читается 要?","options":["yáo","yǎo","yào"],"correct":2},{"q":"Как сказать «Мне не нужно молоко»?","options":["不我要牛奶。","我要不牛奶。","我不要牛奶。"],"correct":2},{"q":"要 может выражать намерение.","tf":true},{"q":"Как сказать «Это очень вкусно»?","options":["好吃很","很好吃","很吃好"],"correct":1},{"q":"Что значит 鱼?","options":["рыба","лапша","яйцо"],"correct":0}]}'),
  ('hsk2-10-3', 1, 'fact', '{"emoji":"🍉","title":"Арбуз пришёл с запада","text":"西瓜 xīguā «арбуз» — «западная дыня»: 西 «запад», 瓜 «дыня, тыква». Арбуз попал в Китай по Шёлковому пути. А 羊肉 yángròu «баранина»: 羊 «баран» и 肉 «мясо». Знак 羊 нарисован как голова с рогами."}'),
  ('hsk2-10-3', 2, 'words', '{"title":"Мясо и фрукты","items":[{"hanzi":"羊肉","pinyin":"yángròu","m":"баранина","emoji":"🍖","ex":{"zh":"我要羊肉。","py":"Wǒ yào yángròu.","m":"Мне баранину."}},{"hanzi":"西瓜","pinyin":"xīguā","m":"арбуз","emoji":"🍉","ex":{"zh":"我喜欢吃西瓜。","py":"Wǒ xǐhuan chī xīguā.","m":"Я люблю арбуз."}}]}'),
  ('hsk2-10-3', 3, 'game', '{"type":"listen","title":"Слушаем: мясо и арбуз","items":[{"say":"羊肉","options":["yángròù","yǎngròu","yángròu"],"correct":2},{"say":"西瓜","options":["xīguǎ","xíguā","xīguā"],"correct":2},{"say":"我喜欢吃西瓜","options":["wǒ xǐhuan chī xīguā","wǒ xǐhuan hē xīguā"],"correct":0},{"say":"羊肉好吃吗","options":["yángròu hǎochī ne","yángròu hǎochī ma"],"correct":1},{"say":"我要羊肉和鱼","options":["wǒ yào yángròu hé yīfu","wǒ yào yángròu hé yú"],"correct":1}]}'),
  ('hsk2-10-3', 4, 'game', '{"type":"tone_visualizer","initialTone":2,"title":"Тренажёр голоса: повторите «yáng» (2 тон)"}'),
  ('hsk2-10-3', 5, 'theory', '{"title":"Меню на выбор","blocks":[{"t":"table","head":["Блюдо","Слово","Глагол"],"rows":[["羊肉","баранина","吃"],["鱼","рыба","吃"],["西瓜","арбуз","吃"],["牛奶, 咖啡","напитки","喝"]]},{"t":"p","text":"Слова из ресторана строятся одинаково: 我要 + блюдо. Для вопроса «вкусно?» добавляйте 好吃吗？"}]}'),
  ('hsk2-10-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🍖","options":["羊肉","西瓜","鱼"],"correct":0},{"emoji":"🍉","options":["鱼","西瓜","羊肉"],"correct":1}]}'),
  ('hsk2-10-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["羊肉","баранина"],["西瓜","арбуз"],["鱼","рыба"],["好吃","вкусный"],["羊肉好吃吗？","баранина вкусная?"]]}'),
  ('hsk2-10-3', 8, 'game', '{"type":"chatsim","title":"В ресторане","messages":[{"speaker":"Официант","text":"你们要什么？","pinyin":"Nǐmen yào shénme?","translation":"Что вы хотите?","options":["我要羊肉和面条。","我们是羊肉。","我要什么吗。"],"correct":0},{"speaker":"Официант","text":"你们喝什么？","pinyin":"Nǐmen hē shénme?","translation":"Что будете пить?","options":["我要咖啡，她要牛奶。","咖啡我们要吃。","我喝是咖啡。"],"correct":0},{"speaker":"Официант","text":"要西瓜吗？","pinyin":"Yào xīguā ma?","translation":"Арбуз будете?","options":["没有，再见。","要，谢谢！","不是，我是西瓜。"],"correct":1}]}'),
  ('hsk2-10-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","要","羊肉"],"hint":"«Мне баранину.»"},{"answer":["我","喜欢","吃","西瓜"],"hint":"«Я люблю арбуз.»"},{"answer":["羊肉","好吃","吗"],"hint":"«Баранина вкусная?»"}]}'),
  ('hsk2-10-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 西瓜?","options":["арбуз","яблоко","рыба"],"correct":0},{"q":"Как читается 羊肉?","options":["yángròù","yǎngròu","yángròu"],"correct":2},{"q":"西瓜 буквально «западная дыня».","tf":true},{"q":"Как спросить «Арбуз вкусный?»","options":["好吃西瓜吗？","西瓜好吃吗？","西瓜吗好吃？"],"correct":1},{"q":"Что значит 羊肉?","options":["баранина","кофе","арбуз"],"correct":0}]}'),
  ('hsk2-10-4', 1, 'fact', '{"emoji":"🍽️","title":"Ужин на двоих","text":"Анна и Ли Мин приходят в ресторан и заказывают еду. В диалоге встретятся 咖啡, 牛奶, 面条, 鱼, 羊肉, 西瓜, 好吃, 要."}'),
  ('hsk2-10-4', 2, 'text', '{"title":"В ресторане","lines":[{"zh":"服务员：你们好！你们要什么？","py":"Fúwùyuán: Nǐmen hǎo! Nǐmen yào shénme?","m":"Официант: Здравствуйте! Что желаете?"},{"zh":"李明：我要面条和鱼。","py":"Lǐ Míng: Wǒ yào miàntiáo hé yú.","m":"Ли Мин: Мне лапшу и рыбу."},{"zh":"安娜：我要一个鸡蛋和一杯咖啡。","py":"Ānnà: Wǒ yào yí gè jīdàn hé yì bēi kāfēi.","m":"Анна: Мне яйцо и чашку кофе."},{"zh":"服务员：你们喝牛奶吗？","py":"Fúwùyuán: Nǐmen hē niúnǎi ma?","m":"Официант: Молоко будете?"},{"zh":"安娜：不要，谢谢。","py":"Ānnà: Bú yào, xièxie.","m":"Анна: Нет, спасибо."},{"zh":"李明：羊肉好吃吗？","py":"Lǐ Míng: Yángròu hǎochī ma?","m":"Ли Мин: Баранина вкусная?"},{"zh":"服务员：非常好吃！","py":"Fúwùyuán: Fēicháng hǎochī!","m":"Официант: Очень вкусная!"},{"zh":"李明：好，我也要羊肉。我们也要一个西瓜吧。","py":"Lǐ Míng: Hǎo, wǒ yě yào yángròu. Wǒmen yě yào yí gè xīguā ba.","m":"Ли Мин: Хорошо, мне ещё баранину. И арбуз тоже возьмём."}],"qs":[{"q":"Что заказывает Ли Мин вначале?","options":["лапшу и рыбу","яйцо и кофе","арбуз"],"correct":0},{"q":"Что просит Анна?","options":["лапшу и рыбу","баранину","яйцо и кофе"],"correct":2},{"q":"Анна хочет молоко.","tf":false,"explain":"Она отвечает 不要."},{"q":"Что говорит официант о баранине?","options":["слишком дорогая","невкусная","очень вкусная"],"correct":2},{"q":"В конце они заказывают арбуз.","tf":true},{"q":"Вставьте слово: 我___面条和鱼。","options":["在","喝","要"],"correct":2},{"q":"Какое слово значит «вкусный»?","options":["好看","好喝","好吃"],"correct":2}]}'),
  ('hsk2-10-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["我要面条和鱼","мне лапшу и рыбу"],["不要，谢谢","нет, спасибо"],["羊肉好吃吗？","баранина вкусная?"],["非常好吃","очень вкусная"],["我们要一个西瓜吧","возьмём арбуз"]]}'),
  ('hsk2-10-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你们要什么","options":["nǐmen xiǎng shénme","nǐmen yào shénme"],"correct":1},{"say":"我要面条和鱼","options":["wǒ yào miàntiáo hé yángròu","wǒ yào miàntiáo hé yú"],"correct":1},{"say":"不要谢谢","options":["bú yào xièxie","bù yào xièxie"],"correct":0},{"say":"非常好吃","options":["fēicháng hǎohē","fēicháng hǎochī"],"correct":1}]}'),
  ('hsk2-10-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: в ресторане","cases":[{"buggyText":"我要面条和鱼吃。","context":"«Мне лапшу и рыбу»","options":["我吃要面条和鱼。","我要面条和鱼。","面条和鱼我要吃。"],"correct":1},{"buggyText":"不要谢谢牛奶。","context":"«Молоко не надо, спасибо»","options":["不牛奶要谢谢。","牛奶不要，谢谢。","谢谢不要牛奶吗。"],"correct":1},{"buggyText":"羊肉吃好吗？","context":"«Баранина вкусная?»","options":["好吃羊肉吗？","羊肉好吃吗？","吗羊肉好吃？"],"correct":1}]}'),
  ('hsk2-10-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как отказаться от молока?","options":["不要，谢谢。","没有，谢谢。","不是，谢谢。"],"correct":0},{"q":"Как читается 非常好吃?","options":["fēicháng hǎochī","fēicháng hǎohē","féicháng hǎochī"],"correct":0},{"q":"Ли Мин спрашивает про баранину.","tf":true}]}'),
  ('hsk2-10-5', 1, 'fact', '{"emoji":"📋","title":"Составьте меню на день","text":"Придумайте завтрак, обед и ужин, соберите знаки еды и «закажите» блюдо. Слова глав 1–10 HSK 2."}'),
  ('hsk2-10-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"奶","correctRadicals":["女","乃"],"title":"Пазл: соберите 奶"}'),
  ('hsk2-10-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"鱼","radicals":["⺈","田","一"],"correctOrder":["⺈","田","一"],"explain":"Сверху ⺈, затем 田, внизу 一."},{"targetHanzi":"蛋","radicals":["疋","虫","女"],"correctOrder":["疋","虫"],"explain":"Сверху 疋, внизу 虫."},{"targetHanzi":"瓜","radicals":["厂","ム","人"],"correctOrder":["厂","ム"],"explain":"Крыша и два крючка."}]}'),
  ('hsk2-10-5', 4, 'game', '{"type":"build","title":"Мастерская меню","items":[{"target":"(Завтрак)","answer":["早上","我","喝","咖啡","，","吃","鸡蛋"],"hint":"«Утром я пью кофе и ем яйцо.»"},{"target":"(Обед)","answer":["中午","我","要","面条","和","鱼"],"hint":"«В обед мне лапшу и рыбу.»"},{"target":"(Ужин)","answer":["晚上","我","要","羊肉"],"hint":"«Вечером мне баранину.»"},{"target":"(Десерт)","answer":["我","喜欢","吃","西瓜"],"hint":"«Я люблю арбуз.»"}]}'),
  ('hsk2-10-5', 5, 'theory', '{"title":"Образец меню","blocks":[{"t":"table","head":["Время","Фраза"],"rows":[["Утро","我喝咖啡，吃鸡蛋。"],["День","我要面条和鱼。"],["Вечер","我要羊肉。"],["Десерт","我要西瓜。"]]}]}'),
  ('hsk2-10-5', 6, 'game', '{"type":"chatsim","title":"WeChat: что мы едим","messages":[{"speaker":"Друг","text":"你早上吃什么？","pinyin":"Nǐ zǎoshang chī shénme?","translation":"Что ты ешь по утрам?","options":["我吃是鸡蛋。","鸡蛋我早上喝。","我吃鸡蛋，喝牛奶。"],"correct":2},{"speaker":"Друг","text":"你喜欢吃什么？","pinyin":"Nǐ xǐhuan chī shénme?","translation":"Что тебе нравится?","options":["我喜欢面条和西瓜。","我喜欢什么吃。","我吃喜欢面条。"],"correct":0},{"speaker":"Друг","text":"羊肉好吃吗？","pinyin":"Yángròu hǎochī ma?","translation":"Баранина вкусная?","options":["非常好吃！","不是，好吃。","羊肉吃吗。"],"correct":0}]}'),
  ('hsk2-10-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["女 + 乃","奶"],["疋 + 虫","蛋"],["羊 + 肉","羊肉"],["西 + 瓜","西瓜"]]}'),
  ('hsk2-10-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"鱼","pinyin":"yú","m":"рыба","hint":"сверху ⺈, внизу 田 и 一"},{"hanzi":"羊","pinyin":"yáng","m":"баран","hint":"две точки, три горизонтали, вертикаль"},{"hanzi":"要","pinyin":"yào","m":"хотеть","hint":"сверху 西, внизу 女"}]}'),
  ('hsk2-10-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я люблю арбуз»?","options":["我吃喜欢西瓜。","我喜欢吃西瓜。","西瓜我吃喜欢。"],"correct":1},{"q":"Какие знаки составляют 西瓜?","options":["女 и 乃","口 и 非","西 и 瓜"],"correct":2},{"q":"Меню составляют из знакомых слов.","tf":true}]}'),
  ('hsk2-10-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 10 (HSK 2)","text":"咖啡, 牛奶, 面条, 鸡蛋, 鱼, 羊肉, 西瓜, 好吃 и 要."}'),
  ('hsk2-10-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"咖啡","options":["niúnǎi","miàntiáo","kāfēi"],"correct":2},{"say":"我要一杯咖啡","options":["wǒ yào yì bēi kāfēi","wǒ yào yí bēi kāfēi"],"correct":0},{"say":"这个菜很好吃","options":["zhège cài hěn hǎochī","zhège cài hěn hǎohē"],"correct":0},{"say":"羊肉","options":["yángròu","xīguā"],"correct":0},{"say":"不要谢谢","options":["bù yào xièxie","bú yào xièxie"],"correct":1},{"say":"我喜欢吃西瓜","options":["wǒ xǐhuan chī xīguā","wǒ xǐhuan hē xīguā"],"correct":0}]}'),
  ('hsk2-10-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"☕","options":["咖啡","鱼","牛奶"],"correct":0},{"emoji":"🍜","options":["鸡蛋","羊肉","面条"],"correct":2},{"emoji":"🥚","options":["鱼","西瓜","鸡蛋"],"correct":2},{"emoji":"🍉","options":["西瓜","面条","咖啡"],"correct":0}]}'),
  ('hsk2-10-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["咖啡","кофе"],["牛奶","молоко"],["面条","лапша"],["鸡蛋","яйцо"],["鱼","рыба"],["羊肉","баранина"],["西瓜","арбуз"],["好吃","вкусный"],["要","хотеть"]]}'),
  ('hsk2-10-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как заказать кофе?","options":["我要一杯咖啡。","我杯咖啡要一。","要我一杯咖啡。"],"correct":0},{"q":"Какой глагол с 牛奶?","options":["喝","吃","买"],"correct":0},{"q":"Как сказать «Это очень вкусно»?","options":["好吃很","很吃好","很好吃"],"correct":2},{"q":"好吃 говорят о еде.","tf":true},{"q":"Как отказаться?","options":["没有，谢谢。","不要，谢谢。","不是，谢谢。"],"correct":1},{"q":"Что значит 西瓜 буквально?","options":["западная дыня","большая дыня","красная дыня"],"correct":0},{"q":"鸡蛋 — это курица.","tf":false},{"q":"Как спросить «Что вы желаете?»","options":["要你们什么？","你们要什么？","你们什么要？"],"correct":1},{"q":"Как читается 羊肉?","options":["yǎngròu","yángròu","yángròù"],"correct":1},{"q":"Что значит 要 перед глаголом?","options":["собираюсь, буду","уже","не хочу"],"correct":0}]}'),
  ('hsk2-10-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","要","一","杯","咖啡"],"hint":"«Мне чашку кофе.»"},{"answer":["我","要","面条","和","鱼"],"hint":"«Мне лапшу и рыбу.»"},{"answer":["羊肉","非常","好吃"],"hint":"«Баранина очень вкусная.»"},{"answer":["我","喜欢","吃","西瓜"],"hint":"«Я люблю арбуз.»"}]}'),
  ('hsk2-10-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我要一杯咖啡个。","context":"«Мне чашку кофе»","options":["我要一杯咖啡。","我要咖啡一杯个。","要我一杯咖啡。"],"correct":0},{"buggyText":"这个菜好吃很。","context":"«Это блюдо вкусное»","options":["好吃这个菜很。","这个菜很好吃。","这个很菜好吃。"],"correct":1},{"buggyText":"我吃要鱼。","context":"«Мне рыбу»","options":["要我鱼。","我要鱼。","我鱼要。"],"correct":1}]}'),
  ('hsk2-10-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Официант","text":"你们要什么？","pinyin":"Nǐmen yào shénme?","translation":"Что желаете?","options":["我要什么吗。","我们是面条。","我要面条和鱼。"],"correct":2},{"speaker":"Официант","text":"你们喝什么？","pinyin":"Nǐmen hē shénme?","translation":"Что будете пить?","options":["咖啡我们吃。","我要咖啡。","我喝是咖啡。"],"correct":1}]}'),
  ('hsk2-10-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"奶","pinyin":"nǎi","m":"молоко","hint":"女 + 乃"},{"hanzi":"鱼","pinyin":"yú","m":"рыба","hint":"⺈ + 田 + 一"},{"hanzi":"要","pinyin":"yào","m":"хотеть","hint":"西 + 女"}]}'),
  ('hsk2-10-6', 10, 'recall', '{"words":[{"hanzi":"咖啡","pinyin":"kāfēi","m":"кофе"},{"hanzi":"牛奶","pinyin":"niúnǎi","m":"молоко"},{"hanzi":"面条","pinyin":"miàntiáo","m":"лапша"},{"hanzi":"鸡蛋","pinyin":"jīdàn","m":"яйцо"},{"hanzi":"鱼","pinyin":"yú","m":"рыба"},{"hanzi":"羊肉","pinyin":"yángròu","m":"баранина"},{"hanzi":"西瓜","pinyin":"xīguā","m":"арбуз"},{"hanzi":"好吃","pinyin":"hǎochī","m":"вкусный"},{"hanzi":"要","pinyin":"yào","m":"хотеть"}],"tf":[{"zh":"我吃咖啡。","py":"wǒ chī kāfēi.","m":"Я пью кофе.","ok":false,"explain":"Кофе пьют: 我喝咖啡."},{"zh":"我要面条和鱼。","py":"wǒ yào miàntiáo hé yú.","m":"Мне лапшу и рыбу.","ok":true}],"sentences":[{"zh":"我要一杯咖啡。","tokens":["我","要","一","杯","咖啡"],"m":"Мне чашку кофе."},{"zh":"我要面条和鱼。","tokens":["我","要","面条","和","鱼"],"m":"Мне лапшу и рыбу."},{"zh":"羊肉非常好吃。","tokens":["羊肉","非常","好吃"],"m":"Баранина очень вкусная."}]}'),
  ('hsk2-11-1', 1, 'fact', '{"emoji":"🏀","title":"Корзина и нога","text":"Слово 篮球 «баскетбол» — это 篮 «корзина» (с ключом 竹 «бамбук») и 球 «мяч». Игра названа по корзине, куда кидают мяч. А 足球 «футбол» — «нога + мяч». И во всех глаголах спорта есть логика: 打 «бить» (по мячу), 踢 «пинать», 跑 «бежать» с ключом 足 «нога»."}'),
  ('hsk2-11-1', 2, 'words', '{"title":"Спорт","items":[{"hanzi":"打篮球","pinyin":"dǎ lánqiú","m":"играть в баскетбол","emoji":"🏀","ex":{"zh":"我喜欢打篮球。","py":"Wǒ xǐhuan dǎ lánqiú.","m":"Я люблю играть в баскетбол."}},{"hanzi":"踢足球","pinyin":"tī zúqiú","m":"играть в футбол","emoji":"⚽","ex":{"zh":"我哥哥踢足球。","py":"Wǒ gēge tī zúqiú.","m":"Мой брат играет в футбол."}},{"hanzi":"跑步","pinyin":"pǎobù","m":"бегать","emoji":"🏃","ex":{"zh":"他每天跑步。","py":"Tā měi tiān pǎobù.","m":"Он каждый день бегает."}},{"hanzi":"游泳","pinyin":"yóuyǒng","m":"плавать","emoji":"🏊","ex":{"zh":"我会游泳。","py":"Wǒ huì yóuyǒng.","m":"Я умею плавать."}}]}'),
  ('hsk2-11-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🏀","options":["踢足球","游泳","打篮球"],"correct":2},{"emoji":"⚽","options":["踢足球","跑步","打篮球"],"correct":0},{"emoji":"🏃","options":["游泳","跑步","踢足球"],"correct":1},{"emoji":"🏊","options":["打篮球","跑步","游泳"],"correct":2}]}'),
  ('hsk2-11-1', 4, 'theory', '{"title":"Какой глагол с каким мячом","blocks":[{"t":"table","head":["Игра","Глагол","Пример"],"rows":[["篮球 (баскетбол)","打 (бить рукой)","打篮球"],["足球 (футбол)","踢 (пинать ногой)","踢足球"],["бег","跑步","每天跑步"],["плавание","游泳","我会游泳"]]},{"t":"p","text":"В китайском глагол зависит от части тела: рукой «бьют» (打), ногой «пинают» (踢). 跑步 и 游泳 — готовые глаголы без дополнений."},{"t":"tip","text":"会 + глагол показывает умение: 我会游泳. 喜欢 + глагол — любимое занятие."}]}'),
  ('hsk2-11-1', 5, 'quiz', '{"title":"Мини-тест: спорт","qs":[{"q":"Какой глагол с 足球?","options":["跑","打","踢"],"correct":2},{"q":"Как сказать «Я умею плавать»?","options":["我游泳会。","我会游泳。","会我游泳。"],"correct":1},{"q":"篮球 содержит ключ 竹 «бамбук».","tf":true}]}'),
  ('hsk2-11-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["打篮球","играть в баскетбол"],["踢足球","играть в футбол"],["跑步","бегать"],["游泳","плавать"],["我会游泳","я умею плавать"]]}'),
  ('hsk2-11-1', 7, 'game', '{"type":"listen","title":"Слушаем спорт","items":[{"say":"打篮球","options":["dǎ lánqiǔ","dǎ lánqiú","dà lánqiú"],"correct":1},{"say":"踢足球","options":["tí zúqiú","tī zùqiú","tī zúqiú"],"correct":2},{"say":"跑步","options":["pàobù","páobù","pǎobù"],"correct":2},{"say":"游泳","options":["yóuyóng","yóuyǒng","yǒuyóng"],"correct":1},{"say":"我喜欢跑步","options":["wǒ xǐhuan pǎobù","wǒ xǐhuan yóuyǒng"],"correct":0}]}'),
  ('hsk2-11-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","喜欢","打","篮球"],"hint":"«Я люблю баскетбол.»"},{"answer":["他","每","天","跑步"],"hint":"«Он каждый день бегает.»"},{"answer":["我","会","游泳"],"hint":"«Я умею плавать.»"}]}'),
  ('hsk2-11-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"球","pinyin":"qiú","m":"мяч","hint":"слева 王, справа 求"},{"hanzi":"跑","pinyin":"pǎo","m":"бежать","hint":"слева 足, справа 包"},{"hanzi":"泳","pinyin":"yǒng","m":"плавать","hint":"слева 氵, справа 永"}]}'),
  ('hsk2-11-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 跑步?","options":["прыгать","бегать","плавать"],"correct":1},{"q":"Как читается 游泳?","options":["yóuyǒng","yǒuyóng","yóuyóng"],"correct":0},{"q":"Как сказать «Я люблю футбол»?","options":["我喜欢踢足球。","我踢喜欢足球。","喜欢我踢足球。"],"correct":0},{"q":"踢 — «пинать ногой».","tf":true},{"q":"Какой ключ в 泳?","options":["氵","足","亻"],"correct":0}]}'),
  ('hsk2-11-2', 1, 'fact', '{"emoji":"🎵","title":"Одна схема для всех увлечений","text":"Схема «喜欢 + глагол» вам знакома: 我喜欢唱歌 «я люблю петь». Теперь у вас есть новые глаголы: 唱歌 chànggē «петь» (唱 «петь» + 歌 «песня»), 跳舞 tiàowǔ «танцевать» (跳 «прыгать» + 舞 «танец»), 运动 yùndòng «заниматься спортом» и 玩 wán «играть, развлекаться»."}'),
  ('hsk2-11-2', 2, 'words', '{"title":"Увлечения","items":[{"hanzi":"跳舞","pinyin":"tiàowǔ","m":"танцевать","emoji":"💃","ex":{"zh":"她喜欢跳舞。","py":"Tā xǐhuan tiàowǔ.","m":"Она любит танцевать."}},{"hanzi":"唱歌","pinyin":"chànggē","m":"петь","emoji":"🎤","ex":{"zh":"我哥哥会唱歌。","py":"Wǒ gēge huì chànggē.","m":"Мой брат умеет петь."}},{"hanzi":"运动","pinyin":"yùndòng","m":"заниматься спортом, спорт","emoji":"🏋️","ex":{"zh":"我每天运动。","py":"Wǒ měi tiān yùndòng.","m":"Я каждый день занимаюсь спортом."}},{"hanzi":"玩","pinyin":"wán","m":"играть, развлекаться","emoji":"🎮","ex":{"zh":"我们去玩吧。","py":"Wǒmen qù wán ba.","m":"Пойдёмте развлекаться."}}]}'),
  ('hsk2-11-2', 3, 'theory', '{"title":"喜欢, 会, 想 + глагол","blocks":[{"t":"table","head":["Схема","Пример","Перевод"],"rows":[["喜欢 + глагол","我喜欢唱歌。","Я люблю петь."],["会 + глагол","我会跳舞。","Я умею танцевать."],["想 + глагол","我想去玩。","Я хочу пойти поиграть."],["每天 + глагол","我每天运动。","Я каждый день занимаюсь."]]},{"t":"p","text":"Все эти слова стоят перед глаголом и не меняют форму. 玩 — самое общее слово для «гулять, играть, развлекаться»: 我们去哪儿玩？ «Куда пойдём развлекаться?»"},{"t":"tip","text":"唱歌 и 跳舞 — «глагол + объект»: между ними можно вставить 个: 唱个歌, 跳个舞."}]}'),
  ('hsk2-11-2', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","喜欢","唱歌"],"hint":"«Я люблю петь.»"},{"answer":["她","会","跳舞"],"hint":"«Она умеет танцевать.»"},{"answer":["我","每","天","运动"],"hint":"«Я каждый день занимаюсь спортом.»"},{"answer":["我们","去","玩","吧"],"hint":"«Пойдёмте развлекаться.»"}]}'),
  ('hsk2-11-2', 5, 'quiz', '{"title":"Мини-тест: увлечения","qs":[{"q":"Как сказать «Я люблю петь»?","options":["我唱歌喜欢。","喜欢我唱歌。","我喜欢唱歌。"],"correct":2},{"q":"Что значит 玩?","options":["работать","играть, развлекаться","спать"],"correct":1},{"q":"会 + глагол — «уметь».","tf":true}]}'),
  ('hsk2-11-2', 6, 'game', '{"type":"listen","title":"Слушаем: увлечения","items":[{"say":"跳舞","options":["tiáowǔ","tiàowù","tiàowǔ"],"correct":2},{"say":"唱歌","options":["chánggē","chǎnggē","chànggē"],"correct":2},{"say":"运动","options":["yùndǒng","yúndòng","yùndòng"],"correct":2},{"say":"玩","options":["wàn","wán","wǎn"],"correct":1},{"say":"我喜欢唱歌","options":["wǒ xǐhuan tiàowǔ","wǒ xǐhuan chànggē"],"correct":1}]}'),
  ('hsk2-11-2', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["跳舞","танцевать"],["唱歌","петь"],["运动","спорт"],["玩","играть, развлекаться"],["我们去玩吧","пойдёмте развлекаться"]]}'),
  ('hsk2-11-2', 8, 'game', '{"type":"bughunt","title":"Китайский детектив: увлечения","cases":[{"buggyText":"我喜欢歌唱。","context":"«Я люблю петь»","options":["我喜欢唱歌。","我歌喜欢唱。","喜欢我歌唱。"],"correct":0},{"buggyText":"她会舞跳。","context":"«Она умеет танцевать»","options":["会她跳舞。","她会跳舞。","她跳会舞。"],"correct":1},{"buggyText":"我们玩去吧。","context":"«Пойдёмте развлекаться»","options":["去我们玩吧。","我们去玩吧。","我们吧去玩。"],"correct":1}]}'),
  ('hsk2-11-2', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как читается 唱歌?","options":["chǎnggē","chánggē","chànggē"],"correct":2},{"q":"Как сказать «Она умеет танцевать»?","options":["她舞会跳。","她会跳舞。","她跳会舞。"],"correct":1},{"q":"喜欢 стоит перед глаголом.","tf":true},{"q":"Как сказать «Мы каждый день занимаемся спортом»?","options":["每天我们吗运动。","我们每天运动。","我们运动每天。"],"correct":1},{"q":"Что значит 运动?","options":["танцы","спорт","пение"],"correct":1}]}'),
  ('hsk2-11-3', 1, 'fact', '{"emoji":"🧳","title":"Знак смеха — это бамбук и ребёнок","text":"В 笑 xiào «смеяться» сверху стоит 竹 «бамбук», внизу 夭: бамбук качается на ветру, как смеющийся человек. А 旅游 lǚyóu «путешествовать» состоит из 旅 «путь» и 游 «гулять, плавать»: путешествие — это дорога и прогулка. Слово 游 уже знакомо по 游泳."}'),
  ('hsk2-11-3', 2, 'words', '{"title":"Поездки и смех","items":[{"hanzi":"旅游","pinyin":"lǚyóu","m":"путешествовать, туризм","emoji":"🧳","ex":{"zh":"我喜欢旅游。","py":"Wǒ xǐhuan lǚyóu.","m":"Я люблю путешествовать."}},{"hanzi":"笑","pinyin":"xiào","m":"смеяться, улыбаться","emoji":"😄","ex":{"zh":"她很爱笑。","py":"Tā hěn ài xiào.","m":"Она очень любит смеяться."}}]}'),
  ('hsk2-11-3', 3, 'game', '{"type":"listen","title":"Слушаем: путешествия и смех","items":[{"say":"旅游","options":["lùyóu","lǚyóu","lǜyóu"],"correct":1},{"say":"笑","options":["xiāo","xiào","xiǎo"],"correct":1},{"say":"我喜欢旅游","options":["wǒ xǐhuan lǚyóu","wǒ xǐhuan yóuyǒng"],"correct":0},{"say":"她很爱笑","options":["tā hěn ài chànggē","tā hěn ài xiào"],"correct":1},{"say":"去北京旅游","options":["qù Běijīng yùndòng","qù Běijīng lǚyóu"],"correct":1}]}'),
  ('hsk2-11-3', 4, 'game', '{"type":"tone_visualizer","initialTone":3,"title":"Тренажёр голоса: повторите «lǚ» (3 тон)"}'),
  ('hsk2-11-3', 5, 'theory', '{"title":"旅游 и 笑","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我喜欢旅游。","Я люблю путешествовать."],["我去北京旅游。","Я еду в Пекин путешествовать."],["她很爱笑。","Она очень любит улыбаться."],["你笑什么？","Чему ты смеёшься?"]]},{"t":"p","text":"旅游 ставится после места: 去北京旅游 «поехать в Пекин путешествовать». 笑 — обычный глагол: 他笑了 «он засмеялся». Перед 笑 часто ставят 爱 или 喜欢."},{"t":"tip","text":"Вопрос 你笑什么？ звучит бытово и мягко, как «чему смеёшься?»."}]}'),
  ('hsk2-11-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🧳","options":["旅游","运动","笑"],"correct":0},{"emoji":"😄","options":["玩","旅游","笑"],"correct":2}]}'),
  ('hsk2-11-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["旅游","путешествовать"],["笑","смеяться"],["去北京旅游","поехать в Пекин"],["爱笑","любить смеяться"],["你笑什么？","чему ты смеёшься?"]]}'),
  ('hsk2-11-3', 8, 'game', '{"type":"chatsim","title":"WeChat: планы на выходные","messages":[{"speaker":"Друг","text":"你喜欢运动吗？","pinyin":"Nǐ xǐhuan yùndòng ma?","translation":"Ты любишь спорт?","options":["不是，我跑。","喜欢，我运动是。","喜欢，我每天跑步。"],"correct":2},{"speaker":"Друг","text":"你想去哪儿旅游？","pinyin":"Nǐ xiǎng qù nǎr lǚyóu?","translation":"Куда ты хочешь поехать?","options":["我想旅游去北京。","我想去北京旅游。","北京我想去旅游吗。"],"correct":1},{"speaker":"Друг","text":"你笑什么？","pinyin":"Nǐ xiào shénme?","translation":"Чему ты смеёшься?","options":["我很高兴！","没关系。","我是笑。"],"correct":0}]}'),
  ('hsk2-11-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","喜欢","旅游"],"hint":"«Я люблю путешествовать.»"},{"answer":["我","去","北京","旅游"],"hint":"«Я еду в Пекин путешествовать.»"},{"answer":["她","很","爱","笑"],"hint":"«Она очень любит смеяться.»"}]}'),
  ('hsk2-11-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 旅游?","options":["петь","бегать","путешествовать"],"correct":2},{"q":"Как читается 笑?","options":["xiǎo","xiāo","xiào"],"correct":2},{"q":"Как сказать «Я еду в Пекин путешествовать»?","options":["我去北京旅游。","我北京去旅游吗。","我旅游去北京。"],"correct":0},{"q":"笑 значит «смеяться».","tf":true},{"q":"Как спросить «Чему ты смеёшься?»","options":["你什么笑？","你笑什么？","笑你什么？"],"correct":1}]}'),
  ('hsk2-11-4', 1, 'fact', '{"emoji":"🎒","title":"Планы на выходные","text":"Анна и Ли Мин обсуждают спорт, танцы и поездки. В диалоге встретятся 运动, 打篮球, 游泳, 踢足球, 唱歌, 跳舞, 玩, 旅游, 笑."}'),
  ('hsk2-11-4', 2, 'text', '{"title":"Планы на выходные","lines":[{"zh":"安娜：李明，你喜欢运动吗？","py":"Ānnà: Lǐ Míng, nǐ xǐhuan yùndòng ma?","m":"Анна: Ли Мин, ты любишь спорт?"},{"zh":"李明：喜欢。我每天早上跑步，星期六打篮球。","py":"Lǐ Míng: Xǐhuan. Wǒ měi tiān zǎoshang pǎobù, xīngqī liù dǎ lánqiú.","m":"Ли Мин: Да. Каждое утро бегаю, по субботам играю в баскетбол."},{"zh":"安娜：你会游泳吗？","py":"Ānnà: Nǐ huì yóuyǒng ma?","m":"Анна: Ты умеешь плавать?"},{"zh":"李明：会，我也喜欢踢足球。你呢？","py":"Lǐ Míng: Huì, wǒ yě xǐhuan tī zúqiú. Nǐ ne?","m":"Ли Мин: Умею, и ещё люблю футбол. А ты?"},{"zh":"安娜：我喜欢唱歌和跳舞。","py":"Ānnà: Wǒ xǐhuan chànggē hé tiàowǔ.","m":"Анна: Я люблю петь и танцевать."},{"zh":"李明：明天我们去玩吧！","py":"Lǐ Míng: Míngtiān wǒmen qù wán ba!","m":"Ли Мин: Давай завтра пойдём развлекаться!"},{"zh":"安娜：好！我们去北京旅游吧！","py":"Ānnà: Hǎo! Wǒmen qù Běijīng lǚyóu ba!","m":"Анна: Хорошо! Поедем в Пекин!"},{"zh":"李明：你笑什么？","py":"Lǐ Míng: Nǐ xiào shénme?","m":"Ли Мин: Чему ты смеёшься?"},{"zh":"安娜：我很高兴！","py":"Ānnà: Wǒ hěn gāoxìng!","m":"Анна: Я так рада!"}],"qs":[{"q":"Что Ли Мин делает каждое утро?","options":["поёт","бегает","плавает"],"correct":1},{"q":"Что любит Анна?","options":["бегать","играть в футбол","петь и танцевать"],"correct":2},{"q":"Ли Мин умеет плавать.","tf":true},{"q":"Когда Ли Мин играет в баскетбол?","options":["каждый день","по субботам","по пятницам"],"correct":1},{"q":"Анна предлагает поехать в Шанхай.","tf":false,"explain":"Она предлагает 北京."},{"q":"Вставьте слово: 明天我们去___吧！","options":["玩","笑","走"],"correct":0},{"q":"Что отвечает Анна на вопрос 你笑什么？","options":["我不累","我很高兴","我很忙"],"correct":1}]}'),
  ('hsk2-11-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["我每天早上跑步","каждое утро бегаю"],["星期六打篮球","по субботам баскетбол"],["我喜欢唱歌和跳舞","люблю петь и танцевать"],["我们去北京旅游吧","поедем в Пекин"],["你笑什么？","чему ты смеёшься?"]]}'),
  ('hsk2-11-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你喜欢运动吗","options":["nǐ xǐhuan chànggē ma","nǐ xǐhuan yùndòng ma"],"correct":1},{"say":"我每天早上跑步","options":["wǒ měi tiān wǎnshang pǎobù","wǒ měi tiān zǎoshang pǎobù"],"correct":1},{"say":"我喜欢唱歌和跳舞","options":["wǒ xǐhuan yóuyǒng hé tiàowǔ","wǒ xǐhuan chànggē hé tiàowǔ"],"correct":1},{"say":"我们去北京旅游吧","options":["wǒmen qù Běijīng yóuyǒng ba","wǒmen qù Běijīng lǚyóu ba"],"correct":1}]}'),
  ('hsk2-11-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: планы","cases":[{"buggyText":"我每天跑步早上。","context":"«Каждое утро я бегаю»","options":["早上我每天跑吗步。","我跑步每天早上。","我每天早上跑步。"],"correct":2},{"buggyText":"我们旅游去北京吧。","context":"«Поедем в Пекин»","options":["我们吧去北京旅游。","去我们北京旅游吧。","我们去北京旅游吧。"],"correct":2},{"buggyText":"你笑吗什么？","context":"«Чему ты смеёшься?»","options":["你笑什么？","你什么笑吗？","笑你什么？"],"correct":0}]}'),
  ('hsk2-11-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Давай завтра пойдём развлекаться»?","options":["去玩明天我们吧。","我们明天吧去玩。","明天我们去玩吧！"],"correct":2},{"q":"Как читается 旅游?","options":["lǜyóu","lùyóu","lǚyóu"],"correct":2},{"q":"Анна любит танцевать.","tf":true}]}'),
  ('hsk2-11-5', 1, 'fact', '{"emoji":"🎢","title":"Спланируйте выходной","text":"Выберите вид спорта, придумайте, что вы любите, и составьте маршрут. Слова глав 1–11 HSK 2."}'),
