  ('hsk2-11-5', 4, 'game', '{"type":"build","title":"Мастерская выходного","items":[{"target":"(Спорт)","answer":["我","每","天","早上","跑步"],"hint":"«Каждое утро я бегаю.»"},{"target":"(Хобби)","answer":["我","喜欢","唱歌","和","跳舞"],"hint":"«Я люблю петь и танцевать.»"},{"target":"(План)","answer":["明天","我们","去","北京","旅游"],"hint":"«Завтра мы поедем в Пекин.»"},{"target":"(Эмоция)","answer":["我","很","高兴","，","我","在","笑"],"hint":"«Я очень рад и смеюсь.»"}]}'),
  ('hsk2-11-5', 5, 'theory', '{"title":"Образец рассказа о выходном","blocks":[{"t":"table","head":["Тема","Фраза"],"rows":[["Спорт","我每天跑步。"],["Хобби","我喜欢唱歌。"],["План","明天去北京旅游。"],["Эмоция","我很高兴。"]]}]}'),
  ('hsk2-11-5', 6, 'game', '{"type":"chatsim","title":"WeChat: что делаем в выходные","messages":[{"speaker":"Друг","text":"你喜欢什么运动？","pinyin":"Nǐ xǐhuan shénme yùndòng?","translation":"Какой спорт тебе нравится?","options":["我喜欢游泳和跑步。","我运动喜欢是。","喜欢游泳我吗。"],"correct":0},{"speaker":"Друг","text":"你会跳舞吗？","pinyin":"Nǐ huì tiàowǔ ma?","translation":"Ты умеешь танцевать?","options":["会，我是跳舞。","会，我也喜欢唱歌。","不会，我唱歌是。"],"correct":1},{"speaker":"Друг","text":"明天去哪儿玩？","pinyin":"Míngtiān qù nǎr wán?","translation":"Куда завтра пойдём?","options":["我们去北京旅游吧。","我们吧去玩。","明天去玩哪儿。"],"correct":0}]}'),
  ('hsk2-11-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["氵 + 永","泳"],["足 + 包","跑"],["王 + 求","球"],["口 + 昌","唱"]]}'),
