  ('hsk2-11-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🏀","options":["跑步","游泳","打篮球"],"correct":2},{"emoji":"⚽","options":["踢足球","打篮球","跳舞"],"correct":0},{"emoji":"💃","options":["唱歌","跳舞","运动"],"correct":1},{"emoji":"🧳","options":["笑","玩","旅游"],"correct":2}]}'),
  ('hsk2-11-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["打篮球","баскетбол"],["踢足球","футбол"],["跑步","бегать"],["游泳","плавать"],["跳舞","танцевать"],["唱歌","петь"],["运动","спорт"],["玩","играть"],["旅游","путешествовать"],["笑","смеяться"]]}'),
  ('hsk2-11-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Какой глагол с 足球?","options":["打","踢","跑"],"correct":1},{"q":"Как сказать «Я умею плавать»?","options":["我游泳会。","会我游泳。","我会游泳。"],"correct":2},{"q":"Как сказать «Я люблю петь»?","options":["我唱歌喜欢。","我喜欢唱歌。","喜欢我唱歌。"],"correct":1},{"q":"会 + глагол означает «уметь».","tf":true},{"q":"Как сказать «Пойдёмте развлекаться»?","options":["去我们玩吧。","我们去玩吧。","我们吧去玩。"],"correct":1},{"q":"Как читается 旅游?","options":["lǚyóu","lùyóu","lǜyóu"],"correct":0},{"q":"笑 значит «петь».","tf":false},{"q":"Как сказать «Я каждый день бегаю»?","options":["我每天跑步。","每天我吗跑步。","我跑步每天。"],"correct":0},{"q":"Что значит 运动?","options":["танцы","пение","спорт"],"correct":2},{"q":"Как спросить «Чему ты смеёшься?»","options":["你笑什么？","笑你什么？","你什么笑？"],"correct":0}]}'),
  ('hsk2-11-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","喜欢","打","篮球"],"hint":"«Я люблю баскетбол.»"},{"answer":["她","会","跳舞"],"hint":"«Она умеет танцевать.»"},{"answer":["我","去","北京","旅游"],"hint":"«Я еду в Пекин путешествовать.»"},{"answer":["我们","去","玩","吧"],"hint":"«Пойдёмте развлекаться.»"}]}'),
  ('hsk2-11-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我喜欢歌唱。","context":"«Я люблю петь»","options":["我喜欢唱歌。","我歌喜欢唱。","喜欢我歌唱。"],"correct":0},{"buggyText":"我们旅游去北京吧。","context":"«Поедем в Пекин»","options":["我们去北京旅游吧。","去我们北京旅游吧。","我们吧去北京旅游。"],"correct":0},{"buggyText":"她会舞跳。","context":"«Она умеет танцевать»","options":["她跳会舞。","她会跳舞。","会她跳舞。"],"correct":1}]}'),
  ('hsk2-11-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"你喜欢什么运动？","pinyin":"Nǐ xǐhuan shénme yùndòng?","translation":"Какой спорт тебе нравится?","options":["我喜欢游泳和跑步。","我运动喜欢是。","喜欢游泳我吗。"],"correct":0},{"speaker":"Друг","text":"明天去哪儿玩？","pinyin":"Míngtiān qù nǎr wán?","translation":"Куда завтра пойдём?","options":["我们去北京旅游吧。","明天去玩哪儿。","我们吧去玩。"],"correct":0}]}'),
  ('hsk2-11-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"球","pinyin":"qiú","m":"мяч","hint":"王 + 求"},{"hanzi":"玩","pinyin":"wán","m":"играть","hint":"王 + 元"},{"hanzi":"笑","pinyin":"xiào","m":"смеяться","hint":"竹 + 夭"}]}'),
  ('hsk2-11-6', 10, 'recall', '{"words":[{"hanzi":"打篮球","pinyin":"dǎ lánqiú","m":"баскетбол"},{"hanzi":"踢足球","pinyin":"tī zúqiú","m":"футбол"},{"hanzi":"跑步","pinyin":"pǎobù","m":"бегать"},{"hanzi":"游泳","pinyin":"yóuyǒng","m":"плавать"},{"hanzi":"跳舞","pinyin":"tiàowǔ","m":"танцевать"},{"hanzi":"唱歌","pinyin":"chànggē","m":"петь"},{"hanzi":"运动","pinyin":"yùndòng","m":"спорт"},{"hanzi":"玩","pinyin":"wán","m":"играть"},{"hanzi":"旅游","pinyin":"lǚyóu","m":"путешествовать"},{"hanzi":"笑","pinyin":"xiào","m":"смеяться"}],"tf":[{"zh":"我喜欢歌唱。","py":"wǒ xǐhuan gēchàng.","m":"Я люблю петь.","ok":false,"explain":"Правильно: 我喜欢唱歌."},{"zh":"我会游泳。","py":"wǒ huì yóuyǒng.","m":"Я умею плавать.","ok":true}],"sentences":[{"zh":"我喜欢打篮球。","tokens":["我","喜欢","打","篮球"],"m":"Я люблю баскетбол."},{"zh":"她会跳舞。","tokens":["她","会","跳舞"],"m":"Она умеет танцевать."},{"zh":"我们去北京旅游吧。","tokens":["我们","去","北京","旅游","吧"],"m":"Поедем в Пекин."}]}'),
  ('hsk2-12-1', 1, 'fact', '{"emoji":"💊","title":"Лекарство — это травы","text":"В знаке 药 «лекарство» сверху 艹 «трава»: китайская медицина веками лечила травами. Знак 病 «болезнь» содержит 疒 «болезнь» — ключ, который стоит в названиях недугов. А 身体 shēntǐ «тело, здоровье» состоит из 身 «тело» и 体 «корпус» (亻 + 本)."}'),
  ('hsk2-12-1', 2, 'words', '{"title":"Тело и здоровье","items":[{"hanzi":"身体","pinyin":"shēntǐ","m":"тело, здоровье","emoji":"🧍","ex":{"zh":"我身体很好。","py":"Wǒ shēntǐ hěn hǎo.","m":"Я здоров."}},{"hanzi":"生病","pinyin":"shēngbìng","m":"заболеть, болеть","emoji":"🤒","ex":{"zh":"他生病了。","py":"Tā shēngbìng le.","m":"Он заболел."}},{"hanzi":"药","pinyin":"yào","m":"лекарство","emoji":"💊","ex":{"zh":"我吃药。","py":"Wǒ chī yào.","m":"Я принимаю лекарство."}},{"hanzi":"眼睛","pinyin":"yǎnjing","m":"глаза","emoji":"👀","ex":{"zh":"我的眼睛很大。","py":"Wǒ de yǎnjing hěn dà.","m":"У меня большие глаза."}}]}'),
  ('hsk2-12-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🧍","options":["药","身体","眼睛"],"correct":1},{"emoji":"🤒","options":["生病","药","身体"],"correct":0},{"emoji":"💊","options":["药","眼睛","生病"],"correct":0},{"emoji":"👀","options":["眼睛","药","身体"],"correct":0}]}'),
  ('hsk2-12-1', 4, 'theory', '{"title":"Как говорить о здоровье","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["我身体很好。","Wǒ shēntǐ hěn hǎo.","Я здоров."],["他生病了。","Tā shēngbìng le.","Он заболел."],["我吃药。","Wǒ chī yào.","Я принимаю лекарство."],["我的眼睛很累。","Wǒ de yǎnjing hěn lèi.","Мои глаза устали."]]},{"t":"p","text":"Лекарство «принимают» глаголом 吃 («есть»), как и еду. Заболеть — 生病, и тут тоже нужна 了: «стало больно»."},{"t":"tip","text":"Не путайте: 药 yào (лекарство, 4 тон) и 要 yào (хотеть, 4 тон) звучат одинаково, но пишутся по-разному."}]}'),
  ('hsk2-12-1', 5, 'quiz', '{"title":"Мини-тест: здоровье","qs":[{"q":"Как сказать «Я принимаю лекарство»?","options":["我喝药。","我药吃。","我吃药。"],"correct":2},{"q":"Что значит 生病?","options":["уставать","выздороветь","заболеть"],"correct":2},{"q":"药 и 要 читаются одинаково.","tf":true}]}'),
  ('hsk2-12-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["身体","тело, здоровье"],["生病","заболеть"],["药","лекарство"],["眼睛","глаза"],["我身体很好","я здоров"]]}'),
  ('hsk2-12-1', 7, 'game', '{"type":"listen","title":"Слушаем: тело и здоровье","items":[{"say":"身体","options":["shēntī","shēntǐ","shéntǐ"],"correct":1},{"say":"生病","options":["shéngbìng","shēngbìng","shēngbǐng"],"correct":1},{"say":"药","options":["yáo","yào","yǎo"],"correct":1},{"say":"眼睛","options":["yǎnjing","yánjing","yànjing"],"correct":0},{"say":"他生病了","options":["tā shēngrì le","tā shēngbìng le"],"correct":1}]}'),
  ('hsk2-12-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","身体","很","好"],"hint":"«Я здоров.»"},{"answer":["他","生病","了"],"hint":"«Он заболел.»"},{"answer":["我","吃","药"],"hint":"«Я принимаю лекарство.»"}]}'),
  ('hsk2-12-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"药","pinyin":"yào","m":"лекарство","hint":"сверху 艹, внизу 约"},{"hanzi":"病","pinyin":"bìng","m":"болезнь","hint":"сверху 疒, внутри 丙"},{"hanzi":"体","pinyin":"tǐ","m":"тело","hint":"слева 亻, справа 本"}]}'),
  ('hsk2-12-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 身体?","options":["лекарство","тело, здоровье","глаза"],"correct":1},{"q":"Как читается 眼睛?","options":["yǎnjing","yànjing","yánjing"],"correct":0},{"q":"Как сказать «Он заболел»?","options":["生病他了。","他了生病。","他生病了。"],"correct":2},{"q":"病 содержит ключ 疒.","tf":true},{"q":"Как сказать «Я принимаю лекарство»?","options":["吃我药。","我吃药。","我药吃。"],"correct":1}]}'),
  ('hsk2-12-2', 1, 'fact', '{"emoji":"🌳","title":"Человек у дерева — отдыхает","text":"Знак 休 «отдыхать» — это 亻 «человек» рядом с 木 «дерево»: человек прислонился к дереву. 洗 xǐ «мыть, стирать» несёт 氵 «воду». А 穿 chuān «носить, надевать» состоит из 穴 «нора, отверстие» и 牙 «зуб»: просовывать себя через отверстие, то есть надеть. Ещё одно полезное правило: частица 了 после глагола показывает завершённое действие."}'),
  ('hsk2-12-2', 2, 'words', '{"title":"Отдых и одежда","items":[{"hanzi":"休息","pinyin":"xiūxi","m":"отдыхать","emoji":"😴","ex":{"zh":"请休息一下。","py":"Qǐng xiūxi yíxià.","m":"Пожалуйста, отдохните."}},{"hanzi":"洗","pinyin":"xǐ","m":"мыть, стирать","emoji":"🧼","ex":{"zh":"我洗衣服。","py":"Wǒ xǐ yīfu.","m":"Я стираю одежду."}},{"hanzi":"穿","pinyin":"chuān","m":"носить, надевать","emoji":"👕","ex":{"zh":"我穿红衣服。","py":"Wǒ chuān hóng yīfu.","m":"Я ношу красную одежду."}}]}'),
  ('hsk2-12-2', 3, 'theory', '{"title":"了 после глагола: завершено","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我吃药了。","Я принял лекарство."],["我洗了衣服。","Я постирал одежду."],["他休息了一个小时。","Он отдыхал час."],["我穿了红衣服。","Я надел красную одежду."]]},{"t":"p","text":"了 бывает двух видов: в конце фразы «ситуация изменилась» (下雨了), а сразу после глагола «действие завершено» (洗了衣服). Для отрицания ставят 没: 我没洗衣服 «я не стирал»."},{"t":"tip","text":"После 没 частица 了 пропадает: 我没吃药, а не 我没吃药了."}]}'),
  ('hsk2-12-2', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","洗","了","衣服"],"hint":"«Я постирал одежду.»"},{"answer":["我","穿","红","衣服"],"hint":"«Я надеваю красную одежду.»"},{"answer":["请","休息","一下"],"hint":"«Пожалуйста, отдохните.»"},{"answer":["我","没","吃","药"],"hint":"«Я не принимал лекарство.»"}]}'),
  ('hsk2-12-2', 5, 'quiz', '{"title":"Мини-тест: 了","qs":[{"q":"Как сказать «Я постирал одежду»?","options":["我衣服洗了。","我洗了衣服。","我了洗衣服。"],"correct":1},{"q":"Как сказать «Я не принимал лекарство»?","options":["我没吃药。","我不吃药了。","我没吃药了。"],"correct":0},{"q":"После 没 частица 了 обычно не нужна.","tf":true}]}'),
  ('hsk2-12-2', 6, 'game', '{"type":"listen","title":"Слушаем: отдых, стирка, одежда","items":[{"say":"休息","options":["xiūxī","xiūxi","xiúxi"],"correct":1},{"say":"洗","options":["xì","xǐ","xí"],"correct":1},{"say":"穿","options":["chuán","chuǎn","chuān"],"correct":2},{"say":"我洗了衣服","options":["wǒ chuān le yīfu","wǒ xǐ le yīfu"],"correct":1},{"say":"请休息一下","options":["qǐng xiūxi yìxià","qǐng xiūxi yíxià"],"correct":1}]}'),
  ('hsk2-12-2', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["休息","отдыхать"],["洗","мыть, стирать"],["穿","носить, надевать"],["洗了衣服","постирал одежду"],["没吃药","не принимал лекарство"]]}'),
  ('hsk2-12-2', 8, 'game', '{"type":"bughunt","title":"Китайский детектив: 了","cases":[{"buggyText":"我洗衣服了了。","context":"«Я постирал одежду»","options":["我洗了衣服。","我了洗衣服。","我洗衣服了了。"],"correct":0},{"buggyText":"我没吃药了。","context":"«Я не принимал лекарство»","options":["我没吃药。","我没了吃药。","我不吃药了。"],"correct":0},{"buggyText":"我穿衣服红。","context":"«Я ношу красную одежду»","options":["穿我红衣服。","我穿红衣服。","我红穿衣服。"],"correct":1}]}'),
  ('hsk2-12-2', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 休息?","options":["отдыхать","носить","мыть"],"correct":0},{"q":"Как читается 穿?","options":["chuān","chuǎn","chuán"],"correct":0},{"q":"Как сказать «Он отдыхал час»?","options":["他一个小时休息了。","休息他一个小时了。","他休息了一个小时。"],"correct":2},{"q":"洗 — «мыть, стирать».","tf":true},{"q":"Как сказать «Я ношу красную одежду»?","options":["我红穿衣服。","我衣服穿红。","我穿红衣服。"],"correct":2}]}'),
  ('hsk2-12-3', 1, 'fact', '{"emoji":"🎉","title":"«Быстро и весело»","text":"快乐 kuàilè «счастливый, весёлый» — слово из пожеланий: 生日快乐 «с днём рождения», 新年快乐 «с Новым годом». 希望 xīwàng «надеяться» состоит из 希 «редкий, надежда» и 望 «смотреть вдаль»: надежда — взгляд в даль. А 可能 kěnéng «возможно» собрано из 可 «можно» и 能 «мочь»."}'),
  ('hsk2-12-3', 2, 'words', '{"title":"Пожелания и надежда","items":[{"hanzi":"快乐","pinyin":"kuàilè","m":"счастливый, весёлый","emoji":"🥳","ex":{"zh":"生日快乐！","py":"Shēngrì kuàilè!","m":"С днём рождения!"}},{"hanzi":"希望","pinyin":"xīwàng","m":"надеяться, надежда","emoji":"🌠","ex":{"zh":"我希望你快乐。","py":"Wǒ xīwàng nǐ kuàilè.","m":"Я надеюсь, ты будешь счастлив."}},{"hanzi":"可能","pinyin":"kěnéng","m":"возможно, может быть","emoji":"🤔","ex":{"zh":"他可能生病了。","py":"Tā kěnéng shēngbìng le.","m":"Возможно, он заболел."}}]}'),
  ('hsk2-12-3', 3, 'game', '{"type":"listen","title":"Слушаем: пожелания","items":[{"say":"快乐","options":["kuǎilè","kuàiyuè","kuàilè"],"correct":2},{"say":"希望","options":["xīwāng","xíwàng","xīwàng"],"correct":2},{"say":"可能","options":["kěnéng","kěnèng","kènéng"],"correct":0},{"say":"生日快乐","options":["shēngrì kuàilè","shēngbìng kuàilè"],"correct":0},{"say":"他可能生病了","options":["tā kěnéng shēngbìng le","tā yǐjīng shēngbìng le"],"correct":0}]}'),
  ('hsk2-12-3', 4, 'game', '{"type":"tone_visualizer","initialTone":4,"title":"Тренажёр голоса: повторите «kuài» (4 тон)"}'),
  ('hsk2-12-3', 5, 'theory', '{"title":"Пожелания и «может быть»","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["生日快乐！","С днём рождения!"],["新年快乐！","С Новым годом!"],["我希望你身体好。","Надеюсь, ты будешь здоров."],["他可能生病了。","Возможно, он заболел."]]},{"t":"p","text":"快乐 — слово пожеланий. 希望 стоит перед придаточным: 我希望 + что. 可能 ставится перед глаголом, как 会, но говорит о вероятности, а не об умении."},{"t":"tip","text":"Не путайте 可以 (можно, разрешено) и 可能 (возможно, вероятно)."}]}'),
  ('hsk2-12-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🥳","options":["可能","希望","快乐"],"correct":2},{"emoji":"🌠","options":["希望","可能","快乐"],"correct":0},{"emoji":"🤔","options":["可能","快乐","希望"],"correct":0}]}'),
  ('hsk2-12-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["快乐","счастливый"],["希望","надеяться"],["可能","возможно"],["生日快乐","с днём рождения"],["我希望你快乐","я надеюсь, ты будешь счастлив"]]}'),
  ('hsk2-12-3', 8, 'game', '{"type":"chatsim","title":"WeChat: пожелания","messages":[{"speaker":"Друг","text":"今天是我的生日。","pinyin":"Jīntiān shì wǒ de shēngrì.","translation":"Сегодня мой день рождения.","options":["生日快乐！","再见！","对不起。"],"correct":0},{"speaker":"Друг","text":"我希望明天天气很好。","pinyin":"Wǒ xīwàng míngtiān tiānqì hěn hǎo.","translation":"Надеюсь, завтра будет хорошая погода.","options":["可能会很好。","好可能很。","可能我是好。"],"correct":0,"explain":"会 здесь показывает вероятность."},{"speaker":"Друг","text":"你身体好吗？","pinyin":"Nǐ shēntǐ hǎo ma?","translation":"Ты здоров?","options":["不是，我药。","很好，谢谢！","没关系。"],"correct":1}]}'),
  ('hsk2-12-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["生日","快乐"],"hint":"«С днём рождения!»"},{"answer":["我","希望","你","身体","好"],"hint":"«Надеюсь, ты будешь здоров.»"},{"answer":["他","可能","生病","了"],"hint":"«Возможно, он заболел.»"}]}'),
  ('hsk2-12-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 快乐?","options":["счастливый","возможно","надеяться"],"correct":0},{"q":"Как читается 希望?","options":["xīwāng","xīwàng","xíwàng"],"correct":1},{"q":"Как сказать «С днём рождения!»?","options":["生日可能！","生日快乐！","生日希望！"],"correct":1},{"q":"可能 говорит о вероятности.","tf":true},{"q":"Как сказать «Я надеюсь, ты здоров»?","options":["希望我你身体好。","我你希望身体好。","我希望你身体好。"],"correct":2}]}'),
  ('hsk2-12-4', 1, 'fact', '{"emoji":"🤒","title":"Ли Мин навещает больную подругу","text":"Анна заболела, Ли Мин звонит и поддерживает её. В диалоге встретятся 身体, 生病, 药, 眼睛, 休息, 希望, 可能, 快乐."}'),
  ('hsk2-12-4', 2, 'text', '{"title":"Анна заболела","lines":[{"zh":"李明：喂，安娜，你怎么了？","py":"Lǐ Míng: Wèi, Ānnà, nǐ zěnme le?","m":"Ли Мин: Алло, Анна, что с тобой? (怎么了 «что случилось?» — новое выражение)"},{"zh":"安娜：我生病了。我的眼睛不好，身体也很累。","py":"Ānnà: Wǒ shēngbìng le. Wǒ de yǎnjing bù hǎo, shēntǐ yě hěn lèi.","m":"Анна: Я заболела. Глаза болят, и тело устало."},{"zh":"李明：你吃药了吗？","py":"Lǐ Míng: Nǐ chī yào le ma?","m":"Ли Мин: Ты приняла лекарство?"},{"zh":"安娜：吃了。医生说我要休息。","py":"Ānnà: Chī le. Yīshēng shuō wǒ yào xiūxi.","m":"Анна: Приняла. Врач сказал, что мне нужно отдохнуть."},{"zh":"李明：你休息吧。我希望你明天身体好。","py":"Lǐ Míng: Nǐ xiūxi ba. Wǒ xīwàng nǐ míngtiān shēntǐ hǎo.","m":"Ли Мин: Отдыхай. Надеюсь, завтра ты будешь здорова."},{"zh":"安娜：谢谢！可能明天我身体就好了。","py":"Ānnà: Xièxie! Kěnéng míngtiān wǒ shēntǐ jiù hǎo le.","m":"Анна: Спасибо! Возможно, завтра мне уже станет лучше. (就 — новое слово)"},{"zh":"李明：好，再见！","py":"Lǐ Míng: Hǎo, zàijiàn!","m":"Ли Мин: Хорошо, до свидания!"}],"qs":[{"q":"Что случилось с Анной?","options":["она устала на работе","она заболела","она потеряла билет"],"correct":1},{"q":"Что у неё болит?","options":["зуб","рука","глаза"],"correct":2},{"q":"Анна приняла лекарство.","tf":true},{"q":"Что сказал врач?","options":["нужно бегать","нужно путешествовать","нужно отдохнуть"],"correct":2},{"q":"Ли Мин желает ей здоровья.","tf":true},{"q":"Вставьте слово: 我___你明天身体好。","options":["希望","快乐","可能"],"correct":0},{"q":"Как Анна говорит о вероятности выздоровления?","options":["可能明天好","已经好","不会好"],"correct":0}]}'),
  ('hsk2-12-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["我生病了","я заболела"],["我的眼睛不好","у меня болят глаза"],["你吃药了吗？","ты приняла лекарство?"],["医生说我要休息","врач сказал мне отдохнуть"],["我希望你身体好","надеюсь, ты будешь здорова"]]}'),
  ('hsk2-12-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"我生病了","options":["wǒ shēngbìng le","wǒ shēngrì le"],"correct":0},{"say":"你吃药了吗","options":["nǐ chī yào le ma","nǐ hē yào le ma"],"correct":0},{"say":"医生说我要休息","options":["yīshēng shuō wǒ yào gōngzuò","yīshēng shuō wǒ yào xiūxi"],"correct":1},{"say":"我希望你身体好","options":["wǒ kěnéng nǐ shēntǐ hǎo","wǒ xīwàng nǐ shēntǐ hǎo"],"correct":1}]}'),
  ('hsk2-12-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: болезнь","cases":[{"buggyText":"我生病。","context":"«Я заболела»","options":["生病我了。","我生病了。","我了生病。"],"correct":1},{"buggyText":"你药吃了吗？","context":"«Ты приняла лекарство?»","options":["吃药你了吗？","你吃了药吗了？","你吃药了吗？"],"correct":2},{"buggyText":"我希望可能你身体好。","context":"«Надеюсь, ты будешь здорова»","options":["希望我身体你好。","我可能希望你身体好。","我希望你身体好。"],"correct":2}]}'),
  ('hsk2-12-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Мне нужно отдохнуть»?","options":["我休息要。","休息我要。","我要休息。"],"correct":2},{"q":"Как читается 休息?","options":["xiūxī","xiúxi","xiūxi"],"correct":2},{"q":"Анна приняла лекарство.","tf":true}]}'),
  ('hsk2-12-5', 1, 'fact', '{"emoji":"💌","title":"Напишите пожелание","text":"Придумайте открытку для друга: поздравление, пожелание здоровья и ободряющая фраза. Слова глав 1–12 HSK 2."}'),
  ('hsk2-12-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"休","correctRadicals":["亻","木"],"title":"Пазл: соберите 休"}'),
  ('hsk2-12-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"洗","radicals":["氵","先","亻"],"correctOrder":["氵","先"],"explain":"Слева 氵, справа 先."},{"targetHanzi":"病","radicals":["疒","丙","亻"],"correctOrder":["疒","丙"],"explain":"Сверху 疒, внутри 丙."},{"targetHanzi":"药","radicals":["艹","约","亻"],"correctOrder":["艹","约"],"explain":"Сверху 艹, внизу 约."}]}'),
  ('hsk2-12-5', 4, 'game', '{"type":"build","title":"Мастерская открытки","items":[{"target":"(Открытка)","answer":["生日","快乐","，","我","希望","你","身体","好"],"hint":"«С днём рождения, желаю тебе здоровья.»"},{"target":"(Совет)","answer":["你","吃","药","，","休息","一下"],"hint":"«Прими лекарство и отдохни.»"},{"target":"(Вероятность)","answer":["明天","可能","下雨"],"hint":"«Завтра, возможно, будет дождь.»"},{"target":"(Одежда)","answer":["我","穿","了","红","衣服"],"hint":"«Я надел красную одежду.»"}]}'),
  ('hsk2-12-5', 5, 'theory', '{"title":"Образец поздравительной открытки","blocks":[{"t":"table","head":["Часть","Фраза"],"rows":[["Поздравление","生日快乐！"],["Пожелание","我希望你身体好。"],["Совет","你休息一下吧。"],["Прощание","明天见！"]]}]}'),
  ('hsk2-12-5', 6, 'game', '{"type":"chatsim","title":"WeChat: поздравление","messages":[{"speaker":"Друг","text":"我今天生日。","pinyin":"Wǒ jīntiān shēngrì.","translation":"Сегодня мой день рождения.","options":["再见！","生日快乐！我希望你很快乐。","对不起。"],"correct":1},{"speaker":"Друг","text":"谢谢！我有点累。","pinyin":"Xièxie! Wǒ yǒudiǎn lèi.","translation":"Спасибо! Я немного устал. (有点 — новое выражение)","options":["你旅游吧。","你休息一下吧。","你吃药吧。"],"correct":1},{"speaker":"Друг","text":"好，明天见！","pinyin":"Hǎo, míngtiān jiàn!","translation":"Хорошо, до завтра!","options":["不客气。","明天见！","对不起。"],"correct":1}]}'),
  ('hsk2-12-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["亻 + 木","休"],["氵 + 先","洗"],["疒 + 丙","病"],["艹 + 约","药"]]}'),
  ('hsk2-12-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"休","pinyin":"xiū","m":"отдыхать","hint":"слева 亻, справа 木"},{"hanzi":"洗","pinyin":"xǐ","m":"мыть","hint":"слева 氵, справа 先"},{"hanzi":"乐","pinyin":"lè","m":"радость","hint":"сверху 白, снизу 木 (упрощённо)"}]}'),
  ('hsk2-12-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как поздравить с днём рождения?","options":["生日休息！","生日药！","生日快乐！"],"correct":2},{"q":"Из чего состоит 休?","options":["亻 и 木","疒 и 丙","氵 и 先"],"correct":0},{"q":"希望 стоит перед пожеланием.","tf":true}]}'),
  ('hsk2-12-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 12 (HSK 2)","text":"身体, 生病, 药, 眼睛, 休息, 洗, 穿, 快乐, 希望 и 可能."}'),
  ('hsk2-12-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"身体","options":["shēngbìng","shēntǐ","yǎnjing"],"correct":1},{"say":"我吃药","options":["wǒ chī yào","wǒ hē yào"],"correct":0},{"say":"他生病了","options":["tā shēngbìng le","tā shēngrì le"],"correct":0},{"say":"请休息一下","options":["qǐng xiūxi yìxià","qǐng xiūxi yíxià"],"correct":1},{"say":"生日快乐","options":["shēngbìng kuàilè","shēngrì kuàilè"],"correct":1},{"say":"他可能生病了","options":["tā yǐjīng shēngbìng le","tā kěnéng shēngbìng le"],"correct":1}]}'),
  ('hsk2-12-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"💊","options":["药","休息","身体"],"correct":0},{"emoji":"🧼","options":["洗","休息","穿"],"correct":0},{"emoji":"🥳","options":["快乐","希望","可能"],"correct":0},{"emoji":"🤒","options":["生病","眼睛","药"],"correct":0}]}'),
  ('hsk2-12-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["身体","тело, здоровье"],["生病","заболеть"],["药","лекарство"],["眼睛","глаза"],["休息","отдыхать"],["洗","мыть"],["穿","носить"],["快乐","счастливый"],["希望","надеяться"],["可能","возможно"]]}'),
  ('hsk2-12-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Я принимаю лекарство»?","options":["我药吃。","我吃药。","我喝药。"],"correct":1},{"q":"Как сказать «Я постирал одежду»?","options":["我了洗衣服。","我衣服洗了。","我洗了衣服。"],"correct":2},{"q":"Как сказать «Я не принимал лекарство»?","options":["我不吃药了。","我没吃药了。","我没吃药。"],"correct":2},{"q":"可能 говорит о вероятности.","tf":true},{"q":"Как сказать «С днём рождения!»?","options":["生日可能！","生日快乐！","生日希望！"],"correct":1},{"q":"Что значит 休息?","options":["отдыхать","мыть","носить"],"correct":0},{"q":"药 и 要 пишутся одинаково.","tf":false},{"q":"Как читается 希望?","options":["xíwàng","xīwàng","xīwāng"],"correct":1},{"q":"Как сказать «Надеюсь, ты здоров»?","options":["希望我你身体好。","我希望你身体好。","我你希望身体好。"],"correct":1},{"q":"Что значит 眼睛?","options":["лекарство","тело","глаза"],"correct":2}]}'),
  ('hsk2-12-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","身体","很","好"],"hint":"«Я здоров.»"},{"answer":["他","生病","了"],"hint":"«Он заболел.»"},{"answer":["我","洗","了","衣服"],"hint":"«Я постирал одежду.»"},{"answer":["生日","快乐"],"hint":"«С днём рождения!»"}]}'),
  ('hsk2-12-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我生病。","context":"«Я заболела»","options":["我了生病。","我生病了。","生病我了。"],"correct":1},{"buggyText":"我没吃药了。","context":"«Я не принимал лекарство»","options":["我没了吃药。","我不吃药了。","我没吃药。"],"correct":2},{"buggyText":"我穿衣服红。","context":"«Я ношу красную одежду»","options":["我穿红衣服。","我红穿衣服。","穿我红衣服。"],"correct":0}]}'),
  ('hsk2-12-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"你怎么了？","pinyin":"Nǐ zěnme le?","translation":"Что с тобой?","options":["我生病了。","我生病，药。","我是生病。"],"correct":0},{"speaker":"Друг","text":"你吃药了吗？","pinyin":"Nǐ chī yào le ma?","translation":"Ты принял лекарство?","options":["吃药，我了。","吃了，我要休息。","没药，我吃。"],"correct":1}]}'),
  ('hsk2-12-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"药","pinyin":"yào","m":"лекарство","hint":"艹 + 约"},{"hanzi":"休","pinyin":"xiū","m":"отдыхать","hint":"亻 + 木"},{"hanzi":"病","pinyin":"bìng","m":"болезнь","hint":"疒 + 丙"}]}'),
  ('hsk2-12-6', 10, 'recall', '{"words":[{"hanzi":"身体","pinyin":"shēntǐ","m":"тело, здоровье"},{"hanzi":"生病","pinyin":"shēngbìng","m":"заболеть"},{"hanzi":"药","pinyin":"yào","m":"лекарство"},{"hanzi":"眼睛","pinyin":"yǎnjing","m":"глаза"},{"hanzi":"休息","pinyin":"xiūxi","m":"отдыхать"},{"hanzi":"洗","pinyin":"xǐ","m":"мыть"},{"hanzi":"穿","pinyin":"chuān","m":"носить"},{"hanzi":"快乐","pinyin":"kuàilè","m":"счастливый"},{"hanzi":"希望","pinyin":"xīwàng","m":"надеяться"},{"hanzi":"可能","pinyin":"kěnéng","m":"возможно"}],"tf":[{"zh":"我没吃药了。","py":"wǒ méi chī yào le.","m":"Я не принимал лекарство.","ok":false,"explain":"Правильно: 我没吃药."},{"zh":"生日快乐！","py":"shēngrì kuàilè!","m":"С днём рождения!","ok":true}],"sentences":[{"zh":"我身体很好。","tokens":["我","身体","很","好"],"m":"Я здоров."},{"zh":"他生病了。","tokens":["他","生病","了"],"m":"Он заболел."},{"zh":"我希望你身体好。","tokens":["我","希望","你","身体","好"],"m":"Надеюсь, ты будешь здоров."}]}'),
  ('hsk2-13-1', 1, 'fact', '{"emoji":"❄️","title":"Дождь и метла","text":"В знаке 雪 «снег» сверху 雨 «дождь», внизу 彐 «щётка, метла»: снег, который нужно подметать. А 晴 «ясный» состоит из 日 «солнце» и 青 «голубой»; 阴 «пасмурный» — 阝 и 月: тень, луна без солнца. Говорят 晴天 «ясный день» и 阴天 «пасмурный день»."}'),
  ('hsk2-13-1', 2, 'words', '{"title":"Погода","items":[{"hanzi":"雪","pinyin":"xuě","m":"снег","emoji":"❄️","ex":{"zh":"今天下雪了。","py":"Jīntiān xià xuě le.","m":"Сегодня пошёл снег."}},{"hanzi":"阴","pinyin":"yīn","m":"пасмурный","emoji":"☁️","ex":{"zh":"今天是阴天。","py":"Jīntiān shì yīn tiān.","m":"Сегодня пасмурно."}},{"hanzi":"晴","pinyin":"qíng","m":"ясный","emoji":"☀️","ex":{"zh":"昨天是晴天。","py":"Zuótiān shì qíng tiān.","m":"Вчера был ясный день."}}]}'),
  ('hsk2-13-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"❄️","options":["雪","阴","晴"],"correct":0},{"emoji":"☁️","options":["雪","晴","阴"],"correct":2},{"emoji":"☀️","options":["雪","阴","晴"],"correct":2}]}'),
  ('hsk2-13-1', 4, 'theory', '{"title":"Как говорить о погоде","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["今天是晴天。","Jīntiān shì qíng tiān.","Сегодня ясно."],["今天是阴天。","Jīntiān shì yīn tiān.","Сегодня пасмурно."],["下雪了。","Xià xuě le.","Пошёл снег."],["明天可能下雪。","Míngtiān kěnéng xià xuě.","Завтра, возможно, будет снег."]]},{"t":"p","text":"Для дождя и снега глагол 下: 下雨, 下雪. Для ясного и пасмурного дня слово 天 «день»: 晴天, 阴天."},{"t":"tip","text":"下雪了 — это «выпал снег»: 了 в конце фразы сообщает о перемене, как в 下雨了."}]}'),
  ('hsk2-13-1', 5, 'quiz', '{"title":"Мини-тест: погода","qs":[{"q":"Как сказать «Пошёл снег»?","options":["雪下了。","下雪了。","了下雪。"],"correct":1},{"q":"Что значит 晴天?","options":["дождливый день","ясный день","пасмурный день"],"correct":1},{"q":"下 используют и с дождём, и со снегом.","tf":true}]}'),
  ('hsk2-13-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["雪","снег"],["阴","пасмурный"],["晴","ясный"],["晴天","ясный день"],["下雪","идёт снег"]]}'),
  ('hsk2-13-1', 7, 'game', '{"type":"listen","title":"Слушаем погоду","items":[{"say":"雪","options":["xué","xuè","xuě"],"correct":2},{"say":"阴","options":["yìn","yīn","yín"],"correct":1},{"say":"晴","options":["qìng","qíng","qǐng"],"correct":1},{"say":"今天是晴天","options":["jīntiān shì yīn tiān","jīntiān shì qíng tiān"],"correct":1},{"say":"下雪了","options":["xià xuě le","xià yǔ le"],"correct":0}]}'),
  ('hsk2-13-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["今天","是","晴天"],"hint":"«Сегодня ясно.»"},{"answer":["今天","是","阴天"],"hint":"«Сегодня пасмурно.»"},{"answer":["明天","可能","下雪"],"hint":"«Завтра, возможно, будет снег.»"}]}'),
  ('hsk2-13-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"雪","pinyin":"xuě","m":"снег","hint":"сверху 雨, внизу 彐"},{"hanzi":"晴","pinyin":"qíng","m":"ясный","hint":"слева 日, справа 青"},{"hanzi":"阴","pinyin":"yīn","m":"пасмурный","hint":"слева 阝, справа 月"}]}'),
  ('hsk2-13-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 雪?","options":["облако","снег","дождь"],"correct":1},{"q":"Как читается 晴?","options":["qǐng","qíng","qìng"],"correct":1},{"q":"Как сказать «Сегодня пасмурно»?","options":["今天阴是天。","今天是阴天。","是今天阴天。"],"correct":1},{"q":"晴 содержит 日 «солнце».","tf":true},{"q":"Как сказать «Завтра, возможно, будет снег»?","options":["明天可能下雪。","明天下雪可能。","可能明天下吗雪。"],"correct":0}]}'),
  ('hsk2-13-2', 1, 'fact', '{"emoji":"📱","title":"Рука + механизм = телефон","text":"Слово 手机 shǒujī «мобильный телефон» складывается из 手 «рука» и 机 «механизм»: «ручная машина». 手表 shǒubiǎo «наручные часы» — «рука + часы». 铅笔 qiānbǐ «карандаш» — 铅 «свинец» + 笔 «кисть, ручка». А 报纸 bàozhǐ «газета» — 报 «сообщать» + 纸 «бумага»."}'),
  ('hsk2-13-2', 2, 'words', '{"title":"Вещи","items":[{"hanzi":"手机","pinyin":"shǒujī","m":"мобильный телефон","emoji":"📱","ex":{"zh":"这是我的手机。","py":"Zhè shì wǒ de shǒujī.","m":"Это мой телефон."}},{"hanzi":"手表","pinyin":"shǒubiǎo","m":"наручные часы","emoji":"⌚","ex":{"zh":"我的手表很贵。","py":"Wǒ de shǒubiǎo hěn guì.","m":"Мои часы дорогие."}},{"hanzi":"铅笔","pinyin":"qiānbǐ","m":"карандаш","emoji":"✏️","ex":{"zh":"我有一支铅笔。","py":"Wǒ yǒu yì zhī qiānbǐ.","m":"У меня есть карандаш. (支 — новое слово)"}},{"hanzi":"报纸","pinyin":"bàozhǐ","m":"газета","emoji":"📰","ex":{"zh":"他每天看报纸。","py":"Tā měi tiān kàn bàozhǐ.","m":"Он каждый день читает газету."}}]}'),
  ('hsk2-13-2', 3, 'theory', '{"title":"这是… и 谁的…？","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["这是我的手机。","Это мой телефон."],["那是谁的手表？","Чьи это часы?"],["这是老师的铅笔。","Это карандаш учителя."],["那是他的报纸。","Это его газета."]]},{"t":"p","text":"Притяжательное 的 после человека или местоимения делает слово «чей»: 我的, 老师的, 谁的. Вопрос «чей?» — 谁的."},{"t":"tip","text":"谁 «кто» вы уже знаете; 谁的 — «чей»: 这是谁的手机？ «Чей это телефон?»"}]}'),
  ('hsk2-13-2', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["这","是","我","的","手机"],"hint":"«Это мой телефон.»"},{"answer":["那","是","谁","的","手表"],"hint":"«Чьи это часы?»"},{"answer":["他","每","天","看","报纸"],"hint":"«Он каждый день читает газету.»"}]}'),
  ('hsk2-13-2', 5, 'quiz', '{"title":"Мини-тест: чьё это","qs":[{"q":"Как спросить «Чей это телефон?»","options":["这是手机谁的？","这是谁的手机？","谁这的是手机？"],"correct":1},{"q":"Что значит 手表?","options":["телефон","наручные часы","газета"],"correct":1},{"q":"谁的 значит «чей».","tf":true}]}'),
  ('hsk2-13-2', 6, 'game', '{"type":"listen","title":"Слушаем вещи","items":[{"say":"手机","options":["shóujī","shǒují","shǒujī"],"correct":2},{"say":"手表","options":["shóubiǎo","shǒubiào","shǒubiǎo"],"correct":2},{"say":"铅笔","options":["qiānbì","qiānbǐ","qiánbǐ"],"correct":1},{"say":"报纸","options":["bàozhǐ","bǎozhǐ","bàozhì"],"correct":0},{"say":"这是谁的手机","options":["zhè shì shéi de shǒujī","zhè shì wǒ de shǒujī"],"correct":0}]}'),
  ('hsk2-13-2', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["手机","мобильный телефон"],["手表","наручные часы"],["铅笔","карандаш"],["报纸","газета"],["谁的","чей"]]}'),
  ('hsk2-13-2', 8, 'game', '{"type":"bughunt","title":"Китайский детектив: вещи","cases":[{"buggyText":"这是手机我的。","context":"«Это мой телефон»","options":["是这我的手机。","这是我的手机。","这手机是我的吗。"],"correct":1},{"buggyText":"那是的谁手表？","context":"«Чьи это часы?»","options":["那谁是的手表？","那是谁的手表？","谁的那是手表？"],"correct":1},{"buggyText":"他看每天报纸。","context":"«Он каждый день читает газету»","options":["他每天看报纸。","他每看天报纸。","看他每天报纸。"],"correct":0}]}'),
  ('hsk2-13-2', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как читается 铅笔?","options":["qiānbì","qiánbǐ","qiānbǐ"],"correct":2},{"q":"Как сказать «Это карандаш учителя»?","options":["老师这是的铅笔。","这是老师的铅笔。","这是铅笔老师的。"],"correct":1},{"q":"报纸 значит «газета».","tf":true},{"q":"Что значит 手机?","options":["компьютер","часы","мобильный телефон"],"correct":2},{"q":"Как сказать «Мои часы дорогие»?","options":["我手表的很贵。","我的手表很贵。","我的很贵手表。"],"correct":1}]}'),
  ('hsk2-13-3', 1, 'fact', '{"emoji":"⏩","title":"Сердце и скорость","text":"В знаках 快 «быстрый» и 慢 «медленный» есть 忄 «сердце»: скорость зависит от настроя. 快 — «и быстро, и скоро», а 慢 «медленно». Чтобы оценить действие, китайский использует «глагол + 得 + оценка»: 他说得很快 «он говорит очень быстро». Слово 说话 «разговаривать» состоит из 说 «говорить» и 话 «речь»."}'),
  ('hsk2-13-3', 2, 'words', '{"title":"Скорость","items":[{"hanzi":"说话","pinyin":"shuōhuà","m":"говорить, разговаривать","emoji":"🗣️","ex":{"zh":"他说话说得很快。","py":"Tā shuōhuà shuō de hěn kuài.","m":"Он говорит очень быстро."}},{"hanzi":"快","pinyin":"kuài","m":"быстрый, быстро","emoji":"⏩","ex":{"zh":"你走得很快。","py":"Nǐ zǒu de hěn kuài.","m":"Ты идёшь быстро."}},{"hanzi":"慢","pinyin":"màn","m":"медленный, медленно","emoji":"🐢","ex":{"zh":"请说慢一点儿。","py":"Qǐng shuō màn yìdiǎnr.","m":"Говорите, пожалуйста, медленнее."}},{"hanzi":"得","pinyin":"de","m":"частица оценки действия","emoji":"📏","ex":{"zh":"他跑得很快。","py":"Tā pǎo de hěn kuài.","m":"Он бегает быстро."}}]}'),
  ('hsk2-13-3', 3, 'theory', '{"title":"Глагол + 得 + оценка","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["他说得很快。","Он говорит очень быстро."],["我走得很慢。","Я иду очень медленно."],["他跑得非常快。","Он бегает очень быстро."],["她说话说得很好。","Она говорит очень хорошо."]]},{"t":"p","text":"После 得 всегда стоит описание действия (很快, 很慢, 很好). Если есть объект, глагол повторяют: 他说话说得很快 («говорит речь — говорит быстро»)."},{"t":"tip","text":"Просьба говорить медленнее: 请说慢一点儿. 一点儿 вы знаете."}]}'),
  ('hsk2-13-3', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["他","说","得","很","快"],"hint":"«Он говорит очень быстро.»"},{"answer":["我","走","得","很","慢"],"hint":"«Я иду очень медленно.»"},{"answer":["请","说","慢","一点儿"],"hint":"«Говорите, пожалуйста, медленнее.»"},{"answer":["他","跑","得","非常","快"],"hint":"«Он бегает очень быстро.»"}]}'),
  ('hsk2-13-3', 5, 'quiz', '{"title":"Мини-тест: 得","qs":[{"q":"Как сказать «Он бегает быстро»?","options":["他跑得很快。","他跑很得快。","他得跑很快。"],"correct":0},{"q":"Как попросить говорить медленнее?","options":["请说慢一点儿。","请慢说一点儿吗。","说请慢一点儿。"],"correct":0},{"q":"После 得 стоит оценка действия.","tf":true}]}'),
  ('hsk2-13-3', 6, 'game', '{"type":"listen","title":"Слушаем: быстро и медленно","items":[{"say":"说话","options":["shuóhuà","shuōhuà","shuōhuá"],"correct":1},{"say":"快","options":["kuài","kuǎi","kuāi"],"correct":0},{"say":"慢","options":["mǎn","mán","màn"],"correct":2},{"say":"他说得很快","options":["tā shuō de hěn kuài","tā shuō de hěn màn"],"correct":0},{"say":"请说慢一点儿","options":["qǐng shuō màn yìdiǎnr","qǐng shuō kuài yìdiǎnr"],"correct":0}]}'),
  ('hsk2-13-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["说话","разговаривать"],["快","быстрый"],["慢","медленный"],["得","частица оценки"],["说得很快","говорит быстро"]]}'),
  ('hsk2-13-3', 8, 'game', '{"type":"chatsim","title":"WeChat: скорость","messages":[{"speaker":"Друг","text":"你说话说得太快了。","pinyin":"Nǐ shuōhuà shuō de tài kuài le.","translation":"Ты говоришь слишком быстро.","options":["没关系，你很慢。","不客气，你说得快。","对不起，我说慢一点儿。"],"correct":2},{"speaker":"Друг","text":"你走得很快。","pinyin":"Nǐ zǒu de hěn kuài.","translation":"Ты идёшь очень быстро.","options":["没有，我慢得走。","对不起，我走慢一点儿。","不是，我走快。"],"correct":1},{"speaker":"Друг","text":"他跑得怎么样？","pinyin":"Tā pǎo de zěnmeyàng?","translation":"Как он бегает?","options":["跑得他很快。","他快跑得。","他跑得很快。"],"correct":2}]}'),
  ('hsk2-13-3', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: оценка действия","cases":[{"buggyText":"他说话很快。","context":"«Он говорит быстро» (с 得)","options":["他说话说得很快。","他说话得很快。","他说得话很快。"],"correct":0},{"buggyText":"我得走很慢。","context":"«Я иду медленно»","options":["我走很得慢。","得我走很慢。","我走得很慢。"],"correct":2},{"buggyText":"请快说一点儿慢。","context":"«Говорите медленнее»","options":["请说慢一点儿。","说请慢一点儿。","请慢说一点儿快。"],"correct":0}]}'),
  ('hsk2-13-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 慢?","options":["громкий","медленный","быстрый"],"correct":1},{"q":"Как читается 快?","options":["kuāi","kuài","kuǎi"],"correct":1},{"q":"Как сказать «Он говорит быстро»?","options":["他说话说得很快。","他得说话很快。","他说话快得很。"],"correct":0},{"q":"Если есть объект, глагол часто повторяют.","tf":true},{"q":"Как сказать «Я иду очень медленно»?","options":["我走得很慢。","我走很得慢。","我得走很慢。"],"correct":0}]}'),
  ('hsk2-13-4', 1, 'fact', '{"emoji":"🌨️","title":"Первый снег","text":"Анна и Ли Мин обсуждают погоду, и Ли Мин находит телефон Анны. В диалоге встретятся 雪, 阴, 晴, 手机, 手表, 说话, 快, 慢."}'),
  ('hsk2-13-4', 2, 'text', '{"title":"Первый снег","lines":[{"zh":"安娜：今天下雪了，真漂亮！","py":"Ānnà: Jīntiān xià xuě le, zhēn piàoliang!","m":"Анна: Сегодня пошёл снег, как красиво!"},{"zh":"李明：真的。昨天是晴天，今天是阴天。","py":"Lǐ Míng: Zhēn de. Zuótiān shì qíng tiān, jīntiān shì yīn tiān.","m":"Ли Мин: Правда. Вчера было ясно, сегодня пасмурно. (真的 «правда» — новое выражение)"},{"zh":"安娜：我的手机在哪儿？","py":"Ānnà: Wǒ de shǒujī zài nǎr?","m":"Анна: Где мой телефон?"},{"zh":"李明：这是你的手机吗？","py":"Lǐ Míng: Zhè shì nǐ de shǒujī ma?","m":"Ли Мин: Это твой телефон?"},{"zh":"安娜：是，谢谢！你说话说得真快。","py":"Ānnà: Shì, xièxie! Nǐ shuōhuà shuō de zhēn kuài.","m":"Анна: Да, спасибо! Ты говоришь очень быстро."},{"zh":"李明：对不起，我说得太快了。","py":"Lǐ Míng: Duìbuqǐ, wǒ shuō de tài kuài le.","m":"Ли Мин: Извини, я говорю слишком быстро."},{"zh":"安娜：没关系。你的手表是新的吗？","py":"Ānnà: Méi guānxi. Nǐ de shǒubiǎo shì xīn de ma?","m":"Анна: Ничего. Твои часы новые?"},{"zh":"李明：是，我哥哥送的。","py":"Lǐ Míng: Shì, wǒ gēge sòng de.","m":"Ли Мин: Да, их подарил брат."}],"qs":[{"q":"Какая погода сегодня?","options":["ясно","пасмурно и идёт снег","жарко"],"correct":1},{"q":"Что нашёл Ли Мин?","options":["телефон Анны","газету","карандаш"],"correct":0},{"q":"Вчера было пасмурно.","tf":false,"explain":"Вчера было ясно: 晴天."},{"q":"Что Анна говорит о речи Ли Мина?","options":["слишком быстрая","очень тихая","слишком медленная"],"correct":0},{"q":"Часы Ли Мина — подарок брата.","tf":true},{"q":"Вставьте слово: 我说得太___了。","options":["慢","快","高"],"correct":1},{"q":"Что отвечает Анна на извинение?","options":["没关系","不客气","谢谢"],"correct":0}]}'),
  ('hsk2-13-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["今天下雪了","сегодня пошёл снег"],["昨天是晴天","вчера было ясно"],["这是你的手机吗？","это твой телефон?"],["你说得真快","ты говоришь очень быстро"],["我哥哥送的","подарил мой брат"]]}'),
  ('hsk2-13-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"今天下雪了","options":["jīntiān xià yǔ le","jīntiān xià xuě le"],"correct":1},{"say":"昨天是晴天","options":["zuótiān shì yīn tiān","zuótiān shì qíng tiān"],"correct":1},{"say":"这是你的手机吗","options":["zhè shì nǐ de shǒubiǎo ma","zhè shì nǐ de shǒujī ma"],"correct":1},{"say":"我说得太快了","options":["wǒ shuō de tài kuài le","wǒ shuō de tài màn le"],"correct":0}]}'),
  ('hsk2-13-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: снежный день","cases":[{"buggyText":"今天是下雪了。","context":"«Сегодня пошёл снег»","options":["今天雪下了是。","今天下雪了。","下雪今天了。"],"correct":1},{"buggyText":"我说太快得了。","context":"«Я говорю слишком быстро»","options":["我得说太快了。","我说得太快了。","我说得快太了。"],"correct":1},{"buggyText":"这是的你手机吗？","context":"«Это твой телефон?»","options":["这是你手机的吗？","这是你的手机吗？","这你的是手机吗？"],"correct":1}]}'),
  ('hsk2-13-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я говорю слишком быстро»?","options":["我说得太快了。","我说太得快了。","我得说太快了。"],"correct":0},{"q":"Как читается 手表?","options":["shóubiǎo","shǒubiào","shǒubiǎo"],"correct":2},{"q":"Ли Мин извиняется за скорость речи.","tf":true}]}'),
  ('hsk2-13-5', 1, 'fact', '{"emoji":"🧣","title":"Соберите вещи и опишите погоду","text":"Сегодня вы описываете погоду, свои вещи и скорость, с которой делаете дела. Слова глав 1–13 HSK 2."}'),
  ('hsk2-13-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"雪","correctRadicals":["雨","彐"],"title":"Пазл: соберите 雪"}'),
  ('hsk2-13-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"晴","radicals":["日","青","月"],"correctOrder":["日","青"],"explain":"Слева 日, справа 青."},{"targetHanzi":"阴","radicals":["阝","月","日"],"correctOrder":["阝","月"],"explain":"Слева 阝, справа 月."},{"targetHanzi":"笔","radicals":["竹","毛","木"],"correctOrder":["竹","毛"],"explain":"Сверху 竹, внизу 毛."}]}'),
  ('hsk2-13-5', 4, 'game', '{"type":"build","title":"Мастерская дня","items":[{"target":"(Погода)","answer":["今天","是","阴天","，","明天","可能","下雪"],"hint":"«Сегодня пасмурно, завтра, возможно, снег.»"},{"target":"(Вещи)","answer":["这","是","我","的","手机","和","手表"],"hint":"«Это мой телефон и часы.»"},{"target":"(Скорость)","answer":["我","走","得","很","慢"],"hint":"«Я иду очень медленно.»"},{"target":"(Чтение)","answer":["他","每","天","看","报纸"],"hint":"«Он каждый день читает газету.»"}]}'),
  ('hsk2-13-5', 5, 'theory', '{"title":"Образец описания дня","blocks":[{"t":"table","head":["Тема","Фраза"],"rows":[["Погода","今天是晴天。"],["Вещи","这是我的手表。"],["Скорость","他说得很快。"],["Просьба","请说慢一点儿。"]]}]}'),
  ('hsk2-13-5', 6, 'game', '{"type":"chatsim","title":"WeChat: день и вещи","messages":[{"speaker":"Друг","text":"今天天气怎么样？","pinyin":"Jīntiān tiānqì zěnmeyàng?","translation":"Какая сегодня погода?","options":["今天阴是天，下雪。","今天是阴天，可能下雪。","今天天阴雪。"],"correct":1},{"speaker":"Друг","text":"这是谁的手机？","pinyin":"Zhè shì shéi de shǒujī?","translation":"Чей это телефон?","options":["这是我的手机。","手机的是我。","这是手机我。"],"correct":0},{"speaker":"Друг","text":"你说得太快了！","pinyin":"Nǐ shuō de tài kuài le!","translation":"Ты говоришь слишком быстро!","options":["对不起，我说慢一点儿。","没关系，我快。","不客气。"],"correct":0}]}'),
  ('hsk2-13-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["雨 + 彐","雪"],["日 + 青","晴"],["阝 + 月","阴"],["竹 + 毛","笔"]]}'),
  ('hsk2-13-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"快","pinyin":"kuài","m":"быстрый","hint":"слева 忄, справа 夬"},{"hanzi":"慢","pinyin":"màn","m":"медленный","hint":"слева 忄, справа 曼"},{"hanzi":"话","pinyin":"huà","m":"речь","hint":"слева 讠, справа 舌"}]}'),
  ('hsk2-13-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Это мой телефон и часы»?","options":["这是手机我的和手表。","这是我的和手机手表。","这是我的手机和手表。"],"correct":2},{"q":"Какие знаки составляют 雪?","options":["雨 и 彐","阝 и 月","日 и 青"],"correct":0},{"q":"Слова погоды стоят после 是.","tf":true}]}'),
  ('hsk2-13-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 13 (HSK 2)","text":"雪, 阴, 晴, 手机, 手表, 铅笔, 报纸, 说话, 快, 慢 и 得."}'),
