  ('hsk2-13-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"❄️","options":["晴","雪","阴"],"correct":1},{"emoji":"📱","options":["手表","手机","报纸"],"correct":1},{"emoji":"⌚","options":["手表","铅笔","手机"],"correct":0},{"emoji":"📰","options":["报纸","手表","铅笔"],"correct":0}]}'),
  ('hsk2-13-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["雪","снег"],["阴","пасмурный"],["晴","ясный"],["手机","мобильный телефон"],["手表","наручные часы"],["铅笔","карандаш"],["报纸","газета"],["说话","разговаривать"],["快","быстрый"],["慢","медленный"]]}'),
  ('hsk2-13-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Пошёл снег»?","options":["下雪了。","雪下了。","了下雪。"],"correct":0},{"q":"Как спросить «Чей это телефон?»","options":["这是手机谁的？","谁这的是手机？","这是谁的手机？"],"correct":2},{"q":"Как сказать «Он говорит быстро»?","options":["他说话说得很快。","他得说话很快。","他说话快得很。"],"correct":0},{"q":"После 得 стоит оценка действия.","tf":true},{"q":"Как попросить говорить медленнее?","options":["说请慢一点儿。","请说慢一点儿。","请慢说一点儿吗。"],"correct":1},{"q":"Что значит 晴天?","options":["снежный день","пасмурный день","ясный день"],"correct":2},{"q":"手表 — это мобильный телефон.","tf":false},{"q":"Как сказать «Я иду очень медленно»?","options":["我走很得慢。","我得走很慢。","我走得很慢。"],"correct":2},{"q":"Как читается 铅笔?","options":["qiánbǐ","qiānbǐ","qiānbì"],"correct":1},{"q":"Как сказать «Он каждый день читает газету»?","options":["他看每天报纸。","他每天看报纸。","他每看天报纸。"],"correct":1}]}'),
  ('hsk2-13-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["今天","是","晴天"],"hint":"«Сегодня ясно.»"},{"answer":["这","是","我","的","手机"],"hint":"«Это мой телефон.»"},{"answer":["他","说","得","很","快"],"hint":"«Он говорит очень быстро.»"},{"answer":["请","说","慢","一点儿"],"hint":"«Говорите, пожалуйста, медленнее.»"}]}'),
  ('hsk2-13-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"这是手机我的。","context":"«Это мой телефон»","options":["这是我的手机。","是这我的手机。","这手机是我的吗。"],"correct":0},{"buggyText":"我说太快得了。","context":"«Я говорю слишком быстро»","options":["我说得太快了。","我得说太快了。","我说得快太了。"],"correct":0},{"buggyText":"今天是下雪了。","context":"«Сегодня пошёл снег»","options":["今天雪下了是。","今天下雪了。","下雪今天了。"],"correct":1}]}'),
  ('hsk2-13-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"今天天气怎么样？","pinyin":"Jīntiān tiānqì zěnmeyàng?","translation":"Какая сегодня погода?","options":["今天阴是天，下雪。","今天是阴天，可能下雪。","今天天阴雪。"],"correct":1},{"speaker":"Друг","text":"你说得太快了！","pinyin":"Nǐ shuō de tài kuài le!","translation":"Ты говоришь слишком быстро!","options":["没关系，我快。","不客气。","对不起，我说慢一点儿。"],"correct":2}]}'),
  ('hsk2-13-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"雪","pinyin":"xuě","m":"снег","hint":"雨 + 彐"},{"hanzi":"快","pinyin":"kuài","m":"быстрый","hint":"忄 + 夬"},{"hanzi":"慢","pinyin":"màn","m":"медленный","hint":"忄 + 曼"}]}'),
  ('hsk2-13-6', 10, 'recall', '{"words":[{"hanzi":"雪","pinyin":"xuě","m":"снег"},{"hanzi":"阴","pinyin":"yīn","m":"пасмурный"},{"hanzi":"晴","pinyin":"qíng","m":"ясный"},{"hanzi":"手机","pinyin":"shǒujī","m":"мобильный телефон"},{"hanzi":"手表","pinyin":"shǒubiǎo","m":"наручные часы"},{"hanzi":"铅笔","pinyin":"qiānbǐ","m":"карандаш"},{"hanzi":"报纸","pinyin":"bàozhǐ","m":"газета"},{"hanzi":"说话","pinyin":"shuōhuà","m":"разговаривать"},{"hanzi":"快","pinyin":"kuài","m":"быстрый"},{"hanzi":"慢","pinyin":"màn","m":"медленный"},{"hanzi":"得","pinyin":"de","m":"частица оценки"}],"tf":[{"zh":"他说话快得很。","py":"tā shuōhuà kuài de hěn.","m":"Он говорит быстро.","ok":false,"explain":"Правильно: 他说话说得很快."},{"zh":"这是谁的手机？","py":"zhè shì shéi de shǒujī?","m":"Чей это телефон?","ok":true}],"sentences":[{"zh":"今天下雪了。","tokens":["今天","下","雪","了"],"m":"Сегодня пошёл снег."},{"zh":"这是我的手机。","tokens":["这","是","我","的","手机"],"m":"Это мой телефон."},{"zh":"他说得很快。","tokens":["他","说","得","很","快"],"m":"Он говорит очень быстро."}]}'),
  ('hsk2-14-1', 1, 'fact', '{"emoji":"🔗","title":"В китайском союзы ходят парами","text":"По-русски мы говорим «потому что…» или «поэтому…» — достаточно одного. Китайский любит пары: 因为…所以… «потому что… поэтому…» и 虽然…但是… «хотя… но…». Обе половины нужны, и это выглядит как два звена цепи. В знаке 因 «причина» человек 大 лежит на циновке 囗: из этого «лежащего на основе» выросло слово «причина»."}'),
  ('hsk2-14-1', 2, 'words', '{"title":"Союзы","items":[{"hanzi":"因为","pinyin":"yīnwèi","m":"потому что","emoji":"➡️","ex":{"zh":"因为我生病了。","py":"Yīnwèi wǒ shēngbìng le.","m":"Потому что я заболел."}},{"hanzi":"所以","pinyin":"suǒyǐ","m":"поэтому","emoji":"⬅️","ex":{"zh":"所以我休息。","py":"Suǒyǐ wǒ xiūxi.","m":"Поэтому я отдыхаю."}},{"hanzi":"虽然","pinyin":"suīrán","m":"хотя","emoji":"🌤️","ex":{"zh":"虽然很贵。","py":"Suīrán hěn guì.","m":"Хотя дорого."}},{"hanzi":"但是","pinyin":"dànshì","m":"но, однако","emoji":"🔀","ex":{"zh":"但是很好吃。","py":"Dànshì hěn hǎochī.","m":"Но очень вкусно."}}]}'),
  ('hsk2-14-1', 3, 'theory', '{"title":"Две пары союзов","blocks":[{"t":"table","head":["Схема","Пример","Перевод"],"rows":[["因为…，所以…","因为我生病了，所以我休息。","Потому что я заболел, поэтому отдыхаю."],["虽然…，但是…","虽然很贵，但是很好吃。","Хотя дорого, но вкусно."]]},{"t":"p","text":"Обе половины стоят в начале своей части. В русском мы часто опускаем вторую, а в китайском её лучше сохранить: 因为…所以… звучит естественно, а один 所以 без 因为 тоже допустим в разговоре."},{"t":"tip","text":"Если подлежащее одно, оно может стоять один раз: 虽然我很忙，但是我很高兴."}]}'),
  ('hsk2-14-1', 4, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"➡️","options":["但是","因为","所以"],"correct":1},{"emoji":"⬅️","options":["因为","所以","虽然"],"correct":1},{"emoji":"🌤️","options":["但是","因为","虽然"],"correct":2},{"emoji":"🔀","options":["但是","虽然","所以"],"correct":0}]}'),
  ('hsk2-14-1', 5, 'quiz', '{"title":"Мини-тест: союзы","qs":[{"q":"Как сказать «Потому что я заболел, поэтому отдыхаю»?","options":["因为我生病了，所以我休息。","所以我生病了，因为我休息。","因为所以我生病休息。"],"correct":0},{"q":"Как сказать «Хотя дорого, но вкусно»?","options":["但是很贵，虽然很好吃。","虽然很贵，但是很好吃。","虽然但是很贵很好吃。"],"correct":1},{"q":"因为 и 所以 стоят парой.","tf":true}]}'),
  ('hsk2-14-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["因为","потому что"],["所以","поэтому"],["虽然","хотя"],["但是","но"],["虽然…但是…","хотя… но…"]]}'),
  ('hsk2-14-1', 7, 'game', '{"type":"listen","title":"Слушаем: союзы","items":[{"say":"因为","options":["yīnwèi","yǐnwèi","yīnwéi"],"correct":0},{"say":"所以","options":["suǒyí","suǒyǐ","suóyǐ"],"correct":1},{"say":"虽然","options":["suírán","suīrán","suīrǎn"],"correct":1},{"say":"但是","options":["dānshì","dànshì","dànshí"],"correct":1},{"say":"因为我生病了所以我休息","options":["yīnwèi wǒ shēngbìng le suǒyǐ wǒ xiūxi","yīnwèi wǒ shēngbìng le dànshì wǒ xiūxi"],"correct":0}]}'),
  ('hsk2-14-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["因为","我","生病","了","，","所以","我","休息"],"hint":"«Потому что я заболел, поэтому отдыхаю.»"},{"answer":["虽然","很","贵","，","但是","很","好吃"],"hint":"«Хотя дорого, но вкусно.»"},{"answer":["因为","下雪","，","所以","我","在","家"],"hint":"«Потому что идёт снег, поэтому я дома.»"}]}'),
  ('hsk2-14-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"因","pinyin":"yīn","m":"причина","hint":"рамка 囗, внутри 大"},{"hanzi":"但","pinyin":"dàn","m":"но","hint":"слева 亻, справа 旦"},{"hanzi":"所","pinyin":"suǒ","m":"место, поэтому","hint":"слева 户, справа 斤"}]}'),
  ('hsk2-14-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 因为?","options":["поэтому","хотя","потому что"],"correct":2},{"q":"Как читается 虽然?","options":["suírán","suīrǎn","suīrán"],"correct":2},{"q":"Что значит 但是?","options":["поэтому","потому что","но"],"correct":2},{"q":"虽然 и 但是 образуют пару.","tf":true},{"q":"Какой знак содержит 囗 и 大?","options":["所","因","但"],"correct":1}]}'),
  ('hsk2-14-2', 1, 'fact', '{"emoji":"⚖️","title":"Два человека рядом — «сравнение»","text":"Знак 比 нарисован как два человека 匕 рядом: «сравнивать». Схема «А 比 В + прилагательное» значит «А больше В»: 我哥哥比我高 «мой брат выше меня». Слово 为什么 «почему» — это «для чего» (为 + 什么), а 别 «не надо» ставится перед глаголом: 别说话 «не разговаривай»."}'),
  ('hsk2-14-2', 2, 'words', '{"title":"Почему, сравнение, запрет","items":[{"hanzi":"为什么","pinyin":"wèishénme","m":"почему","emoji":"❓","ex":{"zh":"你为什么不去？","py":"Nǐ wèishénme bú qù?","m":"Почему ты не идёшь?"}},{"hanzi":"比","pinyin":"bǐ","m":"по сравнению с, чем","emoji":"⚖️","ex":{"zh":"我哥哥比我高。","py":"Wǒ gēge bǐ wǒ gāo.","m":"Мой брат выше меня."}},{"hanzi":"别","pinyin":"bié","m":"не (запрет), не надо","emoji":"🚫","ex":{"zh":"别说话。","py":"Bié shuōhuà.","m":"Не разговаривай."}}]}'),
  ('hsk2-14-2', 3, 'theory', '{"title":"为什么, 比 и 别","blocks":[{"t":"table","head":["Слово","Схема","Пример"],"rows":[["为什么","为什么 + глагол","你为什么不去？"],["比","А 比 В + прилагательное","他比我高。"],["别","别 + глагол","别说话。"]]},{"t":"p","text":"Ответ на 为什么 начинают с 因为: 因为我很忙. 比 ставится между двумя предметами, а прилагательное идёт после В: 这件比那件便宜. Запрет строят с 别: 别忙 «не суетись»."},{"t":"tip","text":"В схеме 比 не добавляйте 很: говорят 他比我高, а не 他比我很高."}]}'),
  ('hsk2-14-2', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["你","为什么","不","去"],"hint":"«Почему ты не идёшь?»"},{"answer":["我","哥哥","比","我","高"],"hint":"«Мой брат выше меня.»"},{"answer":["这","件","比","那","件","便宜"],"hint":"«Эта вещь дешевле той.»"},{"answer":["别","说话"],"hint":"«Не разговаривай.»"}]}'),
  ('hsk2-14-2', 5, 'quiz', '{"title":"Мини-тест: 为什么 и 比","qs":[{"q":"Как сказать «Мой брат выше меня»?","options":["比我哥哥我高。","我哥哥比我高。","我哥哥高比我。"],"correct":1},{"q":"Как спросить «Почему ты не идёшь?»","options":["你为什么不去？","你不去为什么？","为什么你吗不去？"],"correct":0},{"q":"В схеме с 比 перед прилагательным нужно 很.","tf":false,"explain":"Не нужно: 比 уже сравнивает."}]}'),
  ('hsk2-14-2', 6, 'game', '{"type":"listen","title":"Слушаем: почему, сравнение, запрет","items":[{"say":"为什么","options":["wèishěnme","wèishénme","wéishénme"],"correct":1},{"say":"比","options":["bǐ","bí","bì"],"correct":0},{"say":"别","options":["bié","biè","biě"],"correct":0},{"say":"我哥哥比我高","options":["wǒ gēge hé wǒ gāo","wǒ gēge bǐ wǒ gāo"],"correct":1},{"say":"别说话","options":["bù shuōhuà","bié shuōhuà"],"correct":1}]}'),
  ('hsk2-14-2', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["为什么","почему"],["比","чем (сравнение)"],["别","не надо"],["他比我高","он выше меня"],["别说话","не разговаривай"]]}'),
  ('hsk2-14-2', 8, 'game', '{"type":"bughunt","title":"Китайский детектив: сравнение и запрет","cases":[{"buggyText":"我哥哥比我很高。","context":"«Брат выше меня»","options":["我哥哥很比我高。","我比哥哥很高。","我哥哥比我高。"],"correct":2},{"buggyText":"你不去为什么？","context":"«Почему ты не идёшь?»","options":["为什么你不去吗？","你为什么吗不去？","你为什么不去？"],"correct":2},{"buggyText":"不说话别。","context":"«Не разговаривай»","options":["说话别。","别不说话。","别说话。"],"correct":2}]}'),
  ('hsk2-14-2', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 别 перед глаголом?","options":["очень","не надо","уже"],"correct":1},{"q":"Как читается 为什么?","options":["wèishěnme","wèishénme","wéishénme"],"correct":1},{"q":"Как сказать «Эта вещь дешевле той»?","options":["这件比那件便宜。","这件便宜比那件。","这比件那件便宜。"],"correct":0},{"q":"Ответ на 为什么 начинается с 因为.","tf":true},{"q":"Как сказать «Не суетись»?","options":["忙别。","别忙。","别吗忙。"],"correct":1}]}'),
  ('hsk2-14-3', 1, 'fact', '{"emoji":"⚡","title":"Три маленьких слова с большими ролями","text":"就 jiù «сразу, как раз» ставится перед глаголом и означает «уже», «тут же»: 我八点就起床了 «я встал уже в восемь». 还 hái значит «ещё»: 他还没来 «он ещё не пришёл». А 对 duì «правильно, верно»: 你说得对 «ты прав». Эти слова встречаются в каждой фразе."}'),
  ('hsk2-14-3', 2, 'words', '{"title":"Сразу, ещё, верно","items":[{"hanzi":"就","pinyin":"jiù","m":"сразу, уже, именно","emoji":"⚡","ex":{"zh":"我明天就来。","py":"Wǒ míngtiān jiù lái.","m":"Завтра сразу приду."}},{"hanzi":"还","pinyin":"hái","m":"ещё, всё ещё","emoji":"🔁","ex":{"zh":"他还没来。","py":"Tā hái méi lái.","m":"Он ещё не пришёл."}},{"hanzi":"对","pinyin":"duì","m":"верный, правильно","emoji":"✅","ex":{"zh":"你说得对。","py":"Nǐ shuō de duì.","m":"Ты прав."}}]}'),
  ('hsk2-14-3', 3, 'theory', '{"title":"就, 还 и 对","blocks":[{"t":"table","head":["Слово","Что делает","Пример"],"rows":[["就","«сразу, уже»","我八点就起床了。"],["还","«ещё, всё ещё»","他还没来。 / 我还要一杯咖啡。"],["对","«верно»","你说得对。"]]},{"t":"p","text":"就 и 还 стоят перед глаголом. 还没 + глагол значит «ещё не»: 他还没吃药. 对 — прилагательное: 对 в ответе означает «да, верно»."},{"t":"tip","text":"对不起 «извините» вы знаете из HSK 1: там 对 тоже связан с «правильностью»."}]}'),
  ('hsk2-14-3', 4, 'game', '{"type":"listen","title":"Слушаем: сразу, ещё, верно","items":[{"say":"就","options":["jiú","jiù","jiǔ"],"correct":1},{"say":"还","options":["huán","hǎi","hái"],"correct":2},{"say":"对","options":["duí","dùi","duì"],"correct":2},{"say":"我八点就起床了","options":["wǒ bā diǎn hái qǐchuáng le","wǒ bā diǎn jiù qǐchuáng le"],"correct":1},{"say":"你说得对","options":["nǐ shuō de duì","nǐ shuō de cuò"],"correct":0}]}'),
  ('hsk2-14-3', 5, 'game', '{"type":"tone_visualizer","initialTone":4,"title":"Тренажёр голоса: повторите «duì» (4 тон)"}'),
  ('hsk2-14-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"⚡","options":["还","就","对"],"correct":1},{"emoji":"🔁","options":["对","还","就"],"correct":1},{"emoji":"✅","options":["还","就","对"],"correct":2}]}'),
  ('hsk2-14-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["就","сразу"],["还","ещё"],["对","верно"],["还没","ещё не"],["你说得对","ты прав"]]}'),
  ('hsk2-14-3', 8, 'game', '{"type":"chatsim","title":"WeChat: болею","messages":[{"speaker":"Друг","text":"你为什么没来？","pinyin":"Nǐ wèishénme méi lái?","translation":"Почему ты не пришёл?","options":["因为所以我生病。","为什么我生病。","因为我生病了。"],"correct":2},{"speaker":"Друг","text":"你吃药了吗？","pinyin":"Nǐ chī yào le ma?","translation":"Ты принял лекарство?","options":["还吃了，我就没。","没吃，我还药。","还没吃，我现在就吃。"],"correct":2},{"speaker":"Друг","text":"你应该休息。","pinyin":"Nǐ yīnggāi xiūxi.","translation":"Тебе нужно отдохнуть. (应该 «следует» — новое слово)","options":["你说得对。","你说得慢。","你说得错。"],"correct":0}]}'),
  ('hsk2-14-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","八","点","就","起床","了"],"hint":"«Я встал уже в восемь.»"},{"answer":["他","还","没","来"],"hint":"«Он ещё не пришёл.»"},{"answer":["你","说","得","对"],"hint":"«Ты прав.»"}]}'),
  ('hsk2-14-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 还没?","options":["очень","уже","ещё не"],"correct":2},{"q":"Как читается 对?","options":["duì","duí","dùi"],"correct":0},{"q":"Как сказать «Он ещё не пришёл»?","options":["还他没来。","他还没来。","他没还来。"],"correct":1},{"q":"就 может значить «сразу, уже».","tf":true},{"q":"Как сказать «Ты прав»?","options":["得你说对。","你对说得。","你说得对。"],"correct":2}]}'),
  ('hsk2-14-4', 1, 'fact', '{"emoji":"📞","title":"Объяснение по телефону","text":"Ли Мин звонит Анне и спрашивает, почему её не было в школе. В диалоге встретятся 因为, 所以, 虽然, 但是, 为什么, 比, 别, 就, 还, 对."}'),
  ('hsk2-14-4', 2, 'text', '{"title":"Почему тебя не было","lines":[{"zh":"李明：安娜，你为什么不来学校？","py":"Lǐ Míng: Ānnà, nǐ wèishénme bù lái xuéxiào?","m":"Ли Мин: Анна, почему ты не пришла в школу?"},{"zh":"安娜：因为我生病了，所以我在家休息。","py":"Ānnà: Yīnwèi wǒ shēngbìng le, suǒyǐ wǒ zài jiā xiūxi.","m":"Анна: Потому что я заболела, поэтому отдыхаю дома."},{"zh":"李明：你现在身体怎么样？","py":"Lǐ Míng: Nǐ xiànzài shēntǐ zěnmeyàng?","m":"Ли Мин: Как ты себя чувствуешь?"},{"zh":"安娜：虽然还有一点儿累，但是比昨天好。","py":"Ānnà: Suīrán hái yǒu yìdiǎnr lèi, dànshì bǐ zuótiān hǎo.","m":"Анна: Хотя ещё немного устала, но лучше, чем вчера."},{"zh":"李明：太好了！别忙，多休息。","py":"Lǐ Míng: Tài hǎo le! Bié máng, duō xiūxi.","m":"Ли Мин: Здорово! Не суетись, отдыхай побольше."},{"zh":"安娜：你说得对。我吃了药，明天就来学校。","py":"Ānnà: Nǐ shuō de duì. Wǒ chī le yào, míngtiān jiù lái xuéxiào.","m":"Анна: Ты прав. Я приняла лекарство и завтра сразу приду."},{"zh":"李明：好，明天见！","py":"Lǐ Míng: Hǎo, míngtiān jiàn!","m":"Ли Мин: Хорошо, до завтра!"}],"qs":[{"q":"Почему Анна не пришла в школу?","options":["забыла","заболела","уехала в Пекин"],"correct":1},{"q":"Анна чувствует себя лучше, чем вчера.","tf":true},{"q":"Что советует Ли Мин?","options":["путешествовать","бегать","отдыхать"],"correct":2},{"q":"Вставьте слово: 因为我生病了，___我在家休息。","options":["还","但是","所以"],"correct":2},{"q":"Анна придёт в школу через неделю.","tf":false,"explain":"Она говорит 明天就来."},{"q":"Что значит 别忙?","options":["не суетись","не говори","не уходи"],"correct":0},{"q":"Как Анна подтверждает совет?","options":["你说得对","我不对","你说得错"],"correct":0}]}'),
  ('hsk2-14-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["你为什么不来学校？","почему ты не пришла в школу?"],["因为我生病了","потому что я заболела"],["比昨天好","лучше, чем вчера"],["别忙，多休息","не суетись, отдыхай"],["明天就来学校","завтра сразу приду в школу"]]}'),
  ('hsk2-14-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你为什么不来学校","options":["nǐ wèishénme bù lái xuéxiào","nǐ wèishénme bù qù xuéxiào"],"correct":0},{"say":"因为我生病了所以我在家休息","options":["yīnwèi wǒ shēngbìng le suǒyǐ wǒ zài jiā xiūxi","yīnwèi wǒ shēngbìng le dànshì wǒ zài jiā xiūxi"],"correct":0},{"say":"虽然还有一点儿累但是比昨天好","options":["suīrán hái yǒu yìdiǎnr lèi dànshì bǐ zuótiān hǎo","yīnwèi hái yǒu yìdiǎnr lèi suǒyǐ bǐ zuótiān hǎo"],"correct":0},{"say":"明天就来学校","options":["míngtiān jiù lái xuéxiào","míngtiān hái lái xuéxiào"],"correct":0}]}'),
  ('hsk2-14-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: объяснения","cases":[{"buggyText":"因为我生病了，但是我休息。","context":"«Потому что заболела, поэтому отдыхаю»","options":["因为我生病了，所以我休息。","因为我生病了，虽然我休息。","所以我生病了，因为我休息。"],"correct":0},{"buggyText":"比昨天好很。","context":"«Лучше, чем вчера»","options":["昨天比好。","比昨天好。","好比昨天。"],"correct":1},{"buggyText":"别休息忙。","context":"«Не суетись, отдыхай»","options":["别忙，多休息。","别多忙休息。","忙别，休息多。"],"correct":0}]}'),
  ('hsk2-14-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Потому что я заболела, поэтому отдыхаю»?","options":["所以我生病了，因为我休息。","因为我生病了，所以我休息。","因为所以我生病。"],"correct":1},{"q":"Как читается 但是?","options":["dànshì","dānshì","dànshí"],"correct":0},{"q":"Анна обещает прийти завтра.","tf":true}]}'),
  ('hsk2-14-5', 1, 'fact', '{"emoji":"🧠","title":"Постройте логическую цепочку","text":"Сегодня вы объясняете причину, сравниваете вещи и просите не суетиться. Слова глав 1–14 HSK 2."}'),
  ('hsk2-14-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"因","correctRadicals":["囗","大"],"title":"Пазл: соберите 因"}'),
  ('hsk2-14-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"但","radicals":["亻","旦","女"],"correctOrder":["亻","旦"],"explain":"Слева 亻, справа 旦."},{"targetHanzi":"对","radicals":["又","寸","亻"],"correctOrder":["又","寸"],"explain":"Слева 又, справа 寸."},{"targetHanzi":"别","radicals":["另","刂","口"],"correctOrder":["另","刂"],"explain":"Слева 另, справа 刂."}]}'),
  ('hsk2-14-5', 4, 'game', '{"type":"build","title":"Мастерская логики","items":[{"target":"(Причина)","answer":["因为","我","很","忙","，","所以","我","没","去"],"hint":"«Потому что я занят, поэтому не пошёл.»"},{"target":"(Контраст)","answer":["虽然","很","累","，","但是","很","高兴"],"hint":"«Хотя устал, но очень рад.»"},{"target":"(Сравнение)","answer":["这","件","比","那","件","便宜"],"hint":"«Эта вещь дешевле той.»"},{"target":"(Совет)","answer":["别","忙","，","多","休息"],"hint":"«Не суетись, больше отдыхай.»"}]}'),
  ('hsk2-14-5', 5, 'theory', '{"title":"Образец рассуждения","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["Причина","因为…所以…"],["Контраст","虽然…但是…"],["Сравнение","…比…"],["Запрет","别…"]]}]}'),
  ('hsk2-14-5', 6, 'game', '{"type":"chatsim","title":"WeChat: объясняю","messages":[{"speaker":"Друг","text":"你为什么不吃羊肉？","pinyin":"Nǐ wèishénme bù chī yángròu?","translation":"Почему ты не ешь баранину?","options":["因为所以我吃。","为什么我不吃。","因为我不喜欢，所以不吃。"],"correct":2},{"speaker":"Друг","text":"这件衣服比那件贵吗？","pinyin":"Zhè jiàn yīfu bǐ nà jiàn guì ma?","translation":"Эта вещь дороже той?","options":["对，这件比贵那件。","是，虽然贵，但是很漂亮。","不比，我很贵。"],"correct":1},{"speaker":"Друг","text":"别忙，休息一下。","pinyin":"Bié máng, xiūxi yíxià.","translation":"Не суетись, отдохни.","options":["你说得错。","不是，我忙。","你说得对，谢谢！"],"correct":2}]}'),
  ('hsk2-14-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["囗 + 大","因"],["亻 + 旦","但"],["又 + 寸","对"],["另 + 刂","别"]]}'),
  ('hsk2-14-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"比","pinyin":"bǐ","m":"сравнивать","hint":"две 匕 рядом"},{"hanzi":"别","pinyin":"bié","m":"не надо","hint":"слева 另, справа 刂"},{"hanzi":"对","pinyin":"duì","m":"верный","hint":"слева 又, справа 寸"}]}'),
  ('hsk2-14-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Хотя устал, но рад»?","options":["虽然但是累高兴。","虽然累，但是高兴。","但是累，虽然高兴。"],"correct":1},{"q":"Из каких частей состоит 因?","options":["又 и 寸","囗 и 大","亻 и 旦"],"correct":1},{"q":"别 используется для запрета.","tf":true}]}'),
  ('hsk2-14-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 14 (HSK 2)","text":"因为, 所以, 虽然, 但是, 为什么, 比, 别, 就, 还 и 对."}'),
  ('hsk2-14-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"因为","options":["yīnwèi","dànshì","suǒyǐ"],"correct":0},{"say":"虽然很贵但是很好吃","options":["suīrán hěn guì dànshì hěn hǎochī","yīnwèi hěn guì suǒyǐ hěn hǎochī"],"correct":0},{"say":"我哥哥比我高","options":["wǒ gēge hé wǒ gāo","wǒ gēge bǐ wǒ gāo"],"correct":1},{"say":"别说话","options":["bié shuōhuà","bù shuōhuà"],"correct":0},{"say":"我明天就来","options":["wǒ míngtiān jiù lái","wǒ míngtiān hái lái"],"correct":0},{"say":"你说得对","options":["nǐ shuō de cuò","nǐ shuō de duì"],"correct":1}]}'),
  ('hsk2-14-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"➡️","options":["虽然","所以","因为"],"correct":2},{"emoji":"🔀","options":["所以","但是","因为"],"correct":1},{"emoji":"⚖️","options":["比","就","别"],"correct":0},{"emoji":"🚫","options":["还","别","对"],"correct":1}]}'),
  ('hsk2-14-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["因为","потому что"],["所以","поэтому"],["虽然","хотя"],["但是","но"],["为什么","почему"],["比","чем"],["别","не надо"],["就","сразу"],["还","ещё"],["对","верно"]]}'),
  ('hsk2-14-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Потому что я заболел, поэтому отдыхаю»?","options":["所以我生病了，因为我休息。","因为我生病了，所以我休息。","因为所以我生病休息。"],"correct":1},{"q":"Как сказать «Хотя дорого, но вкусно»?","options":["虽然但是很贵很好吃。","虽然很贵，但是很好吃。","但是很贵，虽然很好吃。"],"correct":1},{"q":"Как сказать «Мой брат выше меня»?","options":["比我哥哥我高。","我哥哥高比我。","我哥哥比我高。"],"correct":2},{"q":"В схеме 比 перед прилагательным ставят 很.","tf":false},{"q":"Как сказать «Не разговаривай»?","options":["说话别。","别说话。","别不说话。"],"correct":1},{"q":"Как сказать «Он ещё не пришёл»?","options":["他没还来。","还他没来。","他还没来。"],"correct":2},{"q":"就 может значить «сразу, уже».","tf":true},{"q":"Как сказать «Ты прав»?","options":["你说得对。","得你说对。","你对说得。"],"correct":0},{"q":"Как читается 为什么?","options":["wèishénme","wéishénme","wèishěnme"],"correct":0},{"q":"Что значит 虽然?","options":["поэтому","потому что","хотя"],"correct":2}]}'),
  ('hsk2-14-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["因为","我","生病","了","，","所以","我","休息"],"hint":"«Потому что я заболел, поэтому отдыхаю.»"},{"answer":["虽然","很","贵","，","但是","很","好吃"],"hint":"«Хотя дорого, но вкусно.»"},{"answer":["我","哥哥","比","我","高"],"hint":"«Мой брат выше меня.»"},{"answer":["你","说","得","对"],"hint":"«Ты прав.»"}]}'),
  ('hsk2-14-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我哥哥比我很高。","context":"«Брат выше меня»","options":["我比哥哥很高。","我哥哥很比我高。","我哥哥比我高。"],"correct":2},{"buggyText":"不说话别。","context":"«Не разговаривай»","options":["说话别。","别不说话。","别说话。"],"correct":2},{"buggyText":"因为我生病了，但是我休息。","context":"«Потому что заболел, поэтому отдыхаю»","options":["所以我生病了，因为我休息。","因为我生病了，虽然我休息。","因为我生病了，所以我休息。"],"correct":2}]}'),
  ('hsk2-14-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"你为什么不来？","pinyin":"Nǐ wèishénme bù lái?","translation":"Почему ты не пришёл?","options":["因为所以我生病。","为什么我生病。","因为我生病了，所以在家休息。"],"correct":2},{"speaker":"Друг","text":"别忙，多休息。","pinyin":"Bié máng, duō xiūxi.","translation":"Не суетись, отдыхай.","options":["你说得错。","你说得对，谢谢！","不是，我忙。"],"correct":1}]}'),
  ('hsk2-14-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"因","pinyin":"yīn","m":"причина","hint":"囗 + 大"},{"hanzi":"比","pinyin":"bǐ","m":"сравнивать","hint":"две 匕"},{"hanzi":"对","pinyin":"duì","m":"верный","hint":"又 + 寸"}]}'),
  ('hsk2-14-6', 10, 'recall', '{"words":[{"hanzi":"因为","pinyin":"yīnwèi","m":"потому что"},{"hanzi":"所以","pinyin":"suǒyǐ","m":"поэтому"},{"hanzi":"虽然","pinyin":"suīrán","m":"хотя"},{"hanzi":"但是","pinyin":"dànshì","m":"но"},{"hanzi":"为什么","pinyin":"wèishénme","m":"почему"},{"hanzi":"比","pinyin":"bǐ","m":"чем"},{"hanzi":"别","pinyin":"bié","m":"не надо"},{"hanzi":"就","pinyin":"jiù","m":"сразу"},{"hanzi":"还","pinyin":"hái","m":"ещё"},{"hanzi":"对","pinyin":"duì","m":"верно"}],"tf":[{"zh":"我哥哥比我很高。","py":"wǒ gēge bǐ wǒ hěn gāo.","m":"Брат выше меня.","ok":false,"explain":"Правильно: 我哥哥比我高."},{"zh":"别说话。","py":"bié shuōhuà.","m":"Не разговаривай.","ok":true}],"sentences":[{"zh":"因为我生病了，所以我休息。","tokens":["因为","我","生病","了","所以","我","休息"],"m":"Потому что я заболел, поэтому отдыхаю."},{"zh":"虽然很贵，但是很好吃。","tokens":["虽然","很","贵","但是","很","好吃"],"m":"Хотя дорого, но вкусно."},{"zh":"我哥哥比我高。","tokens":["我","哥哥","比","我","高"],"m":"Мой брат выше меня."}]}'),
  ('hsk2-15-1', 1, 'fact', '{"emoji":"⏳","title":"Бамбук и храм: ждать","text":"Знак 等 děng «ждать» состоит из 竹 «бамбук» и 寺 «храм»: путники ждали у храма с бамбуковыми табличками. 错 cuò «ошибка» — 钅 «металл» и 昔 «прошлое»: что-то не так, как раньше. А 意思 yìsi «смысл» стоит в важнейшем вопросе изучающего язык: 这是什么意思？ «Что это значит?»"}'),
  ('hsk2-15-1', 2, 'words', '{"title":"Вместе, смысл, ошибка, ожидание","items":[{"hanzi":"一起","pinyin":"yìqǐ","m":"вместе","emoji":"🤝","ex":{"zh":"我们一起去吧。","py":"Wǒmen yìqǐ qù ba.","m":"Пойдём вместе."}},{"hanzi":"意思","pinyin":"yìsi","m":"смысл, значение","emoji":"💭","ex":{"zh":"这是什么意思？","py":"Zhè shì shénme yìsi?","m":"Что это значит?"}},{"hanzi":"错","pinyin":"cuò","m":"ошибка, неверный","emoji":"❌","ex":{"zh":"我错了。","py":"Wǒ cuò le.","m":"Я ошибся."}},{"hanzi":"等","pinyin":"děng","m":"ждать","emoji":"⏳","ex":{"zh":"请等一下。","py":"Qǐng děng yíxià.","m":"Подождите немного."}}]}'),
  ('hsk2-15-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🤝","options":["意思","等","一起"],"correct":2},{"emoji":"💭","options":["一起","错","意思"],"correct":2},{"emoji":"❌","options":["错","等","一起"],"correct":0},{"emoji":"⏳","options":["意思","等","错"],"correct":1}]}'),
  ('hsk2-15-1', 4, 'theory', '{"title":"Как пользоваться новыми словами","blocks":[{"t":"table","head":["Слово","Схема","Пример"],"rows":[["一起","一起 + глагол","我们一起去。"],["意思","什么意思？","这是什么意思？"],["错","…错了","我错了。 / 你没错。"],["等","等 + кого / что","我在等你。"]]},{"t":"p","text":"一起 стоит перед глаголом: 一起学习. 错 в ответе на «правильно?» значит «нет»: 你说错了 «ты сказал неверно»."},{"t":"tip","text":"Фраза 这是什么意思？ — самая полезная для изучающего: задавайте её на каждом уроке."}]}'),
  ('hsk2-15-1', 5, 'quiz', '{"title":"Мини-тест: вместе и смысл","qs":[{"q":"Как спросить «Что это значит?»","options":["这是什么意思？","什么这是意思？","这意思什么是？"],"correct":0},{"q":"Как сказать «Я ошибся»?","options":["我错了。","我了错。","错我了。"],"correct":0},{"q":"一起 ставится перед глаголом.","tf":true}]}'),
  ('hsk2-15-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["一起","вместе"],["意思","смысл"],["错","ошибка"],["等","ждать"],["这是什么意思？","что это значит?"]]}'),
  ('hsk2-15-1', 7, 'game', '{"type":"listen","title":"Слушаем: вместе и смысл","items":[{"say":"一起","options":["yíqǐ","yīqǐ","yìqǐ"],"correct":2},{"say":"意思","options":["yísi","yìsi","yìsī"],"correct":1},{"say":"错","options":["cuó","cuò","cuǒ"],"correct":1},{"say":"等","options":["dèng","déng","děng"],"correct":2},{"say":"我们一起去吧","options":["wǒmen yìqǐ lái ba","wǒmen yìqǐ qù ba"],"correct":1}]}'),
  ('hsk2-15-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我们","一起","去","吧"],"hint":"«Пойдём вместе.»"},{"answer":["这","是","什么","意思"],"hint":"«Что это значит?»"},{"answer":["请","等","一下"],"hint":"«Подождите немного.»"}]}'),
  ('hsk2-15-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"等","pinyin":"děng","m":"ждать","hint":"сверху 竹, внизу 寺"},{"hanzi":"错","pinyin":"cuò","m":"ошибка","hint":"слева 钅, справа 昔"},{"hanzi":"思","pinyin":"sī","m":"мысль","hint":"сверху 田, внизу 心"}]}'),
  ('hsk2-15-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 等?","options":["ждать","ошибаться","вместе"],"correct":0},{"q":"Как читается 意思?","options":["yìsi","yìsī","yísi"],"correct":0},{"q":"Как сказать «Я жду тебя»?","options":["我等在你。","在我等你。","我在等你。"],"correct":2},{"q":"错 значит «ошибка».","tf":true},{"q":"Как сказать «Пойдём вместе»?","options":["一起我们去吧。","我们去一起吧。","我们一起去吧。"],"correct":2}]}'),
  ('hsk2-15-2', 1, 'fact', '{"emoji":"🧠","title":"Стрела и рот: знать","text":"知 zhī «знать» — это 矢 «стрела» и 口 «рот»: знание быстро слетает с языка. А 卖 mài «продавать» и 买 mǎi «покупать» отличаются одним штрихом: сверху у 卖 добавлена 十. Запомните: у продавца «лишний десяток». Слова 开始, 觉得 и 知道 — основа вашего разговора."}'),
  ('hsk2-15-2', 2, 'words', '{"title":"Продать, начать, считать, знать","items":[{"hanzi":"卖","pinyin":"mài","m":"продавать","emoji":"🏷️","ex":{"zh":"他卖苹果。","py":"Tā mài píngguǒ.","m":"Он продаёт яблоки."}},{"hanzi":"开始","pinyin":"kāishǐ","m":"начинать, начало","emoji":"▶️","ex":{"zh":"我们开始吧。","py":"Wǒmen kāishǐ ba.","m":"Начнём."}},{"hanzi":"觉得","pinyin":"juéde","m":"считать, чувствовать","emoji":"🤔","ex":{"zh":"我觉得很好。","py":"Wǒ juéde hěn hǎo.","m":"Я считаю, что хорошо."}},{"hanzi":"知道","pinyin":"zhīdào","m":"знать, быть в курсе","emoji":"💡","ex":{"zh":"我知道。","py":"Wǒ zhīdào.","m":"Я знаю."}}]}'),
  ('hsk2-15-2', 3, 'theory', '{"title":"觉得 и 知道: «я считаю» и «я знаю»","blocks":[{"t":"table","head":["Слово","Схема","Пример"],"rows":[["觉得","觉得 + мнение","我觉得汉语很有意思。"],["知道","知道 + факт","我知道他在家。"],["不知道","не знаю","我不知道。"],["开始","开始 + глагол","开始学习。"]]},{"t":"p","text":"觉得 передаёт мнение, 知道 — знание. В отрицании говорят 不知道, а не 没知道. Для начала действия: 开始 + глагол: 开始上课 «начать урок»."},{"t":"tip","text":"Не путайте 卖 mài «продавать» (4 тон) и 买 mǎi «покупать» (3 тон)."}]}'),
  ('hsk2-15-2', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","觉得","汉语","很","有","意思"],"hint":"«Я считаю, что китайский интересен.»"},{"answer":["我","知道","他","在","家"],"hint":"«Я знаю, что он дома.»"},{"answer":["我们","开始","上课","吧"],"hint":"«Начнём урок.»"},{"answer":["他","卖","苹果"],"hint":"«Он продаёт яблоки.»"}]}'),
  ('hsk2-15-2', 5, 'quiz', '{"title":"Мини-тест: мнение и знание","qs":[{"q":"Как сказать «Я не знаю»?","options":["我知道不。","我没知道。","我不知道。"],"correct":2},{"q":"Что значит 卖?","options":["ждать","продавать","покупать"],"correct":1},{"q":"觉得 передаёт мнение.","tf":true}]}'),
  ('hsk2-15-2', 6, 'game', '{"type":"listen","title":"Слушаем: продать, начать, знать","items":[{"say":"卖","options":["mài","mǎi","mái"],"correct":0},{"say":"开始","options":["kǎishǐ","kāishì","kāishǐ"],"correct":2},{"say":"觉得","options":["juéde","juède","juédé"],"correct":0},{"say":"知道","options":["zhídào","zhǐdào","zhīdào"],"correct":2},{"say":"我觉得很好","options":["wǒ zhīdào hěn hǎo","wǒ juéde hěn hǎo"],"correct":1}]}'),
  ('hsk2-15-2', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["卖","продавать"],["开始","начинать"],["觉得","считать"],["知道","знать"],["不知道","не знаю"]]}'),
  ('hsk2-15-2', 8, 'game', '{"type":"bughunt","title":"Китайский детектив: знаю, считаю, продаю","cases":[{"buggyText":"我没知道。","context":"«Я не знаю»","options":["我知道没。","没我知道。","我不知道。"],"correct":2},{"buggyText":"我们开始吧上课。","context":"«Начнём урок»","options":["我们开始上课吧。","我们上课开始吧。","开始我们上课吧。"],"correct":0},{"buggyText":"他买苹果。","context":"«Он продаёт яблоки»","options":["他卖苹果。","他苹果买。","他卖了买苹果。"],"correct":0}]}'),
  ('hsk2-15-2', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как читается 知道?","options":["zhīdào","zhǐdào","zhídào"],"correct":0},{"q":"Как сказать «Начнём»?","options":["开始吧我们。","我们开始吧。","我们吧开始。"],"correct":1},{"q":"没知道 — правильная форма отрицания.","tf":false},{"q":"Как сказать «Я считаю, что хорошо»?","options":["我很好觉得。","我觉得很好。","觉得我很好。"],"correct":1},{"q":"Что значит 开始?","options":["ждать","начинать","заканчивать"],"correct":1}]}'),
  ('hsk2-15-3', 1, 'fact', '{"emoji":"🛠️","title":"Действие в процессе, результате и состоянии","text":"正在 zhèngzài «как раз сейчас» ставится перед глаголом: 我正在学习 «я как раз учусь». 完 wán «закончить» присоединяют к глаголу как результат: 吃完 «доесть», 写完 «дописать». А 着 zhe показывает состояние, которое продолжается: 门开着 «дверь открыта», 他坐着 «он сидит». Вместе с 准备 zhǔnbèi «готовиться» это последние слова HSK 2."}'),
  ('hsk2-15-3', 2, 'words', '{"title":"Подготовка и процесс","items":[{"hanzi":"准备","pinyin":"zhǔnbèi","m":"готовиться, готовить","emoji":"📚","ex":{"zh":"我准备考试。","py":"Wǒ zhǔnbèi kǎoshì.","m":"Я готовлюсь к экзамену."}},{"hanzi":"正在","pinyin":"zhèngzài","m":"как раз сейчас","emoji":"⏱️","ex":{"zh":"我正在学习。","py":"Wǒ zhèngzài xuéxí.","m":"Я как раз учусь."}},{"hanzi":"完","pinyin":"wán","m":"закончить, закончено","emoji":"✅","ex":{"zh":"我写完了。","py":"Wǒ xiěwán le.","m":"Я дописал."}},{"hanzi":"着","pinyin":"zhe","m":"частица длящегося состояния","emoji":"🔒","ex":{"zh":"门开着。","py":"Mén kāi zhe.","m":"Дверь открыта."}}]}'),
  ('hsk2-15-3', 3, 'theory', '{"title":"正在, 完, 着: три способа смотреть на действие","blocks":[{"t":"table","head":["Слово","Что показывает","Пример"],"rows":[["正在","действие идёт сейчас","我正在学习。"],["完","действие завершено","我写完了。"],["着","состояние продолжается","门开着。"],["准备","подготовка","我准备考试。"]]},{"t":"p","text":"正在 ставится перед глаголом, 完 — сразу после глагола, 着 — после глагола и звучит безударно. 准备 + глагол или существительное: 准备考试, 准备吃饭."},{"t":"tip","text":"正在 можно сократить: 我在学习 — тоже «я учусь сейчас»."}]}'),
  ('hsk2-15-3', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","正在","学习"],"hint":"«Я как раз учусь.»"},{"answer":["我","写","完","了"],"hint":"«Я дописал.»"},{"answer":["门","开","着"],"hint":"«Дверь открыта.»"},{"answer":["我","准备","考试"],"hint":"«Я готовлюсь к экзамену.»"}]}'),
  ('hsk2-15-3', 5, 'quiz', '{"title":"Мини-тест: процесс и результат","qs":[{"q":"Как сказать «Я как раз учусь»?","options":["我正在学习。","我学习正在。","正在我学习。"],"correct":0},{"q":"Что значит 完 после глагола?","options":["начало","завершение действия","отрицание"],"correct":1},{"q":"着 показывает продолжающееся состояние.","tf":true}]}'),
  ('hsk2-15-3', 6, 'game', '{"type":"listen","title":"Слушаем: процесс и результат","items":[{"say":"准备","options":["zhúnbèi","zhǔnbēi","zhǔnbèi"],"correct":2},{"say":"正在","options":["zhēngzài","zhèngzài","zhèngzǎi"],"correct":1},{"say":"完","options":["wán","wàn","wǎn"],"correct":0},{"say":"门开着","options":["mén kāi zhe","mén kāi le"],"correct":0},{"say":"我写完了","options":["wǒ xiě le","wǒ xiěwán le"],"correct":1}]}'),
  ('hsk2-15-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["准备","готовиться"],["正在","как раз сейчас"],["完","закончить"],["着","длящееся состояние"],["吃完","доесть"]]}'),
  ('hsk2-15-3', 8, 'game', '{"type":"chatsim","title":"WeChat: что делаешь","messages":[{"speaker":"Друг","text":"你在做什么？","pinyin":"Nǐ zài zuò shénme?","translation":"Что ты делаешь?","options":["我做在准备。","我正在准备考试。","我准备正在考试。"],"correct":1},{"speaker":"Друг","text":"你写完了吗？","pinyin":"Nǐ xiěwán le ma?","translation":"Ты дописал?","options":["写完了。","完写了。","写了完。"],"correct":0},{"speaker":"Друг","text":"门开着吗？","pinyin":"Mén kāi zhe ma?","translation":"Дверь открыта?","options":["开了着。","着开。","开着。"],"correct":2}]}'),
  ('hsk2-15-3', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: процесс","cases":[{"buggyText":"我学习正在。","context":"«Я как раз учусь»","options":["正在我学习。","我正在学习。","我正学习在。"],"correct":1},{"buggyText":"我完写了。","context":"«Я дописал»","options":["我写完了。","完我写了。","我写了完。"],"correct":0},{"buggyText":"门着开。","context":"«Дверь открыта»","options":["门开了着。","着门开。","门开着。"],"correct":2}]}'),
  ('hsk2-15-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как читается 准备?","options":["zhúnbèi","zhǔnbēi","zhǔnbèi"],"correct":2},{"q":"Как сказать «Я готовлюсь к экзамену»?","options":["我考试准备。","我准备考试。","准备我考试。"],"correct":1},{"q":"正在 ставится перед глаголом.","tf":true},{"q":"Как сказать «Я дописал»?","options":["我完写了。","我写完了。","我写了完。"],"correct":1},{"q":"Как сказать «Дверь открыта»?","options":["门开着。","门着开。","着门开。"],"correct":0}]}'),
  ('hsk2-15-4', 1, 'fact', '{"emoji":"📚","title":"Анна и Ли Мин готовятся к экзамену","text":"Это последний диалог HSK 2. Анна и Ли Мин вместе готовятся, спрашивают смысл слов, поправляют друг друга и благодарят. В диалоге встретятся 一起, 意思, 错, 等, 觉得, 知道, 准备, 正在, 完, 开始."}'),
  ('hsk2-15-4', 2, 'text', '{"title":"Подготовка к экзамену","lines":[{"zh":"李明：安娜，你在做什么？","py":"Lǐ Míng: Ānnà, nǐ zài zuò shénme?","m":"Ли Мин: Анна, что делаешь?"},{"zh":"安娜：我正在准备考试。你呢？","py":"Ānnà: Wǒ zhèngzài zhǔnbèi kǎoshì. Nǐ ne?","m":"Анна: Готовлюсь к экзамену. А ты?"},{"zh":"李明：我正在写汉字。我已经写完了。","py":"Lǐ Míng: Wǒ zhèngzài xiě Hànzì. Wǒ yǐjīng xiěwán le.","m":"Ли Мин: Пишу иероглифы. Уже дописал."},{"zh":"安娜：你知道这个字是什么意思吗？","py":"Ānnà: Nǐ zhīdào zhège zì shì shénme yìsi ma?","m":"Анна: Знаешь, что значит этот знак?"},{"zh":"李明：我觉得是“朋友”的意思。","py":"Lǐ Míng: Wǒ juéde shì “péngyou” de yìsi.","m":"Ли Мин: Мне кажется, он значит «друг»."},{"zh":"安娜：你说得对！我错了。","py":"Ānnà: Nǐ shuō de duì! Wǒ cuò le.","m":"Анна: Ты прав! Я ошиблась."},{"zh":"李明：没关系。我们一起学习吧。","py":"Lǐ Míng: Méi guānxi. Wǒmen yìqǐ xuéxí ba.","m":"Ли Мин: Ничего. Давай учиться вместе."},{"zh":"安娜：好，请等我一下，我马上开始。","py":"Ānnà: Hǎo, qǐng děng wǒ yíxià, wǒ mǎshàng kāishǐ.","m":"Анна: Хорошо, подожди немного, я сейчас начну. (马上 «сейчас» — новое слово)"}],"qs":[{"q":"Что делает Анна?","options":["идёт гулять","готовится к экзамену","смотрит кино"],"correct":1},{"q":"Что уже сделал Ли Мин?","options":["купил книгу","сдал экзамен","дописал иероглифы"],"correct":2},{"q":"Ли Мин думает, что знак значит «друг».","tf":true},{"q":"Что говорит Анна о своей ошибке?","options":["我错了","我不知道","我对了"],"correct":0},{"q":"Они решают учиться отдельно.","tf":false,"explain":"Ли Мин говорит 我们一起学习吧."},{"q":"Вставьте слово: 请___我一下。","options":["卖","买","等"],"correct":2},{"q":"Что значит 我觉得?","options":["мне кажется","я знаю","я купил"],"correct":0}]}'),
  ('hsk2-15-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["我正在准备考试","я готовлюсь к экзамену"],["我已经写完了","я уже дописал"],["这个字是什么意思？","что значит этот знак?"],["你说得对，我错了","ты прав, я ошиблась"],["我们一起学习吧","давай учиться вместе"]]}'),
  ('hsk2-15-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"我正在准备考试","options":["wǒ zhèngzài xuéxí Hànyǔ","wǒ zhèngzài zhǔnbèi kǎoshì"],"correct":1},{"say":"我已经写完了","options":["wǒ yǐjīng xiě le","wǒ yǐjīng xiěwán le"],"correct":1},{"say":"你知道这个字是什么意思吗","options":["nǐ juéde zhège zì shì shénme yìsi ma","nǐ zhīdào zhège zì shì shénme yìsi ma"],"correct":1},{"say":"我们一起学习吧","options":["wǒmen yìqǐ qù ba","wǒmen yìqǐ xuéxí ba"],"correct":1}]}'),
  ('hsk2-15-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: подготовка","cases":[{"buggyText":"我准备正在考试。","context":"«Я как раз готовлюсь к экзамену»","options":["我考试正在准备。","我正在准备考试。","正在我准备考试。"],"correct":1},{"buggyText":"我写了完。","context":"«Я дописал»","options":["我写完了。","写完我了。","我完写了。"],"correct":0},{"buggyText":"我们学习一起吧。","context":"«Давай учиться вместе»","options":["我们吧一起学习。","一起我们学习吧。","我们一起学习吧。"],"correct":2}]}'),
  ('hsk2-15-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Мне кажется, это значит „друг“»?","options":["觉得我朋友的意思。","我觉得是“朋友”的意思。","我知道觉得是朋友。"],"correct":1},{"q":"Как читается 开始?","options":["kǎishǐ","kāishǐ","kāishì"],"correct":1},{"q":"Анна признаёт свою ошибку.","tf":true}]}'),
  ('hsk2-15-5', 1, 'fact', '{"emoji":"🎯","title":"Финальный проект HSK 2","text":"Сегодня вы собираете рассказ о себе из слов обоих уровней: что делаете, что любите, что планируете и чему научились. Всё, что вы узнали в HSK 1 и HSK 2."}'),
  ('hsk2-15-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"知","correctRadicals":["矢","口"],"title":"Пазл: соберите 知"}'),
  ('hsk2-15-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"错","radicals":["钅","昔","亻"],"correctOrder":["钅","昔"],"explain":"Слева 钅 «металл», справа 昔."},{"targetHanzi":"等","radicals":["竹","寺","木"],"correctOrder":["竹","寺"],"explain":"Сверху 竹, внизу 寺."},{"targetHanzi":"卖","radicals":["十","买","木"],"correctOrder":["十","买"],"explain":"Сверху 十, внизу 买."}]}'),
  ('hsk2-15-5', 4, 'game', '{"type":"build","title":"Соберите рассказ о себе","items":[{"target":"(О себе)","answer":["我","每","天","早上","七","点","起床"],"hint":"«Каждое утро я встаю в семь.»"},{"target":"(Учёба)","answer":["我","正在","准备","考试"],"hint":"«Я готовлюсь к экзамену.»"},{"target":"(Хобби)","answer":["我","喜欢","唱歌","和","跳舞"],"hint":"«Я люблю петь и танцевать.»"},{"target":"(План)","answer":["我们","一起","去","北京","旅游"],"hint":"«Мы вместе поедем в Пекин.»"},{"target":"(Мнение)","answer":["我","觉得","汉语","很","有","意思"],"hint":"«Я считаю, что китайский интересен.»"}]}'),
  ('hsk2-15-5', 5, 'theory', '{"title":"План рассказа","blocks":[{"t":"table","head":["Тема","Фраза"],"rows":[["Распорядок","我每天早上七点起床。"],["Учёба","我正在准备考试。"],["Увлечения","我喜欢唱歌。"],["План","我们一起去北京旅游。"],["Мнение","我觉得汉语很有意思。"]]}]}'),
  ('hsk2-15-5', 6, 'game', '{"type":"chatsim","title":"WeChat: мои планы","messages":[{"speaker":"Друг","text":"你在做什么？","pinyin":"Nǐ zài zuò shénme?","translation":"Что делаешь?","options":["我正在准备考试。","我做在准备。","我准备正在考试。"],"correct":0},{"speaker":"Друг","text":"你觉得汉语怎么样？","pinyin":"Nǐ juéde Hànyǔ zěnmeyàng?","translation":"Как тебе китайский?","options":["我觉得很有意思。","我知道很有意思。","有意思我觉得。"],"correct":0},{"speaker":"Друг","text":"我们一起去旅游吧！","pinyin":"Wǒmen yìqǐ qù lǚyóu ba!","translation":"Поедем вместе!","options":["不是，旅游我。","好！我们去北京吧。","好，我们一起去不。"],"correct":1}]}'),
  ('hsk2-15-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["矢 + 口","知"],["钅 + 昔","错"],["竹 + 寺","等"],["十 + 买","卖"]]}'),
  ('hsk2-15-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"知","pinyin":"zhī","m":"знать","hint":"слева 矢, справа 口"},{"hanzi":"完","pinyin":"wán","m":"закончить","hint":"сверху 宀, внизу 元"},{"hanzi":"始","pinyin":"shǐ","m":"начало","hint":"слева 女, справа 台"}]}'),
  ('hsk2-15-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я считаю, что китайский интересен»?","options":["觉得我汉语有意思。","我汉语觉得很有意思。","我觉得汉语很有意思。"],"correct":2},{"q":"Из чего состоит 知?","options":["矢 и 口","竹 и 寺","钅 и 昔"],"correct":0},{"q":"Для мнения используют 觉得.","tf":true}]}'),
  ('hsk2-15-6', 1, 'fact', '{"emoji":"🏆","title":"Финальный экзамен уровня","text":"Вы прошли 15 глав HSK 2 и выучили 150 новых слов. Экзамен собирает слова и фразы из всех глав. Нужен проходной балл, чтобы закончить уровень. Если не набрали, вернитесь к главам, где ошибались."}'),
  ('hsk2-15-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"我姓王","options":["wǒ xìng Wáng","wǒ jiào Wáng","wǒ shì Wáng"],"correct":0},{"say":"我有一个哥哥","options":["wǒ yǒu yí gè gēge","wǒ yǒu yí gè dìdi"],"correct":0},{"say":"这件衣服很贵","options":["zhè jiàn yīfu hěn dà","zhè jiàn yīfu hěn guì"],"correct":1},{"say":"一百零五","options":["yì bǎi líng wǔ","yì bǎi wǔ"],"correct":0},{"say":"我早上七点起床","options":["wǒ zǎoshang qī diǎn qǐchuáng","wǒ wǎnshang qī diǎn qǐchuáng"],"correct":0},{"say":"我有一个问题","options":["wǒ yǒu yí gè wèntí","wǒ yǒu yí gè tí"],"correct":0},{"say":"给我一本书","options":["sòng wǒ yì běn shū","gěi wǒ yì běn shū"],"correct":1},{"say":"从学校到机场","options":["cóng jīchǎng dào xuéxiào","cóng xuéxiào dào jīchǎng"],"correct":1},{"say":"我去过北京","options":["wǒ qù le Běijīng","wǒ qù guo Běijīng"],"correct":1},{"say":"我要一杯咖啡","options":["wǒ yào yí bēi kāfēi","wǒ yào yì bēi kāfēi"],"correct":1},{"say":"我喜欢唱歌","options":["wǒ xǐhuan tiàowǔ","wǒ xǐhuan chànggē"],"correct":1},{"say":"他生病了","options":["tā shēngbìng le","tā shēngrì le"],"correct":0},{"say":"他说得很快","options":["tā shuō de hěn màn","tā shuō de hěn kuài"],"correct":1},{"say":"因为我生病了所以我休息","options":["yīnwèi wǒ shēngbìng le dànshì wǒ xiūxi","yīnwèi wǒ shēngbìng le suǒyǐ wǒ xiūxi"],"correct":1},{"say":"我正在准备考试","options":["wǒ zhèngzài zhǔnbèi kǎoshì","wǒ zhèngzài xuéxí Hànyǔ"],"correct":0}]}'),
