  ('hsk2-15-6', 4, 'game', '{"type":"match","title":"Слова всех глав","pairs":[["介绍","представлять"],["孩子","ребёнок"],["颜色","цвет"],["号码","номер"],["小时","час (длительность)"],["问题","вопрос"],["帮助","помогать"],["机场","аэропорт"],["旁边","рядом"],["鸡蛋","яйцо"],["旅游","путешествовать"],["身体","тело, здоровье"],["手机","мобильный телефон"],["因为","потому что"],["知道","знать"]]}'),
  ('hsk2-15-6', 5, 'quiz', '{"title":"Большой экзамен: вопросы","qs":[{"q":"Как сказать «Я тоже студент»?","options":["我也是学生。","也我是学生。","我是学生也。"],"correct":0},{"q":"Как сказать «У меня есть старший брат»?","options":["我有一个哥哥。","有我哥哥一个。","我哥哥有一个。"],"correct":0},{"q":"Как сказать «Эта одежда дорогая»?","options":["这衣服件很贵。","这个衣服很贵。","这件衣服很贵。"],"correct":2},{"q":"Как сказать «Я каждый день учусь два часа»?","options":["我每天学习两个小时。","我两个小时每天学习。","我学习每天两小时个。"],"correct":0},{"q":"Как сказать «Я учусь два часа»?","options":["两个小时我学习。","我两个小时学习。","我学习两个小时。"],"correct":2},{"q":"Как сказать «У меня есть вопрос»?","options":["我问题有。","有我问题。","我有一个问题。"],"correct":2},{"q":"Как сказать «Дай мне книгу»?","options":["给我一本书。","我给书一本。","给一本书我。"],"correct":0},{"q":"Как сказать «от школы до аэропорта»?","options":["从学校到机场","学校从到机场","到学校从机场"],"correct":0},{"q":"Как сказать «Школа близко от дома»?","options":["学校我家离近。","学校从我家很近。","学校离我家很近。"],"correct":2},{"q":"Как сказать «Мне чашку кофе»?","options":["我杯咖啡要一。","要我一杯咖啡。","我要一杯咖啡。"],"correct":2},{"q":"Как сказать «Я умею плавать»?","options":["我会游泳。","会我游泳。","我游泳会。"],"correct":0},{"q":"Как сказать «Я принимаю лекарство»?","options":["我吃药。","我药吃。","我喝药。"],"correct":0},{"q":"Как сказать «Он говорит быстро»?","options":["他说话说得很快。","他说话快得很。","他得说话很快。"],"correct":0},{"q":"Как сказать «Мой брат выше меня»?","options":["我哥哥高比我。","我哥哥比我高。","比我哥哥我高。"],"correct":1},{"q":"Как сказать «Я как раз готовлюсь к экзамену»?","options":["我正在准备考试。","我准备正在考试。","正在我准备考试。"],"correct":0},{"q":"也 ставится в конец предложения.","tf":false},{"q":"Момент времени стоит перед глаголом, длительность после.","tf":true},{"q":"给 может быть предлогом «для».","tf":true},{"q":"В схеме 比 перед прилагательным ставят 很.","tf":false},{"q":"После 没 частица 了 обычно не нужна.","tf":true}]}'),
  ('hsk2-15-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","姓","王"],"hint":"«Моя фамилия Ван.»"},{"answer":["我","有","一个","哥哥"],"hint":"«У меня есть старший брат.»"},{"answer":["这","件","衣服","很","贵"],"hint":"«Эта одежда дорогая.»"},{"answer":["我","早上","七","点","起床"],"hint":"«Я встаю в семь утра.»"},{"answer":["我","有","一个","问题"],"hint":"«У меня есть вопрос.»"},{"answer":["从","学校","到","机场"],"hint":"«От школы до аэропорта.»"},{"answer":["我","要","一","杯","咖啡"],"hint":"«Мне чашку кофе.»"},{"answer":["因为","我","生病","了","，","所以","我","休息"],"hint":"«Потому что я заболел, поэтому отдыхаю.»"}]}'),
  ('hsk2-15-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我是学生也。","context":"«Я тоже студент»","options":["我是也学生。","我也是学生。","也我是学生。"],"correct":1},{"buggyText":"我起床七点。","context":"«Я встаю в семь»","options":["我七点起床。","七点我起床。","我七起床点。"],"correct":0},{"buggyText":"给一本书我。","context":"«Дай мне книгу»","options":["我给一本书。","一本书我给。","给我一本书。"],"correct":2},{"buggyText":"学校从我家很近。","context":"«Школа близко от дома»","options":["学校我家离很近。","学校离我家很近。","学校离近我家很。"],"correct":1},{"buggyText":"我哥哥比我很高。","context":"«Брат выше меня»","options":["我哥哥比我高。","我哥哥很比我高。","我比哥哥很高。"],"correct":0},{"buggyText":"我学习正在。","context":"«Я как раз учусь»","options":["我正学习在。","我正在学习。","正在我学习。"],"correct":1}]}'),
  ('hsk2-15-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"你好！你姓什么？","pinyin":"Nǐ hǎo! Nǐ xìng shénme?","translation":"Здравствуйте! Какая у вас фамилия?","options":["我姓安。","我叫姓安。","我是姓安。"],"correct":0},{"speaker":"Друг","text":"你每天几点起床？","pinyin":"Nǐ měi tiān jǐ diǎn qǐchuáng?","translation":"Во сколько ты встаёшь?","options":["我早上七点起床。","我起床七点早上。","我七点早上起。"],"correct":0},{"speaker":"Друг","text":"你喜欢什么运动？","pinyin":"Nǐ xǐhuan shénme yùndòng?","translation":"Какой спорт ты любишь?","options":["喜欢游泳我吗。","我喜欢游泳和跑步。","我运动喜欢是。"],"correct":1},{"speaker":"Друг","text":"你觉得汉语怎么样？","pinyin":"Nǐ juéde Hànyǔ zěnmeyàng?","translation":"Как тебе китайский?","options":["我觉得很有意思。","我知道很有意思。","有意思我觉得。"],"correct":0}]}'),
